do $importacao$
declare
  v_registros jsonb := $apostila$[{"secao":"Saúde Coletiva e Bioética","numero":1,"orgao":"Prefeitura de Areia-PB","cargo":"ODONTOLÓGO – PSF","ano":2022,"enunciado":"De acordo com o artigo 7º da Lei Orgânica da Saúde 8.080/1990, as ações e serviços públicos de saúde e os serviços privados contratados ou conveniados que integram o Sistema Único de Saúde (SUS) são desenvolvidos de acordo com as diretrizes previstas na Constituição Federal, obedecendo ainda aos seguintes princípios, EXCETO:","alternativas":[{"letra":"A","texto":"universalidade de acesso aos serviços de saúde em todos os níveis de assistência.","ordem":1,"idAlternativa":"ce580c6d-0432-58ac-90d3-d226201a1493"},{"letra":"B","texto":"divulgação de informações referentes ao potencial dos serviços de saúde apenas no meio acadêmico e científico.","ordem":2,"idAlternativa":"fba66585-b6c6-5a78-8b1e-e2db0eeadada"},{"letra":"C","texto":"preservação da autonomia das pessoas na defesa de sua integridade física e moral.","ordem":3,"idAlternativa":"736a5d33-426a-520c-8e20-691f5d3bddb1"},{"letra":"D","texto":"utilização da epidemiologia para o estabelecimento de prioridades.","ordem":4,"idAlternativa":"a588acb2-62ef-5d23-b906-d3f2c598aaf5"},{"letra":"E","texto":"igualdade da assistência à saúde, sem preconceitos ou privilégios de qualquer espécie.","ordem":5,"idAlternativa":"78c5f98e-7397-5619-9af7-fd54bbc99615"}],"gabarito":"B","observacoes":[],"idQuestao":"a29692bd-58af-5945-8f6f-35d8e40380f4","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"b65a1e91-7e51-5d2f-bcc7-bd912e8baf6b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 1"},{"secao":"Saúde Coletiva e Bioética","numero":2,"orgao":"Prefeitura de Areia-PB","cargo":"ODONTOLÓGO – PSF","ano":2022,"enunciado":"Segundo a Lei Orgânica da Saúde 8.080/1990, à direção municipal do Sistema Único de Saúde (SUS) compete:","alternativas":[{"letra":"A","texto":"Formular, avaliar e apoiar políticas de alimentação enutrição.","ordem":1,"idAlternativa":"ba12d794-786d-5266-afb5-7c9f8a03c9ca"},{"letra":"B","texto":"Planejar, organizar, controlar e avaliar as ações e os serviços de saúde e gerir e executar os serviços públicos de saúde.","ordem":2,"idAlternativa":"725daceb-9aa6-5ce8-b794-d92eb8d607f0"},{"letra":"C","texto":"Promover articulação com os órgãos educacionais e de fiscalização do exercício profissional.","ordem":3,"idAlternativa":"a413288f-5e94-5659-a62c-c0795771854e"},{"letra":"D","texto":"Normatizar e coordenar nacionalmente o Sistema Nacional de Sangue.","ordem":4,"idAlternativa":"868f3f4e-4517-52c2-ad9f-afa783798519"},{"letra":"E","texto":"Elaborar o Planejamento Estratégico Nacional no âmbito do SUS.","ordem":5,"idAlternativa":"54401acc-96fe-5596-af78-b1a31872c577"}],"gabarito":"B","observacoes":[],"idQuestao":"cf8ebf16-d0e7-55fd-bf2b-fe1b7fb08e5b","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"b65a1e91-7e51-5d2f-bcc7-bd912e8baf6b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 2"},{"secao":"Saúde Coletiva e Bioética","numero":3,"orgao":"Prefeitura de Areia-PB","cargo":"ODONTOLÓGO – PSF","ano":2022,"enunciado":"A Lei Orgânica da Saúde 8.142/1990 dispõe sobre a participação da comunidade na gestão do Sistema Único de Saúde (SUS) e sobre as transferências intergovernamentais de recursos financeiros na área da saúde. De acordo com a Lei 8.142/1990, assinale a alternativa CORRETA:","alternativas":[{"letra":"A","texto":"A Conferência de Saúde, em caráter permanente e deliberativo, órgão colegiado composto por representantes do governo, prestadores de serviço, profissionais de saúde e usuários, atua na formulação de estratégias e no controle da execução da política de saúde na instância correspondente.","ordem":1,"idAlternativa":"62292c7c-4e78-55f3-a5bd-5a89b057be16"},{"letra":"B","texto":"O Conselho de Saúde reunir-se-á a cada quatro anos com a representação dos vários segmentos sociais, para avaliar a situação de saúde e propor as diretrizes paraa formulação da política de saúde nos níveis correspondentes.","ordem":2,"idAlternativa":"2de4a4d2-578f-5083-80b7-73f2d145263f"},{"letra":"C","texto":"A representação dos usuários nos Conselhos de Saúde e Conferências será paritária em relação ao conjunto dos demais segmentos.","ordem":3,"idAlternativa":"dc801e41-91ef-52a2-b72e-e16fda9a8003"},{"letra":"D","texto":"As Conferências de Saúde e os Conselhos de Saúde terão sua organização e normas de funcionamento definidas pela Secretaria de Saúde no nível em questão, não dispondo de regimento próprio.","ordem":4,"idAlternativa":"d9fc5e9a-14d4-53d6-b48b-9a6bb6d03b74"},{"letra":"E","texto":"O Conselho Nacional de Secretários de Saúde (CONASS) e o Conselho Nacional de Secretários Municipais de Saúde (CONASEMS) não dispõem de representação no Conselho Nacional de Saúde, apenas no municipal e estadual.","ordem":5,"idAlternativa":"3571d5e0-e87a-5898-a636-fd5b9265d843"}],"gabarito":"C","observacoes":[],"idQuestao":"e94b9ccc-84eb-58d0-b13a-56bd03d2e850","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"b65a1e91-7e51-5d2f-bcc7-bd912e8baf6b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 3"},{"secao":"Saúde Coletiva e Bioética","numero":4,"orgao":"Prefeitura de Areia-PB","cargo":"ODONTOLÓGO – PSF","ano":2022,"enunciado":"As diretrizes da política nacional de saúde bucal (PNSB) foram apresentadas em 2004 e apontam para uma reorganização da atenção em saúde bucal, tendo o conceito do cuidado como eixo de reorientação do modelo. Assinale a alternativa CORRETA, no que tange aos princípios norteadores da PNSB:","alternativas":[{"letra":"A","texto":"As atividades educativas e preventivas, ao nível coletivo, devem ser executadas, preferencialmente pelo pessoal auxiliar, com participação ativa do cirurgião-dentista.","ordem":1,"idAlternativa":"74ac9ed0-3355-5447-8a35-56a8bb6d7480"},{"letra":"B","texto":"Aconselha-se que 50% das horas contratadas devem ser dedicadas à assistência e 50% sejam disponibilizadas para outras atividades (planejamento, capacitação, atividades coletivas).","ordem":2,"idAlternativa":"97688e02-8529-508f-a146-a44443de8a54"},{"letra":"C","texto":"A garantia do atendimento de urgência deve ser realizado apenas nas unidades de pronto-atendimento, não sendo objetivo da saúde bucal na atenção básica e não devendo interferir no processo.","ordem":3,"idAlternativa":"b01681f5-4e2e-5620-80d5-fd89b499b6a5"},{"letra":"D","texto":"Os recursos humanos devem ser adequados de acordo com a capacidade do gestor em contratar os profissionais.","ordem":4,"idAlternativa":"e590dc28-573a-5912-918d-02064b1d7a10"},{"letra":"E","texto":"O cirurgião-dentista não deve considerar-se co-responsável pelo enfrentamento dos fatores associados com o processo saúde doença em cadaterritório.","ordem":5,"idAlternativa":"52971fa4-cceb-51db-a33b-09b9d38e0368"}],"gabarito":"A","observacoes":[],"idQuestao":"98319f78-9a21-52ce-a1b1-7acf997937d7","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"b65a1e91-7e51-5d2f-bcc7-bd912e8baf6b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 4"},{"secao":"Saúde Coletiva e Bioética","numero":5,"orgao":"Prefeitura de Areia-PB","cargo":"ODONTOLÓGO – PSF","ano":2022,"enunciado":"A portaria Nº 2.436, de 21 de Setembro de 2017, aprova a Política Nacional de Atenção Básica (PNAB), estabelecendo a revisão de suas diretrizes no âmbito do SUS. No que diz respeito ao funcionamento das Unidades Básicas de Saúde e ao processode trabalho das diferentes modalidades de equipe, assinale a alternativa INCORRETA:","alternativas":[{"letra":"A","texto":"Recomenda-se que sejam alocadas o número máximo de 4 (quatro) equipes por UBS (Atenção Básica ou Saúde da Família), para que possam atingir seu potencial resolutivo.","ordem":1,"idAlternativa":"7d7221bf-3a4e-5e39-8f6d-767db4908eda"},{"letra":"B","texto":"Recomenda-se população adscrita por equipe de Atenção Básica (eAB) e de Saúde da Família (eSF) de 2.000 a 3.500 pessoas, localizada dentro do seu território, garantindo os princípios e diretrizes da Atenção Básica.","ordem":2,"idAlternativa":"05589f94-1c3b-5920-96d0-ec603bc53ae0"},{"letra":"C","texto":"Para a equipe de Atenção Básica, a composição da carga horária mínima por categoria profissional deverá ser de 10 (dez) horas, com no máximo de 3 (três) profissionais por categoria, devendo somar no mínimo 40 horas/semanais.","ordem":3,"idAlternativa":"e1cbfee6-7b08-5689-83d2-051901b6a70b"},{"letra":"D","texto":"Em áreas de grande dispersão territorial, áreas de risco e vulnerabilidade social, recomenda-se a cobertura de 100% da população com número máximo de 1000 pessoas por ACS.","ordem":4,"idAlternativa":"e41412e3-ff80-553a-91cf-ed7a0d21705d"},{"letra":"E","texto":"Recomenda-se que em municípios ou territórios com menos de 2.000 habitantes, uma equipe de Saúde da Família (eSF) ou de Atenção Básica (eAB) seja responsável por toda a população.","ordem":5,"idAlternativa":"8b443958-b959-5440-89ee-40bb497d20d2"}],"gabarito":"D","observacoes":[],"idQuestao":"42e5b8a9-e796-5c18-ae1a-53521235b19b","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"b65a1e91-7e51-5d2f-bcc7-bd912e8baf6b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 5"},{"secao":"Saúde Coletiva e Bioética","numero":6,"orgao":"Prefeitura de Areia-PB","cargo":"ODONTOLÓGO – PSF","ano":2022,"enunciado":"O Código de Ética Odontológica regula os direitos e deveres dos profissionais, das entidades e das operadoras de planos de saúde com inscrição nos Conselhos de Odontologia, segundo suas atribuições específicas. Constitui um direito fundamental dos profissionais inscritos, segundo suas atribuições específicas:","alternativas":[{"letra":"A","texto":"Deixar de esclarecer adequadamente os propósitos, riscos, custos e alternativas do tratamento.","ordem":1,"idAlternativa":"663e86c0-5526-5c1a-9086-775e04a2114e"},{"letra":"B","texto":"Renunciar ao atendimento do paciente, durante o tratamento, quando da constatação de fatos que, a critério do profissional, prejudiquem o bom relacionamento com o paciente ou o pleno desempenhoprofissional.","ordem":2,"idAlternativa":"c90d06be-69f5-5e5a-993f-582a5c155ec4"},{"letra":"C","texto":"Adotar novas técnicas ou materiais que não tenham efetiva comprovação científica.","ordem":3,"idAlternativa":"cde08331-1764-5cac-99a9-d2cb2e606563"},{"letra":"D","texto":"Iniciar qualquer procedimento ou tratamento odontológico sem o consentimento prévio do paciente ou do seu responsável legal.","ordem":4,"idAlternativa":"e6a140ec-57fd-505f-86d8-b6f7ded17ade"},{"letra":"E","texto":"Revelar, sem justa causa, fato sigiloso de que tenha conhecimento em razão do exercício de sua profissão.","ordem":5,"idAlternativa":"929cbab7-d557-530f-9fe7-2aec61e9deb5"}],"gabarito":"B","observacoes":[],"idQuestao":"1de9ebed-bfbf-5dc4-b7c3-060da15783ee","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"b65a1e91-7e51-5d2f-bcc7-bd912e8baf6b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 6"},{"secao":"Saúde Coletiva e Bioética","numero":7,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"No campo da saúde bucal, a organização dos sistemas se mostra favorecida pelo desenho da Política Nacional de Saúde Bucal, que fortalece os princípios do cuidado, da equidade e da integralidade. O Brasil Sorridente direcionou a ampliação no acesso da população à atenção à saúde bucal, em diversos eixos estratégicos e pontos de atenção: na vigilância em saúde bucal (sanitária, epidemiológica, ambiental), na ampliação de sistemas de fluoretação de água, na expansão da oferta de serviços da Atenção Primária à Saúde (APS), na criação e implantação de Centros de Especialidades Odontológicas (CEOs) e na implantação dos Laboratórios Regionais de Prótese Dentária (LRPDs), na inovação referente à estruturação de Centros /Unidadesde Assistência de Alta Complexidade em Oncologia (CACON / UNACON). Diante dessas informações, analise as afirmativas a seguir. I. A Atenção Primária em Saúde (APS) na configuração das Redes de Atenção responsabiliza-se pela atenção à saúde bucal de seus usuários, constituindo-se na principal porta de entrada do sistema, ofertando ações de saúde de caráter individual e coletivo, e organizando o processo de trabalho de equipes multiprofissionais na perspectiva de abordagem integral do processo saúde doença unidade do sistema. II. Os Centros de Especialidades Odontológicas (CEOs) favorecem o acesso da população a procedimentos de maior complexidade tecnológica, não contemplados nas Unidades Básicas de Saúde (UBS). III. Os CEOs assumem a posição de referência especializada de saúde bucal, oferecendo atendimentos como cirurgia oral menor, periodontia e endodontia. IV. O Brasil Sorridente investiu na organização da atenção hospitalar. Destacam-se a atenção às pessoas com neoplasias bucais e os pacientes especiais que necessitam de anestesia geral. Nas neoplasias bucais, a rede foi fortalecida por meio dos Centros / Unidades de Assistência de Alta Complexidade em Oncologia (CACON / UNACON). Estão corretas as afirmativas","alternativas":[{"letra":"A","texto":"I e II, apenas.","ordem":1,"idAlternativa":"2753cd0b-6ed4-5f9b-9421-510d88bca312"},{"letra":"B","texto":"III e IV, apenas.","ordem":2,"idAlternativa":"a2eb942a-12f0-5ed6-bdae-5eb1abddc1a9"},{"letra":"C","texto":"I, II, III e IV.","ordem":3,"idAlternativa":"052bcb9c-64bb-5f93-889b-221e5a5ce600"},{"letra":"D","texto":"II e III, apenas","ordem":4,"idAlternativa":"3c633930-0c81-5629-99e7-0ebe5039da71"}],"gabarito":"C","observacoes":[],"idQuestao":"57e9e45d-b7f3-5d09-b811-dda7c1413971","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 7"},{"secao":"Saúde Coletiva e Bioética","numero":8,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"Paciente de 42 anos de idade, sexo masculino, agricultor, proveniente do meio rural, com histórico de poucas consultas médicas e odontológicas e baixa assiduidade aos serviços oferecidos. Em consulta de acolhimento realizada pelo profissional cirurgiãodentista, o paciente referia, como queixa principal, ardência e dor na boca devido a uma afta que não cicatrizava. Durante a anamnese, o paciente ainda relatou a ocorrência de outra “afta” que aparecera nas semanas anteriores, com características semelhantes, porém com remissão espontânea. Durante o exame clínico, observou-se lesões em áreas superficiais irregulares de necrose da mucosa, de coloração acinzentada, destacáveis e indolores, em fundo de sulco vestibular superior. Conforme relato do paciente, do primeiro sintoma até a consulta, passaram-se de quatro a seis semanas, assim, o diagnóstico sugestivo era de lesão secundáriade sífilis. Após o resultado a positividade para lesão de sífilis e HIV, a abordagem multiprofissional se intensificou e o paciente foi encaminhado para o serviço de referência. Diante dessas informações, analise as afirmativas a seguir. I. O processo de trabalho previsto para os centros de saúde pertencentes ao Sistema Único de Saúde (SUS) se dá por meio de equipes multiprofissionais. A equipe multiprofissional de saúde surge como uma alternativa para efetivar o cuidado integral em saúde. II. Entende-se que o profissional em questão seja atuante em saúde pública, e, além de realizar tratamento de dentes e de processos cariosos, atue na saúde como estado geral do paciente em sua integralidade. III. O cirurgião-dentista em questão, tendo em vista atuação interdisciplinar, é capacitado para detecção precoce de doenças sexualmente transmissíveis, uma ampliação do cuidado em saúde pelo profissional, com enfoque maior que o problema relacionado à cavidade oral, ou seja, é capaz de detectar um problema do estado geral de saúde do paciente. IV. Percebe-se que o olhar ampliado sobre o conceito de saúde e a escuta sob a perspectiva do paciente oportunizaram durante uma consulta simples o diagnóstico de um problema grave de saúde. Estão corretas as afirmativas","alternativas":[{"letra":"A","texto":"I, II, III e IV.","ordem":1,"idAlternativa":"6d6132be-9561-50cb-8bc7-c9241bec2aed"},{"letra":"B","texto":"I, III e IV, apenas.","ordem":2,"idAlternativa":"358300fa-a5ed-55d2-982f-ee29cd077b2b"},{"letra":"C","texto":"II e III, apenas.","ordem":3,"idAlternativa":"0d9693d5-8fac-52ec-80ed-77a3378698ad"},{"letra":"D","texto":"II e IV, apenas.","ordem":4,"idAlternativa":"5c875c5a-efc0-5edf-821b-5a7c95141be1"}],"gabarito":"A","observacoes":[],"idQuestao":"54ccef57-4bf7-57b8-b4e2-2be989ae13f2","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 8"},{"secao":"Saúde Coletiva e Bioética","numero":9,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"O Tratamento Restaurador Atraumático (TRA) tem sido descrito como um método econômico e eficaz na prevenção e controle da doença cárie em populações vulneráveis. É considerado uma estratégia sólida baseada em promoção de saúde e prevenção da doença cárie, permitindo grande alcance populacional em saúde pública. Assinale a alternativa que não se configura como uma vantagem do Tratamento Restaurador Atraumático para a equipe odontológica:","alternativas":[{"letra":"A","texto":"O cirurgião-dentista e sua equipe podem atuar em áreas de sua responsabilidade que estão distantes da sua unidade desaúde.","ordem":1,"idAlternativa":"c335349c-5ca1-5743-8f22-114f444c36c2"},{"letra":"B","texto":"A anestesia local na maioria dos casos é dispensável.","ordem":2,"idAlternativa":"1346c72d-729e-5112-8730-091b5f872494"},{"letra":"C","texto":"O isolamento absoluto é indispensável nessa técnica.","ordem":3,"idAlternativa":"5efcc220-21d9-5450-aa17-3f0a1b72af2c"},{"letra":"D","texto":"A recidiva de cárie é baixa e os reparos quando necessários são simples e rápidos.","ordem":4,"idAlternativa":"6deed58d-9150-5459-a3ff-089a943cd752"}],"gabarito":"C","observacoes":[],"idQuestao":"29ac27c3-0762-54f3-ae6c-08e629027d25","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 9"},{"secao":"Saúde Coletiva e Bioética","numero":10,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"Sobre urgências odontológicas na Atenção Básica, assinale a alternativa incorreta.","alternativas":[{"letra":"A","texto":"São critérios de inclusão: pacientes que procuram a unidade de saúde com dor aguda de origem dentária, que possuem cartão SUS, pacientes com traumatismo dentário, pacientes com patologias de origem dentária e caráter infeccioso / agudo em que a presença e consequente evolução comprometa a saúde geral do paciente ousua estabilização. São critérios de exclusão as lesões de cárie cronificadas (sem dor) sem necessidade de tratamento imediato.","ordem":1,"idAlternativa":"b61bea9a-ca91-542b-95a1-826375598989"},{"letra":"B","texto":"O atendimento das urgências / emergências poderá ser realizado de forma inconclusiva, ou seja, apenas deve medicar em casos que necessitem de intervenções, tais como pulpectomia, exodontia, drenagem etc. A prioridade deve serremover apenas o incômodo e não a causa do problema.","ordem":2,"idAlternativa":"145e5086-4e88-59e3-89f0-c0aa711a849d"},{"letra":"C","texto":"A instalação de programas educativos em saúde com instrução de higiene oral, palestras, aplicação tópica de flúor, por exemplo, é importante para orientar as pessoas sobre as doenças bucais e como evitá-las de modo que o usuário se conscientize que o mesmo procure o serviço odontológico antes que a doença se instale e se agrave.","ordem":3,"idAlternativa":"1ed87e49-3c9e-5ac2-ac7c-1080e3d1c9c3"},{"letra":"D","texto":"Alguns benefícios esperados com o atendimento das urgências nos centros desaúde: remoção da dor, eliminação de infecções odontogênicas, tumefações, eliminação do risco de complicação sistêmica devido à evolução de certas patologias odontológicas que não foram tratadas, e retorno do paciente à sua função social.","ordem":4,"idAlternativa":"c2a1f10f-6ef4-5c40-bbe6-ddd0ed85b2e6"}],"gabarito":"B","observacoes":[],"idQuestao":"bd624640-b3da-5f2f-92b3-a50f910da53c","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 10"},{"secao":"Saúde Coletiva e Bioética","numero":11,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"Os principais meios e métodos de prevenção desenvolvidos de acordo com as especialidades do Programa de Saúde da Família em Saúde Bucal devem abordar a promoção e a prevenção de saúde bucal em ações coletivas, e devem ser enquadrados dentro dos níveis de prevenção. A esse respeito, analise as afirmativas aseguir. I. A doença cárie tem íntima relação com o tipo de alimentação e a higiene bucal dos indivíduos e da população em geral; logo, a ênfase da estratégia preventiva poderá trazer resposta positiva em relação à prevenção da doença cárie. II. A cárie, por ser uma doença multifatorial, é afetada pelas condições socioeconômicas. Assim, as ações de saúde para controle da cárie devem ser direcionadas à população sob risco social, oportunizando acesso aos tratamentos e ao uso do flúor por meio de água fluoretada e dentifrícios fluoretados, vigilância sobre os sinais de atividade da doença, em ambientes coletivos, como escolas, creches e espaços de trabalho para permitir a otimização do planejamento da intervenção para cada realidade encontrada. III. Entre as ações de promoção à saúde para controle e prevenção da cárie na população destacam-se as medidas de saúde pública intersetoriais e educativas, que possibilitem o acesso a alguma forma de flúor, redução do consumo de açúcar e disponibilidade de informação sistemática sobre os fatores de risco e autocuidado. IV. Também são determinantes as políticas relacionadas a melhoria das condições socioeconômicas, da qualidade de vida, do acesso à posse e uso de instrumentos de higiene e estímulo à manutenção da saúde. Nesse sentido, cabe à equipe de saúde comprometer-se no planejamento, organização e suporte técnico à gestão municipal de saúde para efetiva periodicidade das ações de promoção desaúde. Estão corretas as afirmativas","alternativas":[{"letra":"A","texto":"I e II, apenas.","ordem":1,"idAlternativa":"93ae944f-2ae7-510f-9a78-c5e058481882"},{"letra":"B","texto":"III e IV, apenas.","ordem":2,"idAlternativa":"b36569d7-af92-51b9-a24c-f11df33a33ec"},{"letra":"C","texto":"I, II e III, apenas.","ordem":3,"idAlternativa":"f8b2d81c-b145-508b-8ae9-6747d1270108"},{"letra":"D","texto":"I, II, III e IV.","ordem":4,"idAlternativa":"8bcf72f5-0574-54fa-aa97-86df73839318"}],"gabarito":"D","observacoes":[],"idQuestao":"16545764-0ada-54a6-8dd9-dfb96f5a915d","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 11"},{"secao":"Saúde Coletiva e Bioética","numero":12,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"De acordo com Leavell e Clark, a Promoção de Saúde é um nível de aplicação de prevenção primária. Com base nessa afirmativa, considere: A Promoção de Saúde constitui-se de medidas destinadas a melhorar a saúde das populações em geral, a saber: I - Educação para a saúde. II - Exames de saúde periódicos. III - Práticas de esportes. IV - Alimentação. V - Moradia. Estão CORRETOS os itens","alternativas":[{"letra":"A","texto":"I, II e III, apenas.","ordem":1,"idAlternativa":"6e67b3bc-9d4c-5350-b879-9050d6115240"},{"letra":"B","texto":"I, III, IV e V, apenas.","ordem":2,"idAlternativa":"6051f6d9-a92b-54c4-bed9-9b129a2d0eb9"},{"letra":"C","texto":"I, III e IV, apenas.","ordem":3,"idAlternativa":"fddabe11-3376-520a-815b-dd959bfdc4f4"},{"letra":"D","texto":"IV e V, apenas.","ordem":4,"idAlternativa":"eff03029-85a4-5c6e-9a43-e504982b2dfb"},{"letra":"E","texto":"I, II, III, IV e V.","ordem":5,"idAlternativa":"ccf8a97b-a886-5d6b-a0c1-0696a09ac123"}],"gabarito":"E","observacoes":[],"idQuestao":"94cb76aa-dee3-5acd-8c4c-d30e3ecfc76a","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 12"},{"secao":"Saúde Coletiva e Bioética","numero":13,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"Considerando a legislação do Sistema Único de Saúde (SUS), a Portaria n.º 2.135/2013, acrescida do Decreto n.º 7.508/2011, que regulamenta a Lei n.º 8.080/1990, dispõe sobre (o)a I - organização do SUS. II - planejamento da saúde. III - assistência à saúde. IV - articulação interfederativa. Está(ão) CORRETO(S) o(s) item(ns)","alternativas":[{"letra":"A","texto":"I e II, apenas.","ordem":1,"idAlternativa":"1e9abd9e-6278-5c88-b977-4b6942720d46"},{"letra":"B","texto":"II, apenas.","ordem":2,"idAlternativa":"5e50eb01-4a7f-561d-aa73-caec678d5742"},{"letra":"C","texto":"II e III, apenas.","ordem":3,"idAlternativa":"7a72ec65-2dd0-53d9-8a7d-2274f0a9fbeb"},{"letra":"D","texto":"III e IV, apenas.","ordem":4,"idAlternativa":"fd1165b3-735e-5136-acdd-88c6bfc7acb7"},{"letra":"E","texto":"I, II, III e IV.","ordem":5,"idAlternativa":"a7d87824-6c0e-5b78-b6a3-4de5e5671040"}],"gabarito":"E","observacoes":[],"idQuestao":"257636f2-491d-5a74-8712-c22150b30e42","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 13"},{"secao":"Saúde Coletiva e Bioética","numero":14,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"O Cirurgião-Dentista (CD) pode trabalhar com diferentes tipos de profissionais auxiliares na Odontologia. De acordo com a lei em vigor, assinale abaixo o profissional que pode ter contato direto com o paciente, sob supervisão com a presença física do CD:","alternativas":[{"letra":"A","texto":"Técnico em Prótese Dentária.","ordem":1,"idAlternativa":"18f012e3-55c1-541f-a1b1-f89351f03fbb"},{"letra":"B","texto":"Auxiliar de Prótese Dentária.","ordem":2,"idAlternativa":"c58d985a-0629-566c-ac4c-ee2b12584ade"},{"letra":"C","texto":"Técnico em Saúde Bucal.","ordem":3,"idAlternativa":"4a809413-8aab-5403-9586-d926651977e2"},{"letra":"D","texto":"Técnico em Higiene Oral.","ordem":4,"idAlternativa":"ff781cec-a4da-5d72-aa3b-e45d88b6c6f6"}],"gabarito":"C","observacoes":[],"idQuestao":"2a92dde3-1b42-54a6-87c8-a63d10fa8980","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 14"},{"secao":"Saúde Coletiva e Bioética","numero":15,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"A condição de saúde bucal constitui fator de grande interferência na qualidade de vida dos indivíduos. Para criar condições favoráveis e melhorar os níveis de saúde bucal de uma população, é recomendável:","alternativas":[{"letra":"A","texto":"Tentar aplicar selantes em todas as crianças com os 1°s molares permanentes recém erupcionados.","ordem":1,"idAlternativa":"c9918732-d570-5003-b901-474d5a98a896"},{"letra":"B","texto":"Distribuir escovas e ensinar técnicas de escovação à comunidade.","ordem":2,"idAlternativa":"a6c3e177-d214-58c6-b954-4a190a33be11"},{"letra":"C","texto":"Realizar as melhores e mais atuais técnicas de reabilitação oral.","ordem":3,"idAlternativa":"51d29117-8872-548d-9200-63e227e64edb"},{"letra":"D","texto":"Enfatizar a promoção da saúde.","ordem":4,"idAlternativa":"d63a0f77-8e59-5981-b41f-abdf6b025c44"}],"gabarito":"D","observacoes":[],"idQuestao":"32ff6faf-c7f2-5150-a233-434df68fe875","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 15"},{"secao":"Saúde Coletiva e Bioética","numero":16,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"A promoção de saúde bucal foi estabelecida como uma efetiva estratégia visando a modificação do quadro de doenças bucais que atingem a população em nosso país. Dentre as alternativas abaixo, não podemos considerar como exemplo de ação de promoção de saúde bucal:","alternativas":[{"letra":"A","texto":"Produção de peças de teatro abordando os cuidados em saúde bucal.","ordem":1,"idAlternativa":"dc447430-832e-5e01-a698-598ab372305c"},{"letra":"B","texto":"Tratamento remineralizador em manchas brancas dentárias não cavitadas.","ordem":2,"idAlternativa":"0483715e-9f9b-5b6a-aa18-9cc98a3b7d7f"},{"letra":"C","texto":"Orientações e estímulos para a alimentação saudável.","ordem":3,"idAlternativa":"6e2aa5d8-545e-551c-8852-9b7d94caf1d7"},{"letra":"D","texto":"Políticas públicas antitabagistas.","ordem":4,"idAlternativa":"20ca5886-3b73-557a-a937-c68bc299999e"}],"gabarito":"B","observacoes":[],"idQuestao":"697b04df-2784-5f3d-84e9-7830d6cbcd5d","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 16"},{"secao":"Saúde Coletiva e Bioética","numero":17,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Qual alternativa, abaixo, não se caracteriza como uma diretriz do SUS, segundo a lei 8.080 da lei orgânica de saúde?","alternativas":[{"letra":"A","texto":"Universalidade de acesso aos serviços desaúde.","ordem":1,"idAlternativa":"81e73447-e2f2-5f07-a8ba-12487abee9c8"},{"letra":"B","texto":"Integralidade de assistência.","ordem":2,"idAlternativa":"16a9b559-223a-5976-af3f-5c81dd579673"},{"letra":"C","texto":"Preservação da autonomia das pessoas.","ordem":3,"idAlternativa":"f78bb543-08ad-5917-bf62-1fb781adf646"},{"letra":"D","texto":"Igualdade da assistência à saúde.","ordem":4,"idAlternativa":"5c195eb3-cbae-5716-af85-000fcf4a3e16"},{"letra":"E","texto":"Direito a desinformação.","ordem":5,"idAlternativa":"dc203fd7-a3c6-542b-96c2-b71d86dd42bb"}],"gabarito":"E","observacoes":[],"idQuestao":"e2a17578-340b-5724-b961-9c4bbf3e00f1","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 17"},{"secao":"Saúde Coletiva e Bioética","numero":18,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Segundo o artigo 196 da Constituição Federal, a saúde é direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e de outros agravos e ao acesso universal e igualitário às ações e serviços para sua promoção, proteção e recuperação. A qual princípio do SUS esse artigo relaciona-se?","alternativas":[{"letra":"A","texto":"Princípio da Universalidade.","ordem":1,"idAlternativa":"923c5d63-8ea5-5751-9d2d-7ec85884e164"},{"letra":"B","texto":"Princípio da Equidade.","ordem":2,"idAlternativa":"568aae4d-56ab-5d0e-8a71-af08bd249133"},{"letra":"C","texto":"Princípio da Integralidade.","ordem":3,"idAlternativa":"6b0fe492-f380-5984-84b4-6c4c65edf660"},{"letra":"D","texto":"Princípio da Amizade.","ordem":4,"idAlternativa":"be101a9e-a0a9-56ef-a6ea-95a9b464dd88"},{"letra":"E","texto":"Princípio da Assistência.","ordem":5,"idAlternativa":"227d5949-4007-531e-ae3d-d3f2426e2c37"}],"gabarito":"A","observacoes":[],"idQuestao":"e2a4e757-a445-51ee-aece-fcc17c6c15c2","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 18"},{"secao":"Saúde Coletiva e Bioética","numero":19,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"Sobre a Atenção Básica e as politicas relacionadas sobre o assunto, é correto afirmar:","alternativas":[{"letra":"A","texto":"A Atenção Básica é o conjunto de ações de saúde individuais, familiares e coletivas que envolvem promoção, prevenção, proteção, diagnóstico, tratamento, reabilitação, redução de danos, cuidados paliativos e vigilância em saúde.","ordem":1,"idAlternativa":"733b5c48-11af-5d12-9e2e-41f14d4cb3c2"},{"letra":"B","texto":"A Política Nacional de Atenção Básica considera os termos Atenção Básica - AB e Atenção Primária à Saúde - APS, nas atuais concepções, como termosdistintos.","ordem":2,"idAlternativa":"3dad4ecd-fe51-53d7-a016-e3df8aae40b5"},{"letra":"C","texto":"A Atenção Básica é considerada a porta secundária da rede de atenção à saúde (RAS), tendo em vista que as UPAs e emergências devem ser consideradas o acesso principal no SUS.","ordem":3,"idAlternativa":"435339fd-55ca-5da7-8392-04ae1c3a6958"},{"letra":"D","texto":"A Atenção Básica será ofertada integralmente e gratuitamente apenas às pessoas que recolhem contribuição tributária através do INSS, trabalhadores, aposentados e pensionistas.","ordem":4,"idAlternativa":"11beba01-15b0-5eec-8b2a-0293a7793bd6"},{"letra":"E","texto":"A Atenção Básica é o conjunto de ações de saúde coletivas que envolvem ações voltadas à promoção e prevenção, com vistas a reduzir a necessidade de encaminhamentos para o componente secundário e terciário de atenção à saúde.","ordem":5,"idAlternativa":"b50d1497-000d-5ec1-b3af-29bfe82b1fbd"}],"gabarito":"A","observacoes":[],"idQuestao":"7755f65c-b7a4-5491-b6e1-0d7509366e4a","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 19"},{"secao":"Saúde Coletiva e Bioética","numero":20,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"Assinale a alternativa correta sobre os aspectos que envolvem a promoção da saúde.","alternativas":[{"letra":"A","texto":"A promoção de saúde supõe uma concepção que identifica a saúde como sendo a ausência de doença, atuando diretamente em ações com enfoque no tratamento e reabilitação.","ordem":1,"idAlternativa":"5a693345-da26-55fb-b9c8-c9d84f6b273b"},{"letra":"B","texto":"Dentre os temas prioritários evidenciados pelas ações de promoção da saúde podese destacar o incentivo à cessação do tabagismo, alimentação saudável e controle das doenças crônicas como Diabetes e Hipertensão.","ordem":2,"idAlternativa":"ff0d292c-726f-59bf-9ad4-454d5c675f65"},{"letra":"C","texto":"A promoção do desenvolvimento sustentável não é tema priorizado pelas políticas de promoção da saúde, pois correlacionam saúde e meio ambiente, não tendo relação direta com as questões de saúde.","ordem":3,"idAlternativa":"66532892-3362-5876-93b7-607734ccc753"},{"letra":"D","texto":"As ações de promoção da saúde devem ter o foco na doença e no tratamento precoce, a fim de minimizar o incremento das taxas de doenças crônicas em nosso País.","ordem":4,"idAlternativa":"e65536fc-93bc-5640-9762-75d0d2d6564b"},{"letra":"E","texto":"A Política Nacional de Promoção da Saúde tem como objetivo geral promover a qualidade de vida e reduzir fragilidade e riscos à saúde relacionados aos seus determinantes – fatores sociais, condições de trabalho, habitação, ambiente, educação, lazer, cultura e serviços essenciais.","ordem":5,"idAlternativa":"8f7a580b-fb55-59ea-bfa6-dfe5d59553cc"}],"gabarito":"E","observacoes":[],"idQuestao":"dd05b737-d31b-587e-a1b7-d0185aa83efa","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 20"},{"secao":"Saúde Coletiva e Bioética","numero":21,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"São responsabilidades comuns a todas as esferas de governo no que se refere à organização da Atenção Básica no âmbito do SUS: 1. Apoiar e estimular a adoção da Estratégia Saúde da Família (ESF) como estratégia prioritária de expansão, consolidação e qualificação da Atenção Básica. 2. Estimular a gestão centralizada a participação popular e o controle social. 3. Articular com o subsistema indígena nas ações de Educação Permanente e gestão da rede assistencial. 4. Garantir, de forma bipartite, dispositivos para transporte em saúde, para realização de procedimentos e exames de urgência. Assinale a alternativa que indica todas as afirmativas corretas.","alternativas":[{"letra":"A","texto":"São corretas apenas as afirmativas 1 e2.","ordem":1,"idAlternativa":"8428cffa-cd46-597d-8e24-dc02caef9369"},{"letra":"B","texto":"São corretas apenas as afirmativas 1 e 3.","ordem":2,"idAlternativa":"97a62b58-f850-5dfd-b7d8-61e76a6d90b4"},{"letra":"C","texto":"São corretas apenas as afirmativas 1 e 4.","ordem":3,"idAlternativa":"3be45ea4-878e-54ac-881f-b3301be143f8"},{"letra":"D","texto":"São corretas apenas as afirmativas 2 e 3.","ordem":4,"idAlternativa":"268146b9-4c38-5931-842d-90dccc470615"},{"letra":"E","texto":"São corretas apenas as afirmativas 3 e 4.","ordem":5,"idAlternativa":"814f0603-9a76-5766-af6c-1f36872f6e7f"}],"gabarito":"B","observacoes":[],"idQuestao":"2c7899b5-3308-56ae-aed8-8562683a6b29","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 21"},{"secao":"Saúde Coletiva e Bioética","numero":22,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"Sobre educação, saúde e os conceitos correlacionados, é correto afirmar:","alternativas":[{"letra":"A","texto":"A Educação Permanente em Saúde (EPS) parte do pressuposto da aprendizagem significativa e problematizadora, propondo estratégias que possibilitam a construção coletiva.","ordem":1,"idAlternativa":"7eb95279-348e-5cf4-9889-045ed8f2e6c4"},{"letra":"B","texto":"Educação permanente e educação continuada na saúde são consideradas sinônimos pois ambas envolvem a formação profissional.","ordem":2,"idAlternativa":"0bff87ea-85e2-5aa6-841e-655ffb912eae"},{"letra":"C","texto":"A Educação continuada é compreendida como processo de transformação que desenvolve a consciência crítica das pessoas a respeito de seus problemas de saúde e estimula a busca de soluções coletivas para resolvê-los.","ordem":3,"idAlternativa":"975530ef-9628-5290-a28d-857042ab0ef1"},{"letra":"D","texto":"Educação em saúde constitui-se em práticas educativas voltadas à formação e aprimoramento profissional.","ordem":4,"idAlternativa":"4ca64bc4-1934-54d1-84cf-115ddfbb7bde"},{"letra":"E","texto":"A educação em saúde visa a mudança das estratégias de organização e do exercício da atenção, da gestão, da participação ou da formação, devendo considerar a necessidade de implementar um trabalho relevante, de qualidade e resolutividade.","ordem":5,"idAlternativa":"c43bf40f-17a7-5638-a5d6-d2090d0e699b"}],"gabarito":"A","observacoes":[],"idQuestao":"79a0f239-d7e8-5ea4-8842-958892fd9b34","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 22"},{"secao":"Saúde Coletiva e Bioética","numero":23,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"Sobre a Notificação Compulsória de doenças, agravos e eventos de saúde pública nos serviços de saúde públicos e privados em todo o território nacional, é correto afirmar:","alternativas":[{"letra":"A","texto":"A notificação compulsória é obrigatória para os médicos, sendo que os demais profissionais de saúde só poderão realizá-la na ausênciadestes.","ordem":1,"idAlternativa":"ed3b73d5-2c2c-5b83-b07f-964f2eaf475a"},{"letra":"B","texto":"A notificação compulsória é obrigatória à autoridade de saúde, realizada pelos médicos, profissionais de saúde ou responsáveis pelos estabelecimentos de saúde, públicos ou privados, sobre a ocorrência de suspeita ou confirmação de doença, agravo ou evento de saúde pública.","ordem":2,"idAlternativa":"357173d3-1a9d-5411-92fe-648c8ca6b134"},{"letra":"C","texto":"A notificação compulsória será realizada diante da suspeita ou confirmação de doença ou agravo, apenas nas instituições públicas de saúde, sendo facultativa a realização da notificação por hospitais e clínicasprivadas.","ordem":3,"idAlternativa":"b41c2671-a5e8-5448-a8f1-075ba05e4df5"},{"letra":"D","texto":"A notificação compulsória imediata deve ser realizada pelo profissional de saúde ou responsável pelo serviço assistencial que prestar o primeiro atendimento ao paciente, em até 7 dias desse atendimento, pelo meio mais rápido disponível.","ordem":4,"idAlternativa":"9ef53cd9-986d-5f2e-98f2-50e47c894e66"},{"letra":"E","texto":"São considerados agravos de notificação compulsória, devendo ser notificados em até 24 horas, a dengue, HIV/AIDS e as hepatites virais.","ordem":5,"idAlternativa":"87a0143f-c5a4-597b-8bce-f4d329cf5c4d"}],"gabarito":"B","observacoes":[],"idQuestao":"52c88840-1e7c-556d-bb30-5fbc606431c4","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 23"},{"secao":"Saúde Coletiva e Bioética","numero":24,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Considerando que o Capítulo VIII do Código de Ética Odontológico trata dos honorários profissionais, NÃO representa uma infração ética:","alternativas":[{"letra":"A","texto":"Instituir cobrança através deprocedimento mercantilista.","ordem":1,"idAlternativa":"d893805b-c7a9-5b93-b991-e5772f73664b"},{"letra":"B","texto":"Receber ou dar gratificação por encaminhamento de paciente.","ordem":2,"idAlternativa":"b5360499-d65a-5dc3-ba13-49f87fd9f6fc"},{"letra":"C","texto":"Oferecer serviços gratuitos a quem possa remunerá-los adequadamente.","ordem":3,"idAlternativa":"ead2b96b-a3dc-5d2a-a672-451c99504960"},{"letra":"D","texto":"Divulgar ou oferecer consultas e diagnósticos gratuitos ou sem compromisso.","ordem":4,"idAlternativa":"7fe13e51-e62f-5ba7-b49c-917fda37b5df"},{"letra":"E","texto":"Considerar o conceito do profissional e as condições socioeconômicas do paciente no cálculo dos honorários.","ordem":5,"idAlternativa":"0fddc9f1-f940-502b-8b1f-2b38d3ac7340"}],"gabarito":"A","observacoes":[],"idQuestao":"7d2d3e91-8840-50c0-854c-137d6e3c203d","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 24"},{"secao":"Saúde Coletiva e Bioética","numero":25,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"De acordo com o Código de Ética Odontológica, em seu Art. 51, “os preceitos deste Código são de observância obrigatória e sua violação sujeitará o infrator e quem, de qualquer modo, com ele concorrer para a infração, ainda que de forma indireta ou omissa, às penas previstas no Art. 18, da Lei nº 4.324/1964”. Diante do exposto, é correto afirmar que:","alternativas":[{"letra":"A","texto":"As penas devem ser aplicadas sempre emgradação.","ordem":1,"idAlternativa":"2153f426-ad47-568c-a2e7-7c3e3a17b46a"},{"letra":"B","texto":"Em caso de culpa concorrente da vítima a pena pode ser atenuada.","ordem":2,"idAlternativa":"cc5960b0-bfc2-5ae7-a751-1b064d22fd78"},{"letra":"C","texto":"Não há possibilidade de aplicar pena pecuniária ao profissional de odontologia.","ordem":3,"idAlternativa":"7c7340a3-cadc-52ba-a052-a0e72d120287"},{"letra":"D","texto":"Uma das penas previstas no Código de Ética Odontológica é a cassação do diploma do profissional de odontologia.","ordem":4,"idAlternativa":"3663f0bc-8250-54dc-a3d8-b6cf78e8a19d"},{"letra":"E","texto":"Uma das penas previstas no Código de Ética Odontológica é a suspensão do exercício profissional por até noventa dias.","ordem":5,"idAlternativa":"87d36096-cbd2-5050-b78e-5354b079ddbc"}],"gabarito":"B","observacoes":[],"idQuestao":"e08dde4c-ef6b-5ca1-bc15-f874ee4c90df","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 25"},{"secao":"Saúde Coletiva e Bioética","numero":26,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"O Art. 11 do Código de Ética Odontológica trata do relacionamento dos profissionais com o paciente. São consideradas infrações éticas, EXCETO:","alternativas":[{"letra":"A","texto":"Adotar novas técnicas ou materiais que tenham efetiva comprovação científica.","ordem":1,"idAlternativa":"4a3fc002-2af1-5622-8edd-757a7c025e02"},{"letra":"B","texto":"Delegar a profissionais técnicos ou auxiliares atos ou atribuições exclusivas da profissão de cirurgião-dentista.","ordem":2,"idAlternativa":"d3c42245-ffbc-5845-b043-0483f34cdc66"},{"letra":"C","texto":"Deixar de atender paciente que procure cuidados profissionais em caso de urgência, quando não haja outro cirurgião- -dentista em condições de fazê-lo.","ordem":3,"idAlternativa":"bcf9aedd-51ff-5df5-a629-54516ee44a40"},{"letra":"D","texto":"Opor-se a prestar esclarecimentos e/ou fornecer relatórios sobre diagnósticos e terapêuticas realizados no paciente quando solicitados pelo mesmo, por seu representante legal ou nas formas previstas em Lei.","ordem":4,"idAlternativa":"9dcf1255-a833-5e67-af8d-5d5e942f583f"},{"letra":"E","texto":"Abandonar paciente, salvo por motivo justificável, circunstância em que serão conciliados os honorários e que deverá ser informado ao paciente ou ao seu responsável legal de necessidade da continuidade do tratamento.","ordem":5,"idAlternativa":"0af57091-b82d-5d06-a9e3-8b773c26a9d4"}],"gabarito":"A","observacoes":[],"idQuestao":"bb155a03-700f-52dc-bcee-1fb4f2502bbb","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 26"},{"secao":"Saúde Coletiva e Bioética","numero":27,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Considerando que o Art. 3º do Código de Ética Odontológica denota sobre os objetivos da atenção odontológica, a finalidade de toda a atenção odontológica é a saúde do ser humano. “Caberá aos , como integrantes da equipe de saúde, dirigir ações que visem satisfazer as necessidades de saúde da população e da defesa dos princípios das políticas públicas de saúde e ambientais, que garantam a universalidade de acesso aos serviços de saúde, integralidade da assistência à saúde, preservação da autonomia dos indivíduos, participação da comunidade, hierarquização e político-administrativa dos serviços de saúde.” Assinale a alternativa que completa correta e sequencialmente a afirmativa anterior.","alternativas":[{"letra":"A","texto":"profissionais da odontologia / centralização","ordem":1,"idAlternativa":"97a01f68-53f6-529f-9aa5-0105c1b6547c"},{"letra":"B","texto":"profissionais da odontologia /descentralização","ordem":2,"idAlternativa":"99b96b0e-58f8-516a-b351-c64405fe89b5"},{"letra":"C","texto":"somente aos técnicos em saúde bucal / descentralização","ordem":3,"idAlternativa":"23029d3a-d1f7-5f17-a04a-90aa77a34d9a"},{"letra":"D","texto":"cirurgiões-dentistas única e exclusivamente / centralização","ordem":4,"idAlternativa":"b468af9c-6d0f-59d8-a200-415586b63641"},{"letra":"E","texto":"cirurgiões-dentistas única e exclusivamente / descentralização","ordem":5,"idAlternativa":"e423dee1-f456-572c-bc26-8fd17ce6c35d"}],"gabarito":"B","observacoes":[],"idQuestao":"d83da9f3-e7ad-5b64-a8b4-2a080f9ad9ff","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 27"},{"secao":"Saúde Coletiva e Bioética","numero":28,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"O Tratamento Restaurador Atraumático (TRA) alia conceitos visando diminuir o estresse do tratamento, permitindo, também, aumento de cobertura, diminuição de custos e aumento do custo-benefício para o paciente, os serviços e a sociedade. São consideradas características do Tratamento Restaurador Atraumático (TRA), EXCETO:","alternativas":[{"letra":"A","texto":"Nortear-se sempre pela mínimaintervenção.","ordem":1,"idAlternativa":"58e9a6e7-b306-5a5d-b54d-0dad577b4256"},{"letra":"B","texto":"Buscar a máxima preservação das estruturas dentárias.","ordem":2,"idAlternativa":"b1474481-7175-5fe1-81b8-22ea8026740e"},{"letra":"C","texto":"Usar instrumentos rotatórios para formatar a cavidade.","ordem":3,"idAlternativa":"57943354-edaf-5067-a0bd-659d839ba001"},{"letra":"D","texto":"Restaurar com cimento de iono ero de vidro de alta viscosidade.","ordem":4,"idAlternativa":"84694cb4-d009-50a4-9ecf-0984b78f2f92"},{"letra":"E","texto":"Selar fóssulas e fissuras adjacentes com o próprio material restaurador.","ordem":5,"idAlternativa":"5be332b4-4ad0-5915-8181-fd12fe472119"}],"gabarito":"D","observacoes":[],"idQuestao":"455cde68-c309-516d-bc2a-62e6b1f9a390","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 28"},{"secao":"Saúde Coletiva e Bioética","numero":29,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"O capítulo XVI do Código de Ética trata do anúncio, propaganda e publicidades em odontologia. NÃO é considerada infração ética:","alternativas":[{"letra":"A","texto":"Fazer publicidade e propaganda enganosa, abusiva, inclusive com expressões ou imagens de antes e depois, com preços, serviços gratuitos, modalidades de pagamento.","ordem":1,"idAlternativa":"d3892a3d-21c3-5786-9902-e04a5ac7bbdb"},{"letra":"B","texto":"Oferecer trabalho gratuito com intenção de autopromoção ou promover campanhas em troca de favores.","ordem":2,"idAlternativa":"5d370389-d534-5536-b5bb-06b2d60a1774"},{"letra":"C","texto":"Anunciar serviços profissionais como prêmio em concurso de qualquer naturezaou através de aquisição de outros bens pela utilização de serviços prestados.","ordem":3,"idAlternativa":"cf872e47-2868-5f7a-9968-ef6125d0acaf"},{"letra":"D","texto":"Criticar técnicas utilizadas por outros profissionais como sendo inadequadas ou ultrapassadas.","ordem":4,"idAlternativa":"04005bbe-a335-54ae-aa96-3b09c67d68d6"},{"letra":"E","texto":"Anunciar mais de duas especialidades registradas no Conselho.","ordem":5,"idAlternativa":"c8a78f59-3382-51d9-ae0b-9936e25803a5"}],"gabarito":"D","observacoes":[],"idQuestao":"33757923-2b8a-54da-8244-a530d2750842","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 29"},{"secao":"Saúde Coletiva e Bioética","numero":30,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Em 29 de janeiro de 2019, o Conselho Federal de Odontologia (CFO) editou e publicou a resolução 196/2019. Essa resolução traz em seu título o assunto: “Autoriza a divulgação de autorretratos (selfie) e de imagens relativas ao diagnóstico e ao resultado final de tratamentos odontolo ́gicos, e dá outras providências”. Sobre o assunto, marque V para as afirmativas verdadeiras e F para as falsas. ( ) Fica autorizada a divulgação de autorretratos (selfies) de cirurgiões-dentistas, acompanhados de pacientes ou não, desde que com autorização prévia do paciente ou de seu representante legal, através de Termo de Consentimento Livre e Esclarecido. ( ) Fica autorizada a divulgação de antes, durante e depois dos procedimentos realizados. ( ) É permitido utilizar imagens ou vídeos de cursos nas redes sociais (bastidores, ambiente clínico, procedimentos, tratamentos). ( ) Em todas as publicações de imagens e/ou vídeos, deverão constar o nome do profissional e o seu número de inscrição, sendo vedada a divulgação de casos clínicos de autoria de terceiros. Assinale a sequência correta.","alternativas":[{"letra":"A","texto":"V, F, F, V","ordem":1,"idAlternativa":"536c3189-fae7-5954-b2ab-99a0fa113c9e"},{"letra":"B","texto":"V, V, V, V","ordem":2,"idAlternativa":"b04eb698-e4c0-5b84-95b4-68d599d3889e"},{"letra":"C","texto":"F, F, F, F","ordem":3,"idAlternativa":"994989bc-85a9-5107-87d2-21bd94cd2b34"},{"letra":"D","texto":"F, V, V, F","ordem":4,"idAlternativa":"4ff07986-6353-5858-b55c-89b359dbf274"},{"letra":"E","texto":"V, V, F, F","ordem":5,"idAlternativa":"4f4ab6e1-43e8-5396-ad4c-4da0cd54ff1e"}],"gabarito":"C","observacoes":[],"idQuestao":"b8706bb5-4d78-5413-8eb7-ced90d6ce0c5","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 30"},{"secao":"Saúde Coletiva e Bioética","numero":31,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Paciente adulta jovem buscou UBS apresentando lesões nos lábios, fratura da coroa do dente 21 com exposição pulpar, escoriações, arranhões e edemas nos membros superiores e inferiores. Sobre a conduta correta que o cirurgião-dentista deve desempenhar, analise as afirmativas. I- Realizar imediatamente a restauração do dente21. II- Realizar exames físicos intra e extrabucais e radiográfico. III- Indagar sobre a história do trauma, buscando elementos que possam caracterizar sua causa. IV- Indicar que a paciente procure a assistente social da unidade, caso suspeite de violência doméstica. Está correto o que se afirma em:","alternativas":[{"letra":"A","texto":"I e IV, apenas.","ordem":1,"idAlternativa":"846b4f0b-4272-58d5-a04a-0e59887c4fd4"},{"letra":"B","texto":"II e III, apenas.","ordem":2,"idAlternativa":"87b1b95c-5fc7-5e32-8d01-5831a5dc5663"},{"letra":"C","texto":"I e II, apenas.","ordem":3,"idAlternativa":"21e53624-8c45-5387-bb08-c3768197eb4a"},{"letra":"D","texto":"I, III e IV, apenas.","ordem":4,"idAlternativa":"677d3cff-cb03-5ff3-bb26-44af30bfa5b8"},{"letra":"E","texto":"II, III e IV, apenas.","ordem":5,"idAlternativa":"7b6eb663-b913-5dff-b60e-4d03a811d6ef"}],"gabarito":"E","observacoes":[],"idQuestao":"6fe2286b-bd83-5437-9b5c-b735463825e2","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 31"},{"secao":"Saúde Coletiva e Bioética","numero":32,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"A Agência Nacional de Saúde Suplementar (ANS) é a agência reguladora vincu- lada ao Ministério da Saúde, responsável pelo setor de planos de saúde no Brasil. Ela foi instituída a partir da Lei nº 9.656, de junho de 1998, e nasceu pela Lei nº 9.961, de 28 de janeiro de 2000. Compete à ANS: I. Normatizar os conceitos de doença e lesão preexistentes. II. Autorizar o registro dos planos privados de assistência à saúde. III. Autorizar reajustes e revisões das contraprestações pecuniárias dos planos privados de assistência à saúde. IV. Definir preços e reajustes de planos de assistência à saúde. É CORRETO se afirma em:","alternativas":[{"letra":"A","texto":"I, II e III, apenas.","ordem":1,"idAlternativa":"6eff7848-e3e9-55fc-9431-c68b8dab7925"},{"letra":"B","texto":"I, II e IV, apenas.","ordem":2,"idAlternativa":"45795b31-3a5a-53a3-aa11-722d00eec8c0"},{"letra":"C","texto":"II e III, apenas.","ordem":3,"idAlternativa":"70bf8dc5-011e-5117-9445-0dd7860720ff"},{"letra":"D","texto":"II, III e IV, apenas","ordem":4,"idAlternativa":"644161f9-d246-548f-87a5-893c45521fe6"},{"letra":"E","texto":"I, II, III e IV.","ordem":5,"idAlternativa":"18c01020-56e2-57d0-8e2d-5055a00f1542"}],"gabarito":"A","observacoes":[],"idQuestao":"f7502f49-6db7-54b1-b455-d6cef0a523a7","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 32"},{"secao":"Saúde Coletiva e Bioética","numero":33,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"O código de ética odontológica serve como um referencial normativo que deve ser seguido por cirurgiões-dentistas, profissionais técnicos e auxiliares, além de enti- dades e operadoras de planos de saúde, para a boa execução do serviço odonto- lógico, além de garantir direitos e deveres para os profissionais e pacientes. Com relação ao Código de Ética Odontológico, é CORRETO afirmar:","alternativas":[{"letra":"A","texto":"Após o término de curso de especialização, o cirurgião-dentista poderá intitular-se especialista quando o Certificado da especialidade for efetivado junto ao MEC.","ordem":1,"idAlternativa":"b2943f1c-5721-5c5a-adcf-caf73f923d5b"},{"letra":"B","texto":"Constitui infração ética deixar de atuar com absoluta isenção quando designado para servir como perito ou auditor, assim como ultrapassar os limites de suas atribuições e de sua competência.","ordem":2,"idAlternativa":"905b4f60-727e-5d73-8515-ae6c690145ce"},{"letra":"C","texto":"É permitido ao Cirurgião Dentista adotar novas técnicas ou materiais, ainda que não tenham efetiva comprovação científica.","ordem":3,"idAlternativa":"600b35c6-fbc2-501e-8150-7307c3658eda"},{"letra":"D","texto":"Embora constitua infração ética discriminar o ser humano de qualquer forma ou sob qualquer pretexto, em casos de urgência, mesmo que não haja outro cirurgião dentista em condições de atender, um profissional tem o direito de se recusar a fazêlo se não tiver disponibilidade para realizar o atendimento.","ordem":4,"idAlternativa":"6cd16cd8-c46b-5a70-92a1-14d2667ee0de"},{"letra":"E","texto":"O Cirurgião Dentista poderá realizar ou exigir procedimentos aos pacientes e ao profissional, contrários às normas de vigilância sanitária, exclusivamente, para fins de auditoria ou perícia.","ordem":5,"idAlternativa":"3612af84-d366-5174-a30f-5def06b59a88"}],"gabarito":"B","observacoes":[],"idQuestao":"e0ea1b79-43ed-577a-8d94-3207f7242571","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 33"},{"secao":"Saúde Coletiva e Bioética","numero":34,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2004,"enunciado":"A Resolução nº 196, de 10 de outubro de 1996, do Conselho Nacional de Saúde, fundamenta-se nos principais documentos internacionais que emanaram das declarações e diretrizes sobre pesquisas em humanos. Dentre os aspectos éticos da investigação científica envolvendo seres humanos, ressalta-se o consentimento livre e esclarecido, que inclui: I - informação sobre os procedimentos que serão utilizados na pesquisa; II - aviso a respeito dos desconfortos e riscos possíveis; III - conhecimento dos métodos alternativos existentes; IV - garantia do sigilo dos dados confidenciais; V - obrigatoriedade de o pesquisado se manter na pesquisa até o término da mesma. Estão corretos apenas os itens","alternativas":[{"letra":"A","texto":"I, II e IV.","ordem":1,"idAlternativa":"1bf7aa09-cc4f-5449-ba89-af65df5e99ca"},{"letra":"B","texto":"I, IV e V.","ordem":2,"idAlternativa":"bd26ef26-b63b-5bd6-b742-fae8d9dfc27d"},{"letra":"C","texto":"II, III e V.","ordem":3,"idAlternativa":"2e79afce-bbe2-5425-8a2e-af7ca83c99db"},{"letra":"D","texto":"I, II, III e IV.","ordem":4,"idAlternativa":"575dd175-454d-58fa-9f43-aff68d6d7417"},{"letra":"E","texto":"II, III, IV e V.","ordem":5,"idAlternativa":"6204ea9d-6750-5f21-8f3f-68eca1f9d001"}],"gabarito":"D","observacoes":[],"idQuestao":"8a01b181-a38c-5a70-9cf7-a973b8c34e3e","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"e04b197f-8e81-5c4e-b24b-67cb6765b709","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 34"},{"secao":"Saúde Coletiva e Bioética","numero":35,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2004,"enunciado":"Na figura abaixo são observados dados obtidos no mais recente levantamento epidemiológico realizado na população brasileira - Projeto SB Brasil 2003. São mostradas as médias do índice CPO-D e as proporções de crianças aos 12 anos, nas várias situações (dentes perdidos, obturados, obturados/cariados e cariados), de acordo com a região do Brasil. Com base nos dados apresentados, e considerando as condições socioeconômicas das regiões geográficas, é correto afirmar que","alternativas":[{"letra":"A","texto":"as médias de cárie dentária se distribuem igualmente nas crianças aos 12 anos de idade, independentemente da região.","ordem":1,"idAlternativa":"d410e7b4-a9b9-52aa-8a28-6e126afee0f9"},{"letra":"B","texto":"as diferenças observadas nas crianças podem ser decorrentes do modelo de atenção à saúde adotado em cada área geográfica.","ordem":2,"idAlternativa":"c46ceaba-8f11-516a-8937-0dcde02b314d"},{"letra":"C","texto":"as Regiões Sudeste e Sul têm médias mais altas de dentes cariados e perdidos quando comparadas com as outras regiões brasileiras.","ordem":3,"idAlternativa":"7b5d8f58-8f97-5ad1-bad8-af7cdf3266c6"},{"letra":"D","texto":"a análise da situação das crianças mostra pouca relação do índice CPO-D comos determinantes sociais das doenças bucais.","ordem":4,"idAlternativa":"050caca5-0c81-5aae-b127-757d338b8bda"},{"letra":"E","texto":"a influência das desigualdades sociais nas médias de cáries medidas pelo índice CPO-D é mais evidente na Região Centro-Oeste.","ordem":5,"idAlternativa":"a2e473f2-4df9-5fdc-8b16-8af87ae600e0"}],"gabarito":"B","observacoes":["Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."],"idQuestao":"aa2b33e9-ad42-5a68-8098-c1abeedb72c2","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"e04b197f-8e81-5c4e-b24b-67cb6765b709","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"rascunho","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 35 | Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."},{"secao":"Saúde Coletiva e Bioética","numero":36,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2004,"enunciado":"Uma equipe de alunos de uma Faculdade de Odontologia realizou uma pesquisa sobre a incidência de cárie dental em alunos de escolas públicas e privadas. Esse método de investigação epidemiológica não-experimental se caracteriza por","alternativas":[{"letra":"A","texto":"realizar “estudos de intervenção”.","ordem":1,"idAlternativa":"bae5e45d-86ec-5f65-b54b-6bb28125b4c5"},{"letra":"B","texto":"pesquisar situações que ocorremnaturalmente.","ordem":2,"idAlternativa":"aaa47d53-997f-52dd-8271-af85175d6c26"},{"letra":"C","texto":"possibilitar neutralizar as variáveis extrínsecas.","ordem":3,"idAlternativa":"baba620c-a57a-517b-9aa3-6d1a5e501950"},{"letra":"D","texto":"investigar em profundidade a associação entre dois eventos.","ordem":4,"idAlternativa":"e79a43c0-988d-5e6b-8ec5-e99380dbcbd8"},{"letra":"E","texto":"levantar dados para diminuir a incidência decárie.","ordem":5,"idAlternativa":"359cc1c0-0041-5abd-8ba7-f619ccf624f6"}],"gabarito":"B","observacoes":[],"idQuestao":"c4e7a0ec-7f74-5847-b7fb-8ea2a3426134","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"e04b197f-8e81-5c4e-b24b-67cb6765b709","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 36"},{"secao":"Saúde Coletiva e Bioética","numero":37,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2004,"enunciado":"A violência doméstica e o abandono de crianças são problemas atuais na sociedade brasileira, atingindo proporções que podem ser consideradas alarmantes. A promulgação do Estatuto da Criança e do Adolescente estabelece novas responsabilidades para os profissionais que lidam com crianças e adolescentes. Constitui responsabilidade do cirurgião-dentista, prevista no Estatuto da Criança e do Adolescente, diante de casos de suspeita ou confirmação de maustratos contra estes indivíduos,","alternativas":[{"letra":"A","texto":"conversar com os pais, orientando-os a resguardar os direitos e liberdades das crianças e adolescentes.","ordem":1,"idAlternativa":"4fcf52b4-c3be-59a6-9361-b913d973a5ed"},{"letra":"B","texto":"comunicar obrigatoriamente o fato ao Conselho Tutelar da respectiva localidade, sem prejuízo de outras providências legais.","ordem":2,"idAlternativa":"e35d7d46-e4f0-5b46-9ace-a14a64d854f6"},{"letra":"C","texto":"comunicar à autoridade competente, caso considere conveniente, os casos de quetenha conhecimento.","ordem":3,"idAlternativa":"085337f1-17fd-5951-907e-759dd4c21409"},{"letra":"D","texto":"guardar sigilo, por motivos éticos.","ordem":4,"idAlternativa":"1028bcd3-d669-5cde-a182-e325de57c1b3"},{"letra":"E","texto":"dar voz de prisão imediata ao agressor, para que possa ser efetuada a detenção.","ordem":5,"idAlternativa":"543e1c74-b91b-5bde-9c7a-71b66c7997bf"}],"gabarito":"B","observacoes":[],"idQuestao":"b5eb3486-8952-5215-9f36-fe42389e0825","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"e04b197f-8e81-5c4e-b24b-67cb6765b709","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 37"},{"secao":"Saúde Coletiva e Bioética","numero":38,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2007,"enunciado":"As necessidades básicas sociais, psicológicas e educacionais das crianças portadoras de necessidades especiais são idênticas às de todas as crianças e podem ser satisfeitas praticamente da mesma maneira. Pacientes com limitações motoras, com deficiência visual, com deficiência auditiva ou de fala, diabéticos, cardiopatas, HIV positivos, pacientes com disfunção renal, defeitos congênitos ambientais ou transplantados, sem outras limitações, deverão ser atendidos nas unidades básicas de saúde. Qual conduta determina o atendimento a essas crianças com necessidades especiais, dentro dos princípios bioéticos?","alternativas":[{"letra":"A","texto":"Elaborar novos paradigmas de promoção de saúde, para controle da cárie e da doença periodontal nesse tipo de paciente.","ordem":1,"idAlternativa":"b199f04d-086c-5bd5-a690-93438327f1a0"},{"letra":"B","texto":"Prover a unidade de atendimento de equipamentos para sedação com óxido nitroso.","ordem":2,"idAlternativa":"2ad4047d-9985-5add-a817-588b64ba750f"},{"letra":"C","texto":"Disponibilizar atendimento multidisciplinar, com pessoal que possua conhecimento técnico e científico e formação humanística.","ordem":3,"idAlternativa":"8587b8fa-82ad-5abd-9240-254b66bea5fe"},{"letra":"D","texto":"Disponibilizar atendimento às urgências, para eliminação da dor, e tratamento restaurador atraumático.","ordem":4,"idAlternativa":"91d3db3a-9afe-5043-8379-cc100d8af0ec"},{"letra":"E","texto":"Submeter esses pacientes a tratamentos não invasivos, tendo em vista as suas características de saúde.","ordem":5,"idAlternativa":"877ce7f0-33d6-5402-8fe8-837a9630fd42"}],"gabarito":"C","observacoes":[],"idQuestao":"c07795f1-fac1-5700-8382-600bfdecfa0d","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"04d40d7d-9cf1-54bf-bf15-91cbef2199af","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 38"},{"secao":"Saúde Coletiva e Bioética","numero":39,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2007,"enunciado":"As condições de trabalho são de importância significativa para as estruturas bucais, sendo possível ocorrer patologias decorrentes de exposições de natureza ocupacional. É de especial interesse para a Odontologia o estudo sobre a exposição a névoas ácidas, não só pela gravidade e diversidade dos efeitos potenciais, mas também pela sua presença freqüente em inúmeros processos industriais, incluindo a extração, fabricação e acabamento de metais, a produção de fertilizantes e de detergentes, a manufatura de baterias, bem como em vários segmentos das indústrias química e petroquímica. Observe os resultados de estudos sobre os efeitos bucais em conseqüência de exposições ocupacionais a névoas ácidas, apresentados a seguir. Medida de intensidade da exposição: empresas galvânicas com características distintas quanto à adoção de medidas de proteção individuais e coletivas para névoas ácidas. RP = Razão de prevalência Resultados do Teste do x2 de tendência: *p 0,001; **p 0,0001; ***p 0,05 IC = Intervalo de confiança ARAÚJO, M. E., 1998 in VIANNA, M. I. P. e SANTANA, S. S. Exposição ocupacional a névoas ácidas e alterações bucais: uma revisão. Rio de Janeiro, Cad. Saúde Pública, v.17, n.6, p.1335-1344, nov-dez, 2001 (adaptado). Em relação aos dados apresentados acima, e considerando a etiologia das doenças bucais, analise as afirmativas a seguir. I – A erosão dentária (perda mineral de origem não bacteriana) não está associada à exposição a névoas ácidas. II – Exposição a ácidos se associa positivamente com alterações da mucosa bucal, em conseqüência da sua ação irritante sobre os tecidos. III – Existe associação positiva entre a exposição a névoas ácidas e os sintomas ardor e gosto metálico. IV – Alguns problemas de saúde bucal podem ser causados por fatores ocupacionais. Estão corretas as afirmativas","alternativas":[{"letra":"A","texto":"I e IV, apenas.","ordem":1,"idAlternativa":"684e7d8e-051b-55ac-a87d-5a24f382d991"},{"letra":"B","texto":"I , II e III, apenas.","ordem":2,"idAlternativa":"0b26efff-cb71-5874-a839-67beb6f6e8f8"},{"letra":"C","texto":"I, II e IV, apenas.","ordem":3,"idAlternativa":"529e0f54-5738-521d-9412-9e64b7031977"},{"letra":"D","texto":"II, III e IV, apenas.","ordem":4,"idAlternativa":"a73a8d85-c7ec-5deb-987a-d763b83f80a8"},{"letra":"E","texto":"I, II, III e IV.","ordem":5,"idAlternativa":"fc955fe9-52fc-5442-ae5c-361d0b5995c5"}],"gabarito":"D","observacoes":["Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."],"idQuestao":"0ca0f600-9df5-515d-b26b-ee89b927724a","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"04d40d7d-9cf1-54bf-bf15-91cbef2199af","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"rascunho","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 39 | Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."},{"secao":"Saúde Coletiva e Bioética","numero":40,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2007,"enunciado":"Quanto à ocorrência de anormalidades dentofaciais, os dados obtidos no levantamento epidemiológico realizado na população brasileira – Projeto SB Brasil 2003 – mostraram: prevalência de 14,5% de problemas oclusais moderados ou severos na idade de 5 anos e prevalência de 21% da condição oclusal muito severa ou incapacitante nas crianças de 12 anos. Com base no exposto e considerando os possíveis fatores etiológicos das más-oclusões, a 17 abordagem coletiva das anormalidades dentofaciais, mediante ações de promoção à saúde na atenção básica, deve incluir as seguintes medidas: I – atenção e identificação dos principais fatores de risco, salientando-se que as más-oclusões não são afetadas diretamente pela condição socioeconômica; II – identificação dos indivíduos ou comunidades com más-oclusões severas ou incapacitantes, por meio de ações epidemiológicas periódicas; III – aconselhamento e acompanhamento de gestantes a respeito dos cuidados durante o parto e período puerperal, estimulando a amamentação no peito por período mínimo de6 meses; IV – prevenção da cárie dentária, já que a perda precoce de dentes decíduos é um dos principais fatores etiológicos das más-oclusões. Estão corretas as medidas","alternativas":[{"letra":"A","texto":"I e III, apenas.","ordem":1,"idAlternativa":"7059d8f5-f708-578c-b9c0-24af51971dc1"},{"letra":"B","texto":"I, II e III, apenas.","ordem":2,"idAlternativa":"d40f1271-ee7f-55eb-a6f6-1dc50fcbe32d"},{"letra":"C","texto":"I, III e IV, apenas.","ordem":3,"idAlternativa":"fefdb703-d914-5a8d-9d23-5b82cb11b69c"},{"letra":"D","texto":"II, III e IV, apenas.","ordem":4,"idAlternativa":"3e460022-9dfc-5b09-9320-149608bc61ce"},{"letra":"E","texto":"I, II, III e IV.","ordem":5,"idAlternativa":"55952d3d-a7e9-51c8-880c-001d155719d8"}],"gabarito":"D","observacoes":[],"idQuestao":"94f98e88-14ec-51f9-b156-19f074773575","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"04d40d7d-9cf1-54bf-bf15-91cbef2199af","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 40"},{"secao":"Saúde Coletiva e Bioética","numero":41,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2007,"enunciado":"No quadro abaixo é feita uma comparação entre as metas propostas pela Organização Mundial de Saúde (OMS)/Federação Dentária Internacional (FDI) para o ano 2000 com relação à cárie dentária e os resultados do mais recente levantamento epidemiológico realizado na população brasileira – Projeto SB Brasil 2003. Com base nos dados apresentados, qual a conclusão correta?","alternativas":[{"letra":"A","texto":"A cárie dentária se distribui igualmente na população, independente da macrorregião considerada e da idade dos indivíduos.","ordem":1,"idAlternativa":"90219a25-c1f6-5ed6-ae8c-4efa0bd23091"},{"letra":"B","texto":"A situação de saúde bucal da população brasileira, em relação à cárie, se encontra satisfatória, tendo o Brasil atingido grande parte das metas da OMS para o ano2000.","ordem":2,"idAlternativa":"8b863b63-0954-54e9-a0f3-622333599253"},{"letra":"C","texto":"Aproximadamente 40% das crianças brasileiras de 5 anos de idade apresentam, pelo menos, um dente decíduo com experiência de cárie.","ordem":3,"idAlternativa":"6e822c7d-4371-52dd-ab82-ec48cee2f00e"},{"letra":"D","texto":"Na população adulta há um aumento do componente “perdido”, sendo este fenômeno observado nas diferentes macrorregiões.","ordem":4,"idAlternativa":"cb39636a-a459-5f20-b632-dcf3accff730"},{"letra":"E","texto":"As perdas dentárias são progressivas e precoces, embora a necessidade de algum tipo de prótese comece a surgir a partir dos 35 anos de idade.","ordem":5,"idAlternativa":"9cd76a23-9745-5321-9a2b-ef0b99a9536d"}],"gabarito":"D","observacoes":["Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."],"idQuestao":"aa6fb2ab-4473-5ed4-8655-585f5998978a","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"04d40d7d-9cf1-54bf-bf15-91cbef2199af","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"rascunho","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 41 | Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."},{"secao":"Saúde Coletiva e Bioética","numero":42,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2007,"enunciado":"A estratégia Saúde da Família visa à reorganização da Atenção Básica no País, de acordo com os preceitos do Sistema Único de Saúde. Considere as afirmações a seguir, sobre a organização da saúde bucal na atenção básica. I – É necessário conhecer o perfil da distribuição das principais doenças bucais, monitorar riscos e tendências e avaliar o impacto das medidas adotadas. II – Um dos principais indicadores de saúde bucal, no pacto da atenção básica, é a proporção de procedimentos odontológicos especializados em relação às ações odontológicas individuais. III – O atendimento das urgências e pequenas cirurgias ambulatoriais é uma das competências do cirurgião-dentista que atua na atenção básica por meio da estratégia Saúde da Família. IV – As ações intersetoriais, por envolverem estabelecimento de parcerias com setores eatores fora da área da saúde, não integram a prática da equipe de saúdebucal. Estão corretas as afirmativas","alternativas":[{"letra":"A","texto":"I e II, apenas.","ordem":1,"idAlternativa":"fa543e73-33f1-5c47-b3d7-a7f6c69a13c5"},{"letra":"B","texto":"I e III, apenas.","ordem":2,"idAlternativa":"ead2cfda-1c1f-5802-8184-19f0b1d564c5"},{"letra":"C","texto":"I, II e III, apenas.","ordem":3,"idAlternativa":"f03edc2e-4dec-5dbf-befc-fa81f2efd5af"},{"letra":"D","texto":"I, II e IV, apenas.","ordem":4,"idAlternativa":"de39e495-60a0-50df-8323-4c8375342859"},{"letra":"E","texto":"I, II, III e IV.","ordem":5,"idAlternativa":"95ac47c5-4c34-5d26-b6da-efe5b5d89710"}],"gabarito":"B","observacoes":[],"idQuestao":"495b0241-18e5-54f7-bb23-fdaa2402f420","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"04d40d7d-9cf1-54bf-bf15-91cbef2199af","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 42"},{"secao":"Saúde Coletiva e Bioética","numero":43,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2007,"enunciado":"O Código de Ética Odontológica regula os direitos e deveres dos profissionais, das entidades e das operadoras de planos de saúde. Considere os seguintes deveres: I – promover a saúde coletiva no desempenho de suas funções, cargos e cidadania, independente de exercer a profissão no setor público ou privado; II – garantir ao paciente ou ao seu responsável legal, acesso ao seu prontuário; III – zelar pela saúde e pela dignidade do paciente; IV – manter atualizados os conhecimentos profissionais, técnico-científicos e culturais necessários ao pleno desempenho do exercício profissional. Segundo a regulamentação citada, são deveres fundamentais dos profissionais que atuam em Odontologia:","alternativas":[{"letra":"A","texto":"III e IV, apenas.","ordem":1,"idAlternativa":"4bb81d9f-a024-539c-848f-90ff9a7b9ae2"},{"letra":"B","texto":"I, II e III, apenas.","ordem":2,"idAlternativa":"ca153222-0b9e-5f12-a113-912a4a632702"},{"letra":"C","texto":"I, III e IV, apenas.","ordem":3,"idAlternativa":"181287fa-6249-5b51-9338-a00d2b4dc9f4"},{"letra":"D","texto":"II, III e IV, apenas.","ordem":4,"idAlternativa":"737f7b15-a880-52b0-a411-ccaa0c3410c7"},{"letra":"E","texto":"I, II, III e IV.","ordem":5,"idAlternativa":"d57fa45f-8f43-5c3d-aedb-55cb31901150"}],"gabarito":"E","observacoes":[],"idQuestao":"3fa83fca-1315-5ff7-8ef7-601bb77afab8","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"04d40d7d-9cf1-54bf-bf15-91cbef2199af","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 43"},{"secao":"Saúde Coletiva e Bioética","numero":44,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2007,"enunciado":"“Em meio à atribulada rotina clínica a que são submetidos os cirurgiões-dentistas, a manutenção de toda a documentação referente ao atendimento executado nos pacientes reveste-se de aspectos éticos e legais cujo conhecimento é obrigatório.” Sendo a documentação clínica uma das medidas mais efetivas para resguardar o profissional contra reclamações que podem ser infundadas, qual a medida profissional a ser adotada?","alternativas":[{"letra":"A","texto":"Guardar a documentação clínica por toda a vida do profissional ou do paciente.","ordem":1,"idAlternativa":"bc3eed91-87c6-572e-9b3b-3024a659f04f"},{"letra":"B","texto":"Descartar a documentação clínica em caso de abandono detratamento.","ordem":2,"idAlternativa":"8e45dbc7-cdb6-52a1-a98a-0b8436ff265c"},{"letra":"C","texto":"Arquivar a documentação clínica, no consultório ou clínica odontológica, não tendo o paciente direito de pleiteá-la.","ordem":3,"idAlternativa":"bf47b484-a447-5cea-9b01-4df73413d70b"},{"letra":"D","texto":"Considerar que a legislação vigente aceita o prontuário digital como substituto da documentação manuscrita.","ordem":4,"idAlternativa":"3f6bd930-9690-5e6a-bee0-e9d47d4c0586"},{"letra":"E","texto":"Deixar com o paciente as radiografias, eximindo o profissional de mais essa responsabilidade.","ordem":5,"idAlternativa":"2377ad72-6b60-5f5e-ba0b-4779db7da6c3"}],"gabarito":"A","observacoes":[],"idQuestao":"6ccaab1c-c776-5caa-89bf-a7a224a5a237","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"04d40d7d-9cf1-54bf-bf15-91cbef2199af","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 44"},{"secao":"Saúde Coletiva e Bioética","numero":45,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2013,"enunciado":"Segundo o estudo epidemiológico SB Brasil 2010, mais de 3 milhões de idosos entre 65 e 74 anos de idade necessitam de prótese total nas duas arcadas dentárias, e 4 milhões de idosos precisam usar prótese total em uma das arcadas. O gráfico mostra a necessidade de prótese total em idosos, no período de 2003 a 2010. Os laboratórios regionais de prótese produzem anualmente cerca de 480 mil próteses. Com relação à organização de serviços de saúde bucal, avalie as afirmativas a seguir. I. A precariedade das condições de saúde bucal dos idosos requer políticas de saúde que garantam informações sobre saúde bucal, acesso a serviços preventivos e curativos, bem como reabilitadores. II. Apesar do panorama de demandas odontológicas de idosos acumuladas, o tratamento restaurador destinado a crianças deve ser prioritário, tendo em vista a necessidade de reduzir o índice CPOD em escolares. III. O aumento de recursos destinados à atenção terciária, com maior investimento em laboratórios de prótese dentária, visa atender às necessidades acumuladas de reabilitação oral. IV. É necessário reverter um modelo assistencial centrado em práticas curativas e mutiladoras, o que resultou em quadro de elevado edentulismo em idosos brasileiros. V. O menor uso de serviços odontológicos entre os idosos que necessitavam de prótese em uma arcada dentária resulta da necessidade de próteses inferiores, pouco aceitas pelos pacientes idosos devido às dificuldades de adaptação. É correto apenas o que se afirma em","alternativas":[{"letra":"A","texto":"I e II.","ordem":1,"idAlternativa":"b83f3246-0eda-5b31-9084-73954d082b9d"},{"letra":"B","texto":"I e IV.","ordem":2,"idAlternativa":"c7017421-7083-5c73-88b2-d66845fd1d52"},{"letra":"C","texto":"II e III.","ordem":3,"idAlternativa":"60244ba4-40c1-5313-a869-c6011926fb49"},{"letra":"D","texto":"III e V.","ordem":4,"idAlternativa":"406472f6-6bbd-5f79-8439-d14e518553af"},{"letra":"E","texto":"IV e V.","ordem":5,"idAlternativa":"410aa7e5-0fa1-513c-8fff-83f7afcaece0"}],"gabarito":"B","observacoes":["Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."],"idQuestao":"4348bdf6-b765-5c18-aeef-a1322ac16809","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"12f45a66-d8ea-526e-8512-0c33aef45882","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"rascunho","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 45 | Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."},{"secao":"Saúde Coletiva e Bioética","numero":46,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2013,"enunciado":"Um cirurgião-dentista vinculado ao programa odontológico de uma escola da rede pública, ao realizar o atendimento de rotina em uma criança, que já era sua paciente há algum tempo, percebeu alterações de comportamento e alguns hematomas nos braços e ao redor dos olhos. Questionada sobre a causa dos hematomas, a criança manifestou contradições inúmeras vezes. Em conversa com os professores, foi constatada queda no rendimento escolar e tendência ao isolamento dos colegas. Diante do caso relatado, que atitude o cirurgiãodentista deve assumir, de modo a respeitar o Estatuto da Criança e do Adolescente?","alternativas":[{"letra":"A","texto":"Denunciar a suspeita de maus-tratos ao Conselho Tutelar ou à autoridade competente da localidade mais próxima.","ordem":1,"idAlternativa":"0e323c7f-7968-59bd-949d-167083cd15eb"},{"letra":"B","texto":"Continuar a realizar o atendimento, seguindo a rotina, uma vez que crianças são emocionalmente instáveis.","ordem":2,"idAlternativa":"8621884a-9b5b-5637-ab82-93ef131da214"},{"letra":"C","texto":"Investigar a causa dos hematomas e chamar os pais e(ou) responsáveis, para prestarem esclarecimentos.","ordem":3,"idAlternativa":"4215bf12-6028-57aa-a57a-948ecd6393e2"},{"letra":"D","texto":"Comunicar à direção da escola a suspeita de que a criança seja vítima de violência domiciliar, porque a escola é responsável pela investigação do caso.","ordem":4,"idAlternativa":"6b9fad68-180b-5a65-a6cf-00d0bc1c539b"},{"letra":"E","texto":"Investigar o caso com cautela e denunciar ao Conselho Tutelar se houver certeza de que a criança é vítima de maus tratos.","ordem":5,"idAlternativa":"41d0e0c2-d57e-558e-a535-01167c240bc1"}],"gabarito":"A","observacoes":[],"idQuestao":"66eee8ba-f019-5af4-87bc-d369145d9449","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"12f45a66-d8ea-526e-8512-0c33aef45882","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 46"},{"secao":"Saúde Coletiva e Bioética","numero":47,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2013,"enunciado":"Uma paciente com 17 anos de idade procura a clínica odontológica desejando clarear seus dentes, pois ela julga que seu sorriso é “meio amarelado”. Ao exame clínico, o cirurgião- dentista verifica que há muitos dentes com restaurações, tanto anteriores como posteriores. Não há história de tratamento endodôntico. Em relação à conduta clínica e ao respeito aos princípios éticos, o cirurgião dentista deveria I. alertar que podem ocorrer mudanças nas restaurações durante o clareamento, podendo ser necessário o polimento ou a substituição das restaurações. II. informar que o efeito do clareamento ocorre sobre os dentes e não afeta as propriedades físicas e químicas das restaurações. III. garantir o grau de clareamento, desde que a concentração seja controlada e a aplicação do agente clareador seja repetida quantas vezes forem necessárias até se obter o grau de clareamento desejado. IV. orientar que os produtos resultantes da reação dos agentes clareadores podem agredir a polpa dental através dos túbulos dentinários É correto apenas o que se afirma em","alternativas":[{"letra":"A","texto":"I.","ordem":1,"idAlternativa":"4b88b9de-15be-5feb-b910-327ac9eafd3a"},{"letra":"B","texto":"III.","ordem":2,"idAlternativa":"63d4cb34-4dc9-548e-9891-33483b638d2f"},{"letra":"C","texto":"I e IV.","ordem":3,"idAlternativa":"40e507d6-94e7-5470-92cc-b222a544d383"},{"letra":"D","texto":"II e III.","ordem":4,"idAlternativa":"20546aa0-e4c5-5f23-841c-570cb68aa9d6"},{"letra":"E","texto":"II e IV.","ordem":5,"idAlternativa":"01dd927e-db0a-5891-838d-a10a6534a1e3"}],"gabarito":"C","observacoes":[],"idQuestao":"7636d9b5-1152-5d01-9862-cd289d02fa80","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"12f45a66-d8ea-526e-8512-0c33aef45882","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 47"},{"secao":"Saúde Coletiva e Bioética","numero":48,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2013,"enunciado":"A tabela abaixo foi elaborada após o levantamento epidemiológico nacional de saúde bucal de 2010. No que diz respeito às condições periodontais avaliadas pelo Índice Periodontal Comunitário (CPI), em termos populacionais, esse problema aumenta, de modo geral, com a idade. Considerando os dados apresentados, avalie as asserções a seguir e a relação proposta entre elas. I. A presença de cálculo e sangramento é mais comum aos 12 anos de idade e entre adolescentes. As formas mais graves da doença periodontal aparecem de modo mais significativo nos adultos (35 a 44 anos), em que se observa prevalência de 19,4%. PORQUE II. As diferenças regionais correspondem ao percentual de 56,8% de adolescentes da região Sudeste sem problemas gengivais, o que é condizente com melhores condições socioeconômicas e de acesso a serviços odontológicos; os problemas gengivais, em termos populacionais, entre idosos, são expressos pelo percentual médio de 90,5% de dentes excluídos em decorrência de doença periodontal. A respeito dessas asserções, assinale a opção correta.","alternativas":[{"letra":"A","texto":"As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I.","ordem":1,"idAlternativa":"cadcc9a2-e7cf-5ffc-a6b6-212333d9d5a6"},{"letra":"B","texto":"As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa correta da I.","ordem":2,"idAlternativa":"b663eea5-7d33-5b73-99d9-1458d3c4d35d"},{"letra":"C","texto":"A asserção I é uma proposição verdadeira, e a II é umaproposição falsa.","ordem":3,"idAlternativa":"afb804c5-b9fb-5f47-8517-261d9bb59881"},{"letra":"D","texto":"A asserção I é uma proposição falsa, e a II é uma proposiçãoverdadeira.","ordem":4,"idAlternativa":"4df5f801-552c-51c2-9749-3c98c819f3d1"},{"letra":"E","texto":"As asserções I e II são proposições falsas.","ordem":5,"idAlternativa":"50f81efb-ec50-579c-afe4-eab32cb46503"}],"gabarito":"C","observacoes":["Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."],"idQuestao":"ef7bbacd-e880-59d2-b298-8fb0113d79c6","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"12f45a66-d8ea-526e-8512-0c33aef45882","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"rascunho","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 48 | Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."},{"secao":"Saúde Coletiva e Bioética","numero":49,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2013,"enunciado":"Um cirurgião-dentista assumiu a coordenação de saúde bucal de seu município. Na primeira reunião com a sua equipe, propôs a realização de uma oficina para a elaboração do seu plano de gestão, com duração de quatro anos. Foi solicitado aos participantes da oficina que se orientassem pelas Diretrizes da Política Nacional de Saúde Bucal (2004). Considerando essa situação e as ações e estratégias prioritárias que devem orientar a atenção em saúde bucal em todos os níveis, avalie as afirmações a seguir. I. Para melhor identificar os principais grupos a serem priorizados e as ações que irão compor as linhas de cuidado, é necessário conhecer as características do perfil epidemiológico da população, as doenças e agravos de maior prevalência, bem como a forma com que as pessoas vivem e como os serviços de saúde são ofertados. II. As ações de promoção e proteção da saúde, que devem ser desenvolvidas como procedimentos coletivos em parcerias intersetoriais, visam reduzir fatores de risco e compreendem elenco bastante vasto e diversificado de atividades de natureza eminentemente educativo-preventiva. III. Ampliar no município as redes públicas de tratamento de águas, de forma a garantir o acesso à água tratada e fluoretada, é a forma mais abrangente e socialmente justa de acesso ao flúor. IV. As ações de recuperação devem ser centradas na detecção do câncer bucal, por meio de biópsias realizadas dentro da rede de saúde. V. As ações de saúde bucal devem ser inseridas de forma transversal nos diferentes programas integrais de saúde, por linhas de cuidado ou por condição de vida. É correto apenas o que se afirma em","alternativas":[{"letra":"A","texto":"I, II e IV.","ordem":1,"idAlternativa":"2479277f-c172-5597-be53-7afc49af321a"},{"letra":"B","texto":"I, II e V.","ordem":2,"idAlternativa":"e535fd82-91dd-567e-b749-e0e599dd09aa"},{"letra":"C","texto":"I, III e V.","ordem":3,"idAlternativa":"da3b5a0d-4581-5679-a1df-9e780b1a1294"},{"letra":"D","texto":"II, III e IV.","ordem":4,"idAlternativa":"aaeda3d7-341f-538d-b8e2-2ab96ce1e06f"},{"letra":"E","texto":"III, IV e V.","ordem":5,"idAlternativa":"c64a1411-72b7-5df8-b3c1-b5b3a61a12e4"}],"gabarito":"C","observacoes":[],"idQuestao":"3847e3d0-1b54-52e5-b18c-ac177de9b34e","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"12f45a66-d8ea-526e-8512-0c33aef45882","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 49"},{"secao":"Saúde Coletiva e Bioética","numero":50,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2013,"enunciado":"De acordo com os resultados encontrados no Projeto SB Brasil 2010: Pesquisa Nacional de Saúde Bucal, a prevalência de pelo menos um dente incisivo afetado por traumatismo em crianças de 12 anos é de 20,5%. BRASIL. Ministério da Saúde. SB Brasil 2010: Pesquisa Nacional de Saúde Bucal. Brasília, 2011. Disponível em: . Acesso em: 20 jul. 2013. Um cirurgião-dentista que atua em uma Unidade Básica de Saúde constata, na sua área de 22 abrangência, prevalência de 32% de incisivos permanentes afetados por trauma em crianças de 12 anos. Nesse caso, para reduzir esse índice, o profissional da Estratégia de Saúde da Família deverá I. elaborar um protocolo de atendimento, estabelecendo a metodologia a ser utilizada para a definição dos tipos de traumatismos, as técnicas de tratamento e de monitoramento das eventuais sequelas. II. propor ações de promoção da saúde, com ações intersetoriais e de educação em saúde que visem assegurar medidas de proteção, prevenção de acidentes e comportamentos seguros. III. integrar os profissionais de saúde bucal com o restante da equipe de saúde na abordagem de fatores de risco comuns do traumatismo dentário e de outras lesões traumáticas. IV. manter uma equipe de atendimento de urgência na Unidade Básica e estabelecer a possibilidade de encaminhamento de paciente ao centro de especialidades odontológicas ou hospital, de acordo com a gravidade e a extensão do trauma e as condições físicas do paciente. É correto apenas o que se afirma em","alternativas":[{"letra":"A","texto":"I e II.","ordem":1,"idAlternativa":"81cf6491-0735-5689-aa04-5f8ca4a0b640"},{"letra":"B","texto":"I e IV.","ordem":2,"idAlternativa":"32727694-5b33-5d48-b4e7-33453b8c5df7"},{"letra":"C","texto":"II e III.","ordem":3,"idAlternativa":"a12ad865-03e5-55d8-b609-78fc393e0208"},{"letra":"D","texto":"I, III e IV.","ordem":4,"idAlternativa":"360fd039-4d05-5b13-a1d8-9adba4f83286"},{"letra":"E","texto":"II, III e IV","ordem":5,"idAlternativa":"982cac56-85f9-559f-88ca-3ec96e7f078a"}],"gabarito":"C","observacoes":[],"idQuestao":"7c6d82e8-0570-5b64-adfb-c132aa3dad43","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"12f45a66-d8ea-526e-8512-0c33aef45882","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 50"},{"secao":"Saúde Coletiva e Bioética","numero":51,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2013,"enunciado":"Um paciente com 52 anos de idade, do sexo masculino, é atendido na Unidade Básica de Saúde (UBS) e relata queixa de “dentes amolecidos” na arcada inferior. O paciente trabalha na construção civil, na função de pedreiro, e relata fumar cerca de 15 cigarros por dia. No prontuário desse paciente, está registrada a condição de hipertensão. Sua frequência às atividades propostas pela Equipe de Saúde da Família é baixa, devido ao seu horário de trabalho. Durante o exame clínico, o cirurgião-dentista observa que o paciente usa prótese total superior e apresenta lesões sugestivas de candidíase na mucosa palatina, além de quadro de doença periodontal, com bolsas profundas na região anteroinferior e presença generalizada de cálculo dentário. Diante desse caso, avalie as afirmações a seguir. I. A triagem deve ser feita na UBS, para encaminhamento ao Centro de Especialidades Odontológicas (CEO), onde o paciente receberá o tratamento da lesão na mucosa, conforme determinar o especialista em estomatologia. II. O paciente enquadra-se nos critérios de risco para malignização da lesão na mucosa palatina e deve ser referenciado para o CEO, onde deve submeter-se a exames preventivos para o câncer bucal ao menos quatro vezes ao ano. III. O tratamento periodontal requer a raspagem subgengival de maior complexidade, devendo-se referenciar o paciente ao CEO após a adequação do meio bucal e motivação sobre o controle do biofilme dental efetuadas pela Equipe de Saúde Bucal. IV. O tratamento periodontal deverá ser concluído no CEO, onde será efetuada a alta, uma vez que o paciente apresenta condições de realizar os procedimentos de higiene bucal. V. O paciente deve ser estimulado a participar do programa de controle do tabagismo, que o ajudará no enfrentamento da dependência ao cigarro, uma vez que o fumo constitui fator de risco comum às doenças cardiovasculares e à doença periodontal. É correto apenas o que se afirma em","alternativas":[{"letra":"A","texto":"I e II.","ordem":1,"idAlternativa":"48dd1372-578d-59d4-94ff-ff418be4a37d"},{"letra":"B","texto":"I e III.","ordem":2,"idAlternativa":"0e4d65a1-77a2-54c3-a83c-e2c195255f76"},{"letra":"C","texto":"II e IV.","ordem":3,"idAlternativa":"09e5a9af-95bb-54f7-adde-22f3b43c9747"},{"letra":"D","texto":"III e V.","ordem":4,"idAlternativa":"174ce0bf-4869-5c03-90b9-cc45491f3efb"},{"letra":"E","texto":"IV e V.","ordem":5,"idAlternativa":"ba120870-a269-589d-8c82-15eaa52fc463"}],"gabarito":"D","observacoes":[],"idQuestao":"4a76bd3c-489e-5a77-815d-06cb0d08a96b","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"12f45a66-d8ea-526e-8512-0c33aef45882","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 51"},{"secao":"Saúde Coletiva e Bioética","numero":52,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"A figura abaixo ilustra a média do ceo/CPO e respectivos componentes de acordo com o grupo etário. Com base nessa figura, avalie as asserções a seguir e a relação proposta entre elas. I. Os dados ilustram que a cárie dentária está sendo controlada nas populações mais jovens e que, nas populações adulta e idosa, há elevada prevalência de lesões cariosas. PORQUE II. Os dados das populações adulta e idosa denotam o modelo cirúrgico-restaurador, não resolutivo, de atenção odontológica aque esses grupos etários foram submetidos. A respeito destas asserções, assinale a opção correta.","alternativas":[{"letra":"A","texto":"As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I.","ordem":1,"idAlternativa":"04e1ff9d-7ce9-5eb5-b3cb-d8d0d5ed31cb"},{"letra":"B","texto":"As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa correta da I.","ordem":2,"idAlternativa":"506897a2-b8b6-522f-a340-fa4ea182ed3c"},{"letra":"C","texto":"A asserção I é uma proposição verdadeira, e a II é uma proposição falsa.","ordem":3,"idAlternativa":"c4c181d4-7c66-5d8d-a88b-53f56ec874ba"},{"letra":"D","texto":"A asserção I é uma proposição falsa, e a II é uma proposição verdadeira.","ordem":4,"idAlternativa":"7dea1e52-e213-50ce-ae2c-8ccc28b48114"},{"letra":"E","texto":"As asserções I e II são proposições falsas.","ordem":5,"idAlternativa":"06b17b38-fb23-5171-8dbf-05cb10859e41"}],"gabarito":"D","observacoes":["Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."],"idQuestao":"6723d42b-f4dd-5af3-9904-278b286fe56e","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"rascunho","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 52 | Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."},{"secao":"Saúde Coletiva e Bioética","numero":53,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"Uma mulher com 80 anos de idade é portadora da Doença de Alzheimer em grau intermediário. O “esquecimento” fez com que ela abandonasse várias atividades do cotidiano. Sua condição piorou progressivamente, até que surgiram alucinações visuais e ideias delirantes, como ilusões de roubo. Atualmente, precisa de ajuda em todas as atividades, exceto na de alimentar. A família procurou o cirurgiãodentista por encaminhamento do geriatra. A idosa tem duas filhas casadas, que trabalham e se revezam nos cuidados à mãe. As imagens abaixo ilustram as condições clínicas encontradas. Considerando o caso apresentado, avalie as afirmações a seguir, relativas às condutas a serem adotadas pelo cirurgião-dentista. I. Encaminhar solicitação escrita ao médico geriatra de autorização para o início do tratamento da paciente, o qual envolverá raspagem dental, profilaxia profissional e orientação de higiene bucal. II. Solicitar às filhas que aguardem na sala de espera, enquanto estiver orientando a paciente sobre condutas de higiene bucal e da prótese. III. Comunicar-se com outros profissionais da saúde, para abordagem em conjunto, a fim de contornar questões relacionadas ao engajamento da família na prevenção das patologias bucodentárias da paciente. IV. Orientar as filhas sobre técnicas de higiene bucal e da prótese dentária e solicitar à responsável legal pela paciente que assine o Termo de Consentimento Livre e Esclarecido/Informado. É correto apenas o que se afirma em","alternativas":[{"letra":"A","texto":"I e II.","ordem":1,"idAlternativa":"3038a10d-399d-591a-991f-9eec4b53411b"},{"letra":"B","texto":"I e III.","ordem":2,"idAlternativa":"a397d8bf-83f1-578d-9d6f-8eb523c6cc10"},{"letra":"C","texto":"III e IV.","ordem":3,"idAlternativa":"236ed207-8d09-5bc5-b972-ad474b7a1b17"},{"letra":"D","texto":"I, II e IV.","ordem":4,"idAlternativa":"45ad030e-05c9-5d66-bdba-895ffa48f56b"},{"letra":"E","texto":"II, III e IV","ordem":5,"idAlternativa":"ec80698b-52c4-5f77-ad0c-6ee3ffbb292a"}],"gabarito":"C","observacoes":["Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."],"idQuestao":"a63ccedb-9d7d-59bb-ab65-72315ddccd49","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"rascunho","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 53 | Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."},{"secao":"Saúde Coletiva e Bioética","numero":54,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"Pacientes com 60 anos de idade ou mais, portadores de diabetes, participaram de um grupo de promoção do envelhecimento ativo e saudável realizado pela Unidade Básica de Saúde. Diante da proposta de cardápio apresentada pela nutricionista, manifestaram não ter condições de seguir a dieta com mais fibra, pois tinham dificuldades para mastigar e, na maioria das vezes, optavam por uma alimentação mais pastosa. Isso é justificado pelo fato do CPO-D médio para esta faixa etária no Brasil ser de 27,5, do qual o componente perdido representa 91,9% do total do índice, o que indica uma grande necessidade de próteses dentárias. Considerando esse contexto, avalie as asserções a seguir e a relação proposta entre elas. I. Com o objetivo de atender à Política Nacional de Saúde da Pessoa Idosa, que preconiza a atenção integral para essa população, a Equipe de Saúde Bucal deve confeccionar, na atenção básica, as próteses dentárias necessárias à reabilitação e à melhora da mastigação dos idosos, bem como, atuar em conjunto com os outros profissionais de saúde envolvidos na atenção à saúde do idoso. PORQUE II. Na atenção básica, devem ser incorporaradas ações que promovam a melhoria da resolutividade da atenção à pessoa idosa com abordagem global, interdisciplinar e multidimensional, que levam em conta a interação entre os fatores físicos, psicológicos e sociais que influenciam a saúde do idoso. A respeito dessas asserções, assinale a opção correta.","alternativas":[{"letra":"A","texto":"As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I.","ordem":1,"idAlternativa":"600bcb1b-d65f-50e0-8eb1-2455cd1b7ff8"},{"letra":"B","texto":"As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa correta da I.","ordem":2,"idAlternativa":"d27cb3d4-8577-55c8-974d-9a9edf957cdc"},{"letra":"C","texto":"A asserção I é uma proposição verdadeira, e a II é uma proposição falsa.","ordem":3,"idAlternativa":"3d10ca5e-a35b-505f-87e5-c412cc72d59b"},{"letra":"D","texto":"A asserção I é uma proposição falsa, e a II é uma proposição verdadeira.","ordem":4,"idAlternativa":"b761b009-65d2-5a1c-ac29-a5cb4becfcad"},{"letra":"E","texto":"As asserções I e II são proposições falsas.","ordem":5,"idAlternativa":"704f91a8-0849-5d3e-9e43-8d14ee28fc6b"}],"gabarito":"A","observacoes":[],"idQuestao":"a1e6619a-d8cf-59e8-b323-f27365a94f88","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 54"},{"secao":"Saúde Coletiva e Bioética","numero":55,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"Uma mulher com 23 anos de idade apresentando hematoma no lábio superior direito, fratura no terço médio da coroa do dente 12 com exposição pulpar, arranhões nos braços, escoriações e edemas nas pernas é atendida em uma Unidade Básica de Saúde. Nessa situação, avalie as afirmações a seguir, sobre a conduta correta que o cirurgião-dentista deve desempenhar. I. Realizar imediatamente a restauração do dente 12. II. Realizar exames físico intra e extrabucal e radiográfico. III. Indagar sobre a história do trauma buscando elementos que possam caracterizar sua causa. IV. Indicar que a paciente procure a assistente social da unidade, caso suspeite de violência doméstica. É correto apenas o que se afirma em","alternativas":[{"letra":"A","texto":"I e II.","ordem":1,"idAlternativa":"b0a8c618-4564-5390-9345-eb2d025a1ce4"},{"letra":"B","texto":"I e IV.","ordem":2,"idAlternativa":"36f298c4-64cd-542d-87b9-bb38fbad6ff0"},{"letra":"C","texto":"II e III.","ordem":3,"idAlternativa":"fa2b24c9-90e4-53f2-8133-77587e61fb3e"},{"letra":"D","texto":"I, III e IV.","ordem":4,"idAlternativa":"494cf667-8b0b-58b8-82ce-de71fee8f587"},{"letra":"E","texto":"II, III e IV.","ordem":5,"idAlternativa":"14157801-00f4-57a0-820c-094b6b46fd49"}],"gabarito":"C","observacoes":[],"idQuestao":"81e7193c-e1db-549f-9ff9-b0659e5de841","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 55"},{"secao":"Saúde Coletiva e Bioética","numero":56,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"De acordo com a Política Nacional de Saúde do Idoso, o atendimento na atenção básica domiciliar tem como objetivo promover a integração com os demais níveis de atenção e garantir a integralidade por meio da aplicação de modalidades que atendam às necessidades dessa população, a partir de condutas multidisciplinares, sempre que possível. O cirurgiãodentista, ao se deparar com casos de pacientes idosos que necessitam de atendimento domiciliar, deve estar preparado e qualificado para o atendimento, para que o plano de tratamento seja executado de maneira individualizada e multidisciplinar. ROCHA, D. A.; MIRANDA, A. F. Atendimento odontológico domiciliar aos idosos: uma necessidade na prática multidisciplinar em saúde: revisão de literatura. Rev. Bras. Geriatr. Gerontol. v. 16, n. 1, p. 181-189, 2013 (adaptado). A partir dessas informações, relativas ao atendimento domiciliar odontológico, avalie as afirmações a seguir. I. Idosos submetidos a intervenções cirúrgicas cardíacas requerem maior atenção nos procedimentos invasivos. II. Idosos diabéticos apresentam risco maior de doença periodontal com perda de tecido de suporte dentário, com progressão rápida e agressiva. III. Idosos hipertensos controlados apresentam risco aceitável no tratamento odontológico, a ser realizado sob monitorização da pressão arterial. IV. Idosos com saúde bucal insatisfatória e dificuldade de deglutição apresentam fator de risco para contaminações sistêmicas, relacionado à aspiração de conteúdo bacteriano da cavidade bucal e consequente contaminação do trato respiratório inferior. É correto o que se afirma em","alternativas":[{"letra":"A","texto":"I, apenas.","ordem":1,"idAlternativa":"b338cf03-d7da-5915-8108-9bd4e2af41f7"},{"letra":"B","texto":"I e IV, apenas.","ordem":2,"idAlternativa":"e22a0862-ca26-54f4-9324-20a056434a2f"},{"letra":"C","texto":"II e III, apenas.","ordem":3,"idAlternativa":"36039492-764b-5180-b0fc-2bb5458eda29"},{"letra":"D","texto":"II, III e IV, apenas.","ordem":4,"idAlternativa":"7e6bed3a-4759-572e-b710-8b199e7ffcc8"},{"letra":"E","texto":"I, II, III e IV.","ordem":5,"idAlternativa":"680b31cc-746c-5c89-a45e-4c480e2abe79"}],"gabarito":"E","observacoes":[],"idQuestao":"68593ed6-e273-5116-b5ca-f2316978a81f","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 56"},{"secao":"Saúde Coletiva e Bioética","numero":57,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"Um cirurgião-dentista recentemente contratado para compor a Equipe de Saúde da Família identificou, em uma comunidade, alta prevalência de traumatismos dentários em adolescentes. Para uma abordagem coletiva, proativa e empreendedora neste território, os serviços de saúde devem organizar, programar e manter diversas ações de vigilância do traumatismo dentário. Com relação a ações de planejamento em um serviço de atendimento de traumatismo dentário, em uma abordagem coletiva, avalie as afirmações a seguir. I. As equipes de saúde bucal devem investigar casos de traumatismos dentários diagnosticados na sua área de abrangência e identificar fatores sociais, ambientais, culturais e individuais que determinam sua ocorrência. II. As equipes de saúde bucal devem propor ações intersetoriais e de educação em saúde que visem assegurar medidas de proteção e prevenção de acidentes e comportamentos seguros. III. Os profissionais de saúde bucal devem integrar-se ao restante da equipe de saúde na abordagem de fatores de risco comuns do traumatismo dentário e de outras lesões traumáticas. IV. O atendimento de urgência deve ocorrer na unidade básica, podendo-se encaminhar ao CEO ou hospital, de acordo com a gravidade e extensão do trauma e as condições físicas do usuário. É correto o que se afirma em","alternativas":[{"letra":"A","texto":"II, apenas.","ordem":1,"idAlternativa":"8df27c5b-20e6-5e12-956f-bc9d33ef5271"},{"letra":"B","texto":"I e IV, apenas.","ordem":2,"idAlternativa":"fd3d8e57-c289-5cc5-8aaf-485b7c792f78"},{"letra":"C","texto":"III e IV, apenas.","ordem":3,"idAlternativa":"c2bdab47-b99c-5607-8c76-2128872637b3"},{"letra":"D","texto":"I, II e III, apenas.","ordem":4,"idAlternativa":"f67cfb6a-c3fd-51f9-ae8d-c8700394737d"},{"letra":"E","texto":"I, II, III e IV","ordem":5,"idAlternativa":"5df1566f-4190-5a86-9806-0dadd809086f"}],"gabarito":"D","observacoes":[],"idQuestao":"589a1fac-6370-5cdb-bd6a-c4aab324bf19","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 57"},{"secao":"Saúde Coletiva e Bioética","numero":58,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"Um dos principais problemas enfrentados no cotidiano dos serviços de saúde bucal é a organização da demanda, em especial nas atividades assistenciais, o que deve ser amplamente discutido entre usuários e trabalhadores de saúde. O universo da atenção à saúde bucal compreende toda a população da área de abrangência, e as ações de atenção deverão ser desenvolvidas no espaço da Unidade Básica de Saúde e, também, nos diferentes espaços sociais existentes. BRASIL. Ministério da Saúde. Secretaria de Atenção à Saúde. Cadernos de Atenção Básica nº 17. Brasília, 2008 (adaptado). Considerando o planejamento da atenção em saúde bucal, avalie as asserções a seguir e a relação proposta entre elas. I. O reconhecimento das situações de vulnerabilidade e o uso de instrumentos de identificação das necessidades de tratamento odontológico são estratégias que devem ser utilizadas pela Equipe de Saúde Bucal, para a organização das ações de saúde bucal no território sob sua responsabilidade. PORQUE II. A definição do território de ação permite organizar o processo de trabalho com equipes multiprofissionais e acompanhamento da população adstrita, compreender a dinâmica dos lugares e dos sujeitos, de modo a desvelar as desigualdades sociais e as iniquidades em saúde. A respeito dessas asserções, assinale a opção correta.","alternativas":[{"letra":"A","texto":"As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I.","ordem":1,"idAlternativa":"b7feb444-6241-514c-bc27-83f10d54214e"},{"letra":"B","texto":"As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa correta da I.","ordem":2,"idAlternativa":"95e40f05-3763-543f-a73c-98c8c8f58d84"},{"letra":"C","texto":"A asserção I é uma proposição verdadeira, ea II é uma proposição falsa.","ordem":3,"idAlternativa":"8e61a9a0-354e-5a4c-a712-7d17bf9d603e"},{"letra":"D","texto":"A asserção I é uma proposição falsa, e a II é uma proposição verdadeira.","ordem":4,"idAlternativa":"eb074de3-21fb-5ca6-94ca-e58baf6df375"},{"letra":"E","texto":"As asserções I e II são proposições falsas.","ordem":5,"idAlternativa":"a4d4cbaf-cb61-5ded-9408-0baeff90ed50"}],"gabarito":"A","observacoes":[],"idQuestao":"538d29ab-f864-5855-8ba6-c663a05b9cc8","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 58"},{"secao":"Saúde Coletiva e Bioética","numero":59,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"O envelhecimento populacional é um fenômeno mundial. No Brasil, nas três últimas décadas, o número de idosos aumentou nove vezes. Esta transição demográfica demanda mudanças na organização dos serviços, o que é um desafio para gestores e profissionais da saúde, pois requer maior preparo das equipes para o planejamento de medidas de prevenção, monitoramento e tratamento dos agravos em idosos, incluídos os agravos da saúde bucal. Disponível em: . Acesso em: 12 jul. 2016 (adaptado). Considerando esse cenário de transição demográfica, avalie as asserções a seguir e a relação proposta entre elas. I. Em relação aos idosos, a interação do cirurgião-dentista com outros profissionais de saúde na Estratégia de Saúde da Família deve estar focada no tratamento periodontal e nas extrações dentárias. PORQUE II. Os serviços de saúde direcionados aos idosos requerem abordagens por meio de práticas interprofissionais e intersetoriais, principalmente nas questões relacionadas 27 às doenças cujos fatores de risco são comuns, devendo estimular hábitos de vida saudáveis, cuidados diários com a higiene bucal e regularidade nos tratamentos odontológicos da atenção primária. A respeito dessas asserções, assinale a opção correta.","alternativas":[{"letra":"A","texto":"As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I.","ordem":1,"idAlternativa":"df8f6f31-4d8d-55b5-ba21-a35102cfb724"},{"letra":"B","texto":"As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa correta da I.","ordem":2,"idAlternativa":"111320e2-82d8-5725-adf2-210740a88370"},{"letra":"C","texto":"A asserção I é uma proposição verdadeira, e a II é uma proposição falsa.","ordem":3,"idAlternativa":"c9c976d4-176c-5e99-bb38-e85ca9e4b498"},{"letra":"D","texto":"A asserção I é uma proposição falsa, e a II é uma proposição verdadeira.","ordem":4,"idAlternativa":"cd73d67c-d432-5371-ab8a-f0234a0f14b0"},{"letra":"E","texto":"As asserções I e II são proposições falsas.","ordem":5,"idAlternativa":"f3246305-4051-580b-8186-b0666df967a9"}],"gabarito":"D","observacoes":[],"idQuestao":"df9b7049-b799-5c9b-937c-402f6eb0f154","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 59"},{"secao":"Saúde Coletiva e Bioética","numero":60,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"As tecnologias de informação e comunicação (TIC) provocaram mudanças na interação entre profissionais e pacientes, assim como na administração e no planejamento dos serviços de saúde. Diante do cenário de desenvolvimento das TIC na área de saúde, avalie asserções a seguir e a relação proposta entre elas. I. Os prontuários eletrônicos dos pacientes são exemplos das diversas contribuições das tecnologias de informação e comunicação para a gestão de serviçosodontológicos. PORQUE II. Os prontuários eletrônicos dos pacientes promovem agilidade no atendimento ao possibilitarem fácil acesso às informações e à documentação dos atendimentos, proporcionam maior legibilidade dos dados e reduzem os riscos de violação da privacidade dos pacientes e de extravio de documentos. A respeito dessas asserções, assinale a opção correta.","alternativas":[{"letra":"A","texto":"As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I.","ordem":1,"idAlternativa":"b3271183-8050-52b8-a0c2-8d7121e843cc"},{"letra":"B","texto":"As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa correta da I.","ordem":2,"idAlternativa":"bb74b8f1-9a34-5f29-af26-da47d12506be"},{"letra":"C","texto":"A asserção I é uma proposição verdadeira, e a II é uma proposição falsa.","ordem":3,"idAlternativa":"053ddce3-ff4d-57cc-ad26-ee60bd038f5a"},{"letra":"D","texto":"A asserção I é uma proposição falsa, e a II é uma proposição verdadeira.","ordem":4,"idAlternativa":"ac42d3df-0b9c-5577-a20b-78614c1328ee"},{"letra":"E","texto":"As asserções I e II são proposições falsas.","ordem":5,"idAlternativa":"1c7eac53-7400-5e8c-ae2e-4cfacf9585e7"}],"gabarito":"A","observacoes":[],"idQuestao":"43f3379e-5f1f-5039-ad4c-f9434721a7e1","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 60"},{"secao":"Saúde Coletiva e Bioética","numero":61,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"Um cirurgião-dentista atua como gestor em um consultório odontológico, organizando o seu uso em forma de condomínio odontológico de acordo com o quadro abaixo em que o proprietário é o dono; o parceiro é o especialista ou clínico que usa o espaço e a estrutura e paga uma taxa fixa pelo horário de uso do consultório; free lancer é o especialista ou clínico mais experiente que complementa os serviços oferecidos ao paciente. Considerando a estratégia de gestão apresentada e suas implicações, avalie as afirmações a seguir. I. Os horários do consultório odontológico são aproveitados de forma eficiente, quando comparado a um consultório em que um profissional atua isoladamente. II. Os custos de gerenciamento para o parceiro aumentam proporcionalmente ao seu tempo de trabalho. III. Os indicadores econômicos de desempenho do consultório apresentam piora porque há aumento dos custos de manutenção dos equipamentos. IV. Os lucros do proprietário crescem na medida em que aumenta a ocupação do consultório odontológico. É correto apenas o que se afirma em","alternativas":[{"letra":"A","texto":"I e II.","ordem":1,"idAlternativa":"834f0706-d346-59cd-9f63-b511ae3cc315"},{"letra":"B","texto":"I e IV.","ordem":2,"idAlternativa":"ac8630df-0012-5220-9ee5-34637a15f29b"},{"letra":"C","texto":"II e III.","ordem":3,"idAlternativa":"6bd40464-f0f8-5795-82f5-b42ce16df145"},{"letra":"D","texto":"I, III e IV.","ordem":4,"idAlternativa":"b078966f-a0f9-5db3-9de0-f906e40dc3d4"},{"letra":"E","texto":"II, III e IV.","ordem":5,"idAlternativa":"4521cc86-c783-5207-9ccd-0af4148a41cc"}],"gabarito":"B","observacoes":["Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."],"idQuestao":"ac9804e2-e9d8-524a-b106-1709b37983aa","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"rascunho","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 61 | Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."},{"secao":"Saúde Coletiva e Bioética","numero":62,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"O gestor de serviço de saúde bucal de um munícipio brasileiro, cuja água de abastecimento público é fluoretada e apresenta níveis ótimos de cobertura de 80% da população residente, pretende planejar ações para reduzir a incidência de cárie dentária na população de crianças e adolescentes. Considerando a situação proposta, avalie as afirmações a seguir, relativas às medidas necessárias ao planejamento das ações do gestor. I. Devem ser planejadas ações coletivas, como programas de aplicação de selantes oclusais e de bochechos diários com solução fluoretada a 0,2%, destinados à população de alto risco. II. Deve-se proceder a uma abordagem populacional, como a manutenção da fluoretação das águas de abastecimento público em níveis ótimos e com acompanhamento periódico. III. Deve-se priorizar a abordagem individual, como a escovação supervisionada com utilização de dentifrícios fluoretados para a população de alto risco. IV. Devem ser planejadas ações de vigilância em saúde para o acompanhamento do impacto das ações implementadas por meio de indicadores adequados, com registros claros, confiáveis e contínuos. É correto o que se afirma em","alternativas":[{"letra":"A","texto":"II, apenas.","ordem":1,"idAlternativa":"ecf70bb3-a005-5811-80d6-918f0c0c78cf"},{"letra":"B","texto":"I e III, apenas.","ordem":2,"idAlternativa":"052813cc-352a-5d1d-86b4-7f7b3c9c2d41"},{"letra":"C","texto":"II e IV, apenas.","ordem":3,"idAlternativa":"89dfeb7c-67f1-545f-8219-c1c3c4dfeae2"},{"letra":"D","texto":"I, III e IV, apenas.","ordem":4,"idAlternativa":"5fcb6fa0-aa40-55ff-a44b-41f1d2d0cb0d"},{"letra":"E","texto":"I, II, III e IV.","ordem":5,"idAlternativa":"8a4fe043-1a4d-5ae8-ab02-b7801bc14e51"}],"gabarito":"C","observacoes":[],"idQuestao":"dd29219a-9301-58ae-8556-49c91389cbe4","idDisciplina":"3d5c1722-13ec-5ebb-a2cc-57861893ed8d","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Saúde Coletiva e Bioética | Questão 62"},{"secao":"Odontologia Legal","numero":1,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"De acordo com a Lei Federal nº 5.081, de 24 de agosto de 1966, que regula o exercício profissional da odontologia em todo território Nacional, existem dispositivos fundamentais que devem ser obrigatoriamente observados e respeitados pelo cirurgiãodentista na sua atividade laboral. Com relação às competências estabelecidas na referida Lei, analise os dispositivos a seguir: I. utilizar, no exercício da função de perito odontólogo, em casos de necropsia, as vias de acesso do pescoço e da cabeça. II. realizar consultas mediante correspondência, rádio, televisão ou meios semelhantes. III. praticar todos os atos pertinentes à Odontologia, decorrentes de conhecimentos adquiridos em curso regular ou em cursos de pós-graduação. Considerando somente os dispositivos não vedados, está correto o que se atesta em","alternativas":[{"letra":"A","texto":"I, apenas.","ordem":1,"idAlternativa":"a9371183-4fb8-504e-ba26-b48718e08d37"},{"letra":"B","texto":"I, II, apenas.","ordem":2,"idAlternativa":"e180dad8-a26d-5a06-884a-56e8746bba41"},{"letra":"C","texto":"II, apenas.","ordem":3,"idAlternativa":"a3077c19-9599-571c-bb20-32cc2a7dbb3b"},{"letra":"D","texto":"I, III, apenas.","ordem":4,"idAlternativa":"3d92f534-2ef2-564c-977b-b6994875947d"},{"letra":"E","texto":"I, II e III.","ordem":5,"idAlternativa":"17bc70aa-c689-59cf-b889-c3bfdaf2de1f"}],"gabarito":"D","observacoes":[],"idQuestao":"bc2b78a0-ae97-5c79-b88a-a99b694ed68a","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 1"},{"secao":"Odontologia Legal","numero":2,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"A partir do século XIX, diversas obras de relevância relacionadas ao tema da Odontologia Legal foram publicadas. Atualmente a especialidade está consolidada como ciência, participando em diversos campos de atuação por sua importância forense. Considerando o aspecto histórico, relacione as personalidades indicadas com suas respectivas contribuições no processo evolutivo da disciplina: 1.Oscar Amoedo. 2.Luiz Lustosa da Silva. 3.Gösta Gustafson. 4.Henrique Tanner de Abreu. ( ) Autor do livro “Medicina legal aplicada à arte dentária” (1922), primeira obra destinada ao estudo da Odontologia Legal. ( ) Autor da obra “L’Arte Dentaire em Médicine Légale”(1898), onde consta entre os temas abordados, o relato do processo de identificação pelas arcadas dentárias das vítimas da tragédia do incêndio do Bazar de la Charité em Paris (1897). Sendo referenciado por sua contribuição como “Pai” da Odontologia Legal mundial. ( ) Autor do primeiro livro publicado no Brasil com o título “Odontologia Legal” (1924). A paternidade da expressão “ODONTOLOGIA LEGAL” foi atribuída a este profissional durante o Primeiro Congresso Panamericano de Medicina Legal, Odontologia Legal e Criminologia, em Havana (1946). Sendo referenciado por sua contribuição no segmento como “Pai” da Odontologia Legal no Brasil. ( ) Autor da primeira obra publicada no exterior (1966), intitulada “Forensic Odontology” escrita na língua inglesa, que remete à tradução da expressão Odontologia Legal. Foi no Brasil referência bibliográfica utilizada pelo professorMoacyr da Silva e equipe no caso da identificação de Josef Mengele. Assinale a opção que apresenta a relação correta, na ordem apresentada.","alternativas":[{"letra":"A","texto":"4, 1, 2 e 3.","ordem":1,"idAlternativa":"2fd4cf1c-7e40-5c3b-8718-d6dac0a0d4a1"},{"letra":"B","texto":"1, 4, 2 e 3.","ordem":2,"idAlternativa":"2ce1b68f-2772-570f-a6db-6024fcf3a078"},{"letra":"C","texto":"4, 1, 3 e 2.","ordem":3,"idAlternativa":"af197146-db9e-528c-a3d9-9794c38e41c6"},{"letra":"D","texto":"2, 3, 4 e 1.","ordem":4,"idAlternativa":"836fdb12-1c3c-5ad6-aa0f-4411383af55e"},{"letra":"E","texto":"2, 1, 4 e 3.","ordem":5,"idAlternativa":"f276cb44-227b-52fb-9aa4-7c2685c2e21c"}],"gabarito":"A","observacoes":[],"idQuestao":"dae9496c-d455-57a6-8d92-3bc8d3ffb256","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 2"},{"secao":"Odontologia Legal","numero":3,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"A partir da publicação da Lei 5.081/66, no artigo Art. 6º, inciso IV, foram descritos os âmbitos onde o graduado em odontologia devidamente inscrito e registrado nos conselhos de classe poderia proceder à perícia. Considerando de forma literal o conteúdo expresso no referido dispositivo, assinale, dentre as opções apresentadas, somente os fóruns que um cirurgião-dentista poderia proceder à perícia odontolegal.","alternativas":[{"letra":"A","texto":"civil, administrativo e penal.","ordem":1,"idAlternativa":"afe7cb20-8f6b-5782-9f46-18077369e4f1"},{"letra":"B","texto":"civil, criminal e trabalhista.","ordem":2,"idAlternativa":"8dfff69a-811a-54a4-8806-148da5b134c6"},{"letra":"C","texto":"civil, trabalhista e público.","ordem":3,"idAlternativa":"a6bf16d0-cbc1-5f9d-86f4-084f1f199a74"},{"letra":"D","texto":"judicial, ético e administrativo.","ordem":4,"idAlternativa":"d458ef77-0c19-5b6c-bbe0-025200b43397"},{"letra":"E","texto":"federal, estadual e municipal","ordem":5,"idAlternativa":"51d0a683-5069-58df-a353-2fe2def0810b"}],"gabarito":"B","observacoes":[],"idQuestao":"29152255-f5a0-5b6e-9872-96e774fb21ad","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 3"},{"secao":"Odontologia Legal","numero":4,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Com relação a laudos periciais, assinale V para a afirmativa verdadeira e F para a falsa. ( ) Os laudos genericamente contêm somente as partes, a saber: preâmbulo, quesitos, histórico e antecedentes, descrição, discussão, respostas aos quesitos, data e assinatura. ( ) O laudo pode conter elementos de referência como gráficos, esquemas, pareceres, fotografias, fotomicrografias, cópias de documentos (relatórios de exames de laboratório), radiografias, enfim, tudo o que puder esclarecer e justificar o que foi escrito no corpo do documento. ( ) O histórico refere-se aos fatos geradores da perícia. Nessa parte cabem informes colhidos das mais diversas fontes e maneiras, naturalmente dependente do caso e do tipo de perícia. As afirmativas são, respectivamente,","alternativas":[{"letra":"A","texto":"F, V e F.","ordem":1,"idAlternativa":"65ec372d-af0c-5f9b-b004-b57d255e6857"},{"letra":"B","texto":"F, V e V.","ordem":2,"idAlternativa":"ca20ca6a-6920-53cc-95ea-e81f7e84fb57"},{"letra":"C","texto":"V, F e F.","ordem":3,"idAlternativa":"f07c1e47-e4fa-5b9d-b5b3-86460020f302"},{"letra":"D","texto":"V, V e F.","ordem":4,"idAlternativa":"d11e309f-5f2f-5708-b201-acd634daa95f"},{"letra":"E","texto":"F, F e V.","ordem":5,"idAlternativa":"cb033d35-2137-5c95-b97a-245078dbf742"}],"gabarito":"B","observacoes":[],"idQuestao":"e9b38c75-c80f-5333-b431-8b7a354d4a3f","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 4"},{"secao":"Odontologia Legal","numero":5,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Em termos conceituais, as perícias são levadas a efeito por profissionais especializados, dotados de profundo conhecimento teórico e prático do ramo ao qual sededicam. Dessa forma, considerando a rotina habitual, relacione o perito/área com os seus respectivos tipos de perícias. 1.Perito: Louvado/área civil. 2.Perito: Oficial/área criminal. ( ) perícia de arbitramento judicial de honorários de um profissional. ( ) perícia de corpo de delito. ( ) perícia de determinação de idade.( ) perícia de ressarcimento de danos.( ) perícia antropológica. A relação correta, na ordem dada, é","alternativas":[{"letra":"A","texto":"1, 2, 2, 1 e 2.","ordem":1,"idAlternativa":"e42f32f7-4c3f-58a7-bbaf-13bb545cea29"},{"letra":"B","texto":"2, 1, 1, 2 e 1.","ordem":2,"idAlternativa":"6db3a986-b409-50d5-bf11-5564d2b748a6"},{"letra":"C","texto":"2, 2, 1, 2 e 1.","ordem":3,"idAlternativa":"243219d1-fee7-5602-b915-5845d0fac70a"},{"letra":"D","texto":"1, 1, 2, 1 e 2.","ordem":4,"idAlternativa":"9b572717-f680-5aaa-8e98-a6d0aa805a6f"},{"letra":"E","texto":"1, 2, 1, 1 e 2.","ordem":5,"idAlternativa":"717c3596-2a02-5d4c-ad13-52ebf18a1b1f"}],"gabarito":"A","observacoes":[],"idQuestao":"80e4753f-25f4-519d-88ae-e9a12f64fe61","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 5"},{"secao":"Odontologia Legal","numero":6,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Com relação às perícias antropológicas de identificação realizadas em crânios esqueletizados, considerando as informações relacionadas, assinale V para a afirmativa verdadeira e F para a falsa. ( ) A melhor estrutura para fazer diagnóstico diferencial do sexo é o crânio. ( ) Na inspeção do crânio e da mandíbula pode-se, em 97% dos casos, determinar o sexo e estimar a espécie animal. ( ) Podem determinar se é da espécie humana ou não e estimar a estatura, biótipo, sexo e idade. ( ) Os pontos craniométricos dividem-se, pela sua posição anatômica, em pontos medianos e pontos pares. As afirmativas são, respectivamente,","alternativas":[{"letra":"A","texto":"F, F, V e F.","ordem":1,"idAlternativa":"e4216515-0d95-5fcf-a407-d9df5396cd0f"},{"letra":"B","texto":"F, F, V e V.","ordem":2,"idAlternativa":"f70462fb-6844-5840-8910-79873a6475b4"},{"letra":"C","texto":"F, V, F e V.","ordem":3,"idAlternativa":"300e6ee2-4642-500b-83c4-234fde2097b0"},{"letra":"D","texto":"V, F, V e V.","ordem":4,"idAlternativa":"23c5679f-4da6-515b-ac37-62bcb7b7fd32"},{"letra":"E","texto":"V, F, V e F.","ordem":5,"idAlternativa":"e1088165-ab0c-50b4-8ea2-b5f735a3fddf"}],"gabarito":"B","observacoes":[],"idQuestao":"5003a512-cfff-5d35-9d56-c8e16ffbe45b","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 6"},{"secao":"Odontologia Legal","numero":7,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"O atual Código de Ética Odontológica é um instrumento orientador e disciplinador da classe odontológica brasileira, tendo sido aprovado pela Resolução CFO-118/2012. Avalie se os deveres fundamentais contidos nesse estatuto incluem: I. Diagnosticar, planejar e executar tratamentos, com liberdade de convicção, nos limites de suas atribuições, observados o estado atual da ciência e sua dignidade profissional. II. Decidir, em qualquer circunstância, levando em consideração sua experiência e capacidade profissional, o tempo a ser dedicado ao paciente ou periciado, evitando que o acúmulo de encargos, consultas, perícias ou outras avaliações venham prejudicar o exercício pleno da Odontologia. III. Apontar falhas nos regulamentos e nas normas das instituições em que trabalhe, quando as julgar indignas para o exercício da profissão ou prejudiciais ao paciente, devendo dirigir-se, nesses casos, aos órgãos competentes. Está correto o que se afirma em","alternativas":[{"letra":"A","texto":"I, apenas.","ordem":1,"idAlternativa":"bd1fa852-4f02-59e0-8ca3-291d2989c599"},{"letra":"B","texto":"I, II, apenas.","ordem":2,"idAlternativa":"b23a2a69-7d6f-5224-b9c3-18f689cc52f8"},{"letra":"C","texto":"III, apenas.","ordem":3,"idAlternativa":"55798aba-d3b1-5de9-89e2-878f1d60790f"},{"letra":"D","texto":"II, III, apenas.","ordem":4,"idAlternativa":"d47f7bf1-0d5c-514d-b243-712a05930125"},{"letra":"E","texto":"I, II e III.","ordem":5,"idAlternativa":"f47ff763-9293-57c8-8257-295df2816cf0"}],"gabarito":"C","observacoes":[],"idQuestao":"5e74ec07-bc62-566c-a69d-98534c0d14d9","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 7"},{"secao":"Odontologia Legal","numero":8,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"De acordo com a Resolução do Conselho Federal de Odontologia nº 118/2012, que entrou em vigor a partir de 1º de janeiro de 2013, avalie se os preceitos éticos contidos no Capítulo IV, Art. 10, das Auditorias e Perícias Odontológicas, os quais devem ser observados e seguidos pelos profissionais devidamente inscritos no conselho de classe, incluem: I. Atuar com absoluta isenção quando designado para servir como perito ou auditor, assim como não ultrapassar os limites de suas atribuições e de sua competência. II. Realizar ou exigir procedimentos prejudiciais aos pacientes e ao profissional, contrários às normas de Vigilância Sanitária, exclusivamente para fins de auditoria ou perícia. III. Exercer a função de perito, quando: a) for parte interessada; tenha tido participação como mandatário da parte, ou sido designado como assistente técnicode órgão do Ministério Público, ou tenha prestado depoimento como testemunha; c) for cônjuge ou a parte for parente, consanguíneo ou afim, em linha reta ou colateral até o segundo grau; e, d) a parte for paciente, ex-paciente ou qualquer pessoa que tenha ou teve relações sociais, afetivas, comerciais ou administrativas, capazes de comprometer o caráter de imparcialidade do ato pericial ou da auditagem. Considerando somente as afirmativas que levariam a constituir infração ética, está correto o que se declara em","alternativas":[{"letra":"A","texto":"I, apenas.","ordem":1,"idAlternativa":"4572d514-861b-5a6d-bc36-68824a424b0c"},{"letra":"B","texto":"I, II, apenas.","ordem":2,"idAlternativa":"23b809e8-947c-5fe5-88fa-cb4d2ceb9cd0"},{"letra":"C","texto":"II, III, apenas.","ordem":3,"idAlternativa":"5490959d-0917-52e8-b178-9e12b4347a86"},{"letra":"D","texto":"I, III, apenas.","ordem":4,"idAlternativa":"9b6bdbf8-28d6-5782-ab95-b4ce6042d511"},{"letra":"E","texto":"I, II e III.","ordem":5,"idAlternativa":"8d4ba50b-e6ca-515c-80aa-b9bd81305565"}],"gabarito":"C","observacoes":[],"idQuestao":"b6fe20cd-84d3-5c86-b06a-9beedec1e369","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 8"},{"secao":"Odontologia Legal","numero":9,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Em termos conceituais, a traumatologia forense estuda os traumas, lesões, instrumentos e ações vulnerantes, visando elucidar a dinâmica dos fatos. Sabendo-se que o trauma é resultado da ação vulnerante que possui energia capaz de produzir a lesão, correlacione a energia/ordem (causa) com seu respectivo sinal (efeito) sobre o corpo humano. 1.Ordem Mecânica. 2.Ordem Elétrica. 3.Ordem Térmica. ( ) Escara negra. ( ) Bossa linfática. ( ) Sinal de Lichtenberg. ( ) Sinal de Chambert positivo. ( ) Sinal de Jellinek. ( ) Sinal de Bonnet. Assinale a opção que indica a relação correta na ordem apresentada.","alternativas":[{"letra":"A","texto":"3, 1, 2, 3, 2 e 1.","ordem":1,"idAlternativa":"066fa03d-a0fe-5a71-b29f-a5c94ea380dc"},{"letra":"B","texto":"3, 2, 1, 3, 1 e 2.","ordem":2,"idAlternativa":"5ce4db8d-5a60-50ec-8cbc-c3af2e948a32"},{"letra":"C","texto":"2, 1, 2, 1, 3 e 3.","ordem":3,"idAlternativa":"c3de85fd-b3b2-558b-8dfc-1d52c03d2913"},{"letra":"D","texto":"3, 1, 2, 1, 2 e 3.","ordem":4,"idAlternativa":"959ebfcc-5443-5585-bf64-5a1f728a57ab"},{"letra":"E","texto":"1, 2, 3, 2, 3 e 1.","ordem":5,"idAlternativa":"6e9ebe58-aac5-5377-8271-4bab7d9de4b9"}],"gabarito":"A","observacoes":[],"idQuestao":"75a9acd1-97aa-53c6-857b-7a4e6c6d406b","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 9"},{"secao":"Odontologia Legal","numero":10,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Dependendo dos fatores envolvidos, principalmente a forma e força de agressão, existirão diversas modalidades de lesões com repercussões e consequências diferentes. Partindo dessa premissa, relacione a condição com suas respectivas particularidades. 1.Rubefação. 2.Escoriação. 3.Equimose. 4.Hematoma. 5.Esmagamento. ( ) Congestão local passageira. ( ) Coleção sanguínea localizada. ( ) Síndrome de Crush. ( ) Derrame sanguíneo na malha tecidual. ( ) Exposição do córion. Assinale a opção que indica a relação correta na ordem apresentada.","alternativas":[{"letra":"A","texto":"1, 4, 5, 3 e 2.","ordem":1,"idAlternativa":"2610e16e-b526-5703-8e97-8c1845e3b1d4"},{"letra":"B","texto":"1, 4, 3, 5 e 2.","ordem":2,"idAlternativa":"3d96f1ed-48b3-5610-ab6c-78434f750557"},{"letra":"C","texto":"4, 1, 5, 3 e 2.","ordem":3,"idAlternativa":"361b877a-c3df-5bd4-8b10-204c01c67cf7"},{"letra":"D","texto":"4, 1, 2, 5 e 3.","ordem":4,"idAlternativa":"831251b8-2c41-5968-944d-fadd0b110ec9"},{"letra":"E","texto":"3, 4 , 5, 2 e 1.","ordem":5,"idAlternativa":"489c7075-e0ab-5eaf-8bf8-36309f884fd3"}],"gabarito":"A","observacoes":[],"idQuestao":"3f7bd514-d9e2-5399-9822-227249dc7ce4","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 10"},{"secao":"Odontologia Legal","numero":11,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Com relação às lesões causadas por ação física, não mecânica, assinale V para afirmativa verdadeira e F para a falsa. ( ) Lesões causadas por ação térmica que atua difusamente podem levar a insolação e a intermação. ( ) Lesões causadas por ação térmica que atua diretamente sobre o corpo, através de gases, líquidos, ou sólidos aquecidos, ou por chama, podem levar a queimaduras de até 3º grau. ( ) A gravidade das queimaduras depende principalmente da extensão e da profundidade da área queimada. As afirmativas são, respectivamente,","alternativas":[{"letra":"A","texto":"F, V e F.","ordem":1,"idAlternativa":"790ddd05-4c98-5ffb-8494-892bd95595d9"},{"letra":"B","texto":"F, V e V.","ordem":2,"idAlternativa":"8c53dce1-15ca-5994-8c85-db7917c766f1"},{"letra":"C","texto":"V, F e V.","ordem":3,"idAlternativa":"76cbcf12-2e56-5a5b-a4a7-0b5150dfda58"},{"letra":"D","texto":"V, V e F.","ordem":4,"idAlternativa":"4720690d-5b0a-567a-b026-d954edf7e81a"},{"letra":"E","texto":"F, F e V.","ordem":5,"idAlternativa":"5c8bf8ce-d734-58b1-a7e3-d38c6b3dd8b9"}],"gabarito":"E","observacoes":[],"idQuestao":"4758c509-afa1-509b-8c6a-c451f3dbc809","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 11"},{"secao":"Odontologia Legal","numero":12,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"De acordo com um trecho retirado da notícia publicada no The Indian Express: O responsável pelo posto policial de Vatika, declarou que: “quatro homens haviam se abrigado debaixo de uma árvore quando começou a chover fortemente na noite de sexta-feira. Um raio atingiu o local ferindo os quatro indivíduos, sendo que três sobreviveram e um foi a óbito”. Tendo em vista o caso apresentado, analise as afirmativas a seguir: I. Os quatro homens foram atingidos por uma energia de ordem física não mecânica. II. O homem que faleceu foi vítima de eletrocussão. III. As vítimas que sobreviveram sofreramfulguração. IV. Devido ao trauma recebido, podem aparecer desenhos na pele, de cor avermelhada ligeiramente saliente, em ziguezague, arborescente que acompanha os trajetos vasculares, fenômeno considerado de natureza vasoparalítica. Está correto o que se declara em","alternativas":[{"letra":"A","texto":"I e II, apenas.","ordem":1,"idAlternativa":"aed8392f-99a9-5195-9711-0de7f2c5e04e"},{"letra":"B","texto":"I e III, apenas.","ordem":2,"idAlternativa":"49d57be6-5434-50a4-a8e8-13e0d0e9622a"},{"letra":"C","texto":"II e III, apenas.","ordem":3,"idAlternativa":"58d562af-573f-51ad-89ad-26bd2cc1c434"},{"letra":"D","texto":"III e IV, apenas.","ordem":4,"idAlternativa":"315c39af-9c80-5a95-8024-5e7acb80dc55"},{"letra":"E","texto":"I, III e IV, apenas.","ordem":5,"idAlternativa":"efc9552f-b15e-5fee-bbae-0e473180bcde"}],"gabarito":"C","observacoes":[],"idQuestao":"459520da-57bf-5ace-9b83-3208f1e68b3a","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 12"},{"secao":"Odontologia Legal","numero":13,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"No estudo das energias de ordem mecânica, a classificação médico-legal dos agentes pressupõe, invariavelmente, como primeira etapa, a análise da lesão para sua denominação. A literatura científica referencia que os arcos dentários humanos podem produzir vários tipos de feridas. Segundo Arbenz (1988) a dinâmica da mordida é habitualmente classificada como instrumento do tipo","alternativas":[{"letra":"A","texto":"perfurante.","ordem":1,"idAlternativa":"fa47e785-fbc9-554d-853d-971122a68601"},{"letra":"B","texto":"contundente.","ordem":2,"idAlternativa":"63e7ceb9-def9-53ff-8c11-a04b8bf1bdcf"},{"letra":"C","texto":"corto-contundente.","ordem":3,"idAlternativa":"7a18ef77-4ae5-56f3-9622-cbe0c7e2ce46"},{"letra":"D","texto":"cortante.","ordem":4,"idAlternativa":"461d3a94-c660-55e1-bf1d-f0b27845cb62"},{"letra":"E","texto":"perfuro-contundente.","ordem":5,"idAlternativa":"1e19adbd-e08c-5d7f-85e4-6164cd3cf144"}],"gabarito":"D","observacoes":[],"idQuestao":"6270076f-4033-5de3-8429-aee7875d5443","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 13"},{"secao":"Odontologia Legal","numero":14,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Para ser considerado aceitável, o processo de identificação deve preencher cinco requisitos (fundamentos biológicos e técnicos) que irão determinar a maior ou menor credibilidade do procedimento. Assinale a opção que indica apenas os que decorrem de fundamentos biológicos.","alternativas":[{"letra":"A","texto":"unicidade, perenidade e praticabilidade.","ordem":1,"idAlternativa":"8e2f814b-7afe-547a-a63f-168f1f7ac605"},{"letra":"B","texto":"unicidade, imutabilidade e classificabilidade.","ordem":2,"idAlternativa":"c1e8709b-97c5-510d-8ce3-ac23a417c3a0"},{"letra":"C","texto":"perenidade, imutabilidade e praticabilidade.","ordem":3,"idAlternativa":"0099c48d-fc29-56f0-9c0e-b1cfe14195a1"},{"letra":"D","texto":"individualidade, imutabilidade e perenidade.","ordem":4,"idAlternativa":"a0a1f650-fb97-5958-97c5-5c75d2508365"},{"letra":"E","texto":"classificabilidade, praticabilidade e unicidade.","ordem":5,"idAlternativa":"2941f29f-a18c-5e22-8690-3fba0a64c96e"}],"gabarito":"A","observacoes":[],"idQuestao":"0e718987-1efc-5c02-99c6-fccfc215f0bd","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 14"},{"secao":"Odontologia Legal","numero":15,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Com base nos princípios fundamentais da biotipologia descritos por Berardinelli (1942), que são tão importantes para a realização de uma perícia, assinale V para afirmativa verdadeira e F para a falsa. ( ) Todos os indivíduos são diferentes; não há duas pessoas iguais. ( ) O mesmo individuo não é diferente de si mesmo a cada momento. ( ) Dentro das diferenças há semelhanças que permitem agrupar os indivíduos em tipos. ( ) O conhecimento do indivíduo “normal” deve proceder e servir de base ao estudo do indivíduo patológico. As afirmativas são, respectivamente,","alternativas":[{"letra":"A","texto":"V, F, V e F.","ordem":1,"idAlternativa":"e801e42f-c950-5617-a53e-0627928b291a"},{"letra":"B","texto":"F, F, V e V.","ordem":2,"idAlternativa":"ca1059c8-7b72-5970-a0d5-466fd62de9d1"},{"letra":"C","texto":"F, V, F e V.","ordem":3,"idAlternativa":"d6c141c9-5d43-56fd-8cbb-d783f4f9967c"},{"letra":"D","texto":"V, F, V e V.","ordem":4,"idAlternativa":"6df6d0b5-25b4-5638-9c21-9b3ce6a38879"},{"letra":"E","texto":"V, V, V e F.","ordem":5,"idAlternativa":"dc8bb8cc-4cc2-5ea3-b100-085463983941"}],"gabarito":"C","observacoes":[],"idQuestao":"06e4fffa-b560-5565-b3fe-147c8c10cf87","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 15"},{"secao":"Odontologia Legal","numero":16,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"A estimativa do sexo tem seu valor no campo da odontologia legal, principalmente quando é encontrado um crânio separado do esqueleto. Existe um índice idealizado por Baudoin que é utilizado para uma determinada estrutura docrânio. Com relação ao tema, analise as afirmativas a seguir. I. Côndilos mandibulares mais robustos no sexo masculino e índice de Baudoin menor que 55. II. Côndilos occipitais mais curtos e mais largos no sexo feminino e índice de Baudoin maior que 55. III. Côndilos occipitais mais curtos e mais largos no sexo feminino e índice de Baudoin menor que 55. IV. Côndilos mandibulares mais delicados no sexo feminino e índice de Baudoin maior que 55. Está correto o que se afirma em:","alternativas":[{"letra":"A","texto":"I, apenas.","ordem":1,"idAlternativa":"2aa0de6a-f9ad-5a96-84bc-afc49379d493"},{"letra":"B","texto":"I e IV, apenas.","ordem":2,"idAlternativa":"a2b1df95-3431-5181-9cf7-85246cfae8dc"},{"letra":"C","texto":"II, apenas.","ordem":3,"idAlternativa":"290d884f-49f5-5a4c-a055-c28a3c140ada"},{"letra":"D","texto":"III, apenas.","ordem":4,"idAlternativa":"751d35f0-b1de-5efb-b15d-a9363ce21082"},{"letra":"E","texto":"IV, apenas.","ordem":5,"idAlternativa":"0bf75a91-9d57-53f5-8514-8f55afcd7782"}],"gabarito":"C","observacoes":[],"idQuestao":"19c9bdc6-e7d7-514f-8483-26c09cb4d1d8","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 16"},{"secao":"Odontologia Legal","numero":17,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Nos processos de identificação de esqueletos, os conhecimentos do perito odontolegal são imprescindíveis quando se encontra somente o crânio com os elementos dentários. Mesmo com as limitações técnicas, a estatura, idade e cor da pele podem ser estimados a partir da aplicação de alguns métodos e critérios publicados em literatura. Desta forma, relacione as características indicadas, com os recursos passiveis de utilização. 1.Estatura. 2.Idade. 3.Cor da pele/grupo étnico. ( ) Tabela de Nicodemo, Moraes e Medici. ( ) Testes - critérios de Rivet, Cloquet, Welcker,Jacquard. ( ) Método de Carrea. Assinale a opção que indica a relação correta na ordem dada.","alternativas":[{"letra":"A","texto":"1, 2 e 3.","ordem":1,"idAlternativa":"e98ad574-2395-5e58-980b-9c3da729878a"},{"letra":"B","texto":"3, 2 e 1.","ordem":2,"idAlternativa":"616bd566-1d49-54a5-8dc4-890fffb969ea"},{"letra":"C","texto":"2, 3 e 1.","ordem":3,"idAlternativa":"8a75aa73-a312-548b-8b4c-35a98b9e5915"},{"letra":"D","texto":"3, 1 e 2.","ordem":4,"idAlternativa":"2db4d492-9da1-5aee-ad05-7804ccea8d82"},{"letra":"E","texto":"2 ,1 e 3.","ordem":5,"idAlternativa":"37bc4458-ed80-58df-965e-99ebbca28bd1"}],"gabarito":"A","observacoes":[],"idQuestao":"9c2e6d84-9435-5a66-ab89-9fdc0648e6ed","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 17"},{"secao":"Odontologia Legal","numero":18,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Em medicina legal, a determinação do sexo genético tem aplicação quando se encontram fragmentos de tecidos, pelos, manchas de sangue e saliva. No caso particular da odontologia legal, é relevante citar a importância da pesquisa de cromatina sexual na polpa dentária, bem como nas células de descamação da mucosa bucal.Considerando o conteúdo expresso no referido texto, assinale a afirmativa correta.","alternativas":[{"letra":"A","texto":"A cromatina sexual será observada, nos núcleos das células, mais intensamente corada, estando presente (sexo feminino), estando ausente (sexomasculino).","ordem":1,"idAlternativa":"602c01d4-1a5d-5a9d-b34d-f856728e14ff"},{"letra":"B","texto":"A cromatina sexual será observada, nos citoplasmas das células, mais intensamente corada, estando presente (sexo feminino), estando ausente (sexo masculino).","ordem":2,"idAlternativa":"801444d2-4b79-59c0-8868-86bdd38a55a3"},{"letra":"C","texto":"A cromatina sexual será observada, nas mitocôndrias das células, mais intensamente corada, estando presente (sexo masculino), estando ausente (sexo feminino).","ordem":3,"idAlternativa":"4101ed9d-1c0f-5000-b37a-ed22281808dd"},{"letra":"D","texto":"A cromatina sexual será observada, nos núcleos das células, mais intensamente corada, estando presente (sexo masculino), estando ausente (sexofeminino).","ordem":4,"idAlternativa":"45aa325d-de73-517f-918f-6a4266abb416"},{"letra":"E","texto":"A cromatina sexual será observada, nos núcleos das células, menos corada, estando presente (sexo feminino), estando ausente (sexo masculino).","ordem":5,"idAlternativa":"d9d05a54-a18c-52ca-a007-9ff2ce768817"}],"gabarito":"A","observacoes":[],"idQuestao":"05bb804c-531e-5b5a-a286-9a9212940957","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 18"},{"secao":"Odontologia Legal","numero":19,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Sabe-se da importância da dactiloscopia seja para fins civis ou criminais. É sempre relevante citar a classificação dos datilogramas, principalmente o sistema Vucetich. Considere o registro da seguinte notação: Mão direita: polegar (arco); indicador (arco); médio (presilha externa); anular (verticilo); mínimo (presilha interna). Mão esquerda: polegar (verticilo); indicador (presilha interna); médio (verticilo); anular (arco), mínimo (amputado). Assinale a opção que indica a fórmula dactiloscópica correta na ordem apresentada.","alternativas":[{"letra":"A","texto":"Série: A 1 3 4 2 / Secção: V 2 4 1 0.","ordem":1,"idAlternativa":"1861cb5b-f36d-52da-ae37-f36bf4dd1d2a"},{"letra":"B","texto":"Série: A 4 3 1 2 / Secção: V 2 1 4 0.","ordem":2,"idAlternativa":"caf73be9-cde9-5c70-b857-1e559c82bfb5"},{"letra":"C","texto":"Série: A 1 3 4 2 / Secção: V 2 4 1 X.","ordem":3,"idAlternativa":"4221e0a9-4d7f-5c50-b64f-a6ff7dbf255f"},{"letra":"D","texto":"Secção: A 4 3 1 2/ Série: V 2 1 4 X.","ordem":4,"idAlternativa":"19507578-2ed6-5973-92be-8d57d5d1d86a"},{"letra":"E","texto":"Secção: 1 1 3 4 2 / Série: 4 2 4 1 0.","ordem":5,"idAlternativa":"4c4d1ec8-6ed2-5119-a985-408eb6d4eac5"}],"gabarito":"A","observacoes":[],"idQuestao":"ca712c5f-5654-5371-a576-22533c715b27","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 19"},{"secao":"Odontologia Legal","numero":20,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Na documentação odontológica, o prontuário do paciente é um requisito obrigatório e essencial dentro da rotina operacional de um cirurgião-dentista.Segundo Ramos e Calvielli (1991) deve haver um cuidado especial na elaboração de toda documentação relacionada ao paciente e o prontuário tem relevância:","alternativas":[{"letra":"A","texto":"clínica, administrativa e legal.","ordem":1,"idAlternativa":"3c1e896c-a438-51fb-a811-6cdc3874a197"},{"letra":"B","texto":"clínica, individual e legal.","ordem":2,"idAlternativa":"981d5f84-f70e-5bfb-b888-2e2b75eda0ed"},{"letra":"C","texto":"legal, epidemiológica e administrativa.","ordem":3,"idAlternativa":"55eb559c-8011-530f-b6cc-6fe9fb70ea23"},{"letra":"D","texto":"de praticabilidade, de classificabilidade e de unicidade.","ordem":4,"idAlternativa":"9ee644d8-3784-5e4b-abad-e99072ef471b"},{"letra":"E","texto":"ética, científica e epidemiológica.","ordem":5,"idAlternativa":"66a66385-2c5c-57b7-bde3-1ae093352612"}],"gabarito":"C","observacoes":[],"idQuestao":"7dc187ef-d744-5615-978c-237ee78acb98","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 20"},{"secao":"Odontologia Legal","numero":21,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Analise o registro a seguir: “Segundo o boletim de ocorrência, a vítima de 48 anos contou aos policiais que foi agredida com socos e chutes em uma discussão. Ela foi socorrida e levada ao pronto- socorro com ferimentos leves na cabeça e seis dentes quebrados. Em seguida, foi medicada e liberada. ” Tendo em vista o caso apresentado, a vítima, em decorrência da agressão, foi encaminhada para a perícia no IML. Ao exame pericial foi evidenciada a presença de uma fratura coronorradicular de grande extensão com perda significativa de estrutura dentária do incisivo central superior (21), que posteriormente foi extraído por um cirurgião dentista particular. Nos demais elementos (13,12,23) foram evidenciadas fraturas superficiais nos bordos incisais e, no elemento 22, fratura da coroa de cerâmica (prótese sobre implante da região 22). Devido à agressão, a vítima ficou afastada das suas atividades sociais e esportivas por mais de 30 dias. Considerando o que prevê o Código Penal Brasileiro em relação ao relato de caso, o mesmo remete à tipificação de lesão corporal do tipo","alternativas":[{"letra":"A","texto":"dano à coisa.","ordem":1,"idAlternativa":"168e20ae-6df4-5636-bbdf-794b8644158a"},{"letra":"B","texto":"lesão leve.","ordem":2,"idAlternativa":"7755f64e-a3f5-5e56-9289-fca24dd16e26"},{"letra":"C","texto":"lesão grave.","ordem":3,"idAlternativa":"852e241a-9dcd-5c57-aaff-8e8fd183c955"},{"letra":"D","texto":"lesão gravíssima com risco de vida.","ordem":4,"idAlternativa":"325e6e07-7780-5cf9-a454-6e748d8d34ea"},{"letra":"E","texto":"lesão leve com risco de vida.","ordem":5,"idAlternativa":"2a1784e6-d87a-5b1e-8a56-ca848ba8890c"}],"gabarito":"A","observacoes":[],"idQuestao":"1760b76f-7fd9-55b1-a091-61ea8a132200","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 21"},{"secao":"Odontologia Legal","numero":22,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Considerando as tipificações previstas no artigo 129 do código penal, relacione as situações expostas, originadas de um acidente de trânsito causado por motorista alcoolizado, com sua respectiva tipificação: 1- Lesão corporal leve. 2- Lesão corporal grave. 3- Lesão corporal gravíssima. ( ) Incapacidade para as atividades laborais não lucrativas por mais de 30 dias. ( ) Sufusão localizada na hemiface esquerda. ( ) Fratura dentária com exposição pulpar tendo perda estrutural maior que 2/3 da porção coronária do incisivo central superior direito. ( ) Sugilação localizada na hemiface direita. ( ) Queloides extensos na face (região frontal e hemiface direita). Assinale a opção que indica a relação correta na ordem apresentada.","alternativas":[{"letra":"A","texto":"2, 1, 2, 1 e 3.","ordem":1,"idAlternativa":"6e5a3c37-c256-58d9-a0bc-15fb7f6c353d"},{"letra":"B","texto":"1, 1, 2, 2 e 3.","ordem":2,"idAlternativa":"db21fe41-2841-5a73-bcc0-1d6e5ba1dea9"},{"letra":"C","texto":"3, 1, 1, 3 e 2.","ordem":3,"idAlternativa":"3572d579-2279-5b25-8cd4-eac1af5967ed"},{"letra":"D","texto":"2, 2, 2, 1 e 3.","ordem":4,"idAlternativa":"ff07d3fe-0ab6-5359-b3d0-0f4a26a3a2e8"},{"letra":"E","texto":"1, 1, 1, 2 e 3.","ordem":5,"idAlternativa":"96df1696-b033-5c5d-83f6-6b3a2dccce49"}],"gabarito":"B","observacoes":[],"idQuestao":"b7fbe35f-927f-5eca-93ac-4134d7a11ebc","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 22"},{"secao":"Odontologia Legal","numero":23,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"A análise e a descrição das marcas de mordidas deve respeitar a uma sequência de procedimentos. Com relação aos protocolos que podem ser adotados na coleta de evidências, analise as afirmativas a seguir. I.O registro e exame clínico intraoral completo pode incluir: saliva, língua e as condições periodontais do suspeito. II.A forma de registro mais usual das marcas na pele humana é a fotografia. III.Deve-se sempre descontaminar o local da mordida, antes de executar a fotografia e a moldagem. IV.A análise métrica consiste na mensuração de todas as estruturas relacionadas a mordida. Está correto o que se afirma em","alternativas":[{"letra":"A","texto":"I e II, apenas.","ordem":1,"idAlternativa":"d88a3eed-afcc-5589-ba10-6213d4e795a8"},{"letra":"B","texto":"I, II e IV, apenas.","ordem":2,"idAlternativa":"825c11ce-fcd3-5db1-8b85-e65daa727f46"},{"letra":"C","texto":"II e IV, apenas.","ordem":3,"idAlternativa":"fbb4b5f6-cf26-5740-b25f-055d040a02de"},{"letra":"D","texto":"III, apenas.","ordem":4,"idAlternativa":"2f260ab1-f8e3-517d-9593-0ea8972e12ec"},{"letra":"E","texto":"I e IV, apenas.","ordem":5,"idAlternativa":"88d8aeb1-3c2a-5431-9b7a-781587d94728"}],"gabarito":"C","observacoes":[],"idQuestao":"c7436cee-7562-5574-a77d-69c3cac93d1b","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 23"},{"secao":"Odontologia Legal","numero":24,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Em relação às definições relacionadas à asfixiologia forense, assinale V para a afirmativa verdadeira e F para a falsa. ( ) A tríade asfíxica consiste de sangue fluido escuro (exceto no afogamento), congestão polivisceral e equimose de Tardieu. ( ) São exemplos de asfixias produzidas por constrição do pescoço: enforcamento, esganadura e sufocação. ( ) A esganadura é identificada facialmente pela presença de estigmas ungueais ao redor do pescoço. As afirmativas são, respectivamente,","alternativas":[{"letra":"A","texto":"F, V e F.","ordem":1,"idAlternativa":"48a09e17-6b42-5e1a-9c48-f0ec307db690"},{"letra":"B","texto":"F, V e V.","ordem":2,"idAlternativa":"c5b0cafc-f9c5-55bd-b9be-378311402846"},{"letra":"C","texto":"V, F e V.","ordem":3,"idAlternativa":"b0a25001-a962-590c-81c3-0df2c4e31f3c"},{"letra":"D","texto":"F, F e V.","ordem":4,"idAlternativa":"ab18ee2e-b5a0-5c69-9131-bc1d9b3b271f"},{"letra":"E","texto":"V, V e F.","ordem":5,"idAlternativa":"8e5be700-a12d-5668-8dcf-5fcfbdcd70c0"}],"gabarito":"B","observacoes":[],"idQuestao":"57b731bd-c998-5300-8761-2d22c9fecec5","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 24"},{"secao":"Odontologia Legal","numero":25,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"A morte produzida por intoxicação por monóxido de carbono, provoca alterações em algumas estruturas do corpo. Analise as afirmativas a seguir com relação às condições observadas na perinecroscopia nesse caso. I. Pele e mucosas apresentam cor carmim característica ou uma nuança levemente cianótica. II. Espectroscopia mostrará as bandas de absorção características da carboxihemoglobina. III. Pele corrugada em escroto, aréola mamária epênis. IV. Manchas de Tardieu nas serosas pleurais. É correto o que se afirma em","alternativas":[{"letra":"A","texto":"I, II e III, apenas.","ordem":1,"idAlternativa":"ed953635-e149-5a95-a822-e065f77dbd93"},{"letra":"B","texto":"I, II e IV, apenas.","ordem":2,"idAlternativa":"cb2f6f9c-4735-5b2c-965e-241821b438f3"},{"letra":"C","texto":"II e IV, apenas.","ordem":3,"idAlternativa":"7af65c07-d0c4-5ed6-a02b-6776cd6a96f2"},{"letra":"D","texto":"I e II, apenas.","ordem":4,"idAlternativa":"08f33f0f-0c51-599f-a0c2-32c42c69a0da"},{"letra":"E","texto":"I e IV, apenas.","ordem":5,"idAlternativa":"8a180a5b-1cc3-5d2e-979e-ea165cc9c0f8"}],"gabarito":"A","observacoes":[],"idQuestao":"39e9353b-e5d8-547b-9cb7-6e4ed2c8ec0c","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 25"},{"secao":"Odontologia Legal","numero":26,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Considerando os tipos de perícias realizadas no foro criminal e no foro civil, assinale V para a afirmativa verdadeira e F para a falsa. ( ) Os peritos ad hoc são peritos concursados que exercem a função por atribuição de cargo público. ( ) Na falta de peritos não oficiais habilitados, a autoridade judiciária ou policial poderá nomear peritos leigos que apresentem grau de experiência que possibilite o atendimento à requisição legal. ( ) Peritos odontolegistas, médicos legistas e peritos criminais prestam, antes de realizar a perícia, o compromisso de bem e fielmente desempenhar o encargo a eles confiado, devendo assinar, juntamente com a autoridade que estiver presente, o auto de exame lavrado pelo escrivão. As afirmativas são, respectivamente,","alternativas":[{"letra":"A","texto":"F, V e F.","ordem":1,"idAlternativa":"2a1fbadf-8920-5de2-97bb-3456ab439d8c"},{"letra":"B","texto":"F, V e V.","ordem":2,"idAlternativa":"83952fbe-1a63-556f-910c-71e5b0a44ba4"},{"letra":"C","texto":"V, F e V.","ordem":3,"idAlternativa":"4bf6a34b-26e6-5baf-9ab2-58d03f8e9cce"},{"letra":"D","texto":"F, F e V.","ordem":4,"idAlternativa":"93bd4bc1-464c-560a-b0a4-2045f122484e"},{"letra":"E","texto":"V, V e F.","ordem":5,"idAlternativa":"26f1cdf1-0796-57a0-b002-c7419931c36f"}],"gabarito":"C","observacoes":[],"idQuestao":"6135cd54-cf38-5bb2-bd11-459267de1363","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 26"},{"secao":"Odontologia Legal","numero":27,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Em relação à identificação por meio do DNA, analise as afirmativas a seguir: I.O DNA apresenta características únicas para cada indivíduo, com exceção dos gêmeos idênticos ou univitelinos. II.A escolha do método para exame do DNA, dependerá da qualidade e quantidade de DNA que possa ser recuperado do material de prova e da amostra de referência. III.Quando não se conta com volumes apreciáveis de DNA, a técnica do PCR é o procedimento de escolha devido seu alto nível de sensibilidade. Está correto o que se afirma em","alternativas":[{"letra":"A","texto":"I, II e III.","ordem":1,"idAlternativa":"5a88f5b4-e887-5d71-a89e-3df04e208386"},{"letra":"B","texto":"I e III, apenas.","ordem":2,"idAlternativa":"57aedd53-906b-505c-84b9-3e7e6a664cbe"},{"letra":"C","texto":"II e III, apenas.","ordem":3,"idAlternativa":"7e3586b0-34ea-520f-a7c7-ef4ed24268b6"},{"letra":"D","texto":"I e II, apenas.","ordem":4,"idAlternativa":"a85fd1d1-706d-527a-8764-91213503ee4a"},{"letra":"E","texto":"II, apenas.","ordem":5,"idAlternativa":"f9778a01-4223-57c4-a5dd-f14fcd64b8ae"}],"gabarito":"A","observacoes":[],"idQuestao":"bbad7b25-8d40-5b59-a79a-94b5fdf6a521","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 27"},{"secao":"Odontologia Legal","numero":28,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"A estrutura e herança do DNA mitocondrial possui","alternativas":[{"letra":"A","texto":"dupla-hélice circular e é herdado da mãe.","ordem":1,"idAlternativa":"d401fef1-545d-58f1-b02b-6563f0207ac0"},{"letra":"B","texto":"dupla-hélice linear e é herdado da mãe.","ordem":2,"idAlternativa":"37573194-60ac-516a-a0fe-d4fe0583ca4c"},{"letra":"C","texto":"dupla-hélice circular e é herdado do pai e da mãe.","ordem":3,"idAlternativa":"c13ae549-84f7-5156-8854-0a73f0b4b9bf"},{"letra":"D","texto":"dupla-hélice circular e é herdado dopai.","ordem":4,"idAlternativa":"1e648877-edcd-5e26-aa2a-103c9c299b9a"},{"letra":"E","texto":"dupla-hélice linear e é herdado do pai.","ordem":5,"idAlternativa":"be4e78f7-e514-5104-ac47-3eec984d71df"}],"gabarito":"B","observacoes":[],"idQuestao":"cc754f49-5547-52e3-a69c-d3a925fffd6e","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 28"},{"secao":"Odontologia Legal","numero":29,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"Em relação aos aspectos genéticos, a espécie humana possui 46 cromossomos (23 pares) dos quais dois (um par) diferem dos demais. Com relação ao tema, analise as afirmativas a seguir. I. Os gonossomos são responsáveis pelas característicassexuais. II. Os autossomos são responsáveis pelas características somáticas. III. Um complexo cromossômico (constância de número, forma e dimensões) recebe o nome de cariograma. Está correto o que se afirma em","alternativas":[{"letra":"A","texto":"I, e III, apenas.","ordem":1,"idAlternativa":"e4c469ff-baa3-5f8e-a510-82b3699921a7"},{"letra":"B","texto":"I e II, apenas.","ordem":2,"idAlternativa":"12d3c0d5-8c8c-529b-9a30-a2c0a97293d2"},{"letra":"C","texto":"II e III, apenas.","ordem":3,"idAlternativa":"cfbf4a8d-89d8-54d5-80c1-2c5ba549a126"},{"letra":"D","texto":"I, apenas.","ordem":4,"idAlternativa":"a6718a4b-e859-5ec8-9c07-0bbd60b67900"},{"letra":"E","texto":"II, apenas.","ordem":5,"idAlternativa":"05d7765e-96c5-5483-98c7-992684db0ebe"}],"gabarito":"A","observacoes":[],"idQuestao":"7e963563-4f82-5ff9-be76-346683e3b1d8","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 29"},{"secao":"Odontologia Legal","numero":30,"orgao":"Polícia Civil do Amazonas","cargo":"PERITO ODONTOLOGISTA","ano":2021,"enunciado":"No processo de identificação, quando o perito não conta com volumes apreciáveis de DNA (sangue fresco ou saliva) que possa ser recuperado do material de prova e da amostra biológica de referência, deve-se optar por um método com alto nível de sensibilidade. Dentre as opções apresentadas, assinale a que seria mais adequada para casos com amostras exíguas.","alternativas":[{"letra":"A","texto":"Reação em cadeia da polimerase de microssatélites (PCR).","ordem":1,"idAlternativa":"6ebf3222-416c-5b20-bd1c-9bbb602053f5"},{"letra":"B","texto":"Polimorfismo de fragmento amplificado (AmpFLP).","ordem":2,"idAlternativa":"21ef60ae-050c-5db5-aef0-65742c378f7e"},{"letra":"C","texto":"Tipagem de comprimento especifico (TLS).","ordem":3,"idAlternativa":"1bce46f7-1d1c-5c9d-979d-d2aa2a0e00e6"},{"letra":"D","texto":"Polimorfismo de tamanho de fragmentos de restrição (RFLPs).","ordem":4,"idAlternativa":"57c30037-d171-5ea6-8a45-5e7d4d66432b"},{"letra":"E","texto":"Fingerprint.","ordem":5,"idAlternativa":"0ddf1948-f35e-5b5e-b0ef-75c4b6fc6206"}],"gabarito":"B","observacoes":[],"idQuestao":"a994118d-1a8d-5285-8833-39c8e77b4f19","idDisciplina":"034843fd-504e-5b78-af25-b9fa1a0651a6","idConcurso":"978b64f7-4777-56c7-a922-fc8a4b5a58f5","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Odontologia Legal | Questão 30"},{"secao":"Biossegurança","numero":1,"orgao":"Prefeitura de Areia-PB","cargo":"ODONTOLÓGO – PSF","ano":2022,"enunciado":"Na prática odontológica é comum a manipulação de sangue e outros fluidos orgânicos, que são as principais vias de transmissão do HIV e dos vírus da Hepatite B e C. São procedimentos para diminuir o risco de transmissão de doenças por meio de sangue e fluidos orgânicos, EXCETO:","alternativas":[{"letra":"A","texto":"Desprezar todo material perfurocortante em recipiente resistente à perfuração e com tampa.","ordem":1,"idAlternativa":"1080f770-7170-592c-9ec8-8714de177642"},{"letra":"B","texto":"Ter a máxima atenção durante a realização dosprocedimentos.","ordem":2,"idAlternativa":"f7483324-4603-568f-aac8-d552a6d74465"},{"letra":"C","texto":"Não reencapar, entortar, quebrarou retirar agulhas das seringas com as mãos.","ordem":3,"idAlternativa":"1194047e-503a-550a-8bc8-273221b0e17c"},{"letra":"D","texto":"Não utilizar agulhas para fixar papéis.","ordem":4,"idAlternativa":"610cfbef-5147-570d-bab5-000605d7bbd0"},{"letra":"E","texto":"Utilizar os dedos como anteparo durante a realização de procedimentos que envolvam instrumentais perfurocortantes.","ordem":5,"idAlternativa":"c327da21-73e3-575a-8341-66ea930b83b1"}],"gabarito":"E","observacoes":[],"idQuestao":"d14a43d8-0d1e-5290-bd27-91892fcffdcc","idDisciplina":"25da685e-51de-5026-b848-cef8fb688c6f","idConcurso":"b65a1e91-7e51-5d2f-bcc7-bd912e8baf6b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Biossegurança | Questão 1"},{"secao":"Biossegurança","numero":2,"orgao":"Prefeitura de Areia-PB","cargo":"ODONTOLÓGO – PSF","ano":2022,"enunciado":"O ambiente odontológico, pelas suas particularidades, possibilita que o ar seja uma via potencial de transmissão de microrganismos, por meio de gotículas e aerossóis.São procedimentos que visam a diminuição do risco de transmissão aérea, EXCETO:","alternativas":[{"letra":"A","texto":"Usar sugadores de alta potência.","ordem":1,"idAlternativa":"239e087e-462a-5f5a-bc6e-66b7e05b579a"},{"letra":"B","texto":"Usar dique de borracha, sempre que o procedimento permitir.","ordem":2,"idAlternativa":"ac56c950-6bcd-510b-aaae-0c9e2f7b6314"},{"letra":"C","texto":"Sempre usar a seringa tríplice na sua forma spray, acionando água e ar ao mesmo tempo.","ordem":3,"idAlternativa":"8083e431-ca44-52eb-b2a3-d12a2b0158bc"},{"letra":"D","texto":"Higienizar previamente a boca do paciente mediante escovação e/ou bochecho com antisséptico.","ordem":4,"idAlternativa":"643d0530-3e7c-5af0-8e6d-b2708a12bd5f"},{"letra":"E","texto":"Manter o ambiente ventilado.","ordem":5,"idAlternativa":"2fc5bd72-e452-5e16-8713-93e91a75aff1"}],"gabarito":"C","observacoes":[],"idQuestao":"017e2a09-59dc-5377-bb4a-f237d25ae259","idDisciplina":"25da685e-51de-5026-b848-cef8fb688c6f","idConcurso":"b65a1e91-7e51-5d2f-bcc7-bd912e8baf6b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Biossegurança | Questão 2"},{"secao":"Biossegurança","numero":3,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"O paramonoclorofenol (PMC) foi introduzido na Odontologia por Walkhoff, em 1891. Sua utilização é baseada nas propriedades antissépticas do fenol e do íon cloro. Sobre o PMC, não podemos afirmar que:","alternativas":[{"letra":"A","texto":"Desempenha sua atividade antimicrobiana pelo contato direto do líquido com os microrganismos ou pela ação dos vapores liberados.","ordem":1,"idAlternativa":"648b7155-31b0-59f6-9c88-e8705e07ec53"},{"letra":"B","texto":"Possui alta tensão superficial e não atua muito bem por capilaridade no interior dos túbulos dentinários.","ordem":2,"idAlternativa":"4c3b4bd5-2b7a-5570-a6fa-dd8ae82d5bf0"},{"letra":"C","texto":"A cânfora combinada com o PMC funciona como um veículo e reduz o potencial irritante do PMC","ordem":3,"idAlternativa":"2c430735-1b55-5849-a80e-496980622ace"},{"letra":"D","texto":"Sua ação quando aplicado em uma mecha de algodão na câmara pulpar visando um efeito antimicrobiano no canal é efêmera e dura no máximo 48 horas.","ordem":4,"idAlternativa":"2742000f-f34a-54fc-9407-939da41c29b8"}],"gabarito":"B","observacoes":[],"idQuestao":"31cde3cc-5fb2-5688-9b41-87537aaadf7d","idDisciplina":"25da685e-51de-5026-b848-cef8fb688c6f","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Biossegurança | Questão 3"},{"secao":"Biossegurança","numero":4,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"A imunização evita doenças, incapacidade e mortes por enfermidades preveníveis por vacinas. Sobre esse tema, é correto afirmar:","alternativas":[{"letra":"A","texto":"A vacina contra tétano confere imunidade por tempo indeterminado, não sendo necessário dose de reforço.","ordem":1,"idAlternativa":"5d282b98-7962-52fb-9681-16897e6a3653"},{"letra":"B","texto":"A vacina contra dengue protege contra a apresentação hemorrágica e já está contemplada no esquema vacinal básico do SUS.","ordem":2,"idAlternativa":"139d3443-4ae3-5a35-8052-0110111f417f"},{"letra":"C","texto":"A vacina que protege contra o Papilomavírus está disponível apenas para meninas em idade fértil e que já tiveram a sua primeira menarca.","ordem":3,"idAlternativa":"c20ed84b-3022-514b-8e87-e6792fac0fb4"},{"letra":"D","texto":"A vacina pentavalente engloba as vacinas contra difteria, tétano, sarampo, caxumba e rubéola, devendo ser administrada por via intramuscular em 2 doses de reforço.","ordem":4,"idAlternativa":"a1c252fe-148f-545b-a54d-5d7dc7bfa2e3"},{"letra":"E","texto":"A vacina contra a febre amarela é indicada para residentes e/ou viajantes que se destinam às Áreas com Recomendação de Vacinação, com pelo menos 10 dias de antecedência da data da viagem, tempo necessário para que a vacina confira proteção contra a infecção.","ordem":5,"idAlternativa":"c1a1e567-1113-5311-95b0-f8c920ed0a78"}],"gabarito":"E","observacoes":[],"idQuestao":"e2a11555-8be4-5458-8513-c214ccd46c13","idDisciplina":"25da685e-51de-5026-b848-cef8fb688c6f","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Biossegurança | Questão 4"},{"secao":"Biossegurança","numero":5,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"De acordo com Souza (2021), a Resolução da Diretoria Colegiada – RDC nº 222/2018 veio regulamentar as boas práticas de gerenciamento dos Resíduos de Serviços de Saúde (RSS) e se refere a todos os serviços geradores de RSS, cujas atividades envolvam qualquer etapa do gerenciamento, sejam instituições públicas ou privadas, civis ou militares, com fins filantrópicos, incluindo as que exercem ações de ensino e pesquisa. Considerando tal resolução, lâminas de bisturi, brocas, limas endodônticase demais materiais perfurocortantes são classificados como resíduos do grupo:","alternativas":[{"letra":"A","texto":"A","ordem":1,"idAlternativa":"8eeab67e-9c12-5c05-b8a7-3c6c843f2b98"},{"letra":"B","texto":"B","ordem":2,"idAlternativa":"317db3ea-904d-54e9-ac7f-357c97dca1eb"},{"letra":"C","texto":"C","ordem":3,"idAlternativa":"11292a3c-2a67-5a9f-9a97-2632721a9bd1"},{"letra":"D","texto":"D","ordem":4,"idAlternativa":"5b3bc451-bd17-5c15-b08b-3756da1f32e7"},{"letra":"E","texto":"E","ordem":5,"idAlternativa":"de215d7e-76a9-56e2-9f1c-f2fecf7d5634"}],"gabarito":"B","observacoes":[],"idQuestao":"82fb10ea-5d77-5e6d-a5b8-28458291ecef","idDisciplina":"25da685e-51de-5026-b848-cef8fb688c6f","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Biossegurança | Questão 5"},{"secao":"Biossegurança","numero":6,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"A respeito de biossegurança em Odontologia, assinale a afirmativa correta.","alternativas":[{"letra":"A","texto":"A antissepsia do paciente deve ser iniciada pela região intrabucal, prosseguindo para a pele da região peribucal.","ordem":1,"idAlternativa":"62a2802c-8fbb-5d6d-b79e-8e1c7545b222"},{"letra":"B","texto":"Os processos de assepsia, quando executados em superfícies inanimadas, denominam-se desinfecção, podendo ser realizados com álcool.","ordem":2,"idAlternativa":"2ccb83c9-2153-580a-b506-6ec81b64d076"},{"letra":"C","texto":"A desinfecção de alto nível causa inativação de todas as formas de vida microbiana, incluindo esporos, vírus, bactérias e fungos.","ordem":3,"idAlternativa":"da3d2565-7770-5a37-8d6c-2f4d5bb9c51d"},{"letra":"D","texto":"Os resíduos odontológicos potencialmente infectantes devem ser descartados em caixas sólidas identificadas com a cor cinza.","ordem":4,"idAlternativa":"79161976-23aa-547f-a91b-217032bfb8fa"},{"letra":"E","texto":"Perfurador de Ainsworth é considerado material crítico no procedimento de desinfecção.","ordem":5,"idAlternativa":"061d547a-51be-5bbc-aa2f-cfe2fe343fbf"}],"gabarito":"B","observacoes":[],"idQuestao":"6ab436bb-e514-5b42-b014-f97df30cf248","idDisciplina":"25da685e-51de-5026-b848-cef8fb688c6f","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Biossegurança | Questão 6"},{"secao":"Biossegurança","numero":7,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"A ergonomia é fundamental para o bem-estar do profissional de saúde no decorrer de sua carreira. Sobre ergonomia, assinale a afirmativa correta.","alternativas":[{"letra":"A","texto":"A área útil de trabalho do profissional compreende um raio de 1,5 m, sendo o eixo a cabeça do paciente e onde devem estar organizados todos os itens que serão utilizados dentro da boca do paciente e também os dois mochos odontológicos: o do dentista e o do auxiliar.","ordem":1,"idAlternativa":"061c757d-733f-5305-9916-71a7683c932c"},{"letra":"B","texto":"Um odontólogo destro deve ocupar a posição entre 1h e 4h para trabalhar de forma ergonômica em um consultório, segundo as normas de ergonomia padronizadas pela FDI e ISO (Federação Dentária Internacional e International Organization for Standardization).","ordem":2,"idAlternativa":"15bb3c9a-f682-5499-bc64-74bfc4a31bcf"},{"letra":"C","texto":"Ao realizar trabalhos na mandíbula, o cabeçote da cadeira odontológica deve ser posicionado para baixo; para a maxila, ele deve ser acomodado para cima, estando a cadeira odontológica na posição horizontal.","ordem":3,"idAlternativa":"7b113243-1e48-56e3-8897-2665c7aa08fb"},{"letra":"D","texto":"O trabalho a quatro mãos pode representar um fator fundamental para a manutenção da posição ergonomicamente correta, na medida em que diminui a necessidade de movimentação do operador.","ordem":4,"idAlternativa":"45e7f0b9-64fe-5f51-8771-fd93bbd8973e"},{"letra":"E","texto":"Durante os procedimentos odontológicos, operador e auxiliar devem estar sentados, mantendo as pernas em 90° com as plantas dos pés apoiadas nos pés do mocho.","ordem":5,"idAlternativa":"a677ecb8-7774-5fab-9625-1b4fdc7aaaa7"}],"gabarito":"D","observacoes":[],"idQuestao":"60f498fe-47d4-54f7-9563-f726135cb8db","idDisciplina":"25da685e-51de-5026-b848-cef8fb688c6f","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Biossegurança | Questão 7"},{"secao":"Biossegurança","numero":8,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"A exposição ao risco de contaminação e disseminação do Sars-CoV-2 no contexto da assistência odontológica é elevada. A esse respeito, marque para as afirmativas verdadeiras e F para as falsas. ( ) Alguns equipamentos rotatórios geram aerossóis e gotículas muito pequenas que permanecem suspensas no ar por per odos mais longos e colaboram com a disseminação da carga viral no ambiente. ( ) As medidas a serem tomadas na atenção odontológica em razão da pandemia envolvem não somente o reforço a todos os protocolos de biossegurança como também a redução do n mero de consultas e otimização do tempoclínico. ( ) Fazem parte das condições e fatores de risco s formas graves da doença identificados pelo Ministério da Sa de tabagismo, obesidade, miocardiopatias de diferentes etiologias, hipertensão arterial e imunodepressão. Assinale a sequência correta.","alternativas":[{"letra":"A","texto":"V, F, F","ordem":1,"idAlternativa":"7c1bbcf4-62fc-58d0-8271-c938d1115277"},{"letra":"B","texto":"F, V, F","ordem":2,"idAlternativa":"ce5be835-d390-5b25-974e-37cd5585853a"},{"letra":"C","texto":"F, F, V","ordem":3,"idAlternativa":"b2c47dfe-8f40-51a6-8008-361880b39687"},{"letra":"D","texto":"V, V, F","ordem":4,"idAlternativa":"ee2d6cdd-1400-5ae4-aed8-8a26e2b68f15"},{"letra":"E","texto":"V, V, V","ordem":5,"idAlternativa":"7af994d3-253b-52de-a692-16b1566767a7"}],"gabarito":"B","observacoes":[],"idQuestao":"48741f0d-4158-599b-b187-512bca6aaae9","idDisciplina":"25da685e-51de-5026-b848-cef8fb688c6f","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Biossegurança | Questão 8"},{"secao":"Dentística","numero":1,"orgao":"Prefeitura de Areia-PB","cargo":"ODONTOLÓGO – PSF","ano":2022,"enunciado":"Na Odontologia, o conhecimento da nomenclatura das cavidades é fundamental para a compreensão do preparo cavitário. No que diz respeito às classificações complementares à classificação artificial de Black, considera-se o preparo “shot gun” ou “tiro de espingarda”:","alternativas":[{"letra":"A","texto":"Pré-molares inferiores - quando a lesão não atingiu as estruturas de reforço do esmalte, ponte de esmalte e cristas marginais.","ordem":1,"idAlternativa":"68f4d01c-78d3-5b62-9a02-7c4c0f35a0e3"},{"letra":"B","texto":"Pré-molares e molares – quando apenas o sulco principal foi atingido pela cárie.","ordem":2,"idAlternativa":"abb15e45-2029-5379-9291-0ce3bb9a6503"},{"letra":"C","texto":"Pré-molares superiores e inferiores - quando apenas a face proximal cariada é incluída na preparação, sem nenhum envolvimento da superfícieoclusal.","ordem":3,"idAlternativa":"6c0ee14a-6dbe-5c4c-be0f-576a065b87f3"},{"letra":"D","texto":"Pré-molares e molares – quando apenas a face proximal é envolvida, preservando a crista marginal.","ordem":4,"idAlternativa":"fec8a922-206e-5ed4-84c7-d503097b4416"},{"letra":"E","texto":"Molares inferiores - minicavidades nas superfícies oclusais dos molares.","ordem":5,"idAlternativa":"25d84bc6-6419-5bd9-bc13-3aa0847ceb13"}],"gabarito":"E","observacoes":[],"idQuestao":"46bfb9da-b040-51d6-941d-3175e4fd8a5c","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"b65a1e91-7e51-5d2f-bcc7-bd912e8baf6b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 1"},{"secao":"Dentística","numero":2,"orgao":"Prefeitura de Areia-PB","cargo":"ODONTOLÓGO – PSF","ano":2022,"enunciado":"O preparo de cavidades, do ponto de vista terapêutico, é o tratamento biomecânico da cárie e de outras lesões dos tecidos duros do dente, de forma que as estruturas remanescentes possam receber uma restauração que as proteja, seja resistente e previna a reincidência de cárie. Sobre procedimentos do preparo de uma cavidade,de acordo com Black, considera-se forma de “acabamento das paredes de esmalte”:","alternativas":[{"letra":"A","texto":"Remoção dos prismas de esmalte fragilizados, pelo alisamento das paredes internas de esmalte da cavidade, ou no acabamento adequado do ângulo cavossuperficial.","ordem":1,"idAlternativa":"31b9a8f0-8a85-50a5-9f02-10151a30b2f0"},{"letra":"B","texto":"Etapa que visa a possibilitar a instrumentação adequada da cavidade e a inserção do material restaurador.","ordem":2,"idAlternativa":"9f9b32cf-6ce7-5d80-8b43-468f583dd88b"},{"letra":"C","texto":"Forma dada à cavidade para torná-la capaz de firmar a restauração, evitando o seu deslocamento.","ordem":3,"idAlternativa":"8b53c31a-5284-5a15-988a-780d0fba1a16"},{"letra":"D","texto":"Característica dada à cavidade para que as estruturas remanescentes e a restauração sejam capazes de suportar as forçasmastigatórias.","ordem":4,"idAlternativa":"2ff96f43-817f-5336-8df0-5d34ff1f8644"},{"letra":"E","texto":"Remoção de partículas remanescentes das paredes cavitárias, possibilitando a colocação do material restaurador em uma cavidade completamente limpa.","ordem":5,"idAlternativa":"7a3c8143-0776-5c61-802d-77ce56da3da1"}],"gabarito":"A","observacoes":[],"idQuestao":"8a15d25c-825e-51ba-973e-68b764635a32","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"b65a1e91-7e51-5d2f-bcc7-bd912e8baf6b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 2"},{"secao":"Dentística","numero":3,"orgao":"Prefeitura de Areia-PB","cargo":"ODONTOLÓGO – PSF","ano":2022,"enunciado":"O complexo dentina-polpa é uma entidade embriológica e funcional. O ponto crítico da proteção do complexo dentina-polpa está no correto diagnóstico clínico da condição pulpar e na escolha do tipo de tratamento conservador mais indicado para cada situação clínica. A esse respeito, considera-se “capeamento pulpardireto”:","alternativas":[{"letra":"A","texto":"Remoção da polpa coronária em sua totalidade para então revestí-la com material biocompatível, como o hidróxido de cálcio.","ordem":1,"idAlternativa":"ab26e840-4f88-5760-b5c0-46827d10b8ee"},{"letra":"B","texto":"Técnica pulpar não-vital que consiste na preparação dos canais radiculares e posterior obturação dos mesmos com um material reabsorvível.","ordem":2,"idAlternativa":"da0bb6c6-f358-5605-9c7c-9b40aa14d3f9"},{"letra":"C","texto":"Remoção da parte coronária da polpa, evitando-se o risco de contaminação e a manutenção do processo inflamatório.","ordem":3,"idAlternativa":"236b63fb-af94-54d1-8938-1b1a15153a0d"},{"letra":"D","texto":"Uso de um revestimento biológico, geralmente o hidróxido de cálcio, e mais recentemente, o MTA, sobre polpas expostas acidentalmente.","ordem":4,"idAlternativa":"1e9ba441-cb27-5c61-a2ac-cb00d83dee87"},{"letra":"E","texto":"Procedimento realizado em dentes decíduos que demonstram inflamação crónica ou necrose para além da polpa coronária.","ordem":5,"idAlternativa":"31722e96-f780-5370-ac9c-8e2696247dc9"}],"gabarito":"D","observacoes":[],"idQuestao":"669ba699-ab9b-5fde-ae42-b85d52736b6b","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"b65a1e91-7e51-5d2f-bcc7-bd912e8baf6b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 3"},{"secao":"Dentística","numero":4,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"O traumatismo dentário é uma situação de urgência. Muitas vezes, porém, o atendimento que deveria ser imediato não é efetivamente realizado devido à falta de conhecimento afetando o seu prognóstico. A esse respeito, analise as afirmativas a seguir. I. Consideram-se lesões traumáticas dentárias desde uma simples fratura em esmalte até a perda definitiva do elemento dentário. II. O atendimento de urgência nos traumatismos dentários pode contribuir para um melhor prognóstico do caso. III. A negligência em relação ao tratamento odontológico após o traumatismo dentário pode ter como consequência alteração de cor, mobilidade, alteração de posição na arcada dentária, sintomatologia dolorosa, sensibilidade, reabsorções radiculares ou óssea, necrose e perda do elemento dental. IV. As consequências das alterações de traumas não tratados podem acarretar dificuldades de convívio social, baixa autoestima das crianças e problemas de relacionamentos futuros, principalmente pela ausência do elemento dentário. Estão corretas as afirmativas","alternativas":[{"letra":"A","texto":"I e II, apenas.","ordem":1,"idAlternativa":"2342342d-0b3d-58cc-9d71-ecb6dcba8d07"},{"letra":"B","texto":"I, II, III e IV.","ordem":2,"idAlternativa":"9f98689e-1421-544f-818b-9cfe08f7819f"},{"letra":"C","texto":"II e III, apenas.","ordem":3,"idAlternativa":"9c667443-06d4-50f0-a83b-53aede4ed235"},{"letra":"D","texto":"I, III e IV, apenas.","ordem":4,"idAlternativa":"b670a6ca-ba10-5166-a0e0-9ee71c99d2bb"}],"gabarito":"B","observacoes":[],"idQuestao":"609cecee-d62d-5f50-8600-dd1c34310ab6","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 4"},{"secao":"Dentística","numero":5,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"Sobre as proteções do complexo dentinopulpar, analise as afirmativas a seguir. I. A proteção do complexo dentinopulpar consiste na aplicação de um ou mais agentes protetores, tanto em tecido dentinário quanto sobre a polpa que sofreu exposição, a fim de manter ou recuperar a vitalidade desses órgãos. II. A idade do paciente, a condição pulpar e a profundidade da cavidade são aspectos que devem ser considerados juntamente com o tipo de material restaurador para que se obtenha o real objetivo dessa proteção. III. As proteções pulpares indiretas representam a aplicação de agentes seladores, forradores e / ou bases protetoras nas paredes cavitárias com o objetivo de proteger o complexo dentinopulpar dos diferentes tipos de injúrias, manter a vitalidade pulpar, inibir o processo carioso, reduzir a microinfiltração e estimular a formação dedentina esclerosada, reacional e / ou reparadora. IV. As proteções diretas caracterizam-se pela aplicação de um agente protetor diretamente sobre o tecido pulpar exposto, com a finalidade de manter sua vitalidade e consequentemente promover o restabelecimento da polpa, estimular o desenvolvimento de nova dentina e proteger a polpa de irritações adicionais posteriores. Estão corretas as afirmativas","alternativas":[{"letra":"A","texto":"I e II, apenas.","ordem":1,"idAlternativa":"1e2e8465-eabc-53a6-8bb3-063927aaddc3"},{"letra":"B","texto":"III e IV, apenas.","ordem":2,"idAlternativa":"8510fd80-edf5-577d-bd55-fc615af99939"},{"letra":"C","texto":"I, II e III, apenas.","ordem":3,"idAlternativa":"47de8659-5eb9-5e24-9ea1-e6f97ebed7be"},{"letra":"D","texto":"I, II, III e IV.","ordem":4,"idAlternativa":"c0e69d82-2313-50ae-831e-e11e2e2fe242"}],"gabarito":"D","observacoes":[],"idQuestao":"c1a7cc15-a511-540e-b067-b599dbef7d23","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 5"},{"secao":"Dentística","numero":6,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"Os cimentos de ionômero de vidro têm aplicação bastante variada na odontologia. A grande aceitação desse material no meio odontológico deve-se basicamente às suas importantes propriedades. Analise as propriedades a seguir e marque V para as verdadeiras e F para as falsas: ( ) Adesividade às estruturas ósseas. ( ) Biocompatibilidade ao complexo dentinopulpar. ( ) Resistência suficiente como agente protetor. ( ) Ação anticariogênica pela liberação do flúor. ( ) Liberação de flúor para os dentes circunjacentes. Assinale a alternativa que contém a sequência CORRETA, considerando as propriedades de cima para baixo.","alternativas":[{"letra":"A","texto":"F, V, V, V, V.","ordem":1,"idAlternativa":"0c00a0be-6015-5352-9832-b1a4720c2c9f"},{"letra":"B","texto":"V, V, V, V, V.","ordem":2,"idAlternativa":"a1490e25-1638-55d1-b25e-83258f4fc49b"},{"letra":"C","texto":"V, V, V, V, F.","ordem":3,"idAlternativa":"19c56c8e-96d0-5843-a062-225457ff8a10"},{"letra":"D","texto":"F, V, V, V, F.","ordem":4,"idAlternativa":"39c23520-7db8-5879-abf7-6a561193d702"},{"letra":"E","texto":"F, V, F, V, F.","ordem":5,"idAlternativa":"94d889f6-c050-53ea-b6f2-9e9aabd7e1ef"}],"gabarito":"A","observacoes":[],"idQuestao":"b8613787-711c-58bc-9844-abe772a621c7","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 6"},{"secao":"Dentística","numero":7,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"Os produtos à base de hidróxido de cálcio são bastante utilizados na clínica odontológica. Analise as afirmativas a seguir, considerando as propriedades do hidróxido de cálcio, e marque V para as verdadeiras e F para as falsas. ( ) Estimula a formação da dentina reparadora. ( ) Protege a polpa contra estímulos termelétricos. ( ) Possui pH altamente ácido. ( ) Possui pH > 12. ( ) Possui ação antibacteriana. Assinale a alternativa que contém a sequência CORRETA, considerando as afirmativas de cima para baixo.","alternativas":[{"letra":"A","texto":"V, V, F, F, V.","ordem":1,"idAlternativa":"7a384760-be48-530b-bc9f-9cb02eac2d07"},{"letra":"B","texto":"F, F, V, V, V.","ordem":2,"idAlternativa":"8b9e9a54-5d0f-57b9-9270-8b20093cd57c"},{"letra":"C","texto":"V, V, F, V, V.","ordem":3,"idAlternativa":"927200c2-73d9-5378-89ce-99a859bf5d01"},{"letra":"D","texto":"V, F, V, V, F.","ordem":4,"idAlternativa":"99b8b313-579c-555a-9e46-36d0ddc2e721"},{"letra":"E","texto":"F, F, F, V, V.","ordem":5,"idAlternativa":"640463db-554e-5b65-a06d-548ba283e2c3"}],"gabarito":"C","observacoes":[],"idQuestao":"ed3c1073-736f-5a99-a881-bb522df9e69b","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 7"},{"secao":"Dentística","numero":8,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"Existem diferentes tipos de dentina, tecido mineralizado que constitui grande parte da estrutura dentária. Assinale a alternativa correta em relação adentina.","alternativas":[{"letra":"A","texto":"A dentina que reveste o interior dos túbulos dentinários é denominada dentina intertubular.","ordem":1,"idAlternativa":"bcff9bd9-26fb-530d-b2ad-69953d68769d"},{"letra":"B","texto":"A dentina do manto é a primeira a ser formada e está localizada imediatamente abaixo do esmalte ou cemento.","ordem":2,"idAlternativa":"94912da2-c008-51cb-9592-dbf30c361e90"},{"letra":"C","texto":"A dentina secundária é formada em resposta a estímulos externos. É depositada no lado pulpar, logo abaixo do local de injúria.","ordem":3,"idAlternativa":"d94cd1df-79bf-50ad-afa9-92ae83cff437"},{"letra":"D","texto":"A dentina reparadora é formada por odontoblastos que sobreviveram à injúria e exibem túbulos que são contínuos aos túbulos da dentinasecundária.","ordem":4,"idAlternativa":"80fd712b-dfc6-5f32-845d-615683617f84"},{"letra":"E","texto":"A dentina reacional é formada por células recém-diferenciadas semelhantes aos odontoblastos, que se originam a partir de células-tronco mesenquimais da polpa, que substituem os odontoblastos originais destruídos pelo estímulo externo. Os túbulos dentinários (se presentes) não são contínuos aos túbulos da dentina secundária.","ordem":5,"idAlternativa":"1a1642a5-087e-569b-86a1-32b913ee2c29"}],"gabarito":"B","observacoes":[],"idQuestao":"2a143bd1-7f9d-5e67-9f11-123ee02f3cd1","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 8"},{"secao":"Dentística","numero":9,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"As lesóes não cariosas são um desgaste de tecido dentário não relacionado à cárie. Analise as afirmativas abaixo em relação ao assunto. 1. A erosão é um tipo de lesão não cariosa que se caracteriza como um desgaste crónico e químico provocado por ácidos de origem bacteriana. 2. A abrasão é um tipo de lesão não cariosa que se caracteriza pelo desgaste mecánico da estrutura dental que ocorre por causa do contato repetido de um corpo estranho na superfície dental, como por exemplo, escovação inadequada, uso abusivode palito ou de escova interdental, e do consumo de drogas. 3. A abfração é um tipo de lesão não cariosa em que se observa perda de estrutura dental decorrente da flexão da coroa durante a função oclusal, geralmente associada a esforço excessivo em virtude de interferências oclusais, problemas ortodónticos, ausências dentárias ou parafunçóes. 4. As lesóes por abrasão apresentam-se em forma de cunha ou “V”, com contornos bemdelimitados e bordas afiadas. Assinale a alternativa que indica todas as afirmativas corretas.","alternativas":[{"letra":"A","texto":"São corretas apenas as afirmativas 1 e2.","ordem":1,"idAlternativa":"3536bbe3-88dc-5481-91e3-887575a94fce"},{"letra":"B","texto":"São corretas apenas as afirmativas 1 e 4.","ordem":2,"idAlternativa":"81cb0056-3740-557b-90a8-75690b9c82a7"},{"letra":"C","texto":"São corretas apenas as afirmativas 2 e 3.","ordem":3,"idAlternativa":"f3ca261d-cea7-5f53-a1a9-2fcde80dce05"},{"letra":"D","texto":"São corretas apenas as afirmativas 2 e 4.","ordem":4,"idAlternativa":"3cc08646-ed46-5fbf-956a-793d1a59ca51"},{"letra":"E","texto":"São corretas apenas as afirmativas 3 e 4.","ordem":5,"idAlternativa":"97d8f3de-9a26-5b2b-9b97-2af70fb42084"}],"gabarito":"C","observacoes":[],"idQuestao":"8950408f-fe5e-54ca-b3d3-def2a11b6811","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 9"},{"secao":"Dentística","numero":10,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"Numerosas alterações de desenvolvimento dos dentes podem ocorrer. Identifique abaixo as afirmativas verdadeiras ( V ) e as falsas ( F ) em relação ao assunto. ( ) A concrescência é a união, pelo cemento, de dois dentes formados, ligados ao longo das superfícies radiculares. ( ) Pacientes com displasia cleidocraniana podem apresentar hiperdontia. ( ) Os dentes afetados pela taurodontia tendema ser retangulares em sua forma e mostram câmaras pulpares aumentadas no sentido ápico-oclusal e uma bifurcação próxima ao ápice. ( ) A amelogênese imperfeita compreende um grupo complexo de condições que demonstram alterações de desenvolvimento na estrutura da dentina. Assinale a alternativa que indica a sequência correta, de cima para baixo.","alternativas":[{"letra":"A","texto":"V • V • V • F","ordem":1,"idAlternativa":"6537c1d9-b21d-5464-a3b4-5a4a4dc958bc"},{"letra":"B","texto":"V • V • F • F","ordem":2,"idAlternativa":"a95b2573-93b1-585e-9920-809bbb3e5bc5"},{"letra":"C","texto":"V • F • V • F","ordem":3,"idAlternativa":"370649e3-b1fb-5a0e-a9b3-b8ea40fca65a"},{"letra":"D","texto":"F • V • V • V","ordem":4,"idAlternativa":"6b4d542d-4b31-54d8-bf96-5e90b0184c5d"},{"letra":"E","texto":"F • F • V • V","ordem":5,"idAlternativa":"7a1d7b80-1477-5b21-9f0c-b4eaab7db45a"}],"gabarito":"A","observacoes":[],"idQuestao":"67d8b6be-4201-56a9-abde-2ea7e69fc559","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 10"},{"secao":"Dentística","numero":11,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Baratieri (2015), independentemente do tipo de adesivo, a adesão à dentina nas lesões cervicais não cariosas (LCNC) não é ideal. Existem 4 fatores que influenciam de alguma maneira na adesão à dentina esclerosada em LCNC, EXCETO:","alternativas":[{"letra":"A","texto":"presença de colágeno com bactérias.","ordem":1,"idAlternativa":"950a9865-ce9c-56e5-a84e-fc56ef09d3ab"},{"letra":"B","texto":"incapacidade do ácido penetrar para além da zona hipermineralizada superficial.","ordem":2,"idAlternativa":"e27cee4b-6b2d-5968-8478-194c913f159f"},{"letra":"C","texto":"presença de colágeno desnaturado.","ordem":3,"idAlternativa":"652c40f9-7833-59c7-9e3e-5f204ea774b9"},{"letra":"D","texto":"presença de depósitos minerais residuais dentro dos túbulos impedindo a penetração do adesivo.","ordem":4,"idAlternativa":"920dd06e-f816-5160-bd5d-270d197a407f"},{"letra":"E","texto":"diminuição do fluxo do fluido tubular para a superfície.","ordem":5,"idAlternativa":"18081333-4e21-5fda-9e2e-4dc0f3160fb0"}],"gabarito":"E","observacoes":[],"idQuestao":"4b97d676-a7ba-56da-9693-b54ce8da39e6","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 11"},{"secao":"Dentística","numero":12,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Baratieri (2015), assinale opção que apresenta a combinação recomendada entre o tipo de pino quanto à sua composição, o tipo de cimento e o material de confecção do núcleo de preenchimento.","alternativas":[{"letra":"A","texto":"Pino metálico - cimento de fosfato de zinco ou cimento resinoso - núcleo de preenchimento em cerâmica injetada ou amálgama.","ordem":1,"idAlternativa":"47dbe76a-9c1c-582c-9c62-b23011730bb6"},{"letra":"B","texto":"Pino de zircônio - cimento de fosfato de zinco ou cimento resinoso - núcleo de preenchimento em amálgama ou resina composta.","ordem":2,"idAlternativa":"84902c1a-e619-5175-9d1b-e05f1ebd2ba9"},{"letra":"C","texto":"Pino de fibra de carbono - cimento de ionômero de vidro ou cimento resinoso - núcleo de preenchimento em ionômero de vidro ou resina composta.","ordem":3,"idAlternativa":"a5d6b5e3-d61f-5499-aebb-9c83e9daa8c1"},{"letra":"D","texto":"Pino de fibra de vidro - cimento resinoso - núcleo de preenchimento em resina composta ou cerâmica injetada,","ordem":4,"idAlternativa":"092c5868-b8be-54d4-9f7d-b5b0991b1a1d"},{"letra":"E","texto":"Pino de fibra de carbono - cimento de fosfato de zinco ou cimento resinoso ou cimento de ionômero de vidro- núcleo de preenchimento em ionômero de vidro ou resina composta ou cerâmica injetada.","ordem":5,"idAlternativa":"57e8cce6-bc58-5e75-91a2-180d3ea2e9a6"}],"gabarito":"C","observacoes":[],"idQuestao":"f84b09e4-9321-5024-aac8-41a01ff10c26","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 12"},{"secao":"Dentística","numero":13,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Coloque F (falso) ou V (verdadeiro) nas afirmativas abaixo, com relação à dentina, segundo Lopes e Siqueira (2020), assinalando a seguir a opção correta: () A dentina é constituída por 70% de material inorgânico, principalmente cristais de hidroxiapatita, 10% de água e 20% de matriz orgânica composta, principalmente, por colágeno tipo 1. () A dentina primária é a primeira a ser formada e está localizada imediatamente abaixo do esmalte ou cemento. () Durante a dentinogênese, os odontoblastos se movem em direção centrípeta, deixando seus processos celulares na dentina para formar os túbulos dentinários. O processo odontoblástico se estende de um terço até a metade do túbulo dentinário. () A dentina intertubular é mais calcificada e rígida que a dentina peritubular. () A dentina reacional exibe túbulos dentinários que são contínuos aos túbulos da dentina secundária. Na dentina reparadora os túbulos, quando presentes, não são contínuos aos túbulos da dentina secundária.","alternativas":[{"letra":"A","texto":"FVVVV","ordem":1,"idAlternativa":"90c526e5-a458-51e1-88fb-eba9d9ddde63"},{"letra":"B","texto":"VFVFV","ordem":2,"idAlternativa":"17a2bb68-0fde-5cf2-a9a4-930dda0dcdc6"},{"letra":"C","texto":"VVVFF","ordem":3,"idAlternativa":"329604e2-615a-5e0a-b6dc-2ec4738df6aa"},{"letra":"D","texto":"FFFVF","ordem":4,"idAlternativa":"867cf613-d58b-5be5-95f6-b839c3df32fa"},{"letra":"E","texto":"VFVVF","ordem":5,"idAlternativa":"509e3411-741c-51fb-b8bc-bc626e3dca2c"}],"gabarito":"B","observacoes":["Obs.: No PDF a alternativa C aparece como “(6)”; corrigida para C."],"idQuestao":"c6d7500d-5962-50be-b9fb-e8adbd5b576f","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 13 | Obs.: No PDF a alternativa C aparece como “(6)”; corrigida para C."},{"secao":"Dentística","numero":14,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Reis e Loguercio (2021), sobre a incompatibilidade entre os adesivos simplificados e os cimentos resinosos de ativação química ou dupla é correto afirmar que:","alternativas":[{"letra":"A","texto":"quanto menor a acidez do adesivo, maior a redução da resistência de união entre cimento resinoso e dentina.","ordem":1,"idAlternativa":"1c776c56-48cb-57b0-a3d0-d7a139f76ebd"},{"letra":"B","texto":"os adesivos simplificados, por apresentarem alta quantidade de monômeros hidrófobos, são considerados membranas semipermeáveis.","ordem":2,"idAlternativa":"7c1d17f1-0409-5f5e-bd91-433297c26b18"},{"letra":"C","texto":"a redução dessa incompatibilidade pode ser conseguida pela diminuição do grau de conversão dos monômeros com o aumento do tempo de fotoativação de 20 para 60 segundos.","ordem":3,"idAlternativa":"ef5c271f-3364-5a4b-b0b6-1f82a2f805d1"},{"letra":"D","texto":"os sistemas adesivos de dupla ativação retardam a presa dos cimentos resinosos de ativação química e dual reduzindo a chance de ocorrer incompatibilidade física.","ordem":4,"idAlternativa":"d65b9932-c12e-5c4f-849b-9020aa54f86a"},{"letra":"E","texto":"a presença no sistema adesivo de um coiniciador químico, que contém sulfinato benzínico de sódio, impede que as aminas terciárias dos materiais quimicamente ativados sejam consumidas pelos monômeros ácidos dos adesivos simplificados.","ordem":5,"idAlternativa":"1a9781ce-bb08-5c26-bcb7-75062c639ac8"}],"gabarito":"E","observacoes":[],"idQuestao":"62156df7-1761-5f79-b242-c0720f3ecf1a","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 14"},{"secao":"Dentística","numero":15,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Fejerskov ef al. (2017), sobre a progressão da cárie na dentina e a reação do complexo dentina-polpa, analise as afirmativas abaixo. () As lesões em esmalte ou dentina, em uma superfície intacta ou cavitada, podem ser detidas somente pelo controle da placa, desde que a lesão possa ser acessada para limpeza. () A dentina prepara uma defesa conduzida por células para as flutuações do pH do biofilme, resultando na mineralização tubular e peritubular e da dentina terciária no limite dentina-polpa. () As reações inflamatórias pulpares não ocorrem quando a desmineralização está limitada ao esmalte. () Quando a invasão bacteriana penetra a dentina terciária, haverá, finalmente, uma polpa gravemente inflamada, seguida por necrose. () Na progressão rápida das lesões, os odontoblastos podem ser destruídos, o que resulta em caminhos tubulares obliterados na dentina. Assinale a opção correta.","alternativas":[{"letra":"A","texto":"(V) (V) (V) (V) (F)","ordem":1,"idAlternativa":"3691fbef-b533-525f-9865-1e4f44075796"},{"letra":"B","texto":"(V) (F) (V) (F)(V)","ordem":2,"idAlternativa":"5752616a-3898-53ea-82c0-a8f40c4a68e7"},{"letra":"C","texto":"(F) (V) (F) (V)(F)","ordem":3,"idAlternativa":"af6bf87d-216b-5d99-8c3c-ecd11e6aa654"},{"letra":"D","texto":"(V) (F) (V) (V)(V)","ordem":4,"idAlternativa":"9c62e5d5-c015-504c-a9ae-db16af0b3602"},{"letra":"E","texto":"(V) (V) (F) (V)(F)","ordem":5,"idAlternativa":"8c8733e5-da9b-5cb6-aa73-9e73b2754bac"}],"gabarito":"E","observacoes":[],"idQuestao":"87a93d1e-a882-5333-b490-1de6438030a2","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 15"},{"secao":"Dentística","numero":16,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Considerando a reatividade química aos ácidos, as cerâmicas odontológicas podem ser tanto ácidorresistentes quanto ácidossensíveis, de acordo com o grau de degradação superficial produzida pelos ácidos. Segundo Della Bonna (2009), são exemplos de cerâmicas ácidorresistentes EXCETO:","alternativas":[{"letra":"A","texto":"sistemas cerâmicos de alumina.","ordem":1,"idAlternativa":"dec724e3-49a1-5995-9c4e-6f036a2e47f1"},{"letra":"B","texto":"cerâmicas a base de Dissilicato deLítio.","ordem":2,"idAlternativa":"392c97d3-6eb6-5d7f-b472-02c296dbfec8"},{"letra":"C","texto":"sistemas cerâmicos de zircônia infiltrados por vidro.","ordem":3,"idAlternativa":"6476d27b-e4e6-5470-bf71-5c2e0198804d"},{"letra":"D","texto":"cerâmicas de aluminadensamente sinterizadas.","ordem":4,"idAlternativa":"86e82bd3-c34a-5026-8d15-7db13c04ab10"},{"letra":"E","texto":"cerâmicas Y-TZP.","ordem":5,"idAlternativa":"f8ab2ade-313b-5061-9d7b-55d94c55b518"}],"gabarito":"B","observacoes":[],"idQuestao":"ecf01962-f46c-5a99-9779-903f5ce52d68","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 16"},{"secao":"Dentística","numero":17,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"A confecção de restaurações de resina composta é baseada no conceito de cobertura natural que aborda características anatômicas e ópticas típicas dos dentes naturais. De acordo com Chu (2012), com relação às características anatômicas do esmaite dental, é correto afirmar que:","alternativas":[{"letra":"A","texto":"o esmalte jovem apresenta uma pigmentação neutra, baixa opalescência e baixa translucidez.","ordem":1,"idAlternativa":"eed083d7-4eb8-5d2f-a962-98d083730ffe"},{"letra":"B","texto":"o esmalte aduito apresenta pigmentação neutra, alta opalescência e translucidez intermediária.","ordem":2,"idAlternativa":"603d2c73-323e-52e9-9d78-2215fee828e2"},{"letra":"C","texto":"o esmalte envelhecido apresenta pigmentação amarela acinzentada e baixa translucidez,","ordem":3,"idAlternativa":"51d1646e-e50c-5f66-a6c9-673c44073b27"},{"letra":"D","texto":"o esmalte adulto apresenta pigmentação neutra, alta opalescência e baixa translucidez.","ordem":4,"idAlternativa":"774e4be1-e98f-5ca5-842f-3cbd5aef016a"},{"letra":"E","texto":"o esmalte jovem apresenta pigmentação branca, alta opalescência e baixa translucidez.","ordem":5,"idAlternativa":"9f856fbc-b6df-575d-9a01-f70eccf8bc67"}],"gabarito":"E","observacoes":[],"idQuestao":"72824a15-6576-564c-b2f7-73989d350f58","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 17"},{"secao":"Dentística","numero":18,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Reis e Loguercio (2021), com relação ao mecanismo de funcionamento dos retentores intrarradiculares, coloque V (verdadeiro) ou F (falso) nas afirmativasabaixo, assinalando, a seguir, a opção correta. () A parte cimentada do pino de fibra de vidro, que fica dentro do canal radicular, sempre estará em uma condição de completa imobilização caso esteja bem aderida às paredes radiculares. () No caso dos pinos, a parte longa, cimentada na raiz, é responsável pela dissipação das forças aplicadas obliquamente à coroa. Por esse motivo, é importante que o pino seja implantado na maior profundidade possível. () Com a cimentação mais profunda, o nível de tensões que atingem a região mais apical da raiz é de menor intensidade e, portanto, o risco de fraturas émenor. () Em termos comparativos, pode-se dizer que sob cargas oblíquas e perpendiculares, o aumento das tensões na região apical pode ser de até 100 vezes maior que o gerado sob cargas longitudinais. () Nos dentes posteriores, a solicitação mecânica costuma ser paralela ao eixo do órgão dental e não representam risco de fratura do pino.","alternativas":[{"letra":"A","texto":"(F) (F) (V) (V)(V)","ordem":1,"idAlternativa":"f1c27405-f907-5400-8ec6-9ec8c144a483"},{"letra":"B","texto":"(V) (V) (V) (F)(V)","ordem":2,"idAlternativa":"59ec6313-44f4-5169-81f1-0e888a069d28"},{"letra":"C","texto":"(V) (F) (F) (V)(F)","ordem":3,"idAlternativa":"df960831-4f63-54db-af50-8c04086a315e"},{"letra":"D","texto":"(V) (V) (V) (V) (V)","ordem":4,"idAlternativa":"c67fa5e7-4d09-5d2a-8845-d8e9ccb62c96"},{"letra":"E","texto":"(F) (F) (V) (F) (V)","ordem":5,"idAlternativa":"0c58e2ad-184b-54a0-8304-1224fba20dcc"}],"gabarito":"D","observacoes":[],"idQuestao":"ff7c79cf-673b-51ee-b5bf-0edfc418ccb4","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 18"},{"secao":"Dentística","numero":19,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Reis e Loguercio (2021), como é denominado o fotoiniciador que foi desenvolvido e patenteado para proporcionar um espectro de absorção de luz com comprimento de onda maior (em torno de 410 nm), porém com um espectro mais amplo que o de absorção de outros fotoiniciadores alternativos?","alternativas":[{"letra":"A","texto":"Lucirina TPO.","ordem":1,"idAlternativa":"63c1744c-ccd4-55a0-a5e9-0f025dbd63d8"},{"letra":"B","texto":"Dibenzoil-germânio.","ordem":2,"idAlternativa":"5e383b3e-8545-5ecb-8826-13303b38eb86"},{"letra":"C","texto":"Óxido de acilfosfina.","ordem":3,"idAlternativa":"f62b4a37-34e0-5215-9de6-ac9bed128d12"},{"letra":"D","texto":"Óxido de fenilfosfina.","ordem":4,"idAlternativa":"9d1624d9-5bc9-5025-b9e9-e877026d6d8d"},{"letra":"E","texto":"Canforoquinona.","ordem":5,"idAlternativa":"a77beb3a-fadc-5aaf-b3dc-b6afa02881d1"}],"gabarito":"B","observacoes":[],"idQuestao":"53b4d407-07d2-5c92-b1d3-8e77e092e0a7","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 19"},{"secao":"Dentística","numero":20,"orgao":"Marinha do Brasil","cargo":"CIRURGIÃO-DENTISTA – PRÓTESE","ano":2021,"enunciado":"Segundo Andreasen & Andreasen (2001), em casos de traumatismo dental com fratura coronorradicular, é correto afirmar que:","alternativas":[{"letra":"A","texto":"esse tipo de traumatismo, embora não seja muito comum, quando presente geralmente apresenta sérios problemas de tratamento devido à natureza complexa do traumatismo.","ordem":1,"idAlternativa":"0158f67e-1150-5a05-9c44-07169b482907"},{"letra":"B","texto":"a maioria dessas fraturas ocorre como resultado de um impacto vertical.","ordem":2,"idAlternativa":"59f5f55c-4cd8-5f20-8167-c8cfc41b9b1f"},{"letra":"C","texto":"as fraturas coronorradiculares sempre envolvem apolpa.","ordem":3,"idAlternativa":"98ec6f68-054c-5abd-8392-087f29d45b0b"},{"letra":"D","texto":"o diagnóstico radiográfico é fundamental para determinar a extensăo lingual da fratura.","ordem":4,"idAlternativa":"9513787a-2030-57df-9b11-84298d1ecfaa"},{"letra":"E","texto":"os princípios de tratamento de emergência incluem a remoção do fragmento coronário e a restauração supragengival.","ordem":5,"idAlternativa":"39423bf8-dd59-5221-8b23-eeeda75d4bea"}],"gabarito":"E","observacoes":[],"idQuestao":"c9d322b3-09d0-5da8-b7d1-70821feb8e0b","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"6f50e3ce-dc04-5036-b5b3-b85b8c948a94","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 20"},{"secao":"Dentística","numero":21,"orgao":"Marinha do Brasil","cargo":"CIRURGIÃO-DENTISTA – PRÓTESE","ano":2021,"enunciado":"Segundo Fejerskov, Nyvad & Kidd (2017), tratamentos năo operatórios săo relevantes para o controle da cárie dentária. Na maioria dos casos, os papéis da equipe odontológica são aconselhar, informar e estimular a mudança comportamental do indivíduo. Sendo assim, constituem estratégias corretas dos tratamentos náo operatórios:","alternativas":[{"letra":"A","texto":"tratamento restaurador atraumático, uso de estimulantes salivares e uso de fluoreto.","ordem":1,"idAlternativa":"e53437d5-827d-5024-a495-c06d7e19980e"},{"letra":"B","texto":"controle da placa dental, uso de fluoreto emodificaçăo alimentar.","ordem":2,"idAlternativa":"c43372a7-4163-55fb-90ec-ce9a0f21a8b2"},{"letra":"C","texto":"uso de fluoreto, uso de estimulantes salivares eaplicação deselantes.","ordem":3,"idAlternativa":"c6daf16f-c9d5-5975-9520-7c20c4123477"},{"letra":"D","texto":"uso de enxaguatôrio bucal, aconselhamento alimentar e tratamento restaurador atraumático.","ordem":4,"idAlternativa":"33525b29-db2f-5418-bf78-a14552f9e782"},{"letra":"E","texto":"aplicaçăo de selantes, uso de fluoreto e controle da placa dental.","ordem":5,"idAlternativa":"28c76a90-7e56-5126-b66f-46b741e32b07"}],"gabarito":"B","observacoes":[],"idQuestao":"3bf69cf9-f4a7-51c1-bd7a-d1f7a978050b","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"6f50e3ce-dc04-5036-b5b3-b85b8c948a94","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 21"},{"secao":"Dentística","numero":22,"orgao":"Marinha do Brasil","cargo":"CIRURGIÃO-DENTISTA – PRÓTESE","ano":2021,"enunciado":"Segundo Baratieri et al (2017), as referências e princípios estéticos norteiam a elaboração do planejamento individualizado. A respeito do mock-up, correto afirmar que:","alternativas":[{"letra":"A","texto":"nem sempre é necessário o conhecimento do planejamento estabelecido das dimensões ideais dos dentes anteriores superiores.","ordem":1,"idAlternativa":"f3924cc1-a74e-5729-94fe-039d55aa043b"},{"letra":"B","texto":"o mock-up possibilita a visualização do planejamento pelo profissional, porém não permite prever e guiar anecessidade de cirurgia periodontal.","ordem":2,"idAlternativa":"9f21c310-ca06-5fd8-b848-d41521be206c"},{"letra":"C","texto":"dependendo da técnica de simulação, o acabamento e polimento podem permitir a aplicação dos princípios estéticos dentais e a determinação da microestética.","ordem":3,"idAlternativa":"199010ba-2779-516c-8460-5bfaff99ada1"},{"letra":"D","texto":"após a remoção do mock-up, nos pontos em que a resina apresente uma espessura considerável e uma opacidade relevante, deve-se considerar a necessidade de preparo dental.","ordem":4,"idAlternativa":"0fec6d5a-c47c-5b94-85ca-8510116a98a7"},{"letra":"E","texto":"nos casos de dentes que apresentem apinhamentos graves e dentes muito vestibularizados, torna-se necessário o desgaste do dente previamente ao ensaio restaurador.","ordem":5,"idAlternativa":"5363ff23-3776-5ebe-8762-ef59f9394469"}],"gabarito":"E","observacoes":[],"idQuestao":"251bd7be-7904-5e1e-85ea-707d72d875ac","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"6f50e3ce-dc04-5036-b5b3-b85b8c948a94","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 22"},{"secao":"Dentística","numero":23,"orgao":"Marinha do Brasil","cargo":"CIRURGIÃO-DENTISTA – PRÓTESE","ano":2021,"enunciado":"Marque a afirmativa que corresponde corretamente, segundo Magne (2012), a seguinte afirmação: “Propriedade óptica que se refere â capacidade de transmitir certa variação dos comprimentos de luz vermelho-alaranjados”.","alternativas":[{"letra":"A","texto":"Transparência.","ordem":1,"idAlternativa":"4daa0d6a-e5c6-55d8-840a-d9c017ef1e91"},{"letra":"B","texto":"Fluorescência.","ordem":2,"idAlternativa":"8cefcc0e-86a3-5256-8c1f-e14be32b6766"},{"letra":"C","texto":"Valor.","ordem":3,"idAlternativa":"837e6291-8925-5963-a739-7242cd6bcd57"},{"letra":"D","texto":"Opalescência.","ordem":4,"idAlternativa":"2a145c92-06e1-5dd7-806b-3e365f372353"},{"letra":"E","texto":"Transmissão luminosa.","ordem":5,"idAlternativa":"6570fe14-1ccf-5384-a721-bbb24f1514e4"}],"gabarito":"D","observacoes":[],"idQuestao":"ee2cc17f-98c6-5272-989a-2e97fa6466a6","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"6f50e3ce-dc04-5036-b5b3-b85b8c948a94","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 23"},{"secao":"Dentística","numero":24,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"O conhecimento das características estruturais e ultramorfológicas de cada parte envolvida na adesão é de fundamental importância para que se consiga o máximo de desempenho do procedimento restaurador adesivo. A respeito dos substratos envolvidos no processo de adesão, é correto afirmar que","alternativas":[{"letra":"A","texto":"a dentina é composta por, aproximadamente, 88% de mineral, 2% de matriz orgânica e 10% de água (em volume).","ordem":1,"idAlternativa":"42fee6dd-c2ff-5f23-ab08-a3a85f55df0f"},{"letra":"B","texto":"os procedimentos adesivos no esmalte são considerados mais imprevisíveis, devido ao seu alto conteúdo mineral.","ordem":2,"idAlternativa":"7d393653-ed7a-593a-9369-2380375f2f33"},{"letra":"C","texto":"a morfologia da smear layer é determinada, principalmemte, pelo tipo de instrumento utilizado e pela zona da dentina na qual éformada.","ordem":3,"idAlternativa":"37b12ad6-c409-5443-913e-cedf3dfeb0dd"},{"letra":"D","texto":"o túbulo dentinário apresenta formato cônico e seu diâmetro aumenta à medida que se aproxima da junção amelo-dentinária, tornando a dentina profunda menos permeável e susceptível à sensibilidade.","ordem":4,"idAlternativa":"f655ab18-25c9-577d-b3c8-3eaa6651bd4c"}],"gabarito":"C","observacoes":[],"idQuestao":"2032006b-421b-52f0-9502-9d8676b5f898","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 24"},{"secao":"Dentística","numero":25,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"O conceito de Odontologia Minimamente Invasiva (MID - minimally invasive dentistry) evoluiu como uma consequência da compreensão dos novos conceitos sobre a doença cárie e do desenvolvimento de materiais adesivos. Sabe-se que o esmalte e a dentina desmineralizados, mas não cariados/cavitados, podem cicatrizar. Consequentemente, os conceitos atuais baseiam-se na preservação máxima da estrutura dentária. Em relação aos preparos cavitários atuais, é correto afirmar que","alternativas":[{"letra":"A","texto":"remover todo tecido cariado é um dogma.","ordem":1,"idAlternativa":"9ec04040-98cd-5ab5-8c2e-aaf8882b24b4"},{"letra":"B","texto":"desconsidera-se a necessidade de um desenho cavitário geométrico.","ordem":2,"idAlternativa":"f9fba8a5-0e9e-527e-9e7f-243e980321e3"},{"letra":"C","texto":"deve-se remover toda extensão da lesão cariosa e as áreas susceptíveis à doença.","ordem":3,"idAlternativa":"51ec1d10-7449-5448-b7e1-127189021409"},{"letra":"D","texto":"deve-se utilizar a sonda exploradora para melhorar o grau de eficácia na detecção de lesões de cárie não cavitadas e facilitar o preparo cavitário.","ordem":4,"idAlternativa":"ad44f198-acfc-58c9-b78c-3b8e370e74ea"}],"gabarito":"B","observacoes":[],"idQuestao":"9ee2ab30-9d84-5346-ba88-9d46701b649c","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 25"},{"secao":"Dentística","numero":26,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"O desenvolvimento dos sistemas autocondicionantes surgiu com o intuito de reduziras dificuldades da técnica úmida de adesão e simplificar os procedimentos clínicos de aplicação dos adesivos. É correto afirmar que, em relação a estes sistemas,","alternativas":[{"letra":"A","texto":"após a aplicação do primer autocondicionante, uma camada de resina adesiva hidrofílica é então aplicada sobre a dentina tratada.","ordem":1,"idAlternativa":"c1537f33-8edd-5a21-8570-a64102944bd3"},{"letra":"B","texto":"os adesivos de passo único reúnem as etapas de condicionamento, infiltração e adesão em dois procedimentos, apresentando-se em frascos separados.","ordem":2,"idAlternativa":"212b895c-3385-5f73-9c71-24badb6d421b"},{"letra":"C","texto":"os sistemas adesivos autocondicionantes desmineralizam a dentina e infiltram seus monômeros simultaneamente, aumentando o risco de colapso das fibrilas de colágeno.","ordem":3,"idAlternativa":"9d3e92c4-20a6-5db0-8719-7fdb4274cf1f"},{"letra":"D","texto":"primers autocondicionantes, compostos de monômeros ácidos, são aplicados sobre a dentina coberta pela smear layer, sem a necessidade de remoção do material com água subsequentemente.","ordem":4,"idAlternativa":"bce927cc-63ff-50be-8b3c-21e5bc42418e"}],"gabarito":"D","observacoes":[],"idQuestao":"314f0596-f714-5d9b-8fd0-850eb606108b","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 26"},{"secao":"Dentística","numero":27,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"As resinas compostas são materiais vastamente utilizados atualmente e, ao longo das décadas, houve uma evolução em sua composição com o propósito de melhorar as suas propriedades físico-mecânicas. É correto afirmar que o objetivo da incorporação do fotoiniciador, como a canforoquinona, à composição das resinas compostas foi aumentar a/o","alternativas":[{"letra":"A","texto":"viscosidade.","ordem":1,"idAlternativa":"4ea83871-2b08-5827-a293-4694e4309c9b"},{"letra":"B","texto":"tempo de presa.","ordem":2,"idAlternativa":"a5f5ef4d-7403-59b0-b3e8-f6d67ceb82aa"},{"letra":"C","texto":"tempo de trabalho.","ordem":3,"idAlternativa":"77282b31-1fc3-5e20-9e13-7c3e1f6ebff1"},{"letra":"D","texto":"resistência ao desgaste.","ordem":4,"idAlternativa":"5ea5d8de-e3dc-5a3b-92a5-d2f2fe40fe5f"}],"gabarito":"C","observacoes":[],"idQuestao":"34347a7d-f084-5f38-81e1-de055c27d3b5","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 27"},{"secao":"Dentística","numero":28,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Paciente RCM, 16 anos, compareceu à clínica odontológica queixando-se: “Essa mancha no meu dente da frente me incomoda desde pequena e eu gostaria de tirar”. Ao exame clínico, observou-se uma mancha branca pontual no terço incisal do dente 21, com ligeira rugosidade e depressão na superfície do esmalte, com histórico de traumatismo nos dentes decíduos, aos 3 anos de idade. A sequência que apresenta corretamente, com base nas informações acima, o provável diagnóstico da lesão e o tratamento mais indicado, respectivamente, é","alternativas":[{"letra":"A","texto":"hipoplasia do esmalte / fluorterapia.","ordem":1,"idAlternativa":"bb0175e8-7ca8-56d7-be32-6f246679ec75"},{"letra":"B","texto":"lesão cariosa não cavitada inativa /fluorterapia.","ordem":2,"idAlternativa":"3b2f0425-fcb2-521e-9d52-f950ba7580e5"},{"letra":"C","texto":"fluorose localizada / restauração direta com resina composta.","ordem":3,"idAlternativa":"5d9ebf50-694f-54bf-b151-dfeaae361096"},{"letra":"D","texto":"hipoplasia do esmalte / restauração direta com resina composta.","ordem":4,"idAlternativa":"20597414-14d0-5f77-9780-f269c21b6d84"}],"gabarito":"D","observacoes":[],"idQuestao":"3b9d07d9-b9fd-5429-af40-e788d4726909","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 28"},{"secao":"Dentística","numero":29,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"O uso do dique de borracha para se alcançar a mais alta qualidade do material restaurador é essencial, pois é o único método de se manter um campo operatório totalmente livre de umidade durante os preparos cavitários e a inserção do material restaurador. Para a execução deste procedimento, alguns detalhes técnicos devem ser observados para garantir um adequado isolamento. Em relação aos instrumentos utilizados e cuidados durante a técnica, é incorreto afirmar que","alternativas":[{"letra":"A","texto":"o espaço e a relação entre os orifícios, a serem perfurados na borracha, dependem do tamanho e da posição dos dentes.","ordem":1,"idAlternativa":"b874f4a1-8fe8-5cfe-a539-d4d9dc62c32f"},{"letra":"B","texto":"a altura da gengiva interdental determina a posição dos orifícios, portanto, quanto mais baixa a papila interdental, maior a distância entre asperfurações.","ordem":2,"idAlternativa":"4311d2e8-1bbd-5a58-9b8c-39c2546ff5e1"},{"letra":"C","texto":"os dentes que apresentam lesões cervicais subgengivais requerem que o orifício correspondente seja deslocado, aproximadamente, 2mm para vestibular.","ordem":3,"idAlternativa":"b348d0de-faca-50c8-816f-f02f78162eef"},{"letra":"D","texto":"os dentes ovóides e cônicos, com ameias vestibular e lingual extensas, requerem mais espaço entre os orifícios do que os quadrangulares, com pequeno espaço interdental.","ordem":4,"idAlternativa":"e8e95ee2-be93-5f39-b3da-4346437fdf44"}],"gabarito":"B","observacoes":[],"idQuestao":"22d56580-a4bc-542e-8589-532679bfff82","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 29"},{"secao":"Dentística","numero":30,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Os preparos cavitários conservadores foram idealizados em função da evolução dos materiais restauradores e dos conhecimentos científicos a respeito da evolução e desenvolvimento da doença cárie. A sequência que apresenta corretamente os preparos mais indicados para a preservação da crista marginal é","alternativas":[{"letra":"A","texto":"Slot vertical / tipo túnel / slot horizontal.","ordem":1,"idAlternativa":"a5681c46-b203-5348-9df7-3d06c63946fe"},{"letra":"B","texto":"Slot vertical / Classe II típico de Black / tipo túnel.","ordem":2,"idAlternativa":"3271dd21-6e73-5cf2-a27f-0887fc24faf0"},{"letra":"C","texto":"Tipo túnel / slot horizontal / extritamente proximal.","ordem":3,"idAlternativa":"314884f2-8d6a-5261-bc4e-1f7d4e54831e"},{"letra":"D","texto":"Extritamente proximal / slot horizontal / classe II típico de Black.","ordem":4,"idAlternativa":"7b116c51-6176-5a75-a060-e85e7a0b7a24"}],"gabarito":"C","observacoes":[],"idQuestao":"9d584259-6723-50ba-b0b3-ae7b0907c7a1","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 30"},{"secao":"Dentística","numero":31,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Jovem de 17 anos de idade, sexo feminino, compareceu ao serviço odontológico para avaliação. Após exame clínico, notaram-se na face oclusal dos dentes 46 e 36 pequenas manchas de coloração escura, fundo endurecido à sondagem, margens definidas e sem halo de mancha branca opaca e rugosa nas suas extremidades. Radiograficamente, estavam restritas à metade externa do esmalte. A paciente responde bem à higiene local. Considerando esse caso clínico, marque a alternativa que apresenta a hipótese diagnóstica provável.","alternativas":[{"letra":"A","texto":"Lesão de cárie inativa.","ordem":1,"idAlternativa":"f030b709-bd20-5344-a1c2-df86be7ded27"},{"letra":"B","texto":"Lesão de cárie ativa.","ordem":2,"idAlternativa":"6fd90897-f4a9-5428-8be0-cbc2c7ca8a3e"},{"letra":"C","texto":"Lesão de cárie rampante.","ordem":3,"idAlternativa":"36b9f1bf-fe88-511f-bda6-9c6ff5788947"},{"letra":"D","texto":"Lesão de cárie oculta.","ordem":4,"idAlternativa":"61aeb840-21f6-5cff-86d0-f2fb2857f050"},{"letra":"E","texto":"Lesão de cárie residual.","ordem":5,"idAlternativa":"3c6d0287-163b-54c7-b300-b75602ec4781"}],"gabarito":"A","observacoes":[],"idQuestao":"a33d798a-f3d9-5198-8530-4a64fed4a7ba","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 31"},{"secao":"Dentística","numero":32,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"O processo para restaurações com materiais adesivos estéticos é complexo, uma vez que envolve a união dos materiais restauradores aos tecidos dentais. A respeito de adesão e restauração em resina composta de dentes posteriores, analise as afirmativas. I- Em cavidades com profundidade de até 4 mm, resinas bulk fill podem ser inseridas em incrementos únicos. Isso se deve ao fato de que o stress de contração é minimizado por seu baixo grau de contração de polimerização e porque sua alta translucidez permite que a luz incidente penetre mais profundamente naresina. II- A energia resultante de uma exposição de luz a 1.000 mW/cm2 por segundos é idêntica energia de uma exposição a m cm2 por 40 segundos, assim o tempo de exposição de fotopolimerizadores com intensidade de luz menor pode ser compensada pelo aumento no tempo de exposição. III- Adesivos odontológicos autocondicionantes de dois passos requerem que a dentina, após condicionamento com ácido fosfórico 37% por 15 segundos, seja mantida úmida para que ocorra a exposição de um emaranhado de fibras colágenasde modo a permitir a infiltração subsequente do adesivo. IV- Após a instalação da matriz metálica e cunha nas faces mesial e distal, a inserção da resina composta em cavidades MO é iniciada simultaneamente pelas caixas proximais, por meio da aplicação sucessiva de pequenos incrementos horizontais, fotoativados individualmente. Está correto o que se afirmaem","alternativas":[{"letra":"A","texto":"II, III e IV, apenas.","ordem":1,"idAlternativa":"e8544432-839f-5395-a5c4-1e920c0f05c7"},{"letra":"B","texto":"II e IV, apenas.","ordem":2,"idAlternativa":"f844d9a4-fe88-58ef-a7e9-90f49654ee28"},{"letra":"C","texto":"I e II, apenas.","ordem":3,"idAlternativa":"f97152f0-50d5-5238-8545-71f4a9e9ddca"},{"letra":"D","texto":"I e IV, apenas.","ordem":4,"idAlternativa":"762f8b78-81dc-5b5d-8309-770a26e6f963"},{"letra":"E","texto":"I, II e III, apenas.","ordem":5,"idAlternativa":"6c06c44f-26a6-594c-8a04-621a22bd00a0"}],"gabarito":"E","observacoes":[],"idQuestao":"e8b1275c-179a-50c1-be3e-8125342f612f","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 32"},{"secao":"Dentística","numero":33,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Facetas são procedimentos realizados na face vestibular dos dentes para promover alteração de cor ou forma. A respeito de facetas indiretas, assinale a afirmativa correta.","alternativas":[{"letra":"A","texto":"A espessura da peça é determinada pela coloração do substrato – quanto mais escurecido, maior a espessura de cerâmica necessária para mascará-lo.","ordem":1,"idAlternativa":"832b6969-4d90-5921-a5d5-ff0202dcbd39"},{"letra":"B","texto":"Dada a natureza conservadora do preparo, as etapas de acabamento, polimento e regularização dos ângulos devem ser dispensadas.","ordem":2,"idAlternativa":"b9caa0ce-2713-5cd2-beff-86912406f0c9"},{"letra":"C","texto":"A espessura da cerâmica é determinada pela profundidade do desgaste efetuado na estrutura dental remanescente.","ordem":3,"idAlternativa":"96a3d139-17d2-5db0-a307-cb1bc5cccd92"},{"letra":"D","texto":"A expulsividade para incisal é crítica para os procedimentos de moldagem e cimentação da faceta, porque essa é a guia de inserção dapeça.","ordem":4,"idAlternativa":"ed8b2350-f6ac-5f52-850b-e2dbca1daa73"},{"letra":"E","texto":"A curva reversa de Hollemback confere maior espessura do material nas margens proximais e deve ser confeccionada inclusive na borda incisal.","ordem":5,"idAlternativa":"34a179b9-88cb-5ecf-ad6d-6aa596c6c47a"}],"gabarito":"D","observacoes":[],"idQuestao":"33602b3d-05f1-5e25-adfc-c5c31f03b679","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 33"},{"secao":"Dentística","numero":34,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"GROSSO A decisão por reparar ou substituir restaurações de resina composta é um desafio que vários dentistas enfrentam no dia a dia da prática profissional. A respeito dos procedimentos de reparo em resina composta, analise as afirmativas. I- O processo de reparo pode ser mais complicado em uma restauração antiga de resina composta, porque a quantidade de ligações duplas de carbono remanescentes diminui com o tempo. II- O tratamento de superfície tem por finalidade remover a camada superficial alterada, aumentar a energia de superfície da resina envelhecida e ainda aumentar sua área com a criação de irregularidades. III- A asperização de superfície deve ser realizada por meio de pontas diamantadas ou jateamento com óxido de alumínio. IV- O condicionamento da resina com ácido fosfórico promove alteração sobre o seu padrão morfológico, aumentando a força de união do reparo. Está correto o que se afirma em","alternativas":[{"letra":"A","texto":"II e IV, apenas.","ordem":1,"idAlternativa":"fa87fb83-694b-5d45-b775-383644694010"},{"letra":"B","texto":"I, II e III, apenas.","ordem":2,"idAlternativa":"ee02566d-5792-5a7a-b28c-a1adb2f91bc7"},{"letra":"C","texto":"I, III e IV, apenas.","ordem":3,"idAlternativa":"5437ce5b-b20e-5320-bfef-5fc35a7264df"},{"letra":"D","texto":"I, II e IV, apenas.","ordem":4,"idAlternativa":"ff819faa-b2f4-508b-9a1b-18a5d1311a26"},{"letra":"E","texto":"III, apenas.","ordem":5,"idAlternativa":"dee4f010-546a-52b5-a1bb-c07db5b2a157"}],"gabarito":"D","observacoes":[],"idQuestao":"51bf723a-0852-5888-be6c-b292d1b9ca28","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 34"},{"secao":"Dentística","numero":35,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Na última década, triplicou entre os jovens um problema conhecido como envelhecimento precoce dos dentes. A esse respeito, marque V para as afirmativas verdadeiras e F para as falsas. ( ) As lesões causadas pela erosão nos tecidos dentais são irreversíveis. ( ) Alimentos e bebidas ácidas, como refrigerante, energético, álcool e açúcar, quando consumidos em elevada frequência e de modo inadequado, facilitam a degeneração dos tecidos dentais. ( ) O pH crítico para dissolução do esmalte é 6,5. ( ) O estilo de vida também pode impactar, pois o estresse diário pode provocar alterações gástricas. Assinale a sequência correta.","alternativas":[{"letra":"A","texto":"F, V, V, V","ordem":1,"idAlternativa":"085b3f79-d668-5702-9a17-bf1b06e9e48d"},{"letra":"B","texto":"V, V, F, V","ordem":2,"idAlternativa":"b72185e1-5472-522e-a242-ad2687b338aa"},{"letra":"C","texto":"F, F, V, F","ordem":3,"idAlternativa":"a95de700-cd19-5719-b655-38e4547f946f"},{"letra":"D","texto":"V, F, V, V","ordem":4,"idAlternativa":"c830ae4b-4d42-5b40-845d-e5999e534551"},{"letra":"E","texto":"F, V, F, F","ordem":5,"idAlternativa":"99f6c46a-772f-5f4f-8ae2-07d0a0697c3f"}],"gabarito":"B","observacoes":[],"idQuestao":"f670dd1f-ed65-5b2f-92fe-4ba29e98df9b","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 35"},{"secao":"Dentística","numero":36,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Qual é a característica anatômica da coroa do primeiro molar superior?","alternativas":[{"letra":"A","texto":"Maior dente da boca.","ordem":1,"idAlternativa":"a0e9f8e9-e0b9-5ac2-be21-3efaf8118be8"},{"letra":"B","texto":"Cúspide VM e PM com mesmo volume.","ordem":2,"idAlternativa":"319e0051-f614-50a6-b648-cc9f2bd79fb1"},{"letra":"C","texto":"Possui 05 cúspides.","ordem":3,"idAlternativa":"f2047db6-bb44-52cc-8066-129688a4eaec"},{"letra":"D","texto":"Face Palatina é menor que a vestibular.","ordem":4,"idAlternativa":"576ffcf2-65ba-5666-af71-4c92765e9d57"},{"letra":"E","texto":"Ponte de esmalte ligando cúspide MP aDV.","ordem":5,"idAlternativa":"1f6517f2-ea26-5d4f-b9b5-727dcefe45a6"}],"gabarito":"B","observacoes":[],"idQuestao":"353072ae-c5ca-54ec-a3ce-56218219f421","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 36"},{"secao":"Dentística","numero":37,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"A ocorrência de traumatismo dentário é frequente em crianças e adolescentes. É primordial uma conduta célere para um melhor prognóstico. Sobre esse tipo de urgência, marque V para as afirmativas verdadeiras e F para as falsas. ( ) Fratura em esmalte é a perda parcial de esmalte. O fragmento deve ser armazenado em soro fisiológico para colagem (técnica de baixo custo e de resultados estéticos satisfatórios). Também pode ser feita a restauração convencional. ( ) Fratura coronária envolvendo esmalte, dentina e polpa: O atendimento de urgência deve ocorrer em até três horas após o trauma, com intervenções menos invasivas e melhor prognóstico. ( ) Fratura de coroa e raiz é a fratura de esmalte, dentina, cemento e polpa, podendo ocorrer tanto no sentido vertical como horizontal com presença de mobilidade. Se a fratura for no sentido vertical, pode-se manter o elemento radicular por meio de técnicas de reposicionamento dental. Na fratura horizontal, o único tratamento é a extração do elemento dentário. ( ) Fratura da parede e do processo alveolar atinge a parede óssea do alvéolo, envolvendo ou não o elemento dental. Deve-se realizar o reposicionamento do fragmento e contenção rígida ou semirrígida por quatro semanas. Há necessidade de acompanhamento odontológico depois de quatro, oito, 24 semanas a um ano. Assinale a sequência correta.","alternativas":[{"letra":"A","texto":"V, F, F, V","ordem":1,"idAlternativa":"7f5f3ff0-aed7-52b8-8ac9-a5004bce6422"},{"letra":"B","texto":"V, V, V, V","ordem":2,"idAlternativa":"c519a95d-4613-5a31-a0d2-d2bc68109393"},{"letra":"C","texto":"F, F, F, F","ordem":3,"idAlternativa":"5b91cdb0-39d4-5536-84eb-53480a7cd529"},{"letra":"D","texto":"F, V, V, F","ordem":4,"idAlternativa":"27c56eba-49b6-522c-9514-c4fb3592b398"},{"letra":"E","texto":"V, V, F, V","ordem":5,"idAlternativa":"73bc93d2-075e-5c0d-961c-827a540c788a"}],"gabarito":"B","observacoes":[],"idQuestao":"babe8c55-b51d-5f8a-88f3-67eae2cff4f1","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 37"},{"secao":"Dentística","numero":38,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"Um relatório da American Dental Association em 2018 determinou diretrizes baseadas em evidências para tratamento não restaurador de lesões de cárie. Dentre as intervenções mais eficazes, de acordo com o tipo de lesão, superfície dentária e dentição, podemos citar:","alternativas":[{"letra":"A","texto":"10% de fosfopeptídeo de fosfato de cálcio, Creme dental 1400 ppm flúor, flúor fosfato acidulado 1,23%, verniz de fluoreto de Na a 5%.","ordem":1,"idAlternativa":"deb804ce-5d21-5b15-bd2a-e98dda5fab0c"},{"letra":"B","texto":"10% de fosfopeptídeo de fosfato de cálcio, creme dental 5000 ppm flúor, flúor fosfato acidulado 1,23%, verniz de fluoreto de Na a5%.","ordem":2,"idAlternativa":"d1b791dd-ae57-5cf8-9d48-2ae3d0b1c9b4"},{"letra":"C","texto":"10% de fosfopeptídeo de fosfato de cálcio, creme dental 900 ppm flúor, flúor fosfato neutro 1,23%, Selante.","ordem":3,"idAlternativa":"44e07fd9-e43f-57b8-a5be-ccaaa439bd27"},{"letra":"D","texto":"Creme dental 5000 ppm de flúor, Selante, Diamino fluoreto de Prata, flúor fosfato acidulado 1,23%, verniz de fluoreto de Na a 5%","ordem":4,"idAlternativa":"6d722b1f-0744-574e-b2c4-ada368871f32"},{"letra":"E","texto":"Diamino fluoreto de Prata, creme dental 5000 ppm flúor, verniz de fluoreto de Na a 0,5%, Solução de flúor 0,5%.","ordem":5,"idAlternativa":"ec04c837-4bc3-5db9-ae22-ea15fe17ee8c"}],"gabarito":"D","observacoes":[],"idQuestao":"da2aec92-9d02-599e-8641-164867c44c0e","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 38"},{"secao":"Dentística","numero":39,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"Em relação aos materiais dentários na odontologia, podemos afirmar:","alternativas":[{"letra":"A","texto":"As resinas compostas são materiais que apresentam alta taxa de longevidade em restaurações diretas em pacientes com bruxismo e lesões de mancha branca ativa .","ordem":1,"idAlternativa":"1aac11fa-5a42-5b5c-a1cd-f95a6f3ac28d"},{"letra":"B","texto":"Cimentos de Ionômero de vidro químico para forramento ou base são usados na parede pulpar ou axial, antes da inserção da resina, após o condicionamento ácido proporcionando diminuição do risco de fratura do dente.","ordem":2,"idAlternativa":"50571b71-c11e-5a5d-9a56-1c84a2a42823"},{"letra":"C","texto":"Os adesivos autocondicionantes são comumente precedidos por condicionamento do esmalte com ácido fosfórico e aplicação de cimento de hidróxido de Ca na parede pulpar ou axial, em cavidades profundas.","ordem":3,"idAlternativa":"855b8929-5b72-56f1-bf79-0a374c0b6696"},{"letra":"D","texto":"Os adesivos universais disponíveis no mercado apresentam o mesmo grau de acidez que permitem ao dentista aplicar, de acordo com à escolha pessoal, em ambos os modos de E&R (Condicione/lave), Auto condicionante ou o modo combinado envolvendo E&R seletivo do esmalte com autocondicionante.","ordem":4,"idAlternativa":"dd89c99d-1d02-570f-b722-a1ab867af03b"},{"letra":"E","texto":"Sistemas adesivos, E&R (Condicione/lave) que fornecem primers à base de água são mais tolerantes à técnica de adesão e permitem que a dentina seja suavemente seca ao ar sem comprometer a difusão dos monômeros resino- sos.","ordem":5,"idAlternativa":"a8887927-861b-51bf-be1a-defb84059984"}],"gabarito":"E","observacoes":[],"idQuestao":"502f2d4d-5a25-5509-a777-4689a1b752f6","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 39"},{"secao":"Dentística","numero":40,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"“As leso ́es de cáries dentárias resultam de um desvio na atividade metabólica e na ecologia do biofilme, no qual acontece um descompasso no equilíbrio entre o conteúdo mineral do dente e o fluido do biofilme.” Analise as afirmações sobre a etiopatogenia da cárie, sua prevenção e tratamento: I. As hipóteses da placa específica e da placa inespecífica foram, durante anos, as principais escolas do pensamento sobre o papel da placa na eti- ologia da cárie. II. As lesões de cárie podem se desenvolver em qualquer local do dente, desde que se desenvolva um biofilme e que este permaneça por um perí- odo suficiente. III. Qualquer lesão cariosa, exceto as cavitadas, e que a polpa não esteja da- nificada, pode ser controlada e a progressão da lesão ser detida. IV. Com relação ao tratamento minimamente invasivo, em locais onde uma lesão cavitada está circundada por esmalte desmineralizado, este deve ser removido. Estão CORRETAS apenas as afirmativas:","alternativas":[{"letra":"A","texto":"I e II.","ordem":1,"idAlternativa":"a870f03c-7a1d-5087-8f2a-60656c42d0e6"},{"letra":"B","texto":"I e III.","ordem":2,"idAlternativa":"0b87a57a-d243-507a-8b55-9f982ecbf892"},{"letra":"C","texto":"I e IV.","ordem":3,"idAlternativa":"805d9198-b8a6-5179-ae0a-88fb7443e77b"},{"letra":"D","texto":"II e III.","ordem":4,"idAlternativa":"8ff37668-6ba4-5ad4-a16a-c2a528eb512a"},{"letra":"E","texto":"II e IV.","ordem":5,"idAlternativa":"7ce9d56f-ad99-52e5-b619-30f859ec265c"}],"gabarito":"A","observacoes":[],"idQuestao":"33a0c54d-1c60-5ace-92b4-b7a519281924","idDisciplina":"8eb13961-9203-5822-8845-4952ecaff7bd","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Dentística | Questão 40"},{"secao":"Oclusão e Prótese Dentária","numero":1,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Na oclusão dente-dois-dentes, por visão vestibular e levando em consideração o relacionamento das cúspides de contenção Cêntrica dos dentes inferiores com os dentes superiores, onde oclui a cúspide vestibular do segundo pré-molar inferior?","alternativas":[{"letra":"A","texto":"Oclui com a crista marginal mesial do primeiro Pré-molar superior determinando um ponto de oclusão.","ordem":1,"idAlternativa":"01482bb0-bf67-5957-8c29-013da91f9912"},{"letra":"B","texto":"Oclui com a crista marginal distal do primeiro pré-molar superior e mesial do segundo pré-molar superior, determinando dois pontos de oclusão.","ordem":2,"idAlternativa":"34bedcf3-3c1c-54bd-9410-773e2dcbc651"},{"letra":"C","texto":"Oclui com a crista marginal distal do segundo pré-molar superior e mesial do primeiro molar superior, determinando dois pontos de oclusão.","ordem":3,"idAlternativa":"9f5fbeec-f777-587d-821e-3ab55cae90cd"},{"letra":"D","texto":"Oclui com a fossa central do primeiro molar superior, determinando assim três pontos de oclusão, conhecidos como tripoidíssimo.","ordem":4,"idAlternativa":"24bc91c2-d755-57d2-a375-414bbae48cd4"},{"letra":"E","texto":"Devido ao fato desta cúspide ser diminuta, é muito comum não ocorrer um efetivo contato oclusal com o dente antagonista. Quando o contato existe, o mesmo se dá na fossa distas do primeiro molar superior.","ordem":5,"idAlternativa":"2c79775f-5f5f-58ab-876f-0f4a524e3509"}],"gabarito":"B","observacoes":[],"idQuestao":"9a801dbf-66f2-57de-a257-6bafc9b53db3","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 1"},{"secao":"Oclusão e Prótese Dentária","numero":2,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Como é denominada a curvatura dos dentes no sentido vestíbulo-lingual (de um lado a outro da arcada dentária), no plano frontal, que passa pelas cúspides vestibulares e linguais dos dentes posteriores de ambos os lados?","alternativas":[{"letra":"A","texto":"Curva de Spee.","ordem":1,"idAlternativa":"79f02c02-0097-50d4-9dc9-266b10a4961f"},{"letra":"B","texto":"Curva de Angle.","ordem":2,"idAlternativa":"c4aabeb9-0a53-5ead-bc3e-49154b2cdf1f"},{"letra":"C","texto":"Curva de Windser.","ordem":3,"idAlternativa":"26fbccbe-dbdc-5444-97a2-7b43b354e380"},{"letra":"D","texto":"Curva de Wilson.","ordem":4,"idAlternativa":"9c6d85cc-38cf-5203-b9a9-3f20bbd2b8ee"},{"letra":"E","texto":"Curva de Black.","ordem":5,"idAlternativa":"0c98bfdd-684f-55db-9f32-84ed88b2e6e2"}],"gabarito":"D","observacoes":[],"idQuestao":"c4c64573-563b-509d-9979-a00a92a2124a","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 2"},{"secao":"Oclusão e Prótese Dentária","numero":3,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"É o relacionamento maxilo-mandibular independente do contato dentário, em que os côndilos articulam-se, na posição anterossuperior contra as inclinações posteriores das eminências articulares. Nessa posição a mandíbula realiza um movimento, puramente, rotativo. Clinicamente, é uma posição de referência útil e repetível. Qualalternativa, abaixo, é o conceito base do texto acima?","alternativas":[{"letra":"A","texto":"Relação Cêntrica.","ordem":1,"idAlternativa":"ea5627cb-bace-5ee2-9207-67ba9409cd22"},{"letra":"B","texto":"Máxima Intercuspidação Habitual.","ordem":2,"idAlternativa":"5df42957-550c-5f9f-ba1e-dc82501b35eb"},{"letra":"C","texto":"Espaço Livre Funcional.","ordem":3,"idAlternativa":"fff5c38c-7d4f-552f-9668-290f4de45f92"},{"letra":"D","texto":"Dimensão Vertical em Repouso.","ordem":4,"idAlternativa":"f35ae0a0-b970-5432-9357-c4273efdef55"},{"letra":"E","texto":"Dimensão Vertical em Oclusão.","ordem":5,"idAlternativa":"fb770692-1c31-56f0-988d-48d3aa46937b"}],"gabarito":"A","observacoes":[],"idQuestao":"beb83ec5-e6fb-5a20-9adf-fba8320c9220","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 3"},{"secao":"Oclusão e Prótese Dentária","numero":4,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"A partir da MIH, os incisivos centrais inferiores deslizam para a frente guiados pelas faces palatinas dos incisivos centrais superiores e atingem a relação topo-a-topo, na posição de protrusão. Ao alcançar esta posição os dentes posteriores perdem o contato com os antagonistas devido às inclinações das faces palatinas dos incisivos e das fossas mandibulares. Esse evento é denominado de?","alternativas":[{"letra":"A","texto":"Inclinação condilar.","ordem":1,"idAlternativa":"a758facb-d875-56ed-9b53-bfb15d0d3aec"},{"letra":"B","texto":"Guia Canina.","ordem":2,"idAlternativa":"98309c74-0f82-5f38-9086-e56365bb3fb2"},{"letra":"C","texto":"Fenômeno de Cristhensen.","ordem":3,"idAlternativa":"cae233d5-f6b1-5e84-91c5-61b679664742"},{"letra":"D","texto":"Transpasse positivo.","ordem":4,"idAlternativa":"f9481b3c-07d8-5553-9205-f7eac3f8e016"},{"letra":"E","texto":"Transpasse negativo.","ordem":5,"idAlternativa":"af61253b-391b-52ab-9887-0925adbdd0bc"}],"gabarito":"C","observacoes":[],"idQuestao":"e84c24a4-1ac2-5080-838e-d94a1a792471","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 4"},{"secao":"Oclusão e Prótese Dentária","numero":5,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Como é denominada a classificação de Angle que tem a posição distal dos primeiros molares inferiores em relação aos superiores e observase os incisivos superiores inclinados e grande trespasse horizontal, com ou sem sobremordida profunda?","alternativas":[{"letra":"A","texto":"Classe I.","ordem":1,"idAlternativa":"f1159965-1d53-5048-a764-553cec04e61b"},{"letra":"B","texto":"Classe II divisão 1.","ordem":2,"idAlternativa":"a9f041ac-c828-5825-9b48-3ee3bbd79822"},{"letra":"C","texto":"Classe II divisão 2.","ordem":3,"idAlternativa":"d2970391-1c61-5c47-a336-296a01db86d9"},{"letra":"D","texto":"Classe III.","ordem":4,"idAlternativa":"4140d521-7ac6-56c8-9967-a78bad11c1b9"},{"letra":"E","texto":"Classe IV.","ordem":5,"idAlternativa":"f1ed0624-7f1f-5eda-b6e5-a132d969411c"}],"gabarito":"B","observacoes":[],"idQuestao":"f74d16cb-787c-5b4e-80eb-274ee80d2f3b","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 5"},{"secao":"Oclusão e Prótese Dentária","numero":6,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Como é denominada a distância entre a linha que passa, no centro dos implantes mais posteriores com a linha que passa nos implantes mais anteriores, multiplicada por dois?","alternativas":[{"letra":"A","texto":"Overdenture.","ordem":1,"idAlternativa":"7b4036ba-108e-5a14-92a6-4e817cd9f2d4"},{"letra":"B","texto":"Cantiléver.","ordem":2,"idAlternativa":"d825b2a1-d008-5c1e-be87-73fe320c2a28"},{"letra":"C","texto":"Polígono de Roy.","ordem":3,"idAlternativa":"3e0085ec-c63b-57e8-b4e9-b091f637aeba"},{"letra":"D","texto":"Travamento.","ordem":4,"idAlternativa":"1f21b1c9-a895-5002-8f9b-3d4aa7124382"},{"letra":"E","texto":"Alívio.","ordem":5,"idAlternativa":"dc1370c0-ef87-518c-863c-64b24f6216bf"}],"gabarito":"B","observacoes":[],"idQuestao":"4fcf927b-1b99-5b65-8823-e102642c50bd","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 6"},{"secao":"Oclusão e Prótese Dentária","numero":7,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Como são chamadas as próteses em que sua infraestrutura é de metal e possui uma camada de porcelana?","alternativas":[{"letra":"A","texto":"Metal-free.","ordem":1,"idAlternativa":"1e04a071-26f7-5a0b-ab47-c7d8557a2ded"},{"letra":"B","texto":"Metálicas.","ordem":2,"idAlternativa":"5a82ac30-8f0c-5b75-a89c-98a4d010e789"},{"letra":"C","texto":"Metalocerâmicas.","ordem":3,"idAlternativa":"2917a1ea-761a-585d-994c-e2f540a98717"},{"letra":"D","texto":"Flexíveis.","ordem":4,"idAlternativa":"56e111da-8d86-5f78-8da7-eb580af4fa16"},{"letra":"E","texto":"Acrílicas.","ordem":5,"idAlternativa":"fee93a58-a0de-57e0-99e6-15067b5df74b"}],"gabarito":"C","observacoes":[],"idQuestao":"c7f74106-f66f-55e6-88b9-1d4569246726","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 7"},{"secao":"Oclusão e Prótese Dentária","numero":8,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Qual alternativa, abaixo, não determina a extensão de uma prótese fixa dentária?","alternativas":[{"letra":"A","texto":"Eficiência mastigatória do antagonista.","ordem":1,"idAlternativa":"144c7faf-1920-5418-938c-5216a2612eb1"},{"letra":"B","texto":"Polígono de Ruys.","ordem":2,"idAlternativa":"7be15064-61a2-59bf-8179-20ba5257faf6"},{"letra":"C","texto":"Extensão e localização no arco dentário.","ordem":3,"idAlternativa":"57cca427-6654-51f5-b8c3-bb717ae04b3f"},{"letra":"D","texto":"Proporção Coroa x Raiz.","ordem":4,"idAlternativa":"87dfce18-b87e-51b0-b8ea-7316bddc45d4"},{"letra":"E","texto":"Estado periodontal.","ordem":5,"idAlternativa":"6bd8b533-028b-5521-a831-e13e6ff05b99"}],"gabarito":"B","observacoes":[],"idQuestao":"6f02c54b-d86a-5d0a-a00d-7438dae80a08","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 8"},{"secao":"Oclusão e Prótese Dentária","numero":9,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Qual alternativa, abaixo, se caracteriza como um princípio estético do preparo ideal?","alternativas":[{"letra":"A","texto":"Tecido dental.","ordem":1,"idAlternativa":"e052c7ca-26c0-5bc1-85d8-09bb33736809"},{"letra":"B","texto":"Periodonto.","ordem":2,"idAlternativa":"b50cccea-390a-5f32-b373-da54f47f046a"},{"letra":"C","texto":"Espessura da porcelana.","ordem":3,"idAlternativa":"96d9d08a-a0d2-5f7a-91f3-5db61857e546"},{"letra":"D","texto":"Rigidez tecidual.","ordem":4,"idAlternativa":"ddad09e9-85be-514e-8f64-8ff655b16d90"},{"letra":"E","texto":"Resistência.","ordem":5,"idAlternativa":"a6479d1c-0eef-5862-b2e8-64a590fd7ecc"}],"gabarito":"C","observacoes":[],"idQuestao":"43608af0-a14b-5c7f-8413-52a9779a8ccc","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 9"},{"secao":"Oclusão e Prótese Dentária","numero":10,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Qual é o tipo de preparo em que a parede gengival forma um segmento de circunferência da parede axial até a terminação, propriamente, dita?","alternativas":[{"letra":"A","texto":"Chanfrado.","ordem":1,"idAlternativa":"5c7b31df-b33c-5207-bb1e-a55d194b9ad6"},{"letra":"B","texto":"Chanfro.","ordem":2,"idAlternativa":"5179d322-4cbf-5ec9-b4af-d9b190ac94ce"},{"letra":"C","texto":"Degrau biselado.","ordem":3,"idAlternativa":"7ab27ba6-f0b6-50ee-a908-ec76757744e2"},{"letra":"D","texto":"Ombro.","ordem":4,"idAlternativa":"822ff0ca-a3a0-5b34-961a-84f6778e024e"},{"letra":"E","texto":"Degrau arredondado.","ordem":5,"idAlternativa":"c9ee9512-0e84-5005-8412-48ac29ef46a7"}],"gabarito":"B","observacoes":[],"idQuestao":"1ed2adda-4adb-51f6-903a-bc3080da9972","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 10"},{"secao":"Oclusão e Prótese Dentária","numero":11,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Saber qual tipo de material vai usar é essencial para saber quanto de desgaste e espessura deve-se ter. Quando o desgaste é intermediário, qual deve ser o tipo de coroa a ser usada?","alternativas":[{"letra":"A","texto":"Metálica.","ordem":1,"idAlternativa":"76b9da05-1cf6-54f7-819d-24d3b55621bc"},{"letra":"B","texto":"Metal-free.","ordem":2,"idAlternativa":"1c21d83d-d51e-53bd-b6a8-e9aa2a66bf2c"},{"letra":"C","texto":"Resinosa.","ordem":3,"idAlternativa":"35d6940c-de8e-5ad9-914d-952f877a5f73"},{"letra":"D","texto":"Acrílica.","ordem":4,"idAlternativa":"923232c6-f760-5e57-867f-aac03ccd172c"},{"letra":"E","texto":"Metalocerâmica.","ordem":5,"idAlternativa":"66216de7-7b41-5b77-8431-b0f5361aa078"}],"gabarito":"E","observacoes":[],"idQuestao":"5346491b-f7bb-5610-9750-ea25c274c561","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 11"},{"secao":"Oclusão e Prótese Dentária","numero":12,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Deacordo com Baratieri (2015), as restaurações inlay/fonlay com resina composta têm basicamente as mesmas indicações das restaurações metálicas fundidas e das restaurações infay/onlay de porcelana, podendo, portanto, ser consideradas opções para restaurações indiretas. Baseado na afirmação acima, assinale a opção correta:","alternativas":[{"letra":"A","texto":"a resina empregada na confecção das inlay/onlay é diferente das resinas compostas utilizadas na técnica convencional e intrabucal, porém o processo de polimerização é realizado da mesma maneira.","ordem":1,"idAlternativa":"6c031dd8-7635-58af-9858-e4975af514f3"},{"letra":"B","texto":"assim como nas restaurações metálicas não adesivas, as restaurações semidiretas e indiretas em resina composta requerem a cobertura de cúspides como medida preventiva ou para reforçar a estrutura dental.","ordem":2,"idAlternativa":"4a8dc8df-5996-5ac4-b5e4-1f83f94bf3a5"},{"letra":"C","texto":"estudos demonstram que a infiltração marginal na técnica inlay/onlay é maior do que na técnica direta de restauração com resinacomposta.","ordem":3,"idAlternativa":"566b535b-872d-590b-9dda-65c6746237d7"},{"letra":"D","texto":"durante o preparo cavitário, os ângulos internos da cavidade devem ser arredondados. Para onlays, o término do preparo extracoronário deve ser em chanfrado profundo.","ordem":4,"idAlternativa":"9cd0b773-b346-54af-bb67-2f22b5f61fb1"},{"letra":"E","texto":"o preparo da caixa oclusal em onlays é sempre necessário, independentemente de fatores como a altura da coroa do dente a ser preparado.","ordem":5,"idAlternativa":"3c302735-9ec2-5b31-9438-c605e2d65e3e"}],"gabarito":"D","observacoes":[],"idQuestao":"6f728837-0d7c-583e-b0be-670056494b8c","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 12"},{"secao":"Oclusão e Prótese Dentária","numero":13,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Mezzomo (2006), sobre as disfunçöes temporomandibulares envolvendo os músculos da mastigaçăo, é correto afirmar que:","alternativas":[{"letra":"A","texto":"a miosite é definida como uma contração involuntária breve ou prolongada, que causa dor ou limitasao domovimento.","ordem":1,"idAlternativa":"4dab8641-faf1-574d-90fa-d8bc4de4af4c"},{"letra":"B","texto":"nos casos de dor miofascial, o diagnóstico é feito por meio de palpação digital dos pontos de gatilho, que resulta em alteração ou reprodução regional da dor.","ordem":2,"idAlternativa":"df9c0170-df0c-5ebe-bf0d-e628aa5721e2"},{"letra":"C","texto":"espasmo muscular é uma condição aguda, inflamatória, do músculo etecido conjuntivo com presença de edema e dor contínua.","ordem":3,"idAlternativa":"49e294b7-25ff-59a8-a27d-1f26ca32f234"},{"letra":"D","texto":"para estabelecer o diagnóstico de fibromialgia, a dor deve estar presente em dois dos quatro quadrantes do corpo.","ordem":4,"idAlternativa":"4e71dfd0-f514-5193-ad41-3c2d4f80c088"},{"letra":"E","texto":"a contratura muscular pode ser causada por uma mastigaçăo demorada de alimentos muito rígidos.","ordem":5,"idAlternativa":"6e759084-9926-561a-86f3-450a1bb8e66f"}],"gabarito":"B","observacoes":[],"idQuestao":"c9b97f1a-95d9-5b66-8483-f632e2cbcaed","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 13"},{"secao":"Oclusão e Prótese Dentária","numero":14,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Paciente compareceu ao consultório odontológico para confecção de Prótese Total Dupla. Após montagem em Articulados Semi Ajustável (ASA), o clínico percebe, no plano frontal, que o rebordo inferior direito encontra-se desalinhado externamente em relação ao rebordo superior direito, ocasionando invasão do corredor bucal. Segundo Telles (2011), qual conduta clínica deverá ser adotadapelo profissional?","alternativas":[{"letra":"A","texto":"Enxerto ósseo no rebordo superior.","ordem":1,"idAlternativa":"17e99f7c-5eb6-5298-8afc-573af92e09a0"},{"letra":"B","texto":"Osteoplastia no rebordo inferior.","ordem":2,"idAlternativa":"d6d73ab5-8a35-5914-a60b-fd9a43751a16"},{"letra":"C","texto":"Enxerto ósseo superior e osteoplastia no rebordo inferior.","ordem":3,"idAlternativa":"20f6e993-2d97-5d9c-a538-e2697e31d3d1"},{"letra":"D","texto":"Montagem dos dentes posteriores em mordida cruzada.","ordem":4,"idAlternativa":"aa5fafc2-6a2f-594e-b7ee-b1fe9182d515"},{"letra":"E","texto":"Montagem dos dentes inferiores em posição lingualizada.","ordem":5,"idAlternativa":"24a69c4f-e06d-596e-b13f-e78f009ff3a4"}],"gabarito":"D","observacoes":[],"idQuestao":"bceb43df-b0fc-5911-8cc3-9238c6c77dc6","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 14"},{"secao":"Oclusão e Prótese Dentária","numero":15,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Fradeani (2006), o que é Oclusão Cêntrica:","alternativas":[{"letra":"A","texto":"É a posição de intercuspidação onde todos os dentes encontram-se em relação oclusal.","ordem":1,"idAlternativa":"81bb0528-933d-593a-bdf9-26e7d347323a"},{"letra":"B","texto":"É a relação maxilo-mandibular onde os côndilos encontram-se em posição anterossuperior na cavidade glenoide contra a eminência articular.","ordem":2,"idAlternativa":"0375925e-bbf9-559e-9b62-391bf4ee719d"},{"letra":"C","texto":"É a relação maxilo-mandibular onde os côndilos encontram-se em posição superior na cavidade glenoide contra a eminência articular.","ordem":3,"idAlternativa":"755680c0-ab09-567b-96e8-537a49247b99"},{"letra":"D","texto":"É a relação maxilo-mandibular onde há coincidência entre a Relação Cêntrica (RC) e a Máxima lntercuspidação Habitual (MIH).","ordem":4,"idAlternativa":"f92b3ad3-0953-50c4-8b78-76f16d7ddbe0"},{"letra":"E","texto":"É a posição que representa a intercuspidação das arcadas dentárias com a mandíbula em Relação Cêntrica (RC).","ordem":5,"idAlternativa":"368312ba-66ef-54cd-ac77-e9bb0acc546c"}],"gabarito":"E","observacoes":[],"idQuestao":"1f213ffd-eae3-50ec-b6b6-74501fa1a76c","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 15"},{"secao":"Oclusão e Prótese Dentária","numero":16,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Perante a sociedade, as Próteses Parciais Removíveis (PPRs) possuem a imagem de ser pouco eficientes, danosas aos dentes , ao periodonto e à mucosa, além de pouco confortáveis e antiestéticas. Na maioria das vezes, isso é consequência de iatrogenias por ausência de planejamento por parte do profissional. Segundo Kliemann e Oliveira (2011), sobre planejamento em PPR, pode-se afirmar que:","alternativas":[{"letra":"A","texto":"quanto mais flácida for a fibromucosa, maior deverá ser a retenção indireta.","ordem":1,"idAlternativa":"7c273b73-a934-5cfe-9a25-aab5891e2892"},{"letra":"B","texto":"o melhor prognóstico se dá com os rebordos de forma oval.","ordem":2,"idAlternativa":"1d2f2a33-5010-58c9-a5ca-812b6bb282f3"},{"letra":"C","texto":"o rebordo horizontal é de prognóstico mais pobre, pois tende a ocorrência de movimentos de rotação distal.","ordem":3,"idAlternativa":"dba6fc9e-a823-5229-a13b-584720f823f4"},{"letra":"D","texto":"quanto maior for a área chapeável, maior será a unidade de força por área, favorecendo a adesão, coesão e pressão atmosférica.","ordem":4,"idAlternativa":"d68b03c8-ea67-5a2c-9cea-55babdbfd911"},{"letra":"E","texto":"mecanicamente, a posição ideal do retentor indireto é o mais distante possível do fulcro, que se encontra sobre o apoio principal.","ordem":5,"idAlternativa":"bf2dad79-95df-56c0-aa61-aa9581589ca7"}],"gabarito":"A","observacoes":[],"idQuestao":"9a3dce30-f3ec-556c-bca0-e8005f164c03","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 16"},{"secao":"Oclusão e Prótese Dentária","numero":17,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"O trabalho com Prótese Parcial Removível (PPR) pode ser dividido em fases, de forma conceitual. Considere as etapas que ocorrem no tratamento: 1. Instalação inicial, ajustes aos contornos e às superfícies de apoio das selas. 2. Plano de tratamento. 3. Consulta de revisão para a avaliação periódica das respostas do tecido oral às restaurações. 4. Provisão de suporte adequado para a sela da prótese de extremidade livre. 5. Diagnóstico. 6. Estabelecimento e verificação das relações oclusais e relações dentárias com os dentes naturais opostos e remanescentes. Assinale a sequência correta de eventos, considerando a ordem que deve ocorrer do início ao fim do tratamento com PPR.","alternativas":[{"letra":"A","texto":"5, 4, 2, 6, 3, 1.","ordem":1,"idAlternativa":"ce5cf197-67ea-5be5-8dd3-a6e6d7f131d7"},{"letra":"B","texto":"4, 5, 2, 6, 3, 1.","ordem":2,"idAlternativa":"65442fa4-3ade-562c-a1bc-30fbd9b9f9c2"},{"letra":"C","texto":"5, 2, 4, 6, 1, 3.","ordem":3,"idAlternativa":"f9c94dff-536a-55d2-a71d-72f51dc853d5"},{"letra":"D","texto":"4, 5, 2, 1, 6, 3.","ordem":4,"idAlternativa":"f50b7d95-fc1c-58d6-a227-1ce357a0332d"},{"letra":"E","texto":"6, 5, 2, 1, 4, 3.","ordem":5,"idAlternativa":"bf44bff1-90b3-55fa-8405-ed1e1f9e68be"}],"gabarito":"A","observacoes":[],"idQuestao":"fbd3d955-988b-5407-a3e1-a3fe3bc4719c","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 17"},{"secao":"Oclusão e Prótese Dentária","numero":18,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Cada parte de uma prótese parcial removível desempenha função ou funções importantes para o bom desempenho biomecánico da mesma. “Um bem planejado distribui, efetivamente, as forças por todo o arco e atua reduzindo a carga em áreas isoladas, enquanto controla o movimento da prótese de maneira eficaz.” Assinale a alternativa que completa corretamente a afirmativa anterior.","alternativas":[{"letra":"A","texto":"apoio oclusal","ordem":1,"idAlternativa":"849bdf26-8db3-5107-8c54-f0dfe83b860f"},{"letra":"B","texto":"retentor direto","ordem":2,"idAlternativa":"13d5dd32-36d4-5d6e-8fd6-0cba513dff7d"},{"letra":"C","texto":"retentor indireto","ordem":3,"idAlternativa":"ca70aa05-680d-509b-a839-410d276b9513"},{"letra":"D","texto":"conector maior rígido","ordem":4,"idAlternativa":"be6f1de2-2e9d-5da2-bb0d-a35a9d9ec45b"},{"letra":"E","texto":"componente de reciprocidade","ordem":5,"idAlternativa":"e85748dc-2d8f-5d8a-85fe-e955580145ab"}],"gabarito":"A","observacoes":[],"idQuestao":"b76946ad-759f-5225-b0db-c445258e13c0","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 18"},{"secao":"Oclusão e Prótese Dentária","numero":19,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Para a confecção de próteses em Odontologia, há a necessidade de cópias de estruturas. O que define a indicação de um material de moldagem é o conjunto de propriedades que exibe. Considere um material com o seguinte conjunto de propriedades: menor contração de polimerização; baixa distorção; flexibilidade; rápida recuperação da deformação; e, resistência ao rasgamento moderadamente alta. Assinale a classe de materiais de moldagem que corresponde ao conjunto de propriedades descrito.","alternativas":[{"letra":"A","texto":"Poliéter.","ordem":1,"idAlternativa":"682349dd-06d7-5849-9453-ab2b88f5040d"},{"letra":"B","texto":"Polissulfeto.","ordem":2,"idAlternativa":"028d9dec-dd3d-5f78-b070-a258a1a226d0"},{"letra":"C","texto":"Silicone por adição.","ordem":3,"idAlternativa":"f5d0cfcc-abf6-5f61-8c4e-0e5992c1751b"},{"letra":"D","texto":"Hidrocoloide irreversível.","ordem":4,"idAlternativa":"7ee674e2-ea7a-58e7-9e11-40f21d0dcb0e"},{"letra":"E","texto":"Silicone por condensação.","ordem":5,"idAlternativa":"e72db97c-f3a6-555d-adeb-c5dc3d4cbdf5"}],"gabarito":"C","observacoes":[],"idQuestao":"840612a1-16d0-5a06-a3e4-a430ce38d417","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 19"},{"secao":"Oclusão e Prótese Dentária","numero":20,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Na confecção de próteses totais removíveis mucossuportadas, existem áreas fundamentais para suporte e áreas consideradas de alívio. NÃO corresponde a uma área de alívio:","alternativas":[{"letra":"A","texto":"Papila incisiva.","ordem":1,"idAlternativa":"4d1e4877-7eae-5d32-a473-14c3478fb731"},{"letra":"B","texto":"Sutura palatina.","ordem":2,"idAlternativa":"c4772446-c0f8-5c14-b790-0a59631f9bd6"},{"letra":"C","texto":"Forame incisivo.","ordem":3,"idAlternativa":"e02362e5-4afa-5be7-a8f3-48a3233142e2"},{"letra":"D","texto":"Rugosidade palatina.","ordem":4,"idAlternativa":"972f2cff-811c-5fff-a325-6fb747429927"},{"letra":"E","texto":"Crista do rebordo superior.","ordem":5,"idAlternativa":"0ec72f9a-753f-5755-81e5-de68114ff13b"}],"gabarito":"E","observacoes":[],"idQuestao":"b823d69f-7d96-5f61-a874-71a57af067a3","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 20"},{"secao":"Oclusão e Prótese Dentária","numero":21,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Durante a etapa de diagnóstico e planejamento de próteses fixas ou removíveis, os articuladores atuam como equipamento auxiliar na simulação de estruturas e movimentos presentes no sistema estomatognático. Assinale, a seguir, o valor de ângulo condilar fixo dos articuladores de valor médio.","alternativas":[{"letra":"A","texto":"10°","ordem":1,"idAlternativa":"dcd354c0-64ed-5cfb-afcb-40b16aca996d"},{"letra":"B","texto":"15°","ordem":2,"idAlternativa":"9d3c7a4a-5695-5618-b673-cbda826c4a83"},{"letra":"C","texto":"25°","ordem":3,"idAlternativa":"af617338-eae6-508f-b5fa-293f61ed51bd"},{"letra":"D","texto":"30°","ordem":4,"idAlternativa":"1d166e73-8f49-5d2a-981c-38b8d5f21d43"},{"letra":"E","texto":"45°","ordem":5,"idAlternativa":"f6bc17e8-034d-5393-804b-ba1c24dda9d5"}],"gabarito":"B","observacoes":[],"idQuestao":"9f3c123a-58ee-5eb6-887a-007039d09003","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 21"},{"secao":"Oclusão e Prótese Dentária","numero":22,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Considerando o plano de cera e o plano oclusal inferior, há determinantes anatomofisiológicas que devem ser observadas, sempre que possível, nas etapas de confecção de próteses totais removíveis mucossuportadas. NÃO corresponde à posição correta em que o plano oclusal inferior deverá ficar:","alternativas":[{"letra":"A","texto":"Abaixo do dorso da língua.","ordem":1,"idAlternativa":"c7e2be0c-6121-52c0-b2d5-c744bbe005dd"},{"letra":"B","texto":"No nível do terço médio da papila retromolar.","ordem":2,"idAlternativa":"a86bf146-d177-5457-816d-388f4d5f14fd"},{"letra":"C","texto":"No nível ou imediaçóes das comissuras labiais.","ordem":3,"idAlternativa":"ceac786d-2321-5ecb-a1e1-62208244cae0"},{"letra":"D","texto":"Paralelo às fibras médias do músculo bucinador.","ordem":4,"idAlternativa":"ecc9ca27-871e-5860-92f6-c33af583488e"},{"letra":"E","texto":"Coincidente com o terço cervical palatino dos incisivos superiores.","ordem":5,"idAlternativa":"2fb5cf6f-1d4b-5de1-b6dc-a1022f619740"}],"gabarito":"B","observacoes":[],"idQuestao":"16d2c7a4-ac4d-5976-b1b7-e2b8e81250db","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 22"},{"secao":"Oclusão e Prótese Dentária","numero":23,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Na maxila, devem-se aliviar os freios, ficando do fundo dos sulcos labial e vestibular, contornar as tuberosidades, passar pelos sulcos e, na região do selado palatino, acompanhar o limite entre , cobrindo as fóveas palatinas.” Sobre a delimitação da área de suporte no modelo da maxila, assinale a alternativa que completa correta e sequencialmente a afirmativa anterior.","alternativas":[{"letra":"A","texto":"2 a 3 mm aquém / hamulares / o palato duro emole","ordem":1,"idAlternativa":"f8b839d2-c300-5c94-a1b3-030774dea948"},{"letra":"B","texto":"2 a 3 mm além / pterigóideos /o palato duro e mole","ordem":2,"idAlternativa":"829cba5a-a111-532a-ada0-b555fc31957e"},{"letra":"C","texto":"2 a 3 mm aquém / pterigóideos / o palato duro emole","ordem":3,"idAlternativa":"dfb87234-9993-5248-9bb7-b5eecebfa3e4"},{"letra":"D","texto":"2 a 3 mm além / hamulares / a gengiva inserida e a mucosa alveolar","ordem":4,"idAlternativa":"2114d40b-af34-5a77-a53d-8f10fe72f1bd"},{"letra":"E","texto":"2 a 3 mm aquém / pterigóideos / a gengiva inserida e a mucosa alveolar","ordem":5,"idAlternativa":"327404e3-53de-54d3-a9ee-70f4c583adf1"}],"gabarito":"E","observacoes":[],"idQuestao":"f0c63bea-e999-5ff4-b09f-0799fb696ac3","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 23"},{"secao":"Oclusão e Prótese Dentária","numero":24,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"A ocorrência de espaços negros (black spaces) na região interproximal de dentes anteriores é uma ocorrência desagradável em reabilitações sobre implantes, com impacto negativo na aceitação pelo paciente. Algumas características podem predispor ou aumentar a chance desta ocorrência, como a área de contato interdental, volume ósseo e forma do dente natural. Em relação à forma do dente natural, são papilas maiores, finas e longas, predispondo à formação dos citados espaços:","alternativas":[{"letra":"A","texto":"Ovais.","ordem":1,"idAlternativa":"72fbe38c-aaaa-540c-b4ed-f233854a0529"},{"letra":"B","texto":"Quadradas.","ordem":2,"idAlternativa":"ef36c623-6af5-556a-bb93-dcf782981aa2"},{"letra":"C","texto":"Triangulares.","ordem":3,"idAlternativa":"27cffcaa-b872-54ed-8f42-ec8d3ffc4aff"},{"letra":"D","texto":"Trapezoidais.","ordem":4,"idAlternativa":"25208576-3db8-5d1e-93fc-d36a408b5797"},{"letra":"E","texto":"Retangulares.","ordem":5,"idAlternativa":"05d4a406-fda2-5c2d-b118-55c1d2c78241"}],"gabarito":"E","observacoes":[],"idQuestao":"a5357a51-405c-5296-a60d-7f143ed56a18","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 24"},{"secao":"Oclusão e Prótese Dentária","numero":25,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"Sobre a guia canina, analise a afirmação abaixo. “Quando todos os dentes anteriores são examinados, torna-se claro que os caninos são os mais adequados para receber as forças horizontais que ocorrem durante os movimentos excêntricos da mandíbula.” Esta afirmação do autor pressupõe que o canino tem características morfológicas imprescindíveis para que exerça essa função. A alternativa que MELHOR descreve esta condição é:","alternativas":[{"letra":"A","texto":"Raízes longas e largas com melhor relação coroa/raiz, com maior diâmetro vestíbulo-lingual na região cervical do dente, osso alveolar compacto e denso além de posição favorável no arco dental.","ordem":1,"idAlternativa":"ce14418c-f697-5046-a5f6-ac59f4746009"},{"letra":"B","texto":"Raízes longas e largas com melhor relação coroa/raiz, com maior diâmetro mésiodistal na região cervical do dente, osso alveolar compacto e denso além de posição favorável no arco dental.","ordem":2,"idAlternativa":"d553c73e-3a76-56b2-b95a-8f375261a1a7"},{"letra":"C","texto":"Raízes longas e largas, relação coroa/raiz de 1/1 com maior diâmetro mésio- distal na região cervical do dente, osso alveolar mais resiliente além de posição favorável no arco dental para desoclusão em grupo.","ordem":3,"idAlternativa":"b4673b2e-7c15-55ee-8497-f718214b04da"},{"letra":"D","texto":"Raízes longas e largas, relação coroa/raiz de 1/1 com maior diâmetro vestí- bulolingual na região cervical do dente, osso alveolar compacto e denso além de posição favorável no arco dental.","ordem":4,"idAlternativa":"32d75d75-e1af-5a0f-aa45-a2eb95fe57a7"},{"letra":"E","texto":"Volume da coroa semelhante aos demais dentes anteriores, conferindo per- feita harmonia nos movimentos excêntricos da mandíbula.","ordem":5,"idAlternativa":"8f867228-a15e-5cd0-a251-c1da25d6f2c1"}],"gabarito":"A","observacoes":[],"idQuestao":"4d52c3fc-a765-5e27-a0eb-91bda695b5ad","idDisciplina":"ee44d536-3674-57f4-8860-a29e886cb761","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Oclusão e Prótese Dentária | Questão 25"},{"secao":"Periodontia","numero":1,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"Métodos de controle da placa bacteriana como as práticas de higiene bucal: escovação dentária e uso do fio dental, aplicação de flúor e controle da dieta desempenham importante papel na prevenção das doenças bucais. A esse respeito, assinale a alternativa incorreta.","alternativas":[{"letra":"A","texto":"O controle da placa por meio da higiene bucal é a medida mais direta e abrangente de controle e prevenção da cárie dentária e das doenças gengivais, poisse direciona para a causa determinante dessas doenças.","ordem":1,"idAlternativa":"b7afd2bf-7096-51dc-a503-f31274b7f3b3"},{"letra":"B","texto":"A limpeza profissional dos dentes consiste no polimento coronário e na raspagem e alisamento radicular. A limpeza deve ser feita com o auxílio de uma pasta de baixa abrasividade, que pode ser fluoretada ou não.","ordem":2,"idAlternativa":"cfa4359a-1a19-58e9-bbe6-4638c72fac25"},{"letra":"C","texto":"Entre os meios mecânicos para higienizar os dentes, a escova dentária é o mais aceito mundialmente. A escova deve ser funcional e eficiente na remoção do biofilme dental, sem causar danos aos tecidos gengivais e sem provocar ranhuras nas superfícies dentárias.","ordem":3,"idAlternativa":"f23c25a4-a250-5674-9ec2-7f79ae172ca4"},{"letra":"D","texto":"A escovação dental isolada é suficiente, pois remove a placa interdental por completo, não sendo necessária a utilização de alguns dispositivos auxiliares, tais como fios / fitas dentais, escovas dentais interproximais, enxaguatórios bucais, entre outros.","ordem":4,"idAlternativa":"ee039d8a-d833-5fd3-b445-7745c3eba40f"}],"gabarito":"D","observacoes":[],"idQuestao":"596273fd-9cb2-5b52-8e0f-b3e24a6f962c","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 1"},{"secao":"Periodontia","numero":2,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"Na terapia periodontal, as curetas têm se mostrado os instrumentos para a raspagem e o aplainamento radicular manual/mecânico mais versáteis e eficazes. Com base nas aplicações das curetas de Gracey, correlacione a segunda coluna à primeira. 1 - Dentes anteriores 2 - Dentes posteriores, faces vestibular e lingual 3 - Dentes posteriores, face mesial 4 - Dentes posteriores, face distal ( ) Gracey 13-14. ( ) Gracey 11-12. ( ) Gracey 7-8, 9-10. ( ) Gracey 5-6. Assinale a alternativa que apresenta a sequência CORRETA, considerando a correlação estabelecida de cima para baixo.","alternativas":[{"letra":"A","texto":"1, 2, 3, 4.","ordem":1,"idAlternativa":"21d2ff2b-f8bd-5665-a834-564713409d44"},{"letra":"B","texto":"4, 3, 2, 1.","ordem":2,"idAlternativa":"d8e0bd39-c8a1-5694-8424-ef43b1024c1e"},{"letra":"C","texto":"1, 2, 4, 3.","ordem":3,"idAlternativa":"65209bef-b322-5b63-823b-f7eaa0e04d4b"},{"letra":"D","texto":"2, 3, 4, 1.","ordem":4,"idAlternativa":"c88c5003-cb08-53b2-86be-e0dc04cbedab"},{"letra":"E","texto":"2, 4, 1, 3.","ordem":5,"idAlternativa":"f4293a64-92e8-5b74-a560-b3d3a0a49057"}],"gabarito":"B","observacoes":[],"idQuestao":"5ee2e85b-4531-51c7-a8d1-b5341454b70f","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 2"},{"secao":"Periodontia","numero":3,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"Dentre os listados abaixo, o agente microbiológico mais associado à patogênese das doenças periodontais necrosantes é o:","alternativas":[{"letra":"A","texto":"Capnocytophaga gingivalis","ordem":1,"idAlternativa":"0f3ef4a9-a04a-5c35-b9fd-794e751c1c00"},{"letra":"B","texto":"Actinomyces odontolyticus","ordem":2,"idAlternativa":"398296be-6a55-5864-b961-a0fba2ccb0f8"},{"letra":"C","texto":"Escherichia coli","ordem":3,"idAlternativa":"1c2e862c-61ac-5b2f-b91d-6baa9faefae6"},{"letra":"D","texto":"Aggregatibacter actinomycetemcomitans","ordem":4,"idAlternativa":"1b87f8a3-2be0-579a-acbd-b28e4f8ec45c"}],"gabarito":"D","observacoes":[],"idQuestao":"78a670b2-913b-5de4-b508-9b70035e8935","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 3"},{"secao":"Periodontia","numero":4,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"Em relação as diferenças histológicas entre os cementos primário e secundário, assinale a afirmação incorreta:","alternativas":[{"letra":"A","texto":"O cemento secundário é composto de delicadas fibras colágenas orientadas ao acaso e contidas em uma matriz granulosa.","ordem":1,"idAlternativa":"e879c8a7-16f7-5315-ae83-c5f7c8cdafce"},{"letra":"B","texto":"O cemento primário geralmente contém menos linhas de desenvolvimento do que o cemento secundário.","ordem":2,"idAlternativa":"eb1bd446-4744-5307-b519-d5a88ad82d7b"},{"letra":"C","texto":"O cemento primário é acelular e forma-se juntamente com a dentina radicular e na presença da bainha epitelial.","ordem":3,"idAlternativa":"14e8e694-dd50-50c8-9eaa-122ba3d99e51"},{"letra":"D","texto":"O cemento secundário é celular e contém fibras colágenas grosseiras orientadas paralelamente à superfície radicular.","ordem":4,"idAlternativa":"176c1ba4-cb03-5adc-ae33-c4e933168fd0"}],"gabarito":"A","observacoes":[],"idQuestao":"f1b35b19-6689-5013-b674-5bd87e199ca7","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 4"},{"secao":"Periodontia","numero":5,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Como é chamada a mucosa localizada sobre o dorso da língua, que protege a musculatura lingual e, nos 2/3 anteriores da língua, as papilas filiformes e fungiformes, que são recobertas por epitélio queratinizado e não queratinizado,respectivamente?","alternativas":[{"letra":"A","texto":"Mucosa mastigatória.","ordem":1,"idAlternativa":"6d00737e-9321-5233-92fc-e50adf796c8d"},{"letra":"B","texto":"Mucosa de revestimento.","ordem":2,"idAlternativa":"0e953fe8-6223-5f97-9b73-af70181a456f"},{"letra":"C","texto":"Mucosa labial.","ordem":3,"idAlternativa":"c7a27808-6d86-5d9f-9d25-25de36d6cd11"},{"letra":"D","texto":"Mucosa especializada.","ordem":4,"idAlternativa":"7dec1b57-23e4-58eb-ab28-b497e3b8de82"},{"letra":"E","texto":"Mucosa papilar.","ordem":5,"idAlternativa":"bfece77c-c738-5185-99ee-ffae6e9e36ab"}],"gabarito":"D","observacoes":[],"idQuestao":"4db7dff2-d01e-5ee0-b2ed-9d463fcbe37e","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 5"},{"secao":"Periodontia","numero":6,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Qual tecido dental apresenta a maior concentração mineral do corpo e que se constitui quase, exclusivamente, de fosfato de cálcio?","alternativas":[{"letra":"A","texto":"Esmalte.","ordem":1,"idAlternativa":"8797f593-2cbd-5e45-9dd5-aa409577c15e"},{"letra":"B","texto":"Dentina.","ordem":2,"idAlternativa":"81e80994-ebaf-5b5f-b633-734ce17e0d30"},{"letra":"C","texto":"Polpa.","ordem":3,"idAlternativa":"bf0b3883-f4bd-58a3-a73a-1bf6bb176729"},{"letra":"D","texto":"Cemento.","ordem":4,"idAlternativa":"083f0ec2-63f4-5962-94d7-9fed7857252c"},{"letra":"E","texto":"Ligamento.","ordem":5,"idAlternativa":"ef60cea4-700f-56eb-a0e8-20b1848485b2"}],"gabarito":"A","observacoes":[],"idQuestao":"f8aba8f7-92d0-5be2-a42c-0a5fc6ff9faa","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 6"},{"secao":"Periodontia","numero":7,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Qual é o tipo celular predominante, no tecido conjuntivo pulpar?","alternativas":[{"letra":"A","texto":"Macrófagos.","ordem":1,"idAlternativa":"42e7bf89-9762-5e85-ae8b-b312a349169c"},{"letra":"B","texto":"Eosinófilos.","ordem":2,"idAlternativa":"5aedcedf-45d0-5d04-9c5b-10ec2cc37731"},{"letra":"C","texto":"Plasmócitos.","ordem":3,"idAlternativa":"141bf45f-2bf1-5c0d-85de-fe9d0a66ee56"},{"letra":"D","texto":"Fibroblastos.","ordem":4,"idAlternativa":"f7ba31b8-c22d-5701-8789-f6a1eae15a5b"},{"letra":"E","texto":"Linfócitos.","ordem":5,"idAlternativa":"81f020a2-5287-5e0e-9de9-445bb8d217b8"}],"gabarito":"D","observacoes":[],"idQuestao":"c8932bd5-e842-5b39-80c2-315a74a394ee","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 7"},{"secao":"Periodontia","numero":8,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Andreassen e Andreassen (2001), a avulsão de dentes permanentes é mais comum na dentição jovem, em que o desenvolvimento radicular ainda está incompleto e o periodonto muito resiliente. Sobre esse tipo de traumatismo dentário, é correto afirmar que:","alternativas":[{"letra":"A","texto":"o reimplante mediato em associação com um tratamento extraoral com fluoreto está indicado após a avulsão de incisivos permanentes com cáries extensas, ápice aberto e período extra-aiveolar em meio seco maior que 60 minutos.","ordem":1,"idAlternativa":"f83e24fe-285a-5f41-8262-94b582c14c5b"},{"letra":"B","texto":"para otimizar a cicatrização, o alvéolo deve ser irrigado com soro fisiológico para remover debris, porém é importante não remover o coágulo, pois a presença do coágulo no alvéolo no momento do reimplante diminui as chances de anquilose","ordem":2,"idAlternativa":"039ea96f-5e65-5e05-88c1-65281a8066a9"},{"letra":"C","texto":"em dentes com formação radicular incompleta (forame apical maior que 1mm), a polpa dever ser extirpada e o canal radicular preenchido com curativo de hidróxido de cálcio imediatamente antes da remoção da contenção.","ordem":3,"idAlternativa":"ebb8ed6d-8398-5cac-81ca-a5bddfd6302f"},{"letra":"D","texto":"em condições favoráveis para o procedimento de reimplante, a revascularização e a reinervação da polpa são eventos esperados. A polpa inteira de um incisivo de uma pessoa jovem pode serrevascularizada em aproximadamente 35 dias.","ordem":4,"idAlternativa":"1435e0e1-296c-5bc7-ba34-f659107e91e6"},{"letra":"E","texto":"se há um dano mínimo à camada mais interna do ligamento periodontal, este ponto será reabsorvido por macrófagos e osteoclastos, resultando em uma escavação da superfície radicular. Essa cavidade será reparada por novo cemento e fibras de Sharpey. Esse tipo de reabsorção é chamada de reabsorção por substituição","ordem":5,"idAlternativa":"89852279-5c6b-5246-a8a1-5d298c04c340"}],"gabarito":"D","observacoes":[],"idQuestao":"724c7d65-d5b5-5659-a336-ed6d281d68c8","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 8"},{"secao":"Periodontia","numero":9,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Lindhe et al. (2018), como é denominada a técnica de escovação que foi elaborada para o massageamento e estimulação das gengivas, assim como para a limpeza das áreas cervicais dos dentes, na qual a cabeça da escova é posicionada em uma direção oblíqua ao ápice da raiz com cerdas localizadas parcialmente na gengiva e na superfície dos dentes, e na qual uma leve pressão, juntamente com o movimento vibratório leve, é aplicada sobre o cabo, sem que a escova seja deslocada de sua posição original?","alternativas":[{"letra":"A","texto":"Stillman.","ordem":1,"idAlternativa":"ef5e5236-dda7-5a9f-9548-646b4988a45c"},{"letra":"B","texto":"Charters.","ordem":2,"idAlternativa":"35c39011-31c2-5f32-82e0-621cc89deb33"},{"letra":"C","texto":"Rotação.","ordem":3,"idAlternativa":"f6f48eb3-e454-5386-ac88-541fd2836920"},{"letra":"D","texto":"Bass.","ordem":4,"idAlternativa":"72e51f56-1f5e-5567-906f-3d5360df979c"},{"letra":"E","texto":"Esfregaço.","ordem":5,"idAlternativa":"96c82538-d94a-5b16-8ad4-3b23db54ca07"}],"gabarito":"A","observacoes":[],"idQuestao":"0eccec87-5c37-573d-bcf2-7be157270571","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 9"},{"secao":"Periodontia","numero":10,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Lindhe et al. (2018), são fatores ambientais, adquiridos e comportamentais de risco para a periodontite, EXCETO:","alternativas":[{"letra":"A","texto":"polimorfismos gênicos.","ordem":1,"idAlternativa":"4c4d5e4d-535f-51a5-82d0-2d53d9e6c305"},{"letra":"B","texto":"tabagismo,","ordem":2,"idAlternativa":"9087be98-8460-5a95-bf84-eb2967da9305"},{"letra":"C","texto":"diabetes melito.","ordem":3,"idAlternativa":"c3f12c41-d1df-5e84-bea0-a3801c02c37c"},{"letra":"D","texto":"obesidade.","ordem":4,"idAlternativa":"6c95889e-3908-5fe4-b909-4ecca6d221e9"},{"letra":"E","texto":"microbiota específica.","ordem":5,"idAlternativa":"850ce590-27e1-51cc-a71c-c82021da62be"}],"gabarito":"A","observacoes":[],"idQuestao":"3f7de88a-b3ec-5de0-b022-587521349d2b","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 10"},{"secao":"Periodontia","numero":11,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Lindhe, Lang & Karring (2018), sobre as características específicas da infećção periodontal e os princfpios do uso de antibióticos na Periodontia, é correto afirmar que:","alternativas":[{"letra":"A","texto":"a invasăo e a multiplicação das bactérias nos tecidos periodontais năo são consideradas indispensáveis para o desenvolvimento da doença, embora exista confirmação de penetração bacteriana em condições altamente ativas.","ordem":1,"idAlternativa":"7811025c-95fc-598b-bc1b-33cf2dbc040e"},{"letra":"B","texto":"nos biofilmes radiculares formados pela microbiota subgengival, os microrganismos resistentes de baixa virulência intrínseca năo conseguem proteger os patógenos sensíveis ao antibiótico.","ordem":2,"idAlternativa":"c1a0f9cd-c242-51fd-aad8-369f89570227"},{"letra":"C","texto":"a administraçăo sistêmica de antibióticos em Periodontia năo se faz necessária, uma vez que a instrumentaçăo mecánica e o uso de antibióticos locais săo capazes de remover completamente os patógenos periodontais dos locais infectados.","ordem":3,"idAlternativa":"29b05a2b-58a3-58f6-8d13-76534a5dfb92"},{"letra":"D","texto":"em ambientes de bolsa periodontal, os agentes antimicrobianos podem ser ativados pelas massas de microrganismos presentes.","ordem":4,"idAlternativa":"2cd86e85-6985-5c64-846b-0c1b050f4edc"},{"letra":"E","texto":"para serem efetivos, os agentes antimicrobianos usados na terapia periodontal precisam estar disponíveis em concentração baixa năo apenas dentro, mas também forados tecidos afetados.","ordem":5,"idAlternativa":"89c55148-c8e6-5ae6-ab88-29c7d666ed37"}],"gabarito":"A","observacoes":[],"idQuestao":"d3b09e0a-0784-5553-9b3c-ac7d6b9bd0f2","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 11"},{"secao":"Periodontia","numero":12,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Diante da importância do sorriso e da complexidade da avaliação estética, alguns parâmetros, como referências faciais, dento-labiais, gengivais e dentais, são de extrema importância na identificação e no registro de todos os dados necessários para otimizar os resultados de uma reabilitação estético-funcional. Assim, o conhecimento das características inerentes às estruturas a serem restauradas é essencial para o planejamento e a execução dos tratamentos. Na análise dental, as relações e proporções destes elementos determinam um equilíbrio para a percepção estética de um sorriso. A esse respeito, é correto afirmar que","alternativas":[{"letra":"A","texto":"o zênite gengival fica deslocado distalmente ao longo eixo coronário nos dentes com formato quadrado.","ordem":1,"idAlternativa":"7fe19f99-288c-5c02-8e01-cc02acff452c"},{"letra":"B","texto":"as cristas marginais são suaves e convergentes para incisal e cervical nos dentes com formato triangular.","ordem":2,"idAlternativa":"3faf61df-a8bb-58b5-b659-ac958e581970"},{"letra":"C","texto":"os sulcos de desenvolvimento possuem discreta concavidade entre as cristas nos dentes com formato ovoide.","ordem":3,"idAlternativa":"659e0140-8dae-5644-89a1-5acbdd5d5b46"},{"letra":"D","texto":"a área de sombra define a percepção óptica do volume do dente, independentemente da iluminação, apresentando uma transição suave com a área plana em todos os formatos de dentes.","ordem":4,"idAlternativa":"1fbb133b-e621-5871-bff7-47d5d6bccd6d"}],"gabarito":"A","observacoes":[],"idQuestao":"2a04e96b-c838-5ef6-8f54-3298e701e6c1","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 12"},{"secao":"Periodontia","numero":13,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Carranza et al. (2016), na gengiva humana clinicamente saudável, um sulco de alguma profundidade é frequentemente encontrado. A avaliação clínica usada na determinação da profundidade do sulco envolve a introdução de um instrumento metálico, a sonda periodontal e a estimativa da distância que esta penetra (a profundidade de sondagem). Dentre os fatores que influenciam a penetração da sonda destacam-se o/a","alternativas":[{"letra":"A","texto":"diâmetro da sonda, a força de sondagem e o grau de inflamação tecidual.","ordem":1,"idAlternativa":"88df4ffd-eb73-5930-a293-0226c7f5fcd4"},{"letra":"B","texto":"sangramento a sondagem, o diâmetro da sonda e a quantidade de cálculo.","ordem":2,"idAlternativa":"e6113946-84e5-5c7a-a82e-5a9f944b2517"},{"letra":"C","texto":"quantidade de cálculo, a força de sondagem e o sangramento a sondagem.","ordem":3,"idAlternativa":"85d3365e-96a1-5798-ab28-e960b977bf76"},{"letra":"D","texto":"grau de inflamação tecidual, a força de sondagem e o sangramento a sondagem.","ordem":4,"idAlternativa":"47adc000-ecd1-5b5b-807e-cc725970275e"}],"gabarito":"A","observacoes":[],"idQuestao":"41d95b70-5055-5ed0-a6af-c1fc813e1b94","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 13"},{"secao":"Periodontia","numero":14,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"A doença periodontal resulta de uma interação complexa entre o biofilme subgengival e os eventos imunoinflamatórios do hospedeiro que se desenvolvem nos tecidos gengivais e periodontais em resposta aos desafios apresentados pelas bactérias.Informe se é verdadeiro (V) ou falso (F) o que se afirmaabaixo. ( ) A resposta imunoinflamatória do hospedeiro é fundamental para determinar quais indivíduos desenvolverão periodontite. ( ) Page e Schroeder descreveram as mudanças histológicas que ocorrem nos tecidos gengivais como lesão gengival primária, inicial, estabelecida e avançada. ( ) As fímbrias de certas espécies bacterianas, particularmente da P. gingivalis, podem exercer um papel na patogênese periodontal. As fímbrias da P. gingivalis estimulam as respostas imunes, como a secreção da IL-10. De acordo com as afirmações, a sequência correta é","alternativas":[{"letra":"A","texto":"(V); (V); (F).","ordem":1,"idAlternativa":"1acd43d5-77b0-5059-ad14-b83cf635dbdc"},{"letra":"B","texto":"(F); (F);(V).","ordem":2,"idAlternativa":"a6d839a2-495e-5853-9170-cf9db8b493d2"},{"letra":"C","texto":"(V); (F);(F).","ordem":3,"idAlternativa":"015a139b-d73a-56c7-b7ee-152da9add9db"},{"letra":"D","texto":"(F); (V);(V).","ordem":4,"idAlternativa":"79b8aabd-b040-5491-8c1f-bfdacc0757d0"}],"gabarito":"A","observacoes":[],"idQuestao":"5bf32d25-d82c-51e3-955f-7266eac01c86","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 14"},{"secao":"Periodontia","numero":15,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"As doenças crônicas humanas como c câncer, diabetes e doença periodontal destrutiva têm causas complexas. Segundo Carranza et al. (2016), são fatores causadores modificáveis suspeitos para a doença periodontal, exceto a/o","alternativas":[{"letra":"A","texto":"nutrição.","ordem":1,"idAlternativa":"809688a3-43c1-56db-a9cf-de7cfcf41ed5"},{"letra":"B","texto":"tabagismo.","ordem":2,"idAlternativa":"cb8cb06b-03cf-596b-9092-816be39f0e7c"},{"letra":"C","texto":"placa bacteriana.","ordem":3,"idAlternativa":"94cca1f6-1c07-5af4-be4b-2d6929e686cf"},{"letra":"D","texto":"sangramento gengival.","ordem":4,"idAlternativa":"75a70acf-4b47-5238-828d-3bdaf87e9d47"}],"gabarito":"D","observacoes":[],"idQuestao":"877b9386-8e57-515d-a4d2-0f2f08ecc06b","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 15"},{"secao":"Periodontia","numero":16,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"O cálculo dental, ou tártaro, representa a placa bacteriana mineralizada. O cálculo subgengival apresenta camadas mais homogêneas de minerais, já que ele é formado em camadas de densidade mineral igualmente alta. Segundo Lindhe et al. (2018), o mineral predominante nesse tipo de cálculo é a/o","alternativas":[{"letra":"A","texto":"brushita.","ordem":1,"idAlternativa":"373ca234-35cb-560b-b23c-08c14faac2f1"},{"letra":"B","texto":"hidroxiapatita.","ordem":2,"idAlternativa":"c711bb0b-9250-5e42-8202-bd059b608303"},{"letra":"C","texto":"betafosfato tricálcio.","ordem":3,"idAlternativa":"b650f288-a98d-5680-8e5c-4c3df96257d8"},{"letra":"D","texto":"fosfato de octacálcio.","ordem":4,"idAlternativa":"17aa479d-b694-56ba-8dcc-1afd7729ff11"}],"gabarito":"C","observacoes":[],"idQuestao":"41fbf0fc-11c9-52c3-a418-fe4b9e1414d4","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 16"},{"secao":"Periodontia","numero":17,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"O sistema de classificação de casos precisa ser um processo dinâmico que requer revisão ao longo do tempo. De acordo com a classificação periodontal (Sobrape, 2019), assinale a alternativa que responde em qual estágio se caracteriza um paciente que apresenta: nível de inserção clínica maior ou igual a 5mm, perda óssea estendendo ao terço médio ou mais, perda dentária devido à periodontite envolvendoaté 4 dentes, profundidade de sondagem maior ou igual a 6mm, envolvimento de furca Classe II ou III.","alternativas":[{"letra":"A","texto":"Estágio I.","ordem":1,"idAlternativa":"7a363bae-b82f-51f7-9cb2-b5970cd3c51a"},{"letra":"B","texto":"Estágio II.","ordem":2,"idAlternativa":"81d92567-b31d-5297-998c-ed2755815a64"},{"letra":"C","texto":"Estágio III.","ordem":3,"idAlternativa":"3f1225c8-99e3-56ff-9e71-5a069af01d21"},{"letra":"D","texto":"Estágio IV.","ordem":4,"idAlternativa":"b46716c4-54db-5561-9919-67d8c652ae93"}],"gabarito":"C","observacoes":[],"idQuestao":"82778958-e658-5a01-9601-6878fa3ccce1","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 17"},{"secao":"Periodontia","numero":18,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"O exame clínico é o passo inicial para o estabelecimento de um diagnóstico, determinar a presença, severidade e extensão da doença e selecionar os melhores procedimentos de tratamento e considerar o prognóstico. Considerando o diagnóstico da doença periodontal segundo Sobrape (2019), é correto afirmar que a","alternativas":[{"letra":"A","texto":"classificação tipo II de Cairo et.a: a recessão está associada à perda de inserção interproximal, sendo esta maior que a perda de inserção nas faces livres.","ordem":1,"idAlternativa":"1ebcd0e6-e499-5180-a045-056577cb4df9"},{"letra":"B","texto":"mobilidade dental pode ser classificada segundo Miller em grau 0, 1, 2 e 3. O grau 2 tem mobilidade intensa da coroa do dente, nas direções horizontal e vertical, impossibilitando a função do dente.","ordem":2,"idAlternativa":"7d0efa05-337e-5f45-be82-3a33da88d8ce"},{"letra":"C","texto":"sondagem periodontal é o parâmetro mais comum utilizado para documentar a perda de inserção e profundidade de sondagem. A força de sondagem é variável e deve ser em torno de 0,60-0,70N.","ordem":3,"idAlternativa":"c025ff28-916c-536e-a2da-435c443f8747"},{"letra":"D","texto":"classificação das lesões de furca segundo Glickman: o grau III é a furca, que está oculta pela gengiva, mas o nível de perda óssea viabiliza a passagem completa de uma sonda pelo sentido mesiodistal ou vestibulolingual.","ordem":4,"idAlternativa":"b7baa550-94ae-549b-862f-9755f0841929"}],"gabarito":"D","observacoes":[],"idQuestao":"4ee15949-4d2f-5053-80f7-287bd4bb251e","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 18"},{"secao":"Periodontia","numero":19,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Preencha corretamente as lacunas. Segundo Carranza et al.(2016): a Síndrome de Papillon-Lefèvre é uma doença hereditária rara que parece seguir um padrão autossômico . É caracterizada por lesões da pele , grave destruição e, em alguns casos, calcificação da dura-máter. A sequência que preenche corretamente as lacunas do texto é","alternativas":[{"letra":"A","texto":"dominante / hipoceratóticas / da gengiva","ordem":1,"idAlternativa":"7e805288-4f95-59b0-bf86-c75c3e1beb6b"},{"letra":"B","texto":"recessivo / hipoceratóticas / da gengiva","ordem":2,"idAlternativa":"69828f90-2a18-5c48-aed2-cf29c542b811"},{"letra":"C","texto":"dominante / hiperceratóticas / doperiodonto","ordem":3,"idAlternativa":"12ec7f37-4d53-5c12-aac8-d966b1ad05bc"},{"letra":"D","texto":"recessivo / hiperceratóticas / doperiodonto","ordem":4,"idAlternativa":"35bfece4-ba63-5b29-bce1-dadb662c8b3d"}],"gabarito":"D","observacoes":[],"idQuestao":"1c2e7da5-f5e4-56be-a771-2f78ae73f58a","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 19"},{"secao":"Periodontia","numero":20,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"A saúde de periodontal é um pré-requisito da Odontologia integral bem-sucedida, e a preparação do periodonto para a Odontologia restauradora é fundamental para se alcançar a longevidade do tratamento. Sobre o tema, analise as afirmativas. I- A infecção periodontal ativa deve ser tratada e controlada antes do in cio da Odontologia restauradora, estética e de implantes. II- Forças traumáticas posicionadas sobre dentes com periodontite em progressão podem aumentar a mobilidade dentária, o desconforto e a perda de inserção. III- A movimentação ortodôntica de dentes mal posicionados deve ser feita antes do tratamento periodontal, porque tem o tempo de duração diminuído devido à qualidade, quantidade e topografia do periodonto. IV- Pelo fato de a terapia periodontal e restauradora ser situacional e específica fica para cada paciente, o plano de tratamento deve ser adaptável a alterações, dependendo de variáveis encontradas no curso do tratamento. Estão corretas as afirmativas","alternativas":[{"letra":"A","texto":"I, III e IV, apenas.","ordem":1,"idAlternativa":"536d8598-a569-5642-a9e6-b693354fb289"},{"letra":"B","texto":"I e III, apenas.","ordem":2,"idAlternativa":"6e0f9e00-b476-57dc-96ab-0a59ec15f86e"},{"letra":"C","texto":"I, II e IV, apenas.","ordem":3,"idAlternativa":"3bf09c3c-cf2d-51c6-bd59-abfe61b4578d"},{"letra":"D","texto":"II e III, apenas.","ordem":4,"idAlternativa":"a094c800-1d4f-51f1-b9b1-21fa0c84ecf9"},{"letra":"E","texto":"II e IV, apenas.","ordem":5,"idAlternativa":"762fdd66-59d2-5ff6-83ee-f73880b5fe88"}],"gabarito":"C","observacoes":[],"idQuestao":"c8ec5693-0ecd-52fa-9756-b03f147ba228","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 20"},{"secao":"Periodontia","numero":21,"orgao":null,"cargo":null,"ano":null,"enunciado":"é um tipo específico fico de articulação fibrosa, que faz a união da raiz do dente ao seu alvéolo. Assinale a alternativa que preenche corretamente a lacuna.","alternativas":[{"letra":"A","texto":"Cementose","ordem":1,"idAlternativa":"af12c785-72f4-5004-976b-f47e49917225"},{"letra":"B","texto":"Sindesmose","ordem":2,"idAlternativa":"22f14a97-85bc-5d1d-aa48-5921742e2127"},{"letra":"C","texto":"Sharpey","ordem":3,"idAlternativa":"dc397f66-5d1d-5030-8680-4808818eb0d2"},{"letra":"D","texto":"Intrusão","ordem":4,"idAlternativa":"b2e051df-39c5-5e4a-8fc7-436856d01d81"},{"letra":"E","texto":"Gonfose","ordem":5,"idAlternativa":"1b1f3ee3-3431-511e-9c1a-87e1faba786a"}],"gabarito":"E","observacoes":["Obs.: O PDF não traz o cabeçalho (cargo/ano/órgão) desta questão."],"idQuestao":"4cc922c2-bbe8-5291-a5d6-c671ef1f7a3e","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":null,"idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 21 | Obs.: O PDF não traz o cabeçalho (cargo/ano/órgão) desta questão."},{"secao":"Periodontia","numero":22,"orgao":"Polícia Militar do Mato Grosso","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"A erupção parcial ou incompleta dos terceiros molares está frequentemente relacionada com a ocorrência de pericoronarites. Sobre os sinais e sintomas mais frequentes da pericoronarite, considere: I- Presença de mau hálito II- Inchaço da gengiva no localacometido III- Dor no local IV- Aumento do tamanho ou do número de linfonodos cervicais São sinais e sintomas:","alternativas":[{"letra":"A","texto":"III e IV, apenas.","ordem":1,"idAlternativa":"ed80955e-4e41-5de7-a40e-3abcac9ff8a9"},{"letra":"B","texto":"I, II e III, apenas.","ordem":2,"idAlternativa":"a044e3f8-d1d2-525a-a775-0cb9df33d979"},{"letra":"C","texto":"I, II e IV, apenas.","ordem":3,"idAlternativa":"8ab6b9c2-dc00-563f-ad4e-abd57c0baf15"},{"letra":"D","texto":"I, II, III e IV.","ordem":4,"idAlternativa":"f72ecbe3-dca7-5ad6-8854-8893eec4e3e3"},{"letra":"E","texto":"II e III, apenas.","ordem":5,"idAlternativa":"016687a6-6cbf-5c65-abae-4f93d4dba52d"}],"gabarito":"A","observacoes":[],"idQuestao":"7116a71b-aad3-5da3-985a-a4cfba80c354","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"17c6fe71-a261-588c-8f9b-8369907997f1","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 22"},{"secao":"Periodontia","numero":23,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"As informações e mensurações das condições das várias estruturas periodontais obtidas a partir dos parâmetros clínicos e radiográficos devem formar a base para o diagnóstico da doença periodontal. Leia as afirmativas abaixo relativas à avaliação diagnóstica em periodontia I.“Pseudobolsas” podem estar presentes em dentes com perda de inserção e aumento significativo da profundidade de sondagem. II.O diagnóstico de gengivite geralmente caracteriza lesões que atingem o periodonto de inserção até, no máximo, o terço cervical das raízes. III.A periodontite é caracterizada como processo inflamatório de origem in- fecciosa modificado por fatores de ordem sistêmica e ambiental. IV.O tabagismo e a desnutrição aumentam o risco de desenvolvimento da Gengivite Ulcerativa Necrosante Estão CORRETAS apenas as afirmativas:","alternativas":[{"letra":"A","texto":"I e II.","ordem":1,"idAlternativa":"1166c1c8-d563-54c5-9fd2-7e7a086e325a"},{"letra":"B","texto":"I e III.","ordem":2,"idAlternativa":"cc2b62fa-d234-5252-ada5-ec8fd0f0c510"},{"letra":"C","texto":"I e IV.","ordem":3,"idAlternativa":"f1cede99-d23e-58ee-9fee-f2ce953b5978"},{"letra":"D","texto":"II e III.","ordem":4,"idAlternativa":"c0bb7854-c4d3-5d6e-95b9-3e88afa68e3f"},{"letra":"E","texto":"III e IV.","ordem":5,"idAlternativa":"ab1f22bc-f482-59e8-9452-fc7e62dc73ff"}],"gabarito":"E","observacoes":[],"idQuestao":"1de8143b-f3b4-51d7-a833-0c760fb54388","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 23"},{"secao":"Periodontia","numero":24,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"A fase I do tratamento periodontal ou terapia relacionada à causa é considerada uma abordagem voltada para remoção dos biofilmes patogênicos, toxinas e cálcu- los, visando o restabelecimento de uma superfície radicular biologicamente acei- tável (CARRANZA, 2016). Em relação aos objetivos e procedimentos da Fase I do tratamento periodontal, é CORRETO afirmar:","alternativas":[{"letra":"A","texto":"A profundidade de sondagem não mostra relação com a quantidade de cálculo residual após a raspagem","ordem":1,"idAlternativa":"86bd769a-1c6f-5bfb-b440-1a1c10b575d7"},{"letra":"B","texto":"Instrumentos ultrassônicos possibilitam os procedimentos de raspagem e alisamento radicular de forma eficiente","ordem":2,"idAlternativa":"61c91a31-8f9c-5ae6-a62f-3507930f3ded"},{"letra":"C","texto":"O período mínimo para reavaliação da resposta a fase I do tratamento deve ser de duas semanas","ordem":3,"idAlternativa":"66d5498f-0aa2-5337-8210-5128492490b6"},{"letra":"D","texto":"O procedimento de polimento coronário visa a remoção do biofilme minerali- zado","ordem":4,"idAlternativa":"54eae9c3-691c-5f54-8f88-6775d67155d1"},{"letra":"E","texto":"Os procedimentos de raspagem e alisamento radicular removem cálculo, bio- filme dental e cemento","ordem":5,"idAlternativa":"856c17ac-2346-5e34-b60b-acaa8ed0030e"}],"gabarito":"E","observacoes":[],"idQuestao":"c4d10ffb-88f7-5c12-9c97-3d234dcf6a50","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 24"},{"secao":"Periodontia","numero":25,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"Histologicamente, a osseointegração é definida como uma conexão estrutural di- reta e funcional entre o osso vivo e a superfície de um implante submetido à carga mecânica. (CARRANZA, 2016). Em relação aos aspectos físicos e biológicos dos implantes e suas indicações, é CORRETO afirmar:","alternativas":[{"letra":"A","texto":"A estabilidade primária é um conceito importante no sucesso do implante, pois refere-se à aplicação, pela primeira vez, de uma força mecânica sobre o im- plante","ordem":1,"idAlternativa":"780ce549-12df-5a0b-83ef-645c3c3f2cbd"},{"letra":"B","texto":"A osseointegracao, uma vez conseguida, é mantida de forma previsível du- rante toda a vida do indivíduo","ordem":2,"idAlternativa":"b5703a0d-73b2-591d-ae2c-2efb5276f9a9"},{"letra":"C","texto":"A osteotomia realizada durante a preparação para instalação do implante leva a reação inflamatória, reabsorção óssea e libera fatores de crescimento para o local fresado","ordem":3,"idAlternativa":"10aeb070-7618-5fae-83f2-1a3162ee1aa3"},{"letra":"D","texto":"O epitélio juncional e a inserção conjuntiva presentes nos tecidos periimplan- tares são biológica e funcionalmente iguais aos tecidos periodontais.","ordem":4,"idAlternativa":"cfa34279-d713-5d26-98b1-f959b5062303"},{"letra":"E","texto":"O fenômeno da osseointegracao decorre da deposição de uma matriz óssea sobre a superfície do implante, devido aos osteoblastos já presentes no sítio do preparo do leito","ordem":5,"idAlternativa":"0de71102-b5b7-5879-9514-1406d81821e6"}],"gabarito":"C","observacoes":[],"idQuestao":"411e2bc0-e23e-567b-a983-8bac115f7187","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 25"},{"secao":"Periodontia","numero":26,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2007,"enunciado":"Nos últimos 10 anos, diversos estudos têm investigado a temática associação entre doença periodontal materna e baixo peso do recém-nascido. Observe, abaixo, os resultados da 74 análise da condição periodontal em 302 mulheres e o desfecho gestacional. Qual o percentual de prevalência de periodontite entre as mães de filhos com baixo peso?","alternativas":[{"letra":"A","texto":"39,00%.","ordem":1,"idAlternativa":"341ff19c-6578-5786-82cb-6f5a71bbcf3d"},{"letra":"B","texto":"43,06%.","ordem":2,"idAlternativa":"5bd86f60-26b4-5ba4-9a2b-4335419f3af6"},{"letra":"C","texto":"57,84%.","ordem":3,"idAlternativa":"137b9766-e197-5a40-82c3-73c5d7b34b84"},{"letra":"D","texto":"61,00%.","ordem":4,"idAlternativa":"2d4715a6-832d-5d37-85c1-53da7a6de883"},{"letra":"E","texto":"76,47%.","ordem":5,"idAlternativa":"be4ae06a-f969-53b6-8692-8930de8cb0d6"}],"gabarito":"C","observacoes":["Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."],"idQuestao":"4eb59dc7-6ae5-5da6-8cf1-1410e4bcc6ad","idDisciplina":"2a91f68a-ca3e-5630-bf78-2868e44b7307","idConcurso":"04d40d7d-9cf1-54bf-bf15-91cbef2199af","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"rascunho","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Periodontia | Questão 26 | Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."},{"secao":"Endodontia","numero":1,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"Em relação ao diagnóstico em endodontia, assinale a alternativa incorreta.","alternativas":[{"letra":"A","texto":"O diagnóstico em endodontia é o conhecimento de um estado (saúde ou doença) por meio de dados subjetivos, objetivos e exames. Diante da queixa principal, deve- se realizar uma entrevista direcionada: localização, início, intensidade, estímulo, alívio da dor e duração.","ordem":1,"idAlternativa":"3084287e-bbe8-50b9-9767-c9bb9f814dde"},{"letra":"B","texto":"O exame intraoral consiste na avaliação dos tecidos moles, avaliação dentária, alterações de cor ou textura, exame periodontal, sondagem periodontal e transiluminação para mostrar fraturas dentárias.","ordem":2,"idAlternativa":"e45382c6-74aa-5645-84d2-6194a408ab8b"},{"letra":"C","texto":"O teste de sensibilidade pulpar pode diferenciar uma polpa vital de uma não vital. Em casos em que a dor é contínua, sem necessitar de estímulo, a pulpite pode ser considerada irreversível. Em casos em que a dor ocorre por estímulo, a pulpite pode ser reversível.","ordem":3,"idAlternativa":"fd230789-b26b-5be2-8427-18d775f6b476"},{"letra":"D","texto":"Quando a resposta ao teste térmico com o frio for negativa, pode-se afirmar falha na execução e não que esse dente está com uma necrose pulpar.","ordem":4,"idAlternativa":"e2691a43-712c-5a7e-86db-f900e1734b74"}],"gabarito":"D","observacoes":[],"idQuestao":"aa1dc24e-73ea-55e9-a291-00b9aeb090e2","idDisciplina":"f560b96d-5e36-5a80-bdd2-05fe7c20140b","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Endodontia | Questão 1"},{"secao":"Endodontia","numero":2,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"A respeito dos procedimentos endodônticos é CORRETO afirmar que:","alternativas":[{"letra":"A","texto":"Pulpotomia é a remoção apenas da polparadicular.","ordem":1,"idAlternativa":"10fa7d0a-0731-547f-912e-515e6ed5ca54"},{"letra":"B","texto":"Pulpectomia é a remoção total da polpadental.","ordem":2,"idAlternativa":"eca6bdd3-4cc7-5fa2-bcd9-210a2042d3be"},{"letra":"C","texto":"Pulpotomia é a remoção total da polpa dental.","ordem":3,"idAlternativa":"b8fa063f-c821-51e3-aad0-0a9dbf3e12b3"},{"letra":"D","texto":"Pulpectomia é a remoção parcial da polpadental.","ordem":4,"idAlternativa":"8f49e946-0d6a-59eb-91fe-937179a012b5"}],"gabarito":"B","observacoes":[],"idQuestao":"55973383-7a40-53bb-b4f3-156e3b2a0201","idDisciplina":"f560b96d-5e36-5a80-bdd2-05fe7c20140b","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Endodontia | Questão 2"},{"secao":"Endodontia","numero":3,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"A respeito do tratamento conservador da polpa dentária, assinale a alternativa INCORRETA.","alternativas":[{"letra":"A","texto":"Em quadro de exposição pulpar com agravante de tecido de granulação, uma opção conservadora é a pulpotomia.","ordem":1,"idAlternativa":"451f966c-24f3-5f1d-920d-600933d201ba"},{"letra":"B","texto":"O capeamento pulpar indireto é quando não houve contato direto com o tecido pulpar, no entanto, há necessidade de fazer uma proteção à estetecido.","ordem":2,"idAlternativa":"7f958010-4739-5295-90e5-fba372876ac6"},{"letra":"C","texto":"Em caso de pequena exposição de polpa necrótica, deve-se dar preferência para o capeamento pulpar direto.","ordem":3,"idAlternativa":"c86273bd-de56-5079-b53a-ac6b7f3ede43"},{"letra":"D","texto":"Quando a cavidade se aproxima muito do tecido pulpar, deve-se preconizar pela aplicação de materiais que induzam a formação de dentinareparadora.","ordem":4,"idAlternativa":"1719fb62-3c23-5b03-b311-0532ae86c774"}],"gabarito":"C","observacoes":[],"idQuestao":"5c57729c-241c-59b1-b1b9-f0ca1a024f0b","idDisciplina":"f560b96d-5e36-5a80-bdd2-05fe7c20140b","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Endodontia | Questão 3"},{"secao":"Endodontia","numero":4,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"Para a obtenção de um efetivo controle da infecção do sistema de canais radiculares são geralmente necessários os seguintes procedimentos, exceto:","alternativas":[{"letra":"A","texto":"Propiciar a formação de um meio ambiente extremamente ácido no canal radicular.","ordem":1,"idAlternativa":"f1ba1ca7-39be-5da5-90a1-b262da07caf6"},{"letra":"B","texto":"Preparo químico-mecânico completo.","ordem":2,"idAlternativa":"11807da5-c716-557f-a14a-726a1370c11c"},{"letra":"C","texto":"Aplicação de uma medicação intracanaladequada.","ordem":3,"idAlternativa":"90485495-f351-5966-aca7-cbe860ce97c1"},{"letra":"D","texto":"Realização de uma obturação que promova o selamento tridimensional do sistema de canais radiculares.","ordem":4,"idAlternativa":"307ed40d-30ca-561e-91b8-8265496da9dc"}],"gabarito":"A","observacoes":[],"idQuestao":"18e09561-8f3b-5c96-be34-c1ab1cece73b","idDisciplina":"f560b96d-5e36-5a80-bdd2-05fe7c20140b","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Endodontia | Questão 4"},{"secao":"Endodontia","numero":5,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Lopes e Siqueira (2020), embora nenhuma espécie bacteriana tenha sido incontestavelmente relacionada a algum sinal ou sintoma de lesão perirradicular,os perfis da comunidade bacteriana parecem seguir alguns padrões relacionados às diferentes apresentações clínicas da doença. Técnicas de microbiologia molecular têm sido aplicadas ao estudo das comunidades microbianas endodônticas. Com relação aos principais resultados encontrados nesse estudo, assinale a opção correta:","alternativas":[{"letra":"A","texto":"Os diferentes tipos de infecções endodônticas são compostos de comunidades bacterianas mistas. Isso também se aplica a infecções persistentes e secundárias associadas a casos de fracasso endodôntico.","ordem":1,"idAlternativa":"4df03848-7373-5e89-b4e4-d4639a319ae0"},{"letra":"B","texto":"Bactérias não cultiváveis são raramente encontradas em canais radiculares infectados, como parte da comunidade endodôntica.","ordem":2,"idAlternativa":"90608df2-b46d-5874-9754-198ea2b9e9ed"},{"letra":"C","texto":"A composição da microbiota endodôntica é igual entre vários indivíduos com a mesma doença.","ordem":3,"idAlternativa":"526a0d4d-7f92-5def-bf84-5d88528f03d0"},{"letra":"D","texto":"A microbiota encontrada na porção apical não se difere muito daquela encontrada na região mais coronária do canal radicular.","ordem":4,"idAlternativa":"76fc204d-474f-5bec-8da8-ed6d95a4f3b3"},{"letra":"E","texto":"A composição da comunidade bacteriana não apresenta relação com a gravidade da doença.","ordem":5,"idAlternativa":"4ab9f175-1cc5-5d3f-b0c6-039fc22fa1ef"}],"gabarito":"A","observacoes":[],"idQuestao":"93a35e00-3644-5476-984a-c807f25b73a1","idDisciplina":"f560b96d-5e36-5a80-bdd2-05fe7c20140b","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Endodontia | Questão 5"},{"secao":"Endodontia","numero":6,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Lopes & Siqueira (2015), sobre a microbiota endodôntica, é correto afirmar que:","alternativas":[{"letra":"A","texto":"a capacidade de virulência de determinada espécie é semelhante em cultura pura, em pares ou como parte de uma comunidade bacteriana.","ordem":1,"idAlternativa":"304b5ddd-0675-573c-826a-fee68054c643"},{"letra":"B","texto":"o comportamento da comunidade bacteriana e o resultado da interação da comunidade com o hospedeiro dependerão das espécies que compõem a comunidade e das associações que podem ocorrer entre elas.","ordem":2,"idAlternativa":"860a989b-03c3-5f15-b864-98dfa9a03cd4"},{"letra":"C","texto":"o mesmo quadro clinico em indivíduos diferentes estão relacionado a uma composição de microbiota endodôntica semelhante.","ordem":3,"idAlternativa":"55872f60-3494-552a-bbb8-bdd481b6a543"},{"letra":"D","texto":"a porção apical do canal radicular abriga uma microbiota semelhante à presente na regiăo mais coronária do canal.","ordem":4,"idAlternativa":"935a10b6-25a0-55ce-98e2-cb241e096649"},{"letra":"E","texto":"o biofilme intrarradicular apresenta espessura variável, mantendo uma proporção semelhante entre a matriz extracelular e as populações bacterianas.","ordem":5,"idAlternativa":"824e46b0-5bee-5b72-8659-0f8618105b96"}],"gabarito":"B","observacoes":[],"idQuestao":"cb036fac-a4d3-57e3-acd2-11cd92f5e968","idDisciplina":"f560b96d-5e36-5a80-bdd2-05fe7c20140b","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Endodontia | Questão 6"},{"secao":"Endodontia","numero":7,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Hargreaves & Berman (2017), a respeito das inter-relações endodônticas e periodontais, assinale a opção INCORRETA:","alternativas":[{"letra":"A","texto":"Nos casos de lesões combinadas verdadeiras, à medida que as lesões endodônticas e periodontais coalescem, elas podem ser clinicamente indistinguíveis.","ordem":1,"idAlternativa":"53e197f4-7ef4-5367-8b6b-32383dee0b7f"},{"letra":"B","texto":"Nos casos de lesões periodontais primárias, o prognóstico depende exclusivamente da evolução da terapia periodontal.","ordem":2,"idAlternativa":"68805262-64cf-51e7-a578-6d08488f3712"},{"letra":"C","texto":"É possível distinguir radiograficamente lesões periodontais primárias com envolvimento endodôntico secundário das lesões endodônticas primárias com envolvimento periodontal secundário.","ordem":3,"idAlternativa":"b7f407fc-9b6e-5fe9-95fd-a7e81d2293d3"},{"letra":"D","texto":"Nas lesões endodônticas primárias, a resolução completa é geralmente obtida apôs a terapia endodôntica não cirúrgica.","ordem":4,"idAlternativa":"75cde445-4331-5256-be37-fac906ae9873"},{"letra":"E","texto":"Nas lesões endodônticas primárias com envolvimento periodontal secundário, se o tratamento endodôntico for adequado, o prognóstico dependerá da gravidade do envolvimento periodontal e da eficácia da terapiaperiodontal.","ordem":5,"idAlternativa":"c8bb3dc1-94e2-5f7f-96ae-0981ef66aae0"}],"gabarito":"C","observacoes":[],"idQuestao":"51a10aa0-7108-53ba-af72-0316d7f4f849","idDisciplina":"f560b96d-5e36-5a80-bdd2-05fe7c20140b","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Endodontia | Questão 7"},{"secao":"Endodontia","numero":8,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Homem de 48 anos de idade queixa-se de dor no dente 27, ao morder. O paciente relata ter realizado um procedimento no dente há uma semana. Ao exame clínico, observa-se restauração no referido dente com contato prematuro. Os testes térmicos mostram respostas positivas (normais) e a dor é provocada quando se realiza a percussão vertical. O tratamento indicado para esse caso é:","alternativas":[{"letra":"A","texto":"Instrumentação dos canais radiculares e medicaçãointracanal.","ordem":1,"idAlternativa":"97d1f093-0a3f-5c32-a393-b5c3d1f4146d"},{"letra":"B","texto":"Terapia antibiótica e proservação.","ordem":2,"idAlternativa":"32d1d137-edf3-5416-8ed0-cbe9a1793620"},{"letra":"C","texto":"Ajuste da oclusão e acompanhamento.","ordem":3,"idAlternativa":"378b336a-620b-54cb-b9e1-30f3a99b6f74"},{"letra":"D","texto":"Apicectomia e proservação.","ordem":4,"idAlternativa":"24171cc6-a973-51b1-97cf-feab15affa27"},{"letra":"E","texto":"Pulpectomiae restauração definitiva.","ordem":5,"idAlternativa":"344b2add-b128-5269-9fed-670818e86cb5"}],"gabarito":"A","observacoes":[],"idQuestao":"ab10d091-9e95-55a3-86ec-00df5d4bc328","idDisciplina":"f560b96d-5e36-5a80-bdd2-05fe7c20140b","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Endodontia | Questão 8"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":1,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"Muitos procedimentos cirúrgicos se iniciam com uma incisão. O instrumento básico para fazer essas incisões é o bisturi, que é composto por um cabo reutilizável e por uma lâmina afiada estéril e descartável. Com base nesse trecho responda: qual a lâmina de bisturi mais empregada na cirurgia intraoral?","alternativas":[{"letra":"A","texto":"A lâmina n.º 10.","ordem":1,"idAlternativa":"d0eeb23c-5621-5662-baf1-42e7e83eabb1"},{"letra":"B","texto":"A lâmina n.º 15C.","ordem":2,"idAlternativa":"edf5ad45-1a6b-551e-9a76-45270f48f8a1"},{"letra":"C","texto":"A lâmina n.º 15.","ordem":3,"idAlternativa":"06752d00-77d9-5e8e-84b8-3dda864d7889"},{"letra":"D","texto":"A lâmina n.º 11.","ordem":4,"idAlternativa":"0960efba-d100-56b6-9f6c-4b736df28846"},{"letra":"E","texto":"A lâmina n.º 12.","ordem":5,"idAlternativa":"733386af-15e9-5f6a-985e-0a6b7947b82d"}],"gabarito":"C","observacoes":[],"idQuestao":"5ba1aa53-0c16-53c4-8955-681ce9943109","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 1"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":2,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"Qual fórceps é usado em exodontias de dentes molares permanentes inferiores que apresentam raízes fusionadas e cônicas?","alternativas":[{"letra":"A","texto":"Fórceps n.º 151.","ordem":1,"idAlternativa":"c727f877-d12c-5f49-bd29-77a4cc76d5de"},{"letra":"B","texto":"Fórceps n.º 151S.","ordem":2,"idAlternativa":"199d75c5-152a-516d-a0c6-25eb96423c16"},{"letra":"C","texto":"Fórceps n.º 17.","ordem":3,"idAlternativa":"3961c90d-1126-5c68-8de8-e349bf78a13c"},{"letra":"D","texto":"Fórceps n.° 18R.","ordem":4,"idAlternativa":"234ff4f4-ab97-5e56-b15d-5ecf818e95c9"},{"letra":"E","texto":"Fórceps n.° 18L.","ordem":5,"idAlternativa":"5f316482-9b38-5aad-b355-9fb1b77bf991"}],"gabarito":"A","observacoes":[],"idQuestao":"526b8f95-1c8a-5ed6-b8ce-fe2e3c67c73d","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 2"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":3,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"Os anestésicos locais, quando usados adequadamente, constituem um método seguro e eficiente de controlar a dor, durante a realização de cirurgia dentoalveolar. Considerando os fatores de prevenção da toxicidade dos anestésicos locais, analise as afirmativas a seguir e marque V para as verdadeiras e F para as falsas. ( ) A dose de anestésico local administrada deve ser a quantidade necessária para controlar a intensidade da dor. ( ) A dose de anestésico local administrada deve ser a quantidade necessária para controlar a duração da dor. ( ) O cirurgião-dentista deve considerar a massa corporal do paciente na administração do anestésico local. ( ) O cirurgião-dentista deve administrar a dose do anestésico local com injeção intravascular. ( ) O cirurgião-dentista pode desconsiderar a função hepática do paciente na administração do anestésico local. Assinale a alternativa que contém a sequência CORRETA, considerando as afirmativas de cima para baixo.","alternativas":[{"letra":"A","texto":"F, F, F, V, V.","ordem":1,"idAlternativa":"940e696c-7a6b-5d1b-8b0e-169c1c4d24c4"},{"letra":"B","texto":"V, V, V, F, F.","ordem":2,"idAlternativa":"8237606a-15fa-5160-9592-c1bd9afd7af9"},{"letra":"C","texto":"V, F, V, F, V.","ordem":3,"idAlternativa":"56cc6466-20f2-5471-967e-516cf34b0b6d"},{"letra":"D","texto":"V, V, V, V, V.","ordem":4,"idAlternativa":"e494feea-bfe5-5459-8bf7-9e62d740ff1c"},{"letra":"E","texto":"V, V, V, V, F.","ordem":5,"idAlternativa":"8424697e-933d-5f74-8d17-2d5ad427c347"}],"gabarito":"B","observacoes":[],"idQuestao":"da416acf-5d6f-5574-a62e-28aea8680175","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 3"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":4,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"A técnica anestésica é totalmente relacionada com a área a ser anestesiada. A respeito disso assinale a alternativa CORRETA.","alternativas":[{"letra":"A","texto":"A técnica anestésica ptegomandibular é responsável por anestesiar todos osdentes inferiores e a região de forame incisivo.","ordem":1,"idAlternativa":"3a501d1e-4788-526b-a9e5-3db994769a06"},{"letra":"B","texto":"A técnica anestésica infraorbtária é responsável por anestesiar todos os elementos superiores.","ordem":2,"idAlternativa":"81c2411c-0548-5a7b-b6d4-8192083e0ae1"},{"letra":"C","texto":"A anestesia alveolar superior posterior vai anestesiar o segundo molar superior, o terceiro molar superior e as raízes palatina e distovestibular do primeiro molar superior.","ordem":3,"idAlternativa":"301991e9-8f1b-5562-a69d-e79a9e33e550"},{"letra":"D","texto":"A técnica anestésica palatino maior, vai anestesiar apenas segundo e terceiro molar superior, o primeiro molar é anestesiado parcialmente.","ordem":4,"idAlternativa":"26a6b166-80a2-53bb-b0f6-b03c45c2e1e6"}],"gabarito":"C","observacoes":[],"idQuestao":"0955209b-dca9-50e7-bc66-c55b69d7b25d","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 4"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":5,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"O médico francês Rene Le Fort realizou no início do século XX um estudo utilizado até hoje em que ele sugeriu que os padrões das fraturas maxilares dependiam do pontoda aplicação e direção de uma força, velocidade, duração, posição da cabeça duranteo trauma e da massa do agente agressor. Foi então estabelecido que as fraturas faciais seguem leis e compartilham características comuns, que podem ser classificadas da forma correta em:","alternativas":[{"letra":"A","texto":"Fratura Le Fort I: É aquela em que ocorre fragmentação craniofacial que envolve as suturas frontozigomática, frontomaxilar e frontonasal.","ordem":1,"idAlternativa":"86c4a48e-cd32-5934-8b27-e7c5beb792b2"},{"letra":"B","texto":"Fratura Le Fort III: Cruza a porção inferior dos ossos nasais, o processo frontal da maxila até o osso lacrimal, o rebordo infraorbital na junção da maxila e do osso zigomático de forma oblíqua, dirigindo-se posteriormente até a fissura pterigomaxilar.","ordem":2,"idAlternativa":"4a60f859-297d-58a4-9dca-04b0ff547f40"},{"letra":"C","texto":"Fratura Le Fort II: Percorre os ossos nasais, a porção superior dos ossos lacrimais, a parede medial da órbita, as células etmoidais, e continua pela parede lateral da órbita, onde pode separar osso zigomático do frontal na sutura frontozigomática.","ordem":3,"idAlternativa":"ab07d621-691c-52fe-9976-c29e3d2ea962"},{"letra":"D","texto":"Fratura Le Fort I: Começa a partir da abertura piriforme estendendo-se para as laterais da maxila, podendo envolver os processos pterigoides.","ordem":4,"idAlternativa":"15cd6065-dddf-54df-b83e-4d995ef83c18"}],"gabarito":"D","observacoes":[],"idQuestao":"039a7dc5-246e-5ce0-81ee-60a238fec6c8","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 5"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":6,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"No bloqueio do nervo alveolar superior médio, quais são os nervos anestesiados?","alternativas":[{"letra":"A","texto":"Alveolar superior posterior e seus ramosterminais.","ordem":1,"idAlternativa":"4d8d4820-736b-5366-88cc-ddd2b27ea767"},{"letra":"B","texto":"Alveolar superior anterior e alveolar superiormédio.","ordem":2,"idAlternativa":"5209f166-acb1-56ac-80fe-15d7370fb0a4"},{"letra":"C","texto":"Palatino maior.","ordem":3,"idAlternativa":"bafe94c9-4678-506d-a1ac-f9449f26207c"},{"letra":"D","texto":"Palatino menor.","ordem":4,"idAlternativa":"c6d1749b-24b7-5b8e-8c23-422686e990f4"},{"letra":"E","texto":"Alveolar superior médio e seus ramos terminais.","ordem":5,"idAlternativa":"44d782e5-8b7a-57f1-ab98-b9aed6ae806c"}],"gabarito":"E","observacoes":["Obs.: Órgão no PDF aparece colado ao enunciado (“Prefeitura de Americana”); mantido como Americana-SP, mesma sequência da prova."],"idQuestao":"eea0751d-0851-5d17-b47f-4da6258b0bbb","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 6 | Obs.: Órgão no PDF aparece colado ao enunciado (“Prefeitura de Americana”); mantido como Americana-SP, mesma sequência da prova."},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":7,"orgao":"Prefeitura de Americana-SP","cargo":"DENTISTA","ano":2023,"enunciado":"Qual a técnica anestésica usada na anestesia pulpar dos dentes superiores, no lado do bloqueio, o periodonto vestibular e osso sobrejacente a estes dentes, os tecidos moles e osso do palato duro e parte do palato mole, medialmente à linha média e a pele da pálpebra inferior, lateral do nariz, bochecha e lábio superior?","alternativas":[{"letra":"A","texto":"Bloqueio do Nervo alveolar superior.","ordem":1,"idAlternativa":"40ba2bdc-40f4-5249-9248-09698006a4b1"},{"letra":"B","texto":"Bloqueio do Nervo alveolar médio.","ordem":2,"idAlternativa":"e7c65659-56eb-5494-a49f-c8add5486f29"},{"letra":"C","texto":"Bloqueio do Nervo alveolar inferior.","ordem":3,"idAlternativa":"2022dc8e-1282-505e-856f-e7c432a940cd"},{"letra":"D","texto":"Bloqueio do Nervo tuberosidade alta.","ordem":4,"idAlternativa":"f8f04071-63e6-5fd0-a46c-bea82d3a658d"},{"letra":"E","texto":"Bloqueio do Nervo nasopalatino.","ordem":5,"idAlternativa":"80200b62-e2f7-543d-85e3-fb27c586e2c9"}],"gabarito":"D","observacoes":["Obs.: Órgão no PDF aparece colado ao enunciado (“Prefeitura de Americana”); mantido como Americana-SP, mesma sequência da prova."],"idQuestao":"a92c3f76-28cd-5769-a1b2-03b5080fc5a6","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"b4055beb-5db2-5669-b00b-10fad0253e13","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 7 | Obs.: Órgão no PDF aparece colado ao enunciado (“Prefeitura de Americana”); mantido como Americana-SP, mesma sequência da prova."},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":8,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"Assinale a alternatica que indica corretamente um antibiótico que faz parte da família das lincosaminas.","alternativas":[{"letra":"A","texto":"Amoxicilina","ordem":1,"idAlternativa":"10fcf311-c931-5d65-b340-a493ac46104b"},{"letra":"B","texto":"Azitromicina","ordem":2,"idAlternativa":"433228ff-dc83-5bc0-8ad8-09511f4cad85"},{"letra":"C","texto":"Ciprofloxacina","ordem":3,"idAlternativa":"82f77016-ebf7-53ca-ae5d-c638c05e6c07"},{"letra":"D","texto":"Clindamicina","ordem":4,"idAlternativa":"3d03993c-e764-578d-a436-c331f6c84645"},{"letra":"E","texto":"Eritromicina","ordem":5,"idAlternativa":"6435b874-b5ac-57f5-abc3-f90c591587bf"}],"gabarito":"D","observacoes":[],"idQuestao":"2c6a64f2-126b-5a32-9d7a-e639979f3d83","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 8"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":9,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"Relacione as colunas abaixo sobre traumatismos dentários. Coluna 1 – Traumatismos 1. Avulsão 2. Concussão 3. Subluxação 4. Luxação intrusiva Coluna 2 - Definições ( ) Não apresenta deslocamento tampouco mobilidade. A dor à percussão é a única característica presente. ( ) Trata-se do deslocamento total do dente de seu alvéolo. ( ) Trata-se de um deslocamento do elemento dentário na direção apical. ( ) Apresenta sensibilidade à percussão, pode apresentar leve mobilidade e sinais clínicos de sangramento ao nível do sulco gengival. Assinale a alternativa que indica a sequência correta, de cima para baixo.","alternativas":[{"letra":"A","texto":"2 • 1 • 4 • 3","ordem":1,"idAlternativa":"5ef7fc50-fa64-5d12-a747-724d46161979"},{"letra":"B","texto":"2 • 1 • 3 • 4","ordem":2,"idAlternativa":"1bf43a31-7e33-5151-8d3e-fed1a65de38f"},{"letra":"C","texto":"3 • 1 • 4 • 2","ordem":3,"idAlternativa":"1e31aa27-a849-5954-905f-c563744f88c4"},{"letra":"D","texto":"3 • 4 • 1 • 2","ordem":4,"idAlternativa":"39d946c0-8d3e-5d20-b129-3bea8e9751e8"},{"letra":"E","texto":"• 1 • 3 • 2","ordem":5,"idAlternativa":"2727ef31-c9fd-59f4-84ec-a0271ecc0779"}],"gabarito":"A","observacoes":[],"idQuestao":"d26a4973-c384-51b6-a9e0-13af901b9073","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 9"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":10,"orgao":"Prefeitura de Chapecó-SC","cargo":"DENTISTA","ano":2023,"enunciado":"Identifique abaixo as afirmativas verdadeiras ( V ) e as falsas ( F ) sobre os procedimentos cirúrgicos odontológicos. ( ) Quando o retalho cirúrgico é desenhado, a sua base deve ser normalmente mais larga que a sua margem livre para preservar um provimento sanguíneo adequado. ( ) Uma incisão longa e reta com adequado rebatimento do retalho cicatriza mais rapidamente do que uma incisão curta e com dilaceração de tecidos. ( ) Ao fazer incisões na região posterior da mandíbula, principalmente na região do terceiro molar, as incisões devem ser bem próximas da região lingual da mandíbula. ( ) Após exodontia, o alvéolo requer cuidado apropriado. A pressão digital deve ser aplicada às corticais mesial e distal para comprimir as lâminas gentilmente, mas firmemente, na sua posição original. Assinale a alternativa que indica a sequência correta, de cima para baixo.","alternativas":[{"letra":"A","texto":"V • V • V • F","ordem":1,"idAlternativa":"157b1750-134f-52dd-bc3a-70b61f5f73ec"},{"letra":"B","texto":"V • V • F • V","ordem":2,"idAlternativa":"f0a16eae-d681-53c3-878e-03da7cb5476f"},{"letra":"C","texto":"V • V • F • F","ordem":3,"idAlternativa":"0307f8f4-841d-5971-847a-909a99f12d40"},{"letra":"D","texto":"F • V • V • F","ordem":4,"idAlternativa":"b2b54f54-d767-51ae-b8dc-618438fcc804"},{"letra":"E","texto":"F • F • V • V","ordem":5,"idAlternativa":"ad4f8f16-b5eb-51e6-b2d5-ec469a992a35"}],"gabarito":"C","observacoes":[],"idQuestao":"8a7a4795-7fbe-5865-8fa0-871814d0f907","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"cba951c7-4440-5dab-8773-2328a48d18d2","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 10"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":11,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Lopes e Siqueira (2020), na atualidade, o desenvolvimento de anestésicos e técnicas eficazes possibilita a execução de todo e qualquer tipo de tratamento odontológico de forma indolor. Levando em consideração a anestesia em endodontia, é correto afirmar que:","alternativas":[{"letra":"A","texto":"a técnica anestésica deve prover profundidade adequada de anestesia, o tempo de latência deve ser lento e a duração deve ser suficiente para a execução dos procedimentos.","ordem":1,"idAlternativa":"e22a65eb-b80d-5e94-9036-c519fce1710f"},{"letra":"B","texto":"os anestésicos que apresentam grande afinidade aos componentes proteicos da fibra nervosa têm maior probabilidade de se difundir para além do local da injeção e de serem absorvidos pela corrente sanguínea.","ordem":2,"idAlternativa":"cf99a7be-ec89-5e4e-83a8-0367ba6e1bcf"},{"letra":"C","texto":"a articaína deve ser empregada apenas em bloqueios regionais na maxila ou mandíbula.","ordem":3,"idAlternativa":"0fb30260-4c4a-5d12-8c49-23164dfa3243"},{"letra":"D","texto":"o nervo milo-hioideo pode fornecer inervação acessória para os molares inferiores, o que pode explicar parcialmente casos de fracasso no bloqueio do alveolarinferior.","ordem":4,"idAlternativa":"4a7f5619-957e-52ac-9dc6-253791db85b4"},{"letra":"E","texto":"depositar passivamente o anestésico na câmara pulpar é um procedimento geralmente eficaz para atingir a anestesia pulpar.","ordem":5,"idAlternativa":"631d886b-2ea5-54fb-8ff3-ad507dda8ed3"}],"gabarito":"D","observacoes":[],"idQuestao":"b08ed82e-8e92-5b5a-bfe3-8db146d458f7","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 11"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":12,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Andrade (2014), com relação às interações farmacológicas adversas, é correto afirmar que:","alternativas":[{"letra":"A","texto":"a dipirona é indicada para pacientes portadores de doenças metabólicas, como a porfiria hepática ou deficiência congênita da glicose G-fosfatodesidrogenase.","ordem":1,"idAlternativa":"f25be95c-83c2-57e3-b7f8-181aeb8d66ac"},{"letra":"B","texto":"o paracetamol é indicado para pacientes que fazem uso contínuo de varfarina sódica.","ordem":2,"idAlternativa":"334e3620-8ecd-56c1-96c7-dc128d7fa43f"},{"letra":"C","texto":"o ibuprofeno deve ser evitado em pacientes com história de hipersensibilidade ao ácido acetilsalicílico pelo risco potencial de alergia cruzada.","ordem":3,"idAlternativa":"182befb5-12d7-500e-b75c-b0abd50e183d"},{"letra":"D","texto":"quando empregados em dose única pré-operatória ou por tempo restrito, os corticoides aumentam a síntese de leucotrienos C4, D4 e E4.","ordem":4,"idAlternativa":"addfca38-5950-5057-9889-b0acedee2568"},{"letra":"E","texto":"o diclofenaco não bloqueia sensibilização dos nociceptores diretamente a sensibilização dos nociceptores.","ordem":5,"idAlternativa":"05acc288-17bf-518b-bce6-3b49c4cb6253"}],"gabarito":"C","observacoes":[],"idQuestao":"f4350469-fac9-5dd7-b6d6-101672aae8e1","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 12"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":13,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Andrade (2014), são corticoides de duração de açãointermediária:","alternativas":[{"letra":"A","texto":"hidrocortisona e dexametasona.","ordem":1,"idAlternativa":"85fca3d3-2fe1-5a1a-81ef-cd43faae4868"},{"letra":"B","texto":"prednisona e betametasona.","ordem":2,"idAlternativa":"802ffa69-660c-558d-845e-66197032e1c7"},{"letra":"C","texto":"triamcinolona e dexametasona.","ordem":3,"idAlternativa":"e85a1c7f-4401-5a99-8c42-d06ce4c30c64"},{"letra":"D","texto":"triamcinolona e prednisolona.","ordem":4,"idAlternativa":"468372a0-61f9-5e55-8147-7d5034edfe4c"},{"letra":"E","texto":"hidrocortisona e triamcinolona.","ordem":5,"idAlternativa":"5b69a362-6188-5df9-b306-9129fb64bf9a"}],"gabarito":"D","observacoes":[],"idQuestao":"f39b57ba-9ca4-544a-b999-bd2f1afc64c4","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 13"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":14,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Dean, McDonald e Avery (2011), a estabilização protetora é útil para o controle de pacientes combativos e resistentes. Essa técnica é indicada na seguinte situação:","alternativas":[{"letra":"A","texto":"pacientes cooperativos não sedados.","ordem":1,"idAlternativa":"d1f3eedd-950e-5f91-8a2e-9a97c045682a"},{"letra":"B","texto":"pacientes que não podem ser estabilizados com:segurança, devido a condições médicas ou físicas.","ordem":2,"idAlternativa":"1d288f02-864d-53f1-a504-45f2862ccd0c"},{"letra":"C","texto":"experiência prévia de trauma físico ou psicológico com a estabilização protetora (a menos que outras alternativas não estejam disponíveis).","ordem":3,"idAlternativa":"44c39138-1901-5cd5-96e5-a50aed4e63e0"},{"letra":"D","texto":"um paciente que necessite de diagnóstico ou tratamento e não coopera, após falhas em outras técnicas de controle de comportamento.","ordem":4,"idAlternativa":"63752fca-a636-5555-964a-3747d0d832c8"},{"letra":"E","texto":"pacientes não sedados sem necessidade de tratamento de emergência, exigindo tratamentos longos.","ordem":5,"idAlternativa":"2db0ddfc-9208-58d3-870d-ceca38ae9b14"}],"gabarito":"D","observacoes":[],"idQuestao":"b074f142-e2af-5915-8192-c725e103fb5c","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 14"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":15,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Andrade (2014), são antibióticos que atuam na síntese das proteínas:","alternativas":[{"letra":"A","texto":"tetraciclina e clindamicina.","ordem":1,"idAlternativa":"563ed8ec-2554-5b6b-806c-d5545dbbbf03"},{"letra":"B","texto":"metronidazol e eritromicina.","ordem":2,"idAlternativa":"674d675d-8d49-5bcf-a5c1-db5e01f8c9ef"},{"letra":"C","texto":"penicilinas e cefalosporinas.","ordem":3,"idAlternativa":"6bdea611-f2b4-5415-a725-5a2b3b61e663"},{"letra":"D","texto":"azitromicina e cefalosporinas.","ordem":4,"idAlternativa":"9ed58087-3946-5346-8a3c-9a6705ec4169"},{"letra":"E","texto":"clindamicina e metronidazol,","ordem":5,"idAlternativa":"f13ab2ea-c3c2-5b6c-b4d5-0e2a43c7caf4"}],"gabarito":"A","observacoes":[],"idQuestao":"1be420f5-1a92-573e-877f-9dd45ce12a14","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 15"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":16,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"De acordo com Malamed (2013), os anestésicos locais têm ação direta no miocárdio e na musculatura periférica. Entretanto, em geral, o Sistema Cardiovascular parece ser mais resistente aos efeitos de substâncias anestésicas locais do que o Sistema Nervoso Central (SNC). Săo considerados efeitos cardiovasculares e no SNC de nfveis sanguíneos elevados de anestésicos locais, em casos desuperdosagem minima e moderada, EXCETO:","alternativas":[{"letra":"A","texto":"catalepsia.","ordem":1,"idAlternativa":"ce908501-220b-5e28-84e7-0c23c27830ec"},{"letra":"B","texto":"disartria.","ordem":2,"idAlternativa":"fedd126e-704a-5cf8-b3ab-ed60252758ef"},{"letra":"C","texto":"nistagmo.","ordem":3,"idAlternativa":"1c4a3f0d-47e4-549a-b692-6d7b5ef0ab85"},{"letra":"D","texto":"logorreia.","ordem":4,"idAlternativa":"ad6d48c1-75da-5a79-a42e-5cf56e596194"},{"letra":"E","texto":"sudorese.","ordem":5,"idAlternativa":"e1f09518-e366-5cc4-a55f-609b2989f4d6"}],"gabarito":"A","observacoes":[],"idQuestao":"e5bc0de9-d624-5238-b3c2-4d8031472737","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 16"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":17,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"As interações farmacológicas săo modificações na intensidade e na duração da resposta de um fármaco, devido à ingestão simultánea de outro făirmaco, álcool etílico ou determinados alimentos. De acordo com Andrade (2014), com relação âs interaçöes farmacológicas adversas,GoIoque V (verdadeiro) ou F (falso) nas afirmativas abaixo e, em seguida, assinale a opçăo que apresenta a sequência correta. ( ) O cirurgião-dentista deve evitar a prescriçăo de anti- inflamatórios năo esteroides ou paracetamol para pacientes sob tratamento com Varfarina ouClopidogrel. ( ) O uso de corticosteroides em dose única pode ser uma boa alternativa ao uso dos antiinflamatórios não esteroides, em pacientes que fazem uso de hipoglicemiantes orais. ( ) Os princfpios ativos dos medicamentos fitoterápicos não apresentam possibilidade de interaçăo farmacológica. ( ) Pacientes em uso de hipoglicemiantes orais, quando utilizam anti-inflamatórios năo esteroides, podem apresentar episódios de hiperglicemia.","alternativas":[{"letra":"A","texto":"(V) (V). (F) (F)","ordem":1,"idAlternativa":"3cd904df-e70c-51f9-a6d0-7bc822b697c4"},{"letra":"B","texto":"(V) (V) (V) ‹(F)","ordem":2,"idAlternativa":"316a8278-5db1-52ab-9adc-012cfec35c20"},{"letra":"C","texto":"(F) (V) (F) , (V)","ordem":3,"idAlternativa":"ebad250e-fb3d-5bc7-86b3-5a7a1bad87de"},{"letra":"D","texto":"(F) (F) (V) (V)","ordem":4,"idAlternativa":"85195c4e-80f3-59c4-9e86-b47e2855c1d1"},{"letra":"E","texto":"(V) (F) (F) ,(V)","ordem":5,"idAlternativa":"44d6cf24-5a6d-5337-82a3-7d06ba4e7279"}],"gabarito":"A","observacoes":[],"idQuestao":"853c25f9-12fc-5ba2-8729-d32cfdec3e3e","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 17"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":18,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Andrade & Ranali (2011), os métodos de controle da ansiedade podem ser farmacológicos ou não farmacológicos. Dentre os farmacológicos, destaca -se a sedação mínima por via inalatória. Assim, assinale a opção que NÃO apresenta uma vantagem dessa técnica em relação a que emprega a via oral.","alternativas":[{"letra":"A","texto":"Além de sedar o paciente, a técnica promove analgesia relativa.","ordem":1,"idAlternativa":"0ae5d313-770b-5521-b51b-65f578d30833"},{"letra":"B","texto":"Os gases devem ser administrados em dose única para que se atinja o nível adequado de sedação.","ordem":2,"idAlternativa":"d5bf214b-6b8a-5e91-a839-33218d6b59a5"},{"letra":"C","texto":"O óxido nitroso não apresenta efeitos adversos sobre o fígado, pulmões, rins ou sobre o sistema cardiovascular erespiratório.","ordem":3,"idAlternativa":"077d80d5-e569-5924-83bf-8d14b1b9e5c9"},{"letra":"D","texto":"A duração e intensidade da sedação mínima podem ser controladas pelo profissional em qualquer momento do atendimento.","ordem":4,"idAlternativa":"859fc40b-c39d-5421-8999-df9ecfdf749f"},{"letra":"E","texto":"Os tempos são curtos para se atingirem os níveis adequados de sedação e para recuperação do paciente.","ordem":5,"idAlternativa":"b85f769b-ec41-5be7-8b8c-1716e4c1c5c8"}],"gabarito":"B","observacoes":[],"idQuestao":"ddc29696-c4cb-5194-b7a0-cfd95dd1e97a","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 18"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":19,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Sobrape (2019), é um fio de sutura de monofilamento, não absorvível, resistente, macio e com menor acúmulo de biofilme. Entretanto é um fio escorregadio, exige nó adicional, sem flexibilidade e de manuseio mais difícil. Tem seu uso limitado em cirurgias a retalho, ressectivas, mucogengivais e regenerativas. Assinale a opção que melhor representa o fio de sutura.","alternativas":[{"letra":"A","texto":"Poligalactina.","ordem":1,"idAlternativa":"84b71f63-b04b-51e7-92f5-51dd7dd6cff5"},{"letra":"B","texto":"Polipropileno.","ordem":2,"idAlternativa":"d3a10969-bf85-5305-934d-3ed648fe9bc1"},{"letra":"C","texto":"Ácido poliglicólico.","ordem":3,"idAlternativa":"81f45da0-8bce-5e03-8003-04ba035751e1"},{"letra":"D","texto":"Politetrafluoretileno expandido","ordem":4,"idAlternativa":"f003bcc0-509e-5b0e-8b9b-a126756465cf"}],"gabarito":"B","observacoes":[],"idQuestao":"9e8aad6e-1a24-59fa-a8cb-2feedc97813d","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 19"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":20,"orgao":"Aeronáutica do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Os antibióticos são medicamentos que eliminam ou bloqueiam a multiplicação bacteriana em concentrações que são relativamente inócuas aos tecidos do hospedeiro e podem ser usados para tratar infeções causadas por bactérias (Lindhe etal., 2018). Em relação à terapia com antibióticos na periodontia, é correto afirmar que o/as","alternativas":[{"letra":"A","texto":"uso de antibióticos mais documentados na terapia periodontal é com a amoxicilina e azitromicina orais juntos.","ordem":1,"idAlternativa":"6653b25e-ca57-5e50-b481-0e2b7e396046"},{"letra":"B","texto":"cloridrato de tetraciclina é bactericida de amplo espectro e alta toxicidade; além do efeito antimicrobiano, são capazes de inibir a colagenase.","ordem":2,"idAlternativa":"718844da-9c04-52d4-9cb8-63dc5375e83a"},{"letra":"C","texto":"penicilinas apresentam como efeitos adversos mais frequentes: intolerância gastrointestinal, candidíase, mancha e hipoplasia dentária na infância, náuseas e diarreia.","ordem":3,"idAlternativa":"46f7eb3f-1132-5ab9-a533-33ab20a41f23"},{"letra":"D","texto":"metronidazol inibe a síntese de DNA, resultando na morte celular; o processo envolve vias redutivas características das bactérias estritamente anaeróbicas como a P.gengivalis mas não sobre o A.actinomycetemcomitans.","ordem":4,"idAlternativa":"437ad9cf-f198-57bf-b4cf-83a7b61ccab2"}],"gabarito":"D","observacoes":[],"idQuestao":"c70f4df8-c756-5c81-a52b-2613e5b1fcc1","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"4f5e229a-42da-524f-b0c2-b706cd3227c9","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 20"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":21,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Paciente, 50 anos de idade, irá realizar uma cirurgia para instalação de implantes. Durante a anamnese, o cirurgião-dentista suspeitou de uma alteração sistêmica e solicitou um hemograma do paciente. No resultado havia a informação de que o paciente tinha uma anisocitose. Tal fato evidencia:","alternativas":[{"letra":"A","texto":"Variação na forma das hemácias.","ordem":1,"idAlternativa":"8e84f943-a233-53bf-b762-b3f7deac3856"},{"letra":"B","texto":"Presença de eritrócitosimaturos.","ordem":2,"idAlternativa":"7c65a461-f032-5d55-b7f0-ab421ed2d91c"},{"letra":"C","texto":"Variação no tamanho das hemácias.","ordem":3,"idAlternativa":"a67535c8-c1bb-506f-9a17-e6f2006ae7be"},{"letra":"D","texto":"Diminuição no número de plaquetas.","ordem":4,"idAlternativa":"5bbeccca-f3df-5e72-be24-7c05cb06d1dd"},{"letra":"E","texto":"Perda da morfologia típica dos leucócitos.","ordem":5,"idAlternativa":"4f4f9582-4569-5474-a1aa-a59164831562"}],"gabarito":"A","observacoes":[],"idQuestao":"24ba61c6-bae4-5eb8-bdf1-58d4b62fb1c9","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 21"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":22,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Durante a consulta inicial odontológica cabe ao cirurgião-dentista a realização da anamnese, o exame físico e o uso de demais manobras semiológicas. Uma delas é a aferição da pressão arterial, por meio da qual, são determinados os valores de pressão sistólica e diastólica. “A pressão sistólica é a pressão necessária para que o sangue , impulsionado pelo ventrículo , alcance as células do corpo com o oxigênio.” Assinale a alternativa que completa correta e sequencialmente a afirmativa anterior.","alternativas":[{"letra":"A","texto":"mínima / arterial / direito","ordem":1,"idAlternativa":"a00eddc8-b393-5318-bbf7-f86e1ce9cf30"},{"letra":"B","texto":"máxima / arterial / direito","ordem":2,"idAlternativa":"115e99b6-2214-59ac-9ff3-be1f1680090e"},{"letra":"C","texto":"mínima / venoso / esquerdo","ordem":3,"idAlternativa":"4eca57cd-3c10-5d0c-a32f-e8e1d797b272"},{"letra":"D","texto":"máxima / venoso / esquerdo","ordem":4,"idAlternativa":"1827faf9-4a42-5262-bfcd-4e91fc11f1d8"},{"letra":"E","texto":"máxima / arterial / esquerdo","ordem":5,"idAlternativa":"203dcbe4-bc73-5b74-a1a8-879e28c695b3"}],"gabarito":"D","observacoes":[],"idQuestao":"b2f7ae60-b872-5b54-99aa-def5225d2f1e","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 22"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":23,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"Durante a realização de um procedimento odontológico, o cirurgião-dentista optou por realizar a anestesia empregando a técnica de Gow-Gates. Diante do exposto, assinale a afirmativa INCORRETA.","alternativas":[{"letra":"A","texto":"A taxa de aspiração positiva em tal técnica é muitobaixa.","ordem":1,"idAlternativa":"06b501eb-16e6-5b99-ab61-4280b366e645"},{"letra":"B","texto":"A incisura intertrágica é um ponto de referência para a técnica.","ordem":2,"idAlternativa":"7cc8ee1c-0cd4-5295-b05b-a58d0300bce5"},{"letra":"C","texto":"Para a execução correta dessa técnica, a agulha deverá tocar o colo do côndilo mandibular.","ordem":3,"idAlternativa":"e36a82a6-22bf-508a-8ea9-45466e96e8b9"},{"letra":"D","texto":"O formigamento ou a dormência da língua está sempre presente quando tal técnica é executada com sucesso.","ordem":4,"idAlternativa":"8c519e44-2e8c-5dec-820e-a7a6b4b2958b"},{"letra":"E","texto":"O local da penetração da agulha é a distal ao segundo molar superior na altura da ponta da cúspide mesiovestibular.","ordem":5,"idAlternativa":"9f4c4ff4-7d92-5839-9b2b-1aad61020eb2"}],"gabarito":"B","observacoes":[],"idQuestao":"40809318-8160-5a5a-ab43-5aea45806fb3","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 23"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":24,"orgao":"QOSPM (Polícia Militar)","cargo":"DENTISTA MILITAR","ano":2022,"enunciado":"O bloqueio do nervo alveolar superior anterior é uma técnica bastante utilizada em odontologia e altamente segura. É indicada para procedimentos que envolvem dois ou mais dentes anteriores superiores. Diante do exposto, assinale a afirmativa INCORRETA.","alternativas":[{"letra":"A","texto":"A profundidade média da penetração da agulha é de 16 mm para um adulto de estatura média.","ordem":1,"idAlternativa":"2c938e14-3f73-5238-8860-fb635016117c"},{"letra":"B","texto":"Os pontos de referências para tal técnica são: sulco mucovestibular, forame infraorbital e rebordo infraorbital.","ordem":2,"idAlternativa":"e7964882-d5f3-5231-ae31-87d50424a503"},{"letra":"C","texto":"A agulha deve ser inserida na altura do sulco mucovestibular sobre o primeiro prémolar, com o bisel voltado para o osso.","ordem":3,"idAlternativa":"8019335d-692e-5426-ac5b-85b589afa765"},{"letra":"D","texto":"Formigamento e dormência na pálpebra inferior, na lateral do nariz e no lábio superior indicam a anestesia do nervo alveolar superior anterior.","ordem":4,"idAlternativa":"679080f9-d405-5b0e-9be2-81cfbc4cebd8"},{"letra":"E","texto":"Proporciona intensa anestesia pulpar e do tecido mole vestibular do incisivo central superior até os caninos e, na maior parte das vezes, se estende também aos prémolares.","ordem":5,"idAlternativa":"9ad66bbc-7429-5c28-90bd-f2be13ea6e96"}],"gabarito":"B","observacoes":["Obs.: O PDF traz, após a alternativa E, um trecho solto de outra questão (alternativas sobre bradicardia/pressão arterial) que foi descartado."],"idQuestao":"4b2b0b65-b9b9-5982-bd1c-4a7a8dc727fb","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"9017dd1d-547e-5833-8225-dab0e09061c7","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 24 | Obs.: O PDF traz, após a alternativa E, um trecho solto de outra questão (alternativas sobre bradicardia/pressão arterial) que foi descartado."},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":25,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"“A detoxificação dos anestésicos locais é importante, pois a toxicidade geral da substância depende do equilíbrio entre a velocidade de absorção pela corrente sanguínea no local de injeção e a velocidade em que ela é removida do sangue por meio dos processos de absorção tecidual e de metabolismo.” De acordo com esta afirmativa, qual alteração abaixo interfere na biotransformação dos anestésicos do tipo amida?","alternativas":[{"letra":"A","texto":"Cirrose hepática.","ordem":1,"idAlternativa":"4ec17519-7ca1-505f-a8a6-9d158b357b36"},{"letra":"B","texto":"Diabetes Mellitus.","ordem":2,"idAlternativa":"77320350-5d04-5743-9540-56eeae4a9f63"},{"letra":"C","texto":"Doença Pulmonar Obstrutiva Crônica – DPOC.","ordem":3,"idAlternativa":"acaed649-8290-5fb8-9067-aea4fe4cfc6c"},{"letra":"D","texto":"Hipertensão arterial sistêmica.","ordem":4,"idAlternativa":"b3897086-0492-5bce-be54-ac4c1f495f6f"},{"letra":"E","texto":"Insuficiência renal crônica.","ordem":5,"idAlternativa":"c449d53e-694d-5ed6-ae7c-900b96a63db6"}],"gabarito":"A","observacoes":[],"idQuestao":"2f7b46e4-6292-5e71-b3b5-c00f6c639523","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 25"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":26,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"A prevenção e o controle da dor em odontologia é uma das maiores preocupações do cirurgião dentista no dia a dia dos atendimentos odontológicos. Para o efetivo controle da dor no pós-operatório, Anti-inflamatórios Não Esteroidais (AINES) são extremamente uteis. A alternativa que MELHOR representa o mecanismo de atuação dos AINES é:","alternativas":[{"letra":"A","texto":"Inibição central do centro da dor.","ordem":1,"idAlternativa":"d1154df7-1bb9-5b6f-9993-bed3f279acc4"},{"letra":"B","texto":"Inibição da síntese das cicloxigenases.","ordem":2,"idAlternativa":"3ad10a5f-9f34-59d4-8d4f-488df5c3da4b"},{"letra":"C","texto":"Inibição da síntese das lipoxigenase.","ordem":3,"idAlternativa":"d7c9a1e3-e902-5b47-859e-9aa3fd8af855"},{"letra":"D","texto":"Inibição indireta da síntese de lipocortinas.","ordem":4,"idAlternativa":"176854c0-32e2-5196-b624-8bf343e67934"},{"letra":"E","texto":"Inibição periférica da transdução dos impulsos nervos.","ordem":5,"idAlternativa":"85192e6b-796b-5abe-8081-1df5c58da059"}],"gabarito":"B","observacoes":[],"idQuestao":"da4f12d8-dd8f-51d1-bac1-1916c6f38787","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 26"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":27,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"As emergências médicas em odontologia são eventos raros, no entanto, em cirur- gias ambulatoriais, a ocorrência é mais frequente em função do maior número de medicamentos usados e pelo estresse gerado pelo procedimento. Sendo assim, a alternativa que NÃO apresenta sinais e/ou sintomas da Síncope Vasovagal é:","alternativas":[{"letra":"A","texto":"Deglutição frequente.","ordem":1,"idAlternativa":"c7083039-2da6-5cc4-b7e4-4ea7700f9422"},{"letra":"B","texto":"Espasmo muscular.","ordem":2,"idAlternativa":"2c70f7de-74d8-5095-946c-5c86c8a47cde"},{"letra":"C","texto":"Náusea e engasgo.","ordem":3,"idAlternativa":"ef434aca-4c51-52bf-9088-bf3aba655cbb"},{"letra":"D","texto":"Sensação de Ansiedade.","ordem":4,"idAlternativa":"63fa2980-5f58-50c8-91ac-564088a02880"},{"letra":"E","texto":"Sensação de calor.","ordem":5,"idAlternativa":"2ab83021-0b6c-51a4-b7c1-104188abb2ec"}],"gabarito":"B","observacoes":[],"idQuestao":"6d59046f-5d7f-5283-89b0-0498c8dc4991","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 27"},{"secao":"Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas","numero":28,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"Os retalhos cirúrgicos são realizados para que se possa alcançar uma área ou remover tecidos de uma região para a outra. Vários princípios básicos devem ser seguidos para evitar complicações cirúrgicas do retalho. A opção que NÃO contém uma medida preventiva para evitar uma complicação pósoperatória relacionada aos acessos cirúrgicos é:","alternativas":[{"letra":"A","texto":"As incisões relaxantes devem ser convergentes para o fundo do vestíbulo.","ordem":1,"idAlternativa":"944e53d3-74d4-5f6d-b31a-c15e126d40f9"},{"letra":"B","texto":"Deve-se criar um retalho que seja amplo o suficiente para o cirurgião, a fim de evitar a sua dilaceração durante o ato cirúrgico.","ordem":2,"idAlternativa":"c850a97c-3447-50b2-aec9-7b83ca1a3a38"},{"letra":"C","texto":"Durante todo o evento cirúrgico, devemos evitar submeter o retalho à tensão.","ordem":3,"idAlternativa":"2d58b605-b167-53dc-85b5-ccb3d02c3a45"},{"letra":"D","texto":"O comprimento do retalho não deve exceder o dobro da largura da base do retalho.","ordem":4,"idAlternativa":"cb705eef-a447-5691-8477-81fb0d2b08f9"},{"letra":"E","texto":"Sempre realizar incisões sobre o tecido mole e ósseo sadio.","ordem":5,"idAlternativa":"5a760547-5cc8-5b4e-81c5-f12926d044e4"}],"gabarito":"A","observacoes":[],"idQuestao":"2dd82d71-5104-5aac-abbc-cf9abb582871","idDisciplina":"448af2b1-3edb-5f65-b668-37d13a0acae1","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cirurgia, Farmacologia, Anestesiologia e Emergências Médicas | Questão 28"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":1,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"Trata-se de uma infecção fúngica, com marcante predileção por homens de meiaidade, muitos deles trabalhadores rurais. As lesões orais apresentam-se como úlceras moriformes que geralmente acometem a mucosa alveolar, gengiva e palato. A avaliação microscópica pode revelar hiperplasia pseudoepiteliomatosa, além de ulceração no epitélio de superfície. O fungo causador dessa doença desencadeia uma resposta inflamatória granulomatosa no hospedeiro, caracterizada por coleções de macrófagos epitelioides e células gigantes multinucleadas. O enunciado corresponde à:","alternativas":[{"letra":"A","texto":"Paracoccidioidomicose.","ordem":1,"idAlternativa":"0a5749bd-ab83-559a-8b7a-7cb9b5541f70"},{"letra":"B","texto":"Candidíase.","ordem":2,"idAlternativa":"8758da71-682b-5eda-97ae-2e5e5785cf0c"},{"letra":"C","texto":"Histoplasmose.","ordem":3,"idAlternativa":"fe857442-079b-5cb1-baaf-d55e7cf4b1a8"},{"letra":"D","texto":"Aspergilose.","ordem":4,"idAlternativa":"2af4ea72-7eb1-5ba8-8d32-695b374f2d45"},{"letra":"E","texto":"Toxoplasmose.","ordem":5,"idAlternativa":"90e7cb1c-dce7-5b97-9a3f-e3498567db68"}],"gabarito":"A","observacoes":[],"idQuestao":"2e7bda6e-54c9-5d6a-9e0d-eb723e72845d","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 1"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":2,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"Numerosas alterações de desenvolvimento dos dentes podem ocorrer. Estas, são geralmente classificadas no que concerne ao número, tamanho, forma ou estrutura dos elementos. Das alternativas abaixo, todas correspondem a alterações do desenvolvimento dentário relacionadas a estrutura, EXCETO:","alternativas":[{"letra":"A","texto":"Dentinogênese imperfeita.","ordem":1,"idAlternativa":"d43ddf95-1796-5097-951a-9240c65ecdf3"},{"letra":"B","texto":"Amelogênese imperfeita.","ordem":2,"idAlternativa":"d2d47a6c-eccd-5bcd-96a4-0352a97e3429"},{"letra":"C","texto":"Hipodontia.","ordem":3,"idAlternativa":"f5e22046-b48f-5e56-88ea-7beb9912712e"},{"letra":"D","texto":"Displasia dentinária.","ordem":4,"idAlternativa":"086fab0e-5181-5c36-b762-dd60079c6ff5"},{"letra":"E","texto":"Odontodisplasia regional.","ordem":5,"idAlternativa":"0d53b49e-735b-55d2-b113-2fac4e6c3694"}],"gabarito":"C","observacoes":[],"idQuestao":"3bf30756-e9d0-5758-a445-bb30c8a50e19","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 2"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":3,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"Considere um tumor odontogênico, cuja prevalência é maior do que a de todos os outros tumores odontogênicos somados. As crianças e os adolescentes são os mais comumente afetados e a sua remoção é recomendada. O trecho refere-se ao tumor odontogênico denominado","alternativas":[{"letra":"A","texto":"fibroma.","ordem":1,"idAlternativa":"c8675f76-963e-5a10-b47f-6f83f430170d"},{"letra":"B","texto":"mixoma.","ordem":2,"idAlternativa":"dd3ceb3b-c4cc-5545-97dd-0d8cc7f44359"},{"letra":"C","texto":"cementoblastoma.","ordem":3,"idAlternativa":"b2827802-ed53-500e-acf5-2e1e2378f4af"},{"letra":"D","texto":"odontoma.","ordem":4,"idAlternativa":"71807022-ae52-5d74-b7d3-3dfa1fe7129c"},{"letra":"E","texto":"ameloblastoma.","ordem":5,"idAlternativa":"1ed0884c-f37a-539b-9f45-77f32bb3ecfc"}],"gabarito":"D","observacoes":[],"idQuestao":"d7cb8e23-b4de-5c55-8fab-75898b112ab7","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 3"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":4,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"O câncer de boca é atualmente um problema de saúde pública, sendo no último ano registrado mais de 15 mil novos casos (INCA-2020). Alguns fatores podem corroborar para o desenvolvimento desta patologia. Dentre as alternativas abaixo, assinaleaquela que NÃO representa um fator que aumenta o risco de desenvolvimento do câncer de boca.","alternativas":[{"letra":"A","texto":"Tabagismo.","ordem":1,"idAlternativa":"e07a02cb-65f3-55fb-a5a6-ac9e9dfc6263"},{"letra":"B","texto":"Consumo regular de bebidas alcoólicas.","ordem":2,"idAlternativa":"6233f698-dc2c-5ba1-b2b1-e2519e1c75c7"},{"letra":"C","texto":"Exposição ao sol sem proteção.","ordem":3,"idAlternativa":"4a2f7dc1-9959-53b8-83f5-d29ad126bd82"},{"letra":"D","texto":"Uso prolongado de água fluoretada.","ordem":4,"idAlternativa":"2e564699-eda7-58e4-bb6f-043b4d62d670"}],"gabarito":"D","observacoes":[],"idQuestao":"a60a3cc2-0fbe-5972-aef1-d676b8e1e5e7","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 4"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":5,"orgao":"Prefeitura de Acaiaca-MG","cargo":"ODONTÓLOGO – PSF/ESF","ano":2023,"enunciado":"A respeito da anamnese, assinale a alternativa que contenha informações importantes, e que é imprescindível que haja no seuquestionário. I.Identificação do paciente. II.Histórico médico. III. Histórico familiar. IV. Hábitos e vícios. V. Queixa principal. Após análise, assinale a alternativa CORRETA:","alternativas":[{"letra":"A","texto":"Apenas as alternativas II e III estão incorretas.","ordem":1,"idAlternativa":"4960dd1c-e890-5f78-b60c-248091cc5643"},{"letra":"B","texto":"Todas as alternativas estão corretas.","ordem":2,"idAlternativa":"82418f44-ccfe-5428-9cd4-1ed86cc5e6b5"},{"letra":"C","texto":"Apenas as alternativas I, II e a IV estão corretas.","ordem":3,"idAlternativa":"8cdc4437-6056-5716-87a3-a94ef4ac7f10"},{"letra":"D","texto":"Todas as alternativas estão incorretas.","ordem":4,"idAlternativa":"671ba888-e234-5227-83c3-6dedbff5e5fa"}],"gabarito":"B","observacoes":[],"idQuestao":"f56fb325-296d-59d6-9368-f0b13d773fda","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"aacfc330-42a4-5699-b225-600e23696e38","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 5"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":6,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"A prevenção de uma enfermidade pode ser entendida como uma ação antecipada, baseada no conhecimento da História Natural da Doença, com a intenção de impedir o seu progresso. De acordo com os níveis de prevenção propostos por Leavell & Clark (1976), as abordagens sobre os fatores de risco ou de proteção simultâneos tanto para doenças da cavidade bucal quanto para outros agravos, pode ser relacionada a:","alternativas":[{"letra":"A","texto":"Limitação do dano.","ordem":1,"idAlternativa":"7d73b192-424b-5718-9798-518e1b716dd6"},{"letra":"B","texto":"Promoção da saúde.","ordem":2,"idAlternativa":"974f6a89-d415-5921-8a12-98bdacd27d6a"},{"letra":"C","texto":"Proteção inespecífica.","ordem":3,"idAlternativa":"86e50804-15be-5ab1-b521-ca78e6c99d1c"},{"letra":"D","texto":"Proteção específica.","ordem":4,"idAlternativa":"7cc0e03c-96a8-56be-ba5f-0e7e4744df32"}],"gabarito":"B","observacoes":[],"idQuestao":"78252acf-611b-5e14-86ca-75403e50334a","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 6"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":7,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"Assinale abaixo a doença que pode apresentar lesões orais na forma de ulcerações dolorosas, isoladas ou agrupadas, com superfície amarelada e normalmente circundadas por halo eritematoso. Essa enfermidade usualmente acomete homens e mulheres na faixa etária de 25 a 35 anos, possui uma base imunogenética confirmada por fortes associações com certos tipos de antígenos leucocitários humanos e pode também estar associada a lesões oculares, cutâneas e genitais recorrentes.","alternativas":[{"letra":"A","texto":"Eritema multiforme.","ordem":1,"idAlternativa":"3fb40dbd-f760-5f75-ab9e-3a0ec1de747e"},{"letra":"B","texto":"Síndrome de Behçet.","ordem":2,"idAlternativa":"8da17f7a-c8e4-5a9c-8576-f96bb74b3e49"},{"letra":"C","texto":"Tumor marrom do hiperparatireoidismo .","ordem":3,"idAlternativa":"38024b8e-756b-5678-a0a6-79530ad2c4b4"},{"letra":"D","texto":"Síndrome de Stevens-Johnson.","ordem":4,"idAlternativa":"64796db2-07cc-5e59-acbc-0670a56f74e6"}],"gabarito":"D","observacoes":[],"idQuestao":"993c2a7b-59fc-5e1c-b716-b7218246b147","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 7"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":8,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"Para prevenir diversos tipos de enfermidades podemos dispor de vários métodos situados em um único nível de prevenção. Sendo assim, os níveis de aplicação podem ser definidos como níveis onde determinamos o tipo de ação exigida para a utilização dos níveis de prevenção. O ensino da técnica de escovação desenvolvido por profissional técnico ou auxiliar relaciona-se a qual dos níveis de aplicação?","alternativas":[{"letra":"A","texto":"1°nível.","ordem":1,"idAlternativa":"d1b89c4e-ba93-5ade-9986-892c44e35de3"},{"letra":"B","texto":"2°nível.","ordem":2,"idAlternativa":"818306fe-419a-5062-9b03-9d70347a57ca"},{"letra":"C","texto":"3°nível.","ordem":3,"idAlternativa":"9fd6f41f-1418-5cf3-a6f5-c7a24750797d"},{"letra":"D","texto":"4°nível.","ordem":4,"idAlternativa":"2c86f650-fd63-5df8-bf97-9da656f61dba"}],"gabarito":"A","observacoes":[],"idQuestao":"a662aecd-aad7-56d3-bbad-acf27922c996","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 8"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":9,"orgao":"Prefeitura de Jequitinhonha-MG","cargo":"ODONTÓLOGO – PSF","ano":2023,"enunciado":"Os ameloblastomas são tumores que se originam do epitélio:","alternativas":[{"letra":"A","texto":"Odontogênico.","ordem":1,"idAlternativa":"d6b602d6-9dd2-5b91-a2d3-2869877aa845"},{"letra":"B","texto":"Escamoso.","ordem":2,"idAlternativa":"d89da765-b45e-5d9e-8cb4-2b976890be46"},{"letra":"C","texto":"Mesenquimal.","ordem":3,"idAlternativa":"3fb442e4-7430-5469-9f5a-5c17b7cb7e84"},{"letra":"D","texto":"Glandular.","ordem":4,"idAlternativa":"3e396e0f-485d-5bdc-9915-7c77c814484a"}],"gabarito":"B","observacoes":[],"idQuestao":"9567e82b-058e-54a2-a66f-09c6045afd0a","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"7145ec74-34e5-586d-9cfe-17171918faf3","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 9"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":10,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Miloro (2016), o sistema de classificação das osteomielites proposto por Hudson é o mais vantajoso e a osteomilite pode ser dividida em forma aguda e crônica com base na presença da doença por 1 mês, Sendo assim, é uma osteomilite aguda:","alternativas":[{"letra":"A","texto":"a osteomielite de Garré.","ordem":1,"idAlternativa":"df103442-6f79-5318-8633-26bb8123b982"},{"letra":"B","texto":"a hematogênica.","ordem":2,"idAlternativa":"7cbc23fb-efb4-5fd3-bedd-ed0a7f4989ad"},{"letra":"C","texto":"a esclerosante.","ordem":3,"idAlternativa":"6046b5fd-cda0-5447-b516-b26f2164b1f6"},{"letra":"D","texto":"a supurativa ou não supurativa,","ordem":4,"idAlternativa":"8fb129ee-5277-5397-b72d-14860b19ce92"},{"letra":"E","texto":"a multifocal recorrente.","ordem":5,"idAlternativa":"c451762d-2f1d-5e5a-9277-8c42b38dec81"}],"gabarito":"C","observacoes":[],"idQuestao":"49d99016-ec99-5730-8c93-3556c78ef0fe","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 10"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":11,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Neville (2016), como é chamada a patologia óssea caracterizada histopatologicamente por reabsorção e formação de osso descontrolada, sendo a junção entre alternada reabsorção e formação óssea indicada por linhas de inversão basofílca o que resulta em uma aparência de “quebra-cabeça” ou de “mosaico”?","alternativas":[{"letra":"A","texto":"Osteólise maciça.","ordem":1,"idAlternativa":"b804f083-fdb6-598c-97eb-0d9c510a79e5"},{"letra":"B","texto":"Osteoesclerose idiopática.","ordem":2,"idAlternativa":"1e679fc7-609e-5b0c-9540-cc42db4941c6"},{"letra":"C","texto":"Doença de Paget.","ordem":3,"idAlternativa":"2aebbf59-8bd7-50dc-b3cf-d4e31119dfbb"},{"letra":"D","texto":"Querubismo.","ordem":4,"idAlternativa":"56e4266f-487a-5c55-ac01-bd7d8ad63947"},{"letra":"E","texto":"Displasia óssea florida.","ordem":5,"idAlternativa":"163b42f3-2fe5-5280-9060-d861f18b4aa5"}],"gabarito":"C","observacoes":[],"idQuestao":"8d5466e2-c371-5bfb-85f5-f0b1d8491fd2","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 11"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":12,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Dean, McDonald e Avery (2011), são fatores sistêmicos que retardam a erupção dentária:","alternativas":[{"letra":"A","texto":"hipofosfatasia, querubismo e hipotireoidismo.","ordem":1,"idAlternativa":"d0118ec3-8da5-5ba4-8840-f1403b034e60"},{"letra":"B","texto":"Sindrome de Hunter, mucopolissacaridose tipo VI e hipoptuitarismo.","ordem":2,"idAlternativa":"a2386c99-f1f6-5284-abbf-78670880317d"},{"letra":"C","texto":"acrodinia, neutropeniacíclica e hipertireoidismo.","ordem":3,"idAlternativa":"bf0bf6cc-db13-5532-9eac-a48857324fb8"},{"letra":"D","texto":"acatalasia, Síndrome de Ehlers-Danlos ehiperpituitarismo.","ordem":4,"idAlternativa":"dea87a76-b9d6-5b48-b8e1-51e6987ef5d8"},{"letra":"E","texto":"histiocitose X, Síndrome de Chediak-Higashi e leucemia.","ordem":5,"idAlternativa":"b87fb1df-e2e1-59cf-8bd7-b4f9dbc39e79"}],"gabarito":"B","observacoes":[],"idQuestao":"530b0c80-66bd-5339-b9e3-0d6427e0e157","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 12"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":13,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Andrade (2011), com relação às fases da evolução do choque anafilático e seus sinais e sintomas, fazem parte da fase 2 (sistema respiratório) os seguintes sinaise sintomas:","alternativas":[{"letra":"A","texto":"tosse, cianose e taquicardia.","ordem":1,"idAlternativa":"c09f4a54-d6b1-5d35-8214-994ee1842c00"},{"letra":"B","texto":"palidez, hipotensão arterial e perda de consciência.","ordem":2,"idAlternativa":"4f0ce128-2755-59ed-a223-39412adac97d"},{"letra":"C","texto":"dispineia, edema de laringe ecianose.","ordem":3,"idAlternativa":"f18c32fe-896c-59b2-9a43-f9145d92fc4f"},{"letra":"D","texto":"coriza, náuseas e vômito.","ordem":4,"idAlternativa":"35189717-b4de-583c-8fb5-22c8d317865f"},{"letra":"E","texto":"edema de laringe, taquicardia, epalidez.","ordem":5,"idAlternativa":"2c53af1a-9f28-51d5-b41c-3f141139039f"}],"gabarito":"C","observacoes":[],"idQuestao":"3c99c33f-d300-5392-8e9e-7b060f581b10","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 13"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":14,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Neville (2016), como é chamado o cisto fissural raro, que, teoricamente, se desenvolve do epitélio retido ao longo da linha de fusão embrionária das cristas palatinas laterais da maxila?","alternativas":[{"letra":"A","texto":"Cisto da fenda branquial.","ordem":1,"idAlternativa":"0669dcf8-4753-5aa1-9cd0-b4685d7f5b2a"},{"letra":"B","texto":"Cisto palatal mediano.","ordem":2,"idAlternativa":"5bf82050-d92c-5f39-b88a-bff543353162"},{"letra":"C","texto":"Cisto dermóide.","ordem":3,"idAlternativa":"cd609676-4b1e-5f62-8325-6ea7f4f9e68d"},{"letra":"D","texto":"Cisto mandibular mediano.","ordem":4,"idAlternativa":"558dc613-ba97-500b-8159-46f871a4f46b"},{"letra":"E","texto":"Cisto do ducto nasopalatino.","ordem":5,"idAlternativa":"1ab7cfa9-bc71-5c3a-96f0-307463eed497"}],"gabarito":"C","observacoes":[],"idQuestao":"5ca2438d-78f2-5d05-bfd9-0d5d1c1eefa4","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 14"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":15,"orgao":null,"cargo":null,"ano":null,"enunciado":"A candidíase, uma doença fúngica oportunista comum na cavidade bucal, é causada pela Candida albicans. As manifestações clínicas e suas associações com outras causalidades são diversas. A afirmativa que se refere MELHOR à Candidíase bucal é:","alternativas":[{"letra":"A","texto":"Apresenta associação, exclusiva, com quadros de imunossupressão.","ordem":1,"idAlternativa":"3f7b04eb-60dc-5bf0-a346-f89911a27141"},{"letra":"B","texto":"As lesões eritematosas orais aparecem somente no dorso de língua.","ordem":2,"idAlternativa":"c5c8e514-e524-5fb4-9582-e0da0b60a720"},{"letra":"C","texto":"Manifesta-se, comumente, associada a placas brancas pseudomembranosas destacáveis.","ordem":3,"idAlternativa":"8f259b0f-8ba1-5835-b66f-a00da022ab1c"},{"letra":"D","texto":"O diagnóstico deve ser confirmado por meio de biópsia incisional.","ordem":4,"idAlternativa":"d301c6eb-576c-5519-92de-b928cbfe60f5"},{"letra":"E","texto":"Pode-se observar uma forma classificada como candidíase atrófica aguda, associada ao uso de prótese total mal higienizada.","ordem":5,"idAlternativa":"37458b23-534e-5fb3-b923-aea39328063f"}],"gabarito":"C","observacoes":["Obs.: O PDF não traz o cabeçalho (cargo/ano/órgão) desta questão."],"idQuestao":"f3eda602-1686-55ea-a661-e6fa4ca4df5e","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":null,"idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 15 | Obs.: O PDF não traz o cabeçalho (cargo/ano/órgão) desta questão."},{"secao":"Estomatologia e Diagnóstico Bucal","numero":16,"orgao":"Polícia Civil","cargo":"DENTISTA","ano":2022,"enunciado":"O Instituto Nacional do Câncer estimou, para o ano de 2022, a ocorrência de 15.200 novos casos de neoplasias malignas de cavidade oral no Brasil, sendo cerca de 11.200 em homens e 4.000 em mulheres (INCA, 2020). O carcinoma de células escamosas representa mais de 90% das neoplasias malignas que acome- tem a boca. Diante dessas características, avalie as afirmativas a seguir e a relação proposta entre elas. I.O carcinoma de células escamosas de boca caracteriza-se por uma apre- sentação clínica variável, podendo ser observadas lesões exofíticas, en- dofíticas, leucoplásicas, eritroplásicas ou eritroleucoplásicas. PORQUE IIOs principais fatores de risco para o carcinoma de células escamosas de boca são o tabaco, o álcool, a radiação solar e a infecção pelos subtipos 16 e 18 do Papilomavírus Humano (HPV). Está CORRETO o que se afirma em:","alternativas":[{"letra":"A","texto":"I e II são proposições falsas.","ordem":1,"idAlternativa":"37a97c17-5134-552f-9db5-5b8d3c7a85ea"},{"letra":"B","texto":"I e II são proposições verdadeiras, e a II é uma justificativa da I.","ordem":2,"idAlternativa":"aed0d68f-0fad-51c3-ab05-23b93606b320"},{"letra":"C","texto":"I e II são proposições verdadeiras, mas a II não é uma justificativa da I.","ordem":3,"idAlternativa":"ff5bff60-7194-5b26-9c61-27f85353577e"},{"letra":"D","texto":"I é uma proposição falsa, e a II é uma proposiçãoverdadeira.","ordem":4,"idAlternativa":"486cca39-4744-55c1-b928-442b25a71aba"},{"letra":"E","texto":"I é uma proposição verdadeira, e a II é uma proposição falsa.","ordem":5,"idAlternativa":"1b980690-b34f-5d0e-90d8-056946397bde"}],"gabarito":"C","observacoes":[],"idQuestao":"968f4ea5-d30d-5d2a-b20c-04e15a9e30e3","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"768662b3-9529-578c-bca1-0d76a8e23e1b","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 16"},{"secao":"Estomatologia e Diagnóstico Bucal","numero":17,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2007,"enunciado":"O fumo é um dos mais potentes agentes cancerígenos conhecidos que o ser humano introduz voluntariamente no organismo. Dependendo do tipo e da quantidade do tabaco utilizados, os tabagistas apresentam uma probabilidade 4 a 15 vezes maior de desenvolver câncer de boca do que os não tabagistas. A tabela abaixo mostra os efeitos, no Brasil, da suspensão do tabagismo sobre o risco de câncer de boca estratificado pela localização anatômica. *CID-9: (141) Tumor maligno da língua; (143) Tumor maligno da gengiva; (144) Tumor maligno do pavimento da boca; (145) Tumor maligno de outras partes e de partes não especificadas da cavidade bucal. FRANCO e cols. Risk factors for oral cancer in Brazil: a case control study. International Journal of Cancer, 1989, vol. 43, p. 992-1000. Com base nos dados fornecidos e no conhecimento dos efeitos do tabagismo sobre o câncer de boca, conclui-se que","alternativas":[{"letra":"A","texto":"existe uma forte relação entre a quantidade de tabaco usada por dia e a duraçãodo período de exposição, aumentando o risco com a cessação do tabagismo.","ordem":1,"idAlternativa":"b6088da9-6c36-57ca-9116-12bd57a59537"},{"letra":"B","texto":"políticas educativas para a prevenção do câncer no país devem priorizar ações educativas voltadas para estimular a população a realizar o auto-exame da boca, ao invés de criar programas de cessação do hábito de fumar, pois estes somente mostram resultados a longo prazo.","ordem":2,"idAlternativa":"7b7909a8-67c0-582b-aebf-bb0c17ed3d50"},{"letra":"C","texto":"o câncer da boca é um dos mais incidentes em homens brasileiros, e sua ocorrência não está associada a outros fatores de risco além do tabagismo.","ordem":3,"idAlternativa":"350926c9-6252-5a78-9bab-f29e81a75b33"},{"letra":"D","texto":"após 10 anos de abandono do hábito de fumar, o risco decresce para nível semelhante àquele observado entre os que nunca fumaram.","ordem":4,"idAlternativa":"23199e3f-a539-5d9e-9081-1d8e6201d7c7"},{"letra":"E","texto":"na cavidade bucal, a língua e o soalho bucal são as localizações preferenciais de ocorrência do câncer bucal, independente do hábito de fumar, sendo o Sarcoma de Kaposi o tipo histológico mais freqüente.","ordem":5,"idAlternativa":"ab1b4d5c-e32c-5a51-8a76-5c206f5ca417"}],"gabarito":"D","observacoes":["Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."],"idQuestao":"24845319-fc52-5b6c-a2ac-b871d4432823","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"04d40d7d-9cf1-54bf-bf15-91cbef2199af","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"rascunho","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 17 | Obs.: Enunciado depende de figura/tabela/gráfico que não veio no texto do PDF."},{"secao":"Estomatologia e Diagnóstico Bucal","numero":18,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2016,"enunciado":"Mãe descobre que filho foi estuprado após dentista achar doença na boca Uma mãe descobriu que o filho de 6 anos foi estuprado depois que o levou a um cirurgião-dentista no posto de saúde. O garoto tinha uma lesão no lábio inferior e o profissional suspeitou que ele tinha uma doença sexualmente transmissível. O cirurgião-dentista que fez o atendimento à vítima conta que a mãe achava que a lesão era resultado de mordidas. Entretanto, a lesão tinha por características: “verruga” com mancha branca, aspecto papilífero, semelhante a couve flor, pediculado e assintomático. Disponível em: . Acesso em: 26 jul. 2016 (adaptado). Diante do caso apresentado, a hipótese diagnóstica e a conduta adequada do profissional são","alternativas":[{"letra":"A","texto":"herpes; notificar a suspeita de maus tratos ao ConselhoTutelar.","ordem":1,"idAlternativa":"981cf2cd-ba40-5d2d-ad35-099eb8b72485"},{"letra":"B","texto":"herpes; notificar a suspeita de maus tratos ao serviço social da Unidade Básica de Saúde.","ordem":2,"idAlternativa":"3bd993d3-01b7-5aa0-96e5-56cb3d566fbc"},{"letra":"C","texto":"HPV; notificar a suspeita de maus tratos ao Conselho Tutelar.","ordem":3,"idAlternativa":"53ca25f3-7a93-571a-86b0-4c134af18593"},{"letra":"D","texto":"HPV; notificar a suspeita de maus tratos ao serviço social da Unidade Básica de Saúde.","ordem":4,"idAlternativa":"2fa3d3f8-8a22-565b-8688-835834e1d0fd"},{"letra":"E","texto":"sífilis; notificar a suspeita de maus tratos à autoridade policial local.","ordem":5,"idAlternativa":"f6e60987-897a-5533-837e-94e215b0a395"}],"gabarito":"C","observacoes":[],"idQuestao":"07616096-26f8-525e-aa37-f5bd9d2760f6","idDisciplina":"7521f52e-e730-50d8-b0e8-e1b15664115c","idConcurso":"adf047da-a595-5e81-9e5b-15bb3d5c4819","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Estomatologia e Diagnóstico Bucal | Questão 18"},{"secao":"Cariologia e Flúor","numero":1,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"A cárie é uma doença muito antiga, com pelo menos 500 mil anos de idade. Sobre a cárie, aponte a alternativa INCORRETA:","alternativas":[{"letra":"A","texto":"As características clínicas da lesão revelam se a doença está ocorrendo no momento (lesões ativas) ou se são apenas sequelas de experiências passadas de doença (lesões inativas).","ordem":1,"idAlternativa":"2f33e5d4-a9ea-5e23-9a23-89a7a074a064"},{"letra":"B","texto":"A perda mineral dos tecidos dentários é causada por ácidos produzidos pela fermentação bacteriana dos carboidratos da dieta.","ordem":2,"idAlternativa":"ee2b2eb9-2ad0-5e71-bd89-1a7052993c83"},{"letra":"C","texto":"A cárie é uma doença crônica que inicia com a desmineralização submicroscópica do esmalte.","ordem":3,"idAlternativa":"c0b91706-f74d-56f7-ba07-1db75e18ae14"},{"letra":"D","texto":"A lesão da cárie é apenas o sinal clinicamente detectável da doença cárie, que iniciou bem antes da detecção clínica da lesão.","ordem":4,"idAlternativa":"720490cf-26fc-5a6f-9b9c-736bf4407ab8"},{"letra":"E","texto":"O sistema tampão da saliva promove a desmineralização, processo caracterizado pela perda de íons da estrutura dentária para o meioexterno.","ordem":5,"idAlternativa":"e5139af4-85c4-56a0-bc77-26e4a1d869dc"}],"gabarito":"E","observacoes":[],"idQuestao":"f5e273e3-0219-5f05-adce-c2b6efd9b019","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 1"},{"secao":"Cariologia e Flúor","numero":2,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"Em função das evidências científicas acumuladas a seu favor, o flúor passou a ser utilizado em escala mundial como método de prevenção à cárie dentária. Sobre o uso do flúor na Odontologia, assinale a alternativa CORRETA:","alternativas":[{"letra":"A","texto":"A solução neutra de fluoreto de sódio indicada para bochecho semanal possui 0,05% de concentração.","ordem":1,"idAlternativa":"ddd218b2-04f0-5925-8580-071cd1567771"},{"letra":"B","texto":"A dose provavelmente tóxica de flúor é de 10mg por Kg de peso.","ordem":2,"idAlternativa":"9ad3fd50-8eca-5799-b3da-69122d8ca4e6"},{"letra":"C","texto":"Por não terem eficácia comprovada e apresentarem alto custo, os bochechos com fluoretos não são amplamente difundidos.","ordem":3,"idAlternativa":"5bf739f7-e665-5093-9312-efd6f57898e3"},{"letra":"D","texto":"No que concerne à fluoretação das águas de abastecimento, a dosagem admitida é de 0,7mg de fluoreto por litro de água.","ordem":4,"idAlternativa":"97e99a52-0832-58e3-810c-bcfa7dd705ce"},{"letra":"E","texto":"A solução neutra de fluoreto de sódio indicada para bochecho diário possui 0,2% de concentração.","ordem":5,"idAlternativa":"4335a91f-1074-5a2f-b40c-477306c1c31c"}],"gabarito":"D","observacoes":[],"idQuestao":"852827ee-72c1-548f-8847-d67857520952","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 2"},{"secao":"Cariologia e Flúor","numero":3,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"É aceito e estabelecido universalmente que a cárie dentária é uma doença multifatorial, infecciosa e transmissível. O diagrama de Keyes cita três fatores de risco na etiologia da cárie: dente suscetível, microrganismo e dieta. Mas Newbrum inclui outro fator etiológico:","alternativas":[{"letra":"A","texto":"O sol.","ordem":1,"idAlternativa":"a673ebf2-5d6f-5852-b938-ed0e3208b3da"},{"letra":"B","texto":"O frio.","ordem":2,"idAlternativa":"fce564be-fd2d-5746-8f10-250c86b007de"},{"letra":"C","texto":"O calor.","ordem":3,"idAlternativa":"f28a2d56-b420-58e5-b350-e5366c00dd09"},{"letra":"D","texto":"O tempo.","ordem":4,"idAlternativa":"750e530f-5c8a-58d6-9edc-2cc1a5c4e191"},{"letra":"E","texto":"O açúcar.","ordem":5,"idAlternativa":"406af17e-1c7a-585a-be65-268242284566"}],"gabarito":"D","observacoes":[],"idQuestao":"4038d6e5-70e8-5fde-ae9d-971e38331307","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 3"},{"secao":"Cariologia e Flúor","numero":4,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"A intoxicação aguda por fluoretos resulta da ingestão única de uma grande quantidade de flúor que pode apresentar os seguintes sinais e sintomas, exceto:","alternativas":[{"letra":"A","texto":"Parestesia, tetania e depressão do sistema nervosocentral.","ordem":1,"idAlternativa":"84217bcc-dd7b-5728-b4a7-3f9902612751"},{"letra":"B","texto":"Vômito e diarreia.","ordem":2,"idAlternativa":"e42ea120-ab20-510c-b688-a14bcdba2700"},{"letra":"C","texto":"Alcalose e hipercalcemiasanguíneas.","ordem":3,"idAlternativa":"024f8a97-b3a1-5cd5-81cb-dde746b89b2b"},{"letra":"D","texto":"Hipotensão e palidez.","ordem":4,"idAlternativa":"0943ea76-b5a2-5b35-b9ab-67609d4638b6"}],"gabarito":"C","observacoes":[],"idQuestao":"a788515d-ad45-507b-ba30-053b211cd7a2","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 4"},{"secao":"Cariologia e Flúor","numero":5,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"Qual é o valor limite de ingestão de flúor diária contabilizando a ingestão de água fluoretada?","alternativas":[{"letra":"A","texto":"0,04mgF/Kg/dia.","ordem":1,"idAlternativa":"b7af3ad0-66f2-5cf8-a492-5bfc6be423b8"},{"letra":"B","texto":"0,05mgF/Kg/dia.","ordem":2,"idAlternativa":"22a011b7-5185-5e85-a6ae-4fdfbeb863f2"},{"letra":"C","texto":"0,06mgF/Kg/dia.","ordem":3,"idAlternativa":"848faa90-9e3a-50c6-b2d3-764591b0f205"},{"letra":"D","texto":"0,07mgF/Kg/dia.","ordem":4,"idAlternativa":"17cf1d62-7ac7-5e20-8d9c-c964aca263fb"},{"letra":"E","texto":"0,08mgF/Kg/dia.","ordem":5,"idAlternativa":"478fb60e-49c2-5f09-8746-92d624fc16b0"}],"gabarito":"D","observacoes":[],"idQuestao":"a4a6dd18-1dfe-5023-9659-14e6a451870c","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 5"},{"secao":"Cariologia e Flúor","numero":6,"orgao":"Prefeitura de Pedrão-BA","cargo":"ODONTÓLOGO – PSF","ano":2021,"enunciado":"Como é chamado o distúrbio do esmalte causado por exposições excessivas a concentrações de flúor, que ocasiona a formação do esmalte com um menor conteúdo mineral e maior porosidade, sendo caracterizadas por áreas brancas sem brilho e opacas, no esmalte?","alternativas":[{"letra":"A","texto":"Fluorose.","ordem":1,"idAlternativa":"40a146eb-0b60-5ded-8189-5fb4e12c222a"},{"letra":"B","texto":"Mancha branca ativa","ordem":2,"idAlternativa":"f1031402-cb59-5fa2-bf59-7f24383cbbe4"},{"letra":"C","texto":"Mancha branca inativa.","ordem":3,"idAlternativa":"63d953a9-73ad-5bf5-9c95-0f20fc43655c"},{"letra":"D","texto":"Fluorapatita.","ordem":4,"idAlternativa":"18b86107-cc19-5d4d-92ae-b4b3046e997a"},{"letra":"E","texto":"Fluoretazia.","ordem":5,"idAlternativa":"5234a81e-fee6-5898-aacd-aee0abf75c63"}],"gabarito":"A","observacoes":[],"idQuestao":"7adcdc95-5ecc-517a-ba6d-aec210d29257","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"644420d4-273b-5d15-8f19-489527c5ee0f","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 6"},{"secao":"Cariologia e Flúor","numero":7,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"No processo etiológico da doença cárie ocorre uma disbiose acompanhada pelo domínio de bactérias acidogênicas (produtoras de ácidos a partir do metabolismo anaeróbico do açúcar) e acidúricas (vivem bem em ambiente ácido). Além disso, tais bactérias são capazes de produzir substâncias que aumentam o potencial de aderência entre bactérias, servem como reserva energética, protegem as bactérias contra agentes antimicrobianos e dificultam a sua remoção mecânica pela escovação. Trata-se da substância:","alternativas":[{"letra":"A","texto":"Lipídeos intracelulares.","ordem":1,"idAlternativa":"e3258659-f2fd-5d54-bc06-d190ceeb313f"},{"letra":"B","texto":"Lipídeos extracelulares.","ordem":2,"idAlternativa":"ab43d273-8a06-5381-ad48-f5b2bf04e709"},{"letra":"C","texto":"Monoproteínas intracelulares.","ordem":3,"idAlternativa":"6d69f3f4-235e-5ba4-95e3-2ec679085d68"},{"letra":"D","texto":"Polissacarídeos intracelulares.","ordem":4,"idAlternativa":"7320c399-eab2-5959-872c-4aad18e6f750"},{"letra":"E","texto":"Polissacarídeos extracelulares.","ordem":5,"idAlternativa":"b811528e-d0d2-5c83-bb61-de7ee82c5634"}],"gabarito":"A","observacoes":[],"idQuestao":"b8dc15a2-0b57-5d65-81bf-71dfcaaac6c8","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 7"},{"secao":"Cariologia e Flúor","numero":8,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Com os avanços da Odontologia, constatou-se que o uso do flúor é a medida de maior impacto e relevância para o controle da cárie dentária. Uma das razões principais para o sucesso do flúor é a facilidade e diversidade de suas formas de aplicação. A respeito do uso do flúor, marque V para as afirmativas verdadeiras e F para as falsas. ( ) Embora os métodos de liberação de flúor possam ser divididos em sistêmicos e tópicos, o modo primário de ação desse mineral resulta de atividade t pica na cavidade bucal. ( ) necessário manter a exposição regular ao flúor, seja com o uso sistêmico ou t pico para manter sua concentração no ambiente bucal e na placa dentária. ( ) O uso t pico do flúor tem efeito na remineralização das lesões erosivas e também na prevenção do desenvolvimento futuro dessas lesões. Assinale a sequência correta.","alternativas":[{"letra":"A","texto":"F, F, F","ordem":1,"idAlternativa":"aaebbca5-5b8e-5401-a037-8f9cd66b6efb"},{"letra":"B","texto":"F,V, V","ordem":2,"idAlternativa":"b5974b3b-9114-5643-b6f1-72b625bdcc43"},{"letra":"C","texto":"F, F, V","ordem":3,"idAlternativa":"e57fa9a9-beb2-5f4e-bada-7bf51cbcc88d"},{"letra":"D","texto":"V, F, V","ordem":4,"idAlternativa":"0994bd72-134d-540c-ac72-1d8b5e77ea5e"},{"letra":"E","texto":"V, V, F","ordem":5,"idAlternativa":"facf1fdf-beb6-5749-b7d5-82f042adb5d4"}],"gabarito":"C","observacoes":[],"idQuestao":"bd4adaae-a7f2-5569-be92-c859da09b014","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 8"},{"secao":"Cariologia e Flúor","numero":9,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Fejerskov et a!. (2017), com relação à cárie dentária, assinale a opção INCORRETA.","alternativas":[{"letra":"A","texto":"Uma lesão considerada progressiva, em que se prevê que a lesão se desenvolveria mais em um exame subsequente, seria descrita como uma lesão de cárie ativa.","ordem":1,"idAlternativa":"e143b03c-d7f5-53d4-99bf-bf3d660107c3"},{"letra":"B","texto":"O termo “cáries rampantes\" é dado para múltiplas lesóes de cárie ativa que ocorrem em um mesmo paciente.","ordem":2,"idAlternativa":"36274277-bf80-59e0-bd80-2d69fa2e3640"},{"letra":"C","texto":"As lesões de cárie dentária se desenvolvem na mesma velocidade em todas as partes da boca.","ordem":3,"idAlternativa":"f01ab5cf-cb7f-5038-9764-78ec361cd9db"},{"letra":"D","texto":"As lesões de cárie dentária são o resultado do descompasso no equilibrio fisiológico entre o conteúdo mineral do dente e o fluido do biofilme.","ordem":4,"idAlternativa":"4e78f467-0609-54ce-905e-9a687bd95695"},{"letra":"E","texto":"Caso o biofilme seja parcial ou totalmente removido, a perda mineral pode ser interrompida ou, até mesmo revertida.","ordem":5,"idAlternativa":"a402f58b-a432-5a10-88d6-d9d859e995e4"}],"gabarito":"C","observacoes":[],"idQuestao":"b1b6f97a-c68d-5bd8-a860-73615d8ce656","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 9"},{"secao":"Cariologia e Flúor","numero":10,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Pereira et al. (2009), a temperatura é fator ambiental de maior importância para a determinação da concentrasao de flúor na água de abastecimento, já que seu consumo está intimamente relacionado à temperatura, sendo correto afirmar que a dose ideal de flúor na água de abastecimento recomendada a países de clima tropical, em mg de F/l de água, ź:","alternativas":[{"letra":"A","texto":"0,4","ordem":1,"idAlternativa":"2441db97-63f4-502a-bb43-c6bc0c5f958b"},{"letra":"B","texto":"0,5","ordem":2,"idAlternativa":"c5894518-b359-548d-9093-4ebe2f2a6a73"},{"letra":"C","texto":"0,7","ordem":3,"idAlternativa":"19044fd2-80e2-552d-8c0c-ec9e0bb9350f"},{"letra":"D","texto":"0,9","ordem":4,"idAlternativa":"4adb9337-07ab-5127-acd8-97fbd56c68c8"},{"letra":"E","texto":"1,5","ordem":5,"idAlternativa":"4a0694e2-7cb8-55c9-9912-22d5e582563e"}],"gabarito":"C","observacoes":[],"idQuestao":"9fd5a7cb-b3ac-5e04-8d12-3631973031fa","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 10"},{"secao":"Cariologia e Flúor","numero":11,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2004,"enunciado":"O Brasil Sorridente é um programa que engloba diversas ações do Ministério da Saúde e busca melhorar as condições de saúde bucal da população brasileira. Esse programa propõe.","alternativas":[{"letra":"A","texto":"fluoretação das águas de abastecimento de 50% dos municípios brasileiros.","ordem":1,"idAlternativa":"e3627726-a6d2-5f16-a654-31962da255e4"},{"letra":"B","texto":"distribuição de kits de cremes dentais e escovas dentais para todas as famílias atendidas pelo Programa.","ordem":2,"idAlternativa":"43e5ac31-d3f3-5d5d-a5f9-892439c8dda8"},{"letra":"C","texto":"construção de Centros de Referência para tratamentos especializados tais como endodontia, periodontia, cirurgia buco-maxilofacial e ortodontia.","ordem":3,"idAlternativa":"c888c272-cc10-5c54-9dbb-8b1e21efcfbf"},{"letra":"D","texto":"formação de equipes de saúde bucal compostas por um cirurgião-dentista e um auxiliar de consultório dentário para atendimento a populações carentes.","ordem":4,"idAlternativa":"734e8a02-a83c-5b54-a755-f58e7f04a05c"},{"letra":"E","texto":"criação de equipes de saúde bucal aptas a realizar extrações dentárias, restaurações e aplicações tópicas de flúor, além de educação para saúde.","ordem":5,"idAlternativa":"e6cec866-b9ec-535c-a168-44213fb6dbef"}],"gabarito":"C","observacoes":[],"idQuestao":"11343d38-29e2-537e-9515-cd4ead6390eb","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"e04b197f-8e81-5c4e-b24b-67cb6765b709","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 11"},{"secao":"Cariologia e Flúor","numero":12,"orgao":"ENADE (INEP/MEC)","cargo":"Prova de Odontologia","ano":2013,"enunciado":"Ao planejar as ações em uma população adscrita de uma Unidade Básica de Saúde na área rural, o cirurgião-dentista incorporou a medição de íon flúor nas águas dos poços artesianos que as famílias usam para o consumo humano, visando realizar mapeamento das áreas com teores residuais de flúor. Considerando o uso do flúor em área rural e a Estratégia de Saúde da Família, avalie as afirmativas a seguir. I. A presença de flúor em teores acima do recomendado nas águas dos poços artesianos que abastecem a população na área rural constitui um dos fatores de risco à fluorose dentária na população. II. O baixo teor de flúor residual na água de poços artesianos de consumo humano na área rural dispensa a realização dos levantamentos epidemiológicos de fluorose dentária pela Estratégia de Saúde da Família. III. A realização de levantamento epidemiológico de cárie e fluorose dentária e a determinação da concentração de flúor nas águas dos poços artesianos contribuem para o planejamento das ações coletivas de saúde. IV. A vigilância, o controle e a orientação à população quanto às várias formas de utilização do flúor são medidas necessárias para o controle das formas agudas e crônicas de intoxicação por flúor e constituem ações de abordagem individual na prevenção da fluorose dentária. É correto apenas o que se afirma em","alternativas":[{"letra":"A","texto":"I e II.","ordem":1,"idAlternativa":"549269e3-264d-58bc-8b6b-7019bbefe38a"},{"letra":"B","texto":"I e III.","ordem":2,"idAlternativa":"ecc808b4-480f-5f40-80a2-30506502a2b7"},{"letra":"C","texto":"II e IV.","ordem":3,"idAlternativa":"8ee1ff31-98ce-59b2-b4d9-3940add43c86"},{"letra":"D","texto":"I, IIIe IV.","ordem":4,"idAlternativa":"385f00cc-0d67-504f-b6e1-c41232e32efc"},{"letra":"E","texto":"II, IIIe IV.","ordem":5,"idAlternativa":"d0064920-8ba9-58bd-ab60-10f071393139"}],"gabarito":"B","observacoes":[],"idQuestao":"738df15d-f75d-56ed-a975-83d5c95c08b5","idDisciplina":"6ce0515c-b4a3-50cf-81cc-25cb9e5cd757","idConcurso":"12f45a66-d8ea-526e-8512-0c33aef45882","idBanca":"b54a6da0-0ba4-55e3-857f-409cc620bec6","status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Cariologia e Flúor | Questão 12"},{"secao":"Radiologia e Ortodontia","numero":1,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Neto, Kurita e Campos (2019), sobre a interação da radiação eletromagnética (Raios X) com a matéria, é correto afirmar que:","alternativas":[{"letra":"A","texto":"os 3 processos fundamentais de interação com a matéria são: efeito fotoelétrico, efeito Compton e efeito Coulomb.","ordem":1,"idAlternativa":"cefdccf9-f728-5a22-a9d1-ef6039d03a1e"},{"letra":"B","texto":"no Efeito Compton ou espalhamento quanto mais elevada a energia, maior a probabilidade de ocorrer o espalhamento.","ordem":2,"idAlternativa":"e792cf82-be41-566a-a48a-ec823a4ac76d"},{"letra":"C","texto":"a probabilidade de ocorrer uma interação fotoelétrica é indiretamente proporcional à densidade do meio.","ordem":3,"idAlternativa":"40dfcf2c-6436-5be4-9567-14fd23e83e29"},{"letra":"D","texto":"o espalhamento Compton é dominante para a faixa de energia 10KeV<E<100KeV, em tecidos biológicos.","ordem":4,"idAlternativa":"7ea95025-40ef-5390-88ab-e1815c2a190c"},{"letra":"E","texto":"no efeito fotoelétrico o fóton incidente éabsorvido.","ordem":5,"idAlternativa":"2094cf0c-2079-5971-8129-d0967edbeaec"}],"gabarito":"E","observacoes":[],"idQuestao":"cd2ceb5c-702b-5269-9459-c38935755fa3","idDisciplina":"dcbdfc2c-6a69-5cc4-ba40-934d9c07924c","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Radiologia e Ortodontia | Questão 1"},{"secao":"Radiologia e Ortodontia","numero":2,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Neto, Kurita e Campos (2019), nos aparelhos de RX, adota-se uma medida que visa reduzir o tamanho real da área focal, fazendo-a funcionar, efetivamente, como uma área de menor tamanho, Essa redução virtual tem por objetivo reduzir a penumbra e aumentar a nitidez da imagem radiográfica, e é alcançada com a inclinação da área focal de 20º em relação ao plano vertical. A medida descrita acimaé conhecida como efeito:","alternativas":[{"letra":"A","texto":"Compton.","ordem":1,"idAlternativa":"51589324-ec67-5f14-b1e5-477ffb00726a"},{"letra":"B","texto":"Kerma.","ordem":2,"idAlternativa":"24b4e00d-781a-5df2-922b-35321a8a1dad"},{"letra":"C","texto":"Benson.","ordem":3,"idAlternativa":"98195e6e-2897-5dad-a9c0-e454df7d4e90"},{"letra":"D","texto":"Bremsstrahlung.","ordem":4,"idAlternativa":"450cdfc9-a75b-56c2-9cb1-c3177b7b5e9f"},{"letra":"E","texto":"Bystander.","ordem":5,"idAlternativa":"af80d1de-cc87-5abf-a334-f9265acd5d3b"}],"gabarito":"C","observacoes":[],"idQuestao":"3174c64e-fc49-568b-8f37-60c7773904bb","idDisciplina":"dcbdfc2c-6a69-5cc4-ba40-934d9c07924c","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Radiologia e Ortodontia | Questão 2"},{"secao":"Radiologia e Ortodontia","numero":3,"orgao":null,"cargo":null,"ano":null,"enunciado":"De acordo com White & Pharoah (2015), os princfpios da projeção geométrica descrevem o efeito do tamanho do ponto focal e a posição relativa do objeto e o receptor de imagem na penumbra, na ampliaçáo e na distorçăo da imagem. Em relasa a esses princfpios, no que diz respeito à nitidez e resoluçăo da imagem radiográfica, é correto afirmar que:","alternativas":[{"letra":"A","texto":"a nitidez mede o quanto a radiografia é capaz de demonstrar pequenos objetos que estão próximos entre si.","ordem":1,"idAlternativa":"14a3a2d2-62f9-5714-85fb-3cb41e384275"},{"letra":"B","texto":"quanto maior o tamanho do ponto focal, maior a faltade nitidez.","ordem":2,"idAlternativa":"f219ef6e-daea-5955-b916-f552eba9c6cb"},{"letra":"C","texto":"a resoluçăo espacial da imagem mede o quanto os limites entre duas áreas de diferentes radiodensidades são bem distinguíveis.","ordem":3,"idAlternativa":"0afc7d2b-be95-5ae6-9ae8-2139379606a8"},{"letra":"D","texto":"diminuir a distância entre o ponto focal e o objeto, utilizando um cilindro grande e aberto, é um meio para maximizar a nitidez da imagem.","ordem":4,"idAlternativa":"d66c1282-a09b-5bed-bb58-0d365a309186"},{"letra":"E","texto":"aumentar a distância entre o objeto e o receptor da imagem é um meio para maximizar a nitidez da imagem.","ordem":5,"idAlternativa":"54b32074-7c43-5a1f-8654-ef2d452704e3"}],"gabarito":"E","observacoes":["Obs.: O PDF não traz o cabeçalho (cargo/ano/órgão) desta questão."],"idQuestao":"9df349ef-f8a0-58d3-a4d9-7326c232c031","idDisciplina":"dcbdfc2c-6a69-5cc4-ba40-934d9c07924c","idConcurso":null,"idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Radiologia e Ortodontia | Questão 3 | Obs.: O PDF não traz o cabeçalho (cargo/ano/órgão) desta questão."},{"secao":"Radiologia e Ortodontia","numero":4,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"As imagens radiográficas, na prática odontológica, fornecem importantes informações sobre tecidos dentários e ósseos adjacentes, inacessíveis por meio de exames clínicos. Sobre o tema e considerando somente exames de Raios X, assinale a afirmativa correta.","alternativas":[{"letra":"A","texto":"A radiografia panorâmica permite uma visão global de todas as estruturas com grandes detalhes e pouca distorção.","ordem":1,"idAlternativa":"57752393-a6b3-52a6-b480-72f4e45c00bf"},{"letra":"B","texto":"A radiografia interproximal permite ao mesmo tempo o registro radiográfico das coroas dos dentes posteriores, superiores e inferiores.","ordem":2,"idAlternativa":"96799dd3-c585-5411-a61b-2c34c9f45c82"},{"letra":"C","texto":"A radiografia panorâmica não é indicada para pacientes com pouca abertura bucal.","ordem":3,"idAlternativa":"fc5eb3f8-9b2d-5b60-8406-6c0ddda6a8e5"},{"letra":"D","texto":"A radiografia periapical da bissetriz em dentes posteriores possui menor distorção para verificação de altura de crista ósseaalveolar.","ordem":4,"idAlternativa":"c9918dc2-616b-5ab8-8bb4-8a1390425a03"},{"letra":"E","texto":"As lesões do periápice dental são melhor observadas na radiografia panorâmica.","ordem":5,"idAlternativa":"486d7f0b-dc86-51da-8b97-3618b86cbae8"}],"gabarito":"C","observacoes":[],"idQuestao":"b6c52bdb-c6ec-5d92-9856-20ee83459224","idDisciplina":"dcbdfc2c-6a69-5cc4-ba40-934d9c07924c","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Radiologia e Ortodontia | Questão 4"},{"secao":"Radiologia e Ortodontia","numero":5,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Dean et. al (2011), no processo de diagnóstico para seleção de dentes decíduos em crianças que sejam candidatas adequadas à execusao da terapia pulpar em dente vital, os seguintes fatores devem ser considerados, EXCETO:","alternativas":[{"letra":"A","texto":"nível de cooperação e motivação do paciente e dos pais para receber o tratamento.","ordem":1,"idAlternativa":"55470cec-947e-5505-b915-99020b627282"},{"letra":"B","texto":"estágio de desenvolvimento dental do paciente.","ordem":2,"idAlternativa":"f061b6cf-3588-5e6a-a051-ff2b1b2979fe"},{"letra":"C","texto":"grau previsto de dificuldade para a adequada execução da terapia pulpar (instrumentação) em umcaso particular.","ordem":3,"idAlternativa":"d01a59f1-a332-50f9-a73f-e142e0666ac3"},{"letra":"D","texto":"obtenção do primeiro levante de mordida do processo de desenvolvimento oclusal.","ordem":4,"idAlternativa":"a606e9e2-d900-5d66-8f04-1db98dbc9636"},{"letra":"E","texto":"extrusão excessiva do dente com envolvimento pulpar, resultante da perda de dentes antagonistas.","ordem":5,"idAlternativa":"5d71e5a7-a825-5a08-a32f-950c014b60bb"}],"gabarito":"D","observacoes":[],"idQuestao":"7b3f394b-8745-50b8-b5e5-29da5c9ae569","idDisciplina":"dcbdfc2c-6a69-5cc4-ba40-934d9c07924c","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Radiologia e Ortodontia | Questão 5"},{"secao":"Radiologia e Ortodontia","numero":6,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"Segundo Proffit (2012), no arco dental inferior, quando os incisivos laterais permanentes erupcionam, há, em média, 1,6 mm a menos de espaso disponfvel para o alinhamento dos quatro incisivos permanentes. Essa diferensa entre a quantidade de espaço necessário para os incisivos e a quantidade disponível para eles é chamada Desvantagem Incisiva. Assinale a opção que apresenta corretamente os mecanismos fisiolôgicos do desenvolvimento da oclusão, que permitem ao organismo obter o espas adicional para alinhar os incisivos inferiores permanentes, após o período de apinhamento normal suave.","alternativas":[{"letra":"A","texto":"Posicionamento lingual da coroa dos incisivos permanentes em relação aos incisivos decíduos.","ordem":1,"idAlternativa":"572e383a-462a-569c-aaf8-6ff03f603a78"},{"letra":"B","texto":"Reposicionamento distal dos caninos inferiores.","ordem":2,"idAlternativa":"6b4cd398-2829-57f0-a07f-df15a22da601"},{"letra":"C","texto":"Crescimento esquelético significante na parte anteriorda mandíbula.","ordem":3,"idAlternativa":"de5fec2b-5aec-532b-9337-1b6a29d4c8fd"},{"letra":"D","texto":"Molares decíduos significativamente menores do que os pré-molares que irão substitui-los.","ordem":4,"idAlternativa":"a3ee45a5-937f-51e7-b150-9fd879df82c0"},{"letra":"E","texto":"Comprimento e circunferência do arco dental com tendência a aumentar durante a transição.","ordem":5,"idAlternativa":"ef97fdc2-9b35-50b1-8f2f-848afc3a0ce9"}],"gabarito":"B","observacoes":[],"idQuestao":"9bba7606-092a-597a-a39d-fe8ce788e688","idDisciplina":"dcbdfc2c-6a69-5cc4-ba40-934d9c07924c","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Radiologia e Ortodontia | Questão 6"},{"secao":"Radiologia e Ortodontia","numero":7,"orgao":"Marinha do Brasil","cargo":"DENTISTA PRIMEIRO TENENTE","ano":2022,"enunciado":"O deslocamento mandibular ortopédico, principalmente pelo uso contínuo de aparelhos como Herbst ou similares, refere-se à mudança do posicionamento mandibular em função de uma nova posição do côndilo mandibular, ditada pela remodelação da fossa mandibular, ou glenoide. De acordo com CONSOLARO (2014), analise as sentenças abaixo e assinale a alternativa incorreta:","alternativas":[{"letra":"A","texto":"Com o uso de tais aparelhos, haverá no local um ganho de novas camadas ósseas, especialmente na superfície da parede anterior da fossa mandibular, ou glenoide.","ordem":1,"idAlternativa":"21475de5-1ea9-59b5-b8ca-a97f6f5ce331"},{"letra":"B","texto":"A fossa mandibular, ou glenoide, como uma cavidade, não aumenta, e sim diminui, sua profundidade.","ordem":2,"idAlternativa":"672b998a-e782-5254-a303-c5d3c581a35f"},{"letra":"C","texto":"Apenas a parede posterior da fossa mandibular tem periósteo em sua superfície, onde se insere o tecido conjuntivo retrodiscal do disco articular daATM.","ordem":3,"idAlternativa":"14a3418b-ac8a-585b-988b-dad875f5e094"},{"letra":"D","texto":"A neoformação óssea, apesar de menos intensa, também é possível em pacientes adultos, pois independe do estágio de crescimento e está relacionada às alterações viscoelásticas na região periosteal da ATM.","ordem":4,"idAlternativa":"04f583e6-7ed5-580e-8631-b0e54c4e527e"}],"gabarito":"A","observacoes":[],"idQuestao":"64c9ed6d-2f59-5519-9da4-3383e4f5b7f0","idDisciplina":"dcbdfc2c-6a69-5cc4-ba40-934d9c07924c","idConcurso":"48a7e490-a935-53fa-9dfe-86f7852c2684","idBanca":null,"status":"publicada","fonte":"Apostila Questões Concurso Público – PPGO/UFU (2023) | Radiologia e Ortodontia | Questão 7"}]$apostila$::jsonb;
  v_questao jsonb; v_alternativa jsonb;
  v_idDisciplina uuid; v_idConcurso uuid; v_idBanca uuid;
  v_total integer;
begin
  for v_questao in select value from jsonb_array_elements(v_registros) loop
    select "idDisciplina" into v_idDisciplina from public.disciplinas
      where nome = v_questao->>'secao' order by criado_em limit 1;
    if v_idDisciplina is null then
      v_idDisciplina := (v_questao->>'idDisciplina')::uuid;
      insert into public.disciplinas("idDisciplina", nome, descricao, ativa)
        values(v_idDisciplina, v_questao->>'secao', 'Importada da apostila PPGO/UFU (2023)', true);
    end if;
    v_idConcurso := null;
    if v_questao->>'orgao' is not null then
      select "idConcurso" into v_idConcurso from public.concursos
        where orgao = v_questao->>'orgao' and cargo = v_questao->>'cargo'
          and ano = (v_questao->>'ano')::integer order by criado_em limit 1;
      if v_idConcurso is null then
        v_idConcurso := (v_questao->>'idConcurso')::uuid;
        insert into public.concursos("idConcurso", nome, orgao, cargo, estado, ano, descricao)
        values(v_idConcurso, concat(v_questao->>'orgao', ' — ', v_questao->>'cargo', ' (', v_questao->>'ano', ')'),
          v_questao->>'orgao', v_questao->>'cargo',
          coalesce(substring(v_questao->>'orgao' from '-([A-Z]{2})$'), ''),
          (v_questao->>'ano')::integer, 'Referência da apostila PPGO/UFU (2023)');
      end if;
    end if;
    v_idBanca := null;
    if v_questao->>'idBanca' is not null then
      select "idBanca" into v_idBanca from public.bancas
        where upper(nome) = 'INEP' order by criado_em limit 1;
      if v_idBanca is null then
        v_idBanca := (v_questao->>'idBanca')::uuid;
        insert into public.bancas("idBanca", nome, sigla) values(v_idBanca, 'INEP', 'INEP');
      end if;
    end if;
    if exists (select 1 from public.questoes where "idQuestao" = (v_questao->>'idQuestao')::uuid) then
      raise exception 'Colisão de idQuestao na apostila: %', v_questao->>'idQuestao';
    end if;
    insert into public.questoes("idQuestao", "idConcurso", "idBanca", "idDisciplina",
      enunciado, tipo, dificuldade, ano, fonte, imagem_url, explicacao, status)
    values((v_questao->>'idQuestao')::uuid, v_idConcurso, v_idBanca, v_idDisciplina,
      v_questao->>'enunciado', 'multipla_escolha', 'media', (v_questao->>'ano')::integer,
      v_questao->>'fonte', null, '', v_questao->>'status');
    for v_alternativa in select value from jsonb_array_elements(v_questao->'alternativas') loop
      insert into public.alternativas("idAlternativa", "idQuestao", letra, texto, ordem)
      values((v_alternativa->>'idAlternativa')::uuid, (v_questao->>'idQuestao')::uuid,
        v_alternativa->>'letra', v_alternativa->>'texto', (v_alternativa->>'ordem')::integer);
    end loop;
    insert into public.gabaritos("idQuestao", "idAlternativaCorreta", status, explicacao, fonte_gabarito)
      values((v_questao->>'idQuestao')::uuid,
        (select "idAlternativa" from public.alternativas
          where "idQuestao" = (v_questao->>'idQuestao')::uuid and letra = v_questao->>'gabarito'),
        'definitivo', '', 'Gabarito da apostila PPGO/UFU (2023)');
  end loop;
  select count(*) into v_total from public.questoes where fonte like 'Apostila Questões Concurso Público – PPGO/UFU (2023)%';
  if v_total <> 264 then raise exception 'Importação incompleta: % questões', v_total; end if;
  select count(*) into v_total from public.questoes where fonte like 'Apostila Questões Concurso Público – PPGO/UFU (2023)%' and status = 'rascunho';
  if v_total <> 10 then raise exception 'Contagem inesperada de questões com figura ausente: %', v_total; end if;
  select count(*) into v_total from public.alternativas a join public.questoes q on q."idQuestao" = a."idQuestao"
    where q.fonte like 'Apostila Questões Concurso Público – PPGO/UFU (2023)%';
  if v_total <> 1275 then raise exception 'Contagem inesperada de alternativas: %', v_total; end if;
  select count(*) into v_total from public.gabaritos g join public.questoes q on q."idQuestao" = g."idQuestao"
    where q.fonte like 'Apostila Questões Concurso Público – PPGO/UFU (2023)%';
  if v_total <> 264 then raise exception 'Contagem inesperada de gabaritos: %', v_total; end if;
end $importacao$;
